// Runtime is how the host reaches one installed plugin. WS8a (hosted) and
// WS8b (remote) implement it; tests use a fake. Call must honour ctx
// deadlines. Close releases the instance; the host may open a fresh one
// after a failure (restart with backoff).
type Runtime interface {
	Call(ctx context.Context, req Request) (Response, error)
	Close() error
}

// Installed is the host's record of one installed plugin, handed to a
// RuntimeFactory when an instance is opened.
type Installed struct {
	ID       string
	Manifest Manifest
	// SourceURL is where the manifest came from (remote endpoint base).
	SourceURL string
	// Files returns an artifact file (entry, module, strings, schema) for
	// the installed version, or false. Hosted runtimes load code through it.
	Files func(path string) ([]byte, bool)
	// Host is the per-plugin host-services handle (SPEC §5.1.5).
	Host Host
}

// RuntimeFactory opens a Runtime for one installed plugin. The factory is
// chosen by manifest ether.runtime.kind ("hosted" or "remote").
type RuntimeFactory func(inst Installed) (Runtime, error)

// Host is the set of Ether services a plugin may call (SPEC §5.1.5).
// Every method re-checks the plugin's live grants, so a revoke takes
// effect mid-call. Writes are journalled; in shadow mode they are
// recorded without applying. The hosted runtime exposes Host as imports;
// remote plugins reach it over /ether/plugin-host/* (WS8b).
type Host interface {
	KVGet(ctx context.Context, key string) ([]byte, bool, error)
	KVPut(ctx context.Context, key string, value []byte) error
	KVDelete(ctx context.Context, key string) error
	KVList(ctx context.Context, prefix string) ([]string, error)

	// SecretGet returns a sealed setting the manifest declared in
	// permissions.secrets. Hosted plugins only.
	SecretGet(ctx context.Context, name string) (string, error)

	// HTTPFetch fetches through egress and safefetch; only manifest
	// network hosts are allowed. Observed hosts feed the privacy label.
	HTTPFetch(ctx context.Context, req FetchRequest) (FetchResponse, error)

	// CatalogSearch and CatalogGet need catalog: read. Results are JSON
	// title summaries produced by the injected catalog backend.
	CatalogSearch(ctx context.Context, query string, limit, offset int) (json.RawMessage, error)
	CatalogGet(ctx context.Context, id string) (json.RawMessage, error)

	// ViewerHistory needs viewers.watch_history for that viewer.
	ViewerGranted(ctx context.Context) (json.RawMessage, error)
	ViewerHistory(ctx context.Context, viewerID int64, limit, offset int) (json.RawMessage, error)
	// SetWatchState needs viewers.write_watch_state; journalled.
	SetWatchState(ctx context.Context, viewerID int64, titleID string, watched bool) error
	// CollectionsUpsert needs collections: write; journalled.
	CollectionsUpsert(ctx context.Context, collection json.RawMessage) error

	// KindUpsert and KindDelete need catalog_provider and a push-mode
	// kind (spec §3.6): the sync engine is the only writer for pull
	// kinds. Writes are journalled in shadow mode without applying.
	KindUpsert(ctx context.Context, kindKey string, items []core.KindItem) (accepted int, err error)
	KindDelete(ctx context.Context, kindKey string, externalIDs []string) error
	// KindItems reads the plugin's own library back, keyset-paged.
	KindItems(ctx context.Context, kindKey, cursor string, limit int) (core.KindPage, error)
	// ResolveSources needs kind_resolver and permissions.sources
	// (search to look, acquire to open debrid content, §4.5).
	ResolveSources(ctx context.Context, q core.SourceQuery) ([]core.SourceCandidate, error)
	// CachePut stores one blob in a kind library's cache namespace and
	// returns its "blob:<sha256>" reference; CacheOpen reads one back.
	CachePut(ctx context.Context, libraryKey, name string, r io.Reader) (blobRef string, err error)
	CacheOpen(ctx context.Context, blobRef string) (io.ReadSeekCloser, error)

	// StreamURL mints a short-lived, scoped ticket for one of this
	// plugin's own kind items and returns the Ether stream URL a frontend
	// adapter embeds instead of a plugin URL (spec §6.5). The viewer is
	// the one the proxied request authenticated (X-Ether-Viewer); items
	// from another plugin, or a library the viewer cannot see, are
	// refused. Bytes are then served by Ether, never by the plugin.
	StreamURL(ctx context.Context, itemRef string) (string, error)

	// FoldersList and FoldersStat need folders: read and an owner-picked
	// root. They never return file contents.
	FoldersList(ctx context.Context, root, path string) ([]FolderEntry, error)
	FoldersStat(ctx context.Context, root, path string) (FolderEntry, error)
	FoldersHash(ctx context.Context, root, path string) (FolderHash, error)
	FoldersHashStart(ctx context.Context, root, path string) (FolderHashJob, error)
	FoldersHashPoll(ctx context.Context, id string) (FolderHashJob, error)
	FoldersHashCancel(ctx context.Context, id string) (FolderHashJob, error)

	// Settings returns the plugin's current non-secret settings. Plugins
	// read them per request instead of keeping them in instance memory,
	// because hosted plugins run in a pool of instances that restart.
	// Secrets stay behind SecretGet.
	Settings(ctx context.Context) (map[string]any, error)

	// NotifyOwner posts a console notice (rate-limited).
	NotifyOwner(ctx context.Context, text string) error
	// Log appends to the plugin's log ring (redacted, rate-limited).
	Log(ctx context.Context, level, msg string, attrs map[string]any) error
}

// FetchRequest is one plugin outbound HTTP call.
type FetchRequest struct {
	Method  string            `json:"method"`
	URL     string            `json:"url"`
	Headers map[string]string `json:"headers,omitempty"`
	Body    []byte            `json:"body,omitempty"`
}

// FetchResponse is the answer to a FetchRequest (body capped at 10 MiB).
type FetchResponse struct {
	Status  int               `json:"status"`
	Headers map[string]string `json:"headers,omitempty"`
	Body    []byte            `json:"body,omitempty"`
}

// FolderHashJob is a pollable background hash. Bytes is the progress so far.
// Terminal states are done, canceled and error. Only done carries Result.
type FolderHashJob struct {
	ID     string      `json:"id"`
	State  string      `json:"state"`
	Bytes  int64       `json:"bytes"`
	Result *FolderHash `json:"result,omitempty"`
	Error  string      `json:"error,omitempty"`
}

// FolderHash contains digests, never file contents. ModTime is Unix seconds.
type FolderHash struct {
	Size    int64  `json:"size"`
	ModTime int64  `json:"modTime"`
	CRC32   string `json:"crc32"`
	MD5     string `json:"md5"`
	SHA1    string `json:"sha1"`
}

// FolderEntry is one entry from FoldersList or FoldersStat.
type FolderEntry struct {
	Name  string `json:"name"`
	Path  string `json:"path"`
	Dir   bool   `json:"dir"`
	Size  int64  `json:"size,omitempty"`
	Mtime int64  `json:"mtime,omitempty"` // unix seconds
}

// Event is one normalized Ether event (SPEC §5.7). Payload is JSON with no
// secrets; viewer identity appears only for plugins granted it (the host
// strips it per plugin at delivery).
type Event struct {
	ID       string          `json:"id"`
	Name     string          `json:"name"`
	At       time.Time       `json:"at"`
	ViewerID int64           `json:"viewerId,omitempty"`
	Payload  json.RawMessage `json:"payload,omitempty"`
}

// KnownEvents is the closed v1 event set.
var KnownEvents = map[string]bool{
	EventPlaybackStarted: true, EventPlaybackPaused: true, EventPlaybackResumed: true,
	EventPlaybackStopped: true, EventPlaybackCompleted: true, EventPlaybackError: true,
	EventPlaybackFailover: true, EventTitleAvailable: true, EventViewerAdded: true,
	EventViewerAccess: true, EventCollectionRebuilt: true, EventServerHealth: true,
}

// ClientCaps is what the playing client can show.
type ClientCaps struct {
	MaxHeight int      `json:"maxHeight,omitempty"`
	HDR       []string `json:"hdr,omitempty"`
	Codecs    []string `json:"codecs,omitempty"`
}

// CatalogueArtifact is a resolved version from the signed plugin catalogue (WS12).
type CatalogueArtifact struct {
	ID           string
	Version      string
	URL          string
	SHA256       string
	Kind         Kind
	Permissions  Permissions
	Capabilities []Capability
}

// Catalogue is the signed catalogue hook used by the owner API, install
// and update flows (WS12).
type Catalogue interface {
	http.Handler
	// Resolve looks up a plugin in the verified catalogue by plugin ID (or
	// artifact URL) and optional version (empty means latest). It fails when
	// the plugin is not in the catalogue or is revoked.
	Resolve(ctx context.Context, idOrURL, version string) (CatalogueArtifact, error)
}

// FieldError is one validation problem, keyed by a dotted field path.
type FieldError struct {
	Field   string `json:"field"`
	Message string `json:"message"`
}

func (e *ValidationError) Error() string {
	if len(e.Fields) == 0 {
		return "plugins: invalid"
	}
	return fmt.Sprintf("plugins: invalid: %s: %s", e.Fields[0].Field, e.Fields[0].Message)
}

// MetadataMeta declares a provider of canonical catalogue records. Resolution
// happens during explicit materialization, never as part of ordinary browsing.
// Ether-native providers implement POST /ether/metadata/resolve using
// core.MetadataRequest and a {"title": core.Title} response.
type MetadataMeta struct {
	Types []string `json:"types"`
}

// DirectoryMeta declares a protocol-neutral plugin discovery source.
// Entries are suggestions, never installation authorization or verification.
type DirectoryMeta struct {
	Key   string `json:"key"`
	Label string `json:"label"`
}

// OnAirFeed declares a bounded household feed. MaxAge is a Go duration.
type OnAirFeed struct {
	ID     string            `json:"id"`
	Fields map[string]string `json:"fields"`
	Sample map[string]any    `json:"sample,omitempty"`
	MaxAge string            `json:"maxAge"`
}

// OnAirSegment is a fixed-duration declarative scene, never arbitrary video.
type OnAirSegment struct {
	ID       string   `json:"id"`
	Name     string   `json:"name"`
	Duration int      `json:"duration"`
	File     string   `json:"file"`
	Feeds    []string `json:"feeds"`
	Rating   string   `json:"rating,omitempty"`
}

// textOf converts a manifest label ("$t:key" or plain text) to registry
// Text. Plain plugin text is carried as Resolved so the console shows it
// without a catalogue entry; $t: keys resolve through plugin strings.
func textOf(plugin, s string) extend.Text {
	if strings.HasPrefix(s, "$t:") {
		return extend.PluginText(plugin, strings.TrimPrefix(s, "$t:"))
	}
	return extend.Text{Resolved: s}
}

// DescriptorsFor builds the registry descriptors a manifest contributes.
// Exported for the kit and Studio previews.
func DescriptorsFor(man Manifest) []extend.Descriptor {
	man.Ether = man.EffectiveEther()
	id := man.ID
	c := man.Ether.Contributes
	var out []extend.Descriptor
	add := func(kind extend.Kind, key string, label extend.Text, meta any) {
		d := extend.Descriptor{Kind: kind, ID: extend.PluginID(id, key), Owner: id, Label: label, Group: man.Name}
		if meta != nil {
			d = d.WithMeta(meta)
		}
		out = append(out, d)
	}
	if man.HasCapability(CapOnAirContent) {
		for _, seg := range c.OnAirSegments {
			add(extend.KindOnAirSegment, seg.ID, textOf(id, seg.Name), map[string]any{"duration": seg.Duration, "rating": seg.Rating, "feeds": seg.Feeds})
		}
	}
	for _, p := range c.Pages {
		meta := map[string]any{"route": p.Route, "pluginRoute": "/api/plugins/" + id + "/views/" + p.Key, "icon": p.Icon}
		if p.Group != "" {
			meta["group"] = p.Group
		}
		add(extend.KindPage, p.Key, textOf(id, p.Label), meta)
		add(extend.KindNavItem, "page-"+p.Key, textOf(id, p.Label), map[string]any{
			"route": "/plugins/" + id + "/" + p.Key, "pageKey": p.Key})
	}
	for _, s := range c.Slots {
		add(extend.KindSlot, s.Key, textOf(id, s.Label), map[string]any{"slot": s.Slot, "route": s.Route, "action": s.Action, "key": s.Key})
	}
	for _, cm := range c.Commands {
		add(extend.KindCommand, cm.Key, textOf(id, cm.Label), map[string]any{"action": cm.Action})
	}
	for _, rs := range c.RankingSteps {
		add(extend.KindRankingStep, rs.Key, textOf(id, rs.Label), map[string]any{
			"editor": rs.Editor, "budget": rs.Budget, "hint": rs.Hint})
	}
	for _, rc := range c.RuleConditions {
		add(extend.KindRuleField, rc.Key, textOf(id, rc.Label), map[string]any{
			"operators": rc.Operators, "editor": rc.Editor})
	}
	for _, ls := range c.ListSources {
		if !man.HasCapability(CapListSource) {
			continue
		}
		pid := extend.PluginID(id, ls.Key)
		fields, defaults := ParamFieldsFromList(id, ParseListParamFields(ls.Params))
		var values map[string]any
		_ = json.Unmarshal([]byte(defaults), &values)
		sourceDefaults := map[string]any{}
		if len(values) > 0 {
			sourceDefaults["params"] = values
		}
		meta := map[string]any{
			"catalog":          ls.Catalog,
			"params":           fields,
			"editor":           "plugin",
			"defaults":         sourceDefaults,
			"maxItems":         ls.MaxItems,
			"refresh":          ls.Refresh,
			"hint":             ls.Hint,
			"hubId":            pid,
			"rowKind":          pid,
			"collectionSource": pid,
			"sections":         []string{"home", "movies", "shows"},
		}
		dCol := extend.Descriptor{Kind: extend.KindCollectionSource, ID: pid, Owner: id, Label: textOf(id, ls.Label), Group: man.Name}
		dRow := extend.Descriptor{Kind: extend.KindRowSource, ID: pid, Owner: id, Label: textOf(id, ls.Label), Group: man.Name}
		if ls.Hint != "" {
			h := textOf(id, ls.Hint)
			dCol.Hint, dRow.Hint = h, h
		}
		out = append(out, dCol.WithMeta(meta), dRow.WithMeta(meta))
	}
	if man.HasCapability(CapLiveTV) && c.Channels != nil {
		add(extend.KindLiveTVSource, "channels", textOf(id, man.Name), map[string]any{
			"refresh": c.Channels.Refresh, "yieldsChannels": true, "yieldsGuide": true})
	}
	if man.HasCapability(CapNotify) && c.Notification != nil {
		add(extend.KindChannelKind, "notify", textOf(id, man.Name), map[string]any{
			"fields": notificationFields(id, c.Notification.Fields), "sendTest": c.Notification.SendTest, "selectable": true, "formats": c.Notification.Formats, "maxLength": c.Notification.MaxLength})
	}
	if man.HasCapability(CapPluginDirectory) {
		for _, d := range c.Directories {
			add(extend.KindPluginDirectory, d.Key, textOf(id, d.Label), map[string]any{"key": d.Key})
		}
	}
	if man.HasCapability(CapMetadata) && c.Metadata != nil {
		add(extend.KindMetadataProvider, "metadata", textOf(id, man.Name), c.Metadata)
	}
	if man.HasCapability(CapSubtitles) && c.Subtitles != nil {
		add(extend.KindSubtitleProvider, "subtitles", textOf(id, man.Name), map[string]any{
			"languages": c.Subtitles.Languages, "formats": c.Subtitles.Formats})
	}
	if man.HasCapability(CapMarkers) && c.Markers != nil {
		add(extend.KindMarkerSource, "markers", textOf(id, man.Name), map[string]any{"kinds": c.Markers.Kinds})
	}
	if man.HasCapability(CapStreamSource) && c.Source != nil {
		add(extend.KindSourceKind, "stream", textOf(id, man.Name), map[string]any{
			"class": c.Source.Class, "abilities": c.Source.Abilities, "limits": c.Source.Limits})
	}
	if man.HasCapability(CapDebridProvider) && c.Source != nil {
		add(extend.KindSourceKind, "debrid", textOf(id, man.Name), map[string]any{"class": "debrid", "abilities": c.Source.Abilities})
	}
	if man.Ether.Kind == KindIntegration && c.Integration != nil {
		add(extend.KindIntegration, "integration", textOf(id, man.Name), map[string]any{
			"category": c.Integration.Category, "adds": c.Integration.Adds, "connect": c.Integration.Connect, "logo": c.Integration.Logo})
	}
	for _, tl := range c.Tools {
		add(extend.KindTool, tl.Name, textOf(id, tl.Title), map[string]any{
			"name": ToolName(id, tl.Name), "readOnly": tl.ReadOnly && man.RuntimeKind() == "hosted", "destructive": tl.Destructive, "openWorld": tl.OpenWorld})
	}
	return out
}

// ToolName namespaces a plugin tool for the catalogue: dots and dashes
// become underscores ("<plugin>__<name>").
func ToolName(plugin, name string) string {
	p := strings.NewReplacer(".", "_", "-", "_").Replace(plugin)
	return p + "__" + name
}

// syncDescriptors replaces a plugin's registry descriptors and tools to
// match its record: none while disabled.
func (m *Manager) syncDescriptors(ctx context.Context, r Record) {
	if !r.Enabled {
		m.deps.OnAirContent.RemovePlugin(r.ID)
	} else {
		m.deps.OnAirContent.EnablePlugin(r.ID)
	}
	m.indexEventSubscriptions(r)
	m.syncNotificationKind(r)
	m.mu.Lock()
	m.shadow[r.ID] = r.Shadow
	m.mu.Unlock()
	if m.deps.Registry != nil {
		var ds []extend.Descriptor
		if r.Enabled {
			ds = DescriptorsFor(r.Manifest)
		}
		if err := m.deps.Registry.ReplaceOwner(r.ID, ds); err != nil {
			m.log.Warn("plugins: registry sync", "plugin", r.ID, "err", err)
		}
	}
	if m.deps.Tools != nil {
		var ts []tools.Tool
		if r.Enabled && r.Manifest.Ether != nil {
			for _, tl := range r.Manifest.Ether.Contributes.Tools {
				ts = append(ts, m.pluginTool(r, tl))
			}
		}
		if err := m.deps.Tools.ReplaceOwner(r.ID, ts); err != nil {
			m.log.Warn("plugins: tool sync", "plugin", r.ID, "err", err)
		}
	}
	m.mu.Lock()
	hooks := append([]func(context.Context, Record){}, m.syncHooks...)
	m.mu.Unlock()
	for _, fn := range hooks {
		fn(ctx, r)
	}
	m.prewarmHot(r)
}

// pluginTool adapts one contributed tool to the catalogue. Read-only tools
// execute through /ether/tool/{name}; writes return a Proposal whose
// Apply runs the call after owner approval (SPEC §5.10). Hosted read-only
// calls carry a host-enforced write restriction; remote tools always require
// approval because a sidecar can write independently of the current call.
func (m *Manager) pluginTool(r Record, tl ToolMeta) tools.Tool {
	pluginID, name := r.ID, tl.Name
	readOnly := tl.ReadOnly && r.Manifest.RuntimeKind() == "hosted"
	title := tl.Title
	if strings.HasPrefix(title, "$t:") {
		title = name
	}
	run := func(ctx context.Context, input map[string]any) (tools.Result, error) {
		body, err := json.Marshal(input)
		if err != nil {
			return tools.Result{}, err
		}
		resp, err := m.Call(ctx, pluginID, Request{Method: "POST", Path: "/ether/tool/" + name, Body: body})
		if err != nil {
			return tools.Result{}, tools.Userf("Plugin %s tool %s failed.", pluginID, name)
		}
		if resp.Status >= 300 {
			return tools.Result{}, tools.Userf("Plugin %s tool %s failed with status %d.", pluginID, name, resp.Status)
		}
		if len(resp.Body) > 64*1024 {
			return tools.Result{}, tools.Userf("Plugin tool output is too large.")
		}
		var data map[string]any
		if len(resp.Body) > 0 {
			if err := json.Unmarshal(resp.Body, &data); err != nil {
				return tools.Result{}, tools.Userf("Plugin tool returned invalid output.")
			}
		}
		encoded, err := json.Marshal(data)
		if err != nil {
			return tools.Result{}, tools.Userf("Plugin tool returned invalid output.")
		}
		clean := m.store.redactKnown(ctx, pluginID, string(encoded))
		if err := json.Unmarshal([]byte(clean), &data); err != nil {
			return tools.Result{}, tools.Userf("Plugin tool output could not be safely displayed.")
		}
		redactValue(data)
		return tools.Result{Data: data}, nil
	}
	return tools.Tool{
		Name: ToolName(pluginID, name), Title: title, Description: tl.Description,
		InputSchema: tl.InputSchema, ReadOnly: readOnly, Destructive: tl.Destructive,
		OpenWorld: tl.OpenWorld, Audience: tools.AudienceOwner, Owner: pluginID,
		Execute: func(ctx context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			encoded, err := json.Marshal(input)
			if err != nil || len(encoded) > 64*1024 {
				return tools.Result{}, tools.Userf("Tool input is invalid or too large.")
			}
			var snapshot map[string]any
			if err := json.Unmarshal(encoded, &snapshot); err != nil {
				return tools.Result{}, tools.Userf("Tool input is invalid.")
			}
			if err := agent.ValidateToolInput(tl.InputSchema, snapshot); err != nil {
				return tools.Result{}, tools.Userf("Invalid tool input: %s", err)
			}
			if readOnly {
				return run(context.WithValue(ctx, readOnlyToolContextKey{}, true), snapshot)
			}
			return tools.Result{Proposal: &tools.Proposal{
				Category:    fmt.Sprintf("Run %s from %s", title, r.Name),
				Description: tl.Description,
				Input:       snapshot,
				Apply: func(ctx context.Context) (tools.Result, error) {
					var approved map[string]any
					if err := json.Unmarshal(encoded, &approved); err != nil {
						return tools.Result{}, err
					}
					return run(ctx, approved)
				},
			}}, nil
		},
	}
}

// PermissionSheet returns the plain-language lines the owner sees at
// install (SPEC §5.4). needsViewers and needsFolders say the sheet needs
// viewer or folder picks.
func PermissionSheet(man Manifest) (lines []string, needsViewers, needsFolders bool) {
	if man.Ether != nil && man.Ether.Runtime.Kind == "data" {
		return []string{"Adds channel styles and licensed artwork. Runs no code."}, false, false
	}
	if man.Ether == nil {
		return []string{"Connects to the add-on address you gave"}, false, false
	}
	if man.Ether.Stremio {
		lines = append(lines, "Connects to the add-on it was made from")
	}
	p := man.Ether.Permissions
	for _, h := range p.Network {
		lines = append(lines, "Connects to "+h)
	}
	if normLevel(p.Catalog) == "read" {
		lines = append(lines, "Reads your catalogue")
	}
	if normLevel(p.Viewers.Identity) != "none" {
		lines = append(lines, "Sees who is watching (viewers you choose)")
		needsViewers = needsViewers || normLevel(p.Viewers.Identity) == "granted_viewers"
	}
	if normLevel(p.Viewers.WatchHistory) != "none" {
		lines = append(lines, "Reads watch history")
		needsViewers = needsViewers || normLevel(p.Viewers.WatchHistory) == "granted_viewers"
	}
	if normLevel(p.Viewers.WriteWatchState) != "none" {
		lines = append(lines, "Marks titles watched")
		needsViewers = true
	}
	if normLevel(p.Collections) == "write" {
		lines = append(lines, "Creates and updates collections")
	}
	if normLevel(p.Folders) == "read" {
		lines = append(lines, "Reads folders you choose")
		needsFolders = true
	}
	switch normLevel(p.Sources) {
	case "search":
		lines = append(lines, "Searches your indexers for sources")
	case "acquire":
		lines = append(lines, "Searches your indexers and opens sources through your debrid accounts")
	}
	for _, k := range man.Ether.Contributes.MediaKinds {
		if !k.HasLibrary() {
			continue
		}
		name := k.Library.Name
		if strings.HasPrefix(name, "$t:") {
			name = k.Key
		}
		lines = append(lines, "Adds a library: "+name)
	}
	for range p.Secrets {
		lines = append(lines, "Stores an access token")
	}
	if man.HasCapability(CapEvents) {
		lines = append(lines, "Gets play and new-release events")
	}
	if len(lines) == 0 {
		lines = []string{"Needs no access to your server or the network"}
	}
	return lines, needsViewers, needsFolders
}

// PermissionDiff lists the permissions `next` asks for that `cur` does
// not have. A non-empty result pauses auto-update and asks the owner.
func PermissionDiff(cur, next Manifest) []string {
	if cur.Ether == nil || next.Ether == nil {
		if next.Ether != nil {
			lines, _, _ := PermissionSheet(next)
			return lines
		}
		return nil
	}
	a, b := cur.Ether.Permissions, next.Ether.Permissions
	var added []string
	have := map[string]bool{}
	for _, h := range a.Network {
		have[h] = true
	}
	for _, h := range b.Network {
		if !have[h] {
			added = append(added, "Connects to "+h)
		}
	}
	level := map[string]int{"none": 0, "granted_viewers": 1, "read": 1, "write": 1, "all": 2}
	raised := func(x, y string) bool { return level[normLevel(y)] > level[normLevel(x)] }
	if raised(a.Catalog, b.Catalog) {
		added = append(added, "Reads your catalogue")
	}
	if raised(a.Viewers.Identity, b.Viewers.Identity) {
		added = append(added, "Sees who is watching (viewers you choose)")
	}
	if raised(a.Viewers.WatchHistory, b.Viewers.WatchHistory) {
		added = append(added, "Reads watch history")
	}
	if raised(a.Viewers.WriteWatchState, b.Viewers.WriteWatchState) {
		added = append(added, "Marks titles watched")
	}
	if raised(a.Collections, b.Collections) {
		added = append(added, "Creates and updates collections")
	}
	if raised(a.Folders, b.Folders) {
		added = append(added, "Reads folders you choose")
	}
	sourcesLevel := map[string]int{"none": 0, "search": 1, "acquire": 2}
	if sourcesLevel[normLevel(b.Sources)] > sourcesLevel[normLevel(a.Sources)] {
		if normLevel(b.Sources) == "acquire" {
			added = append(added, "Searches your indexers and opens sources through your debrid accounts")
		} else {
			added = append(added, "Searches your indexers for sources")
		}
	}
	haveKindLib := map[string]bool{}
	for _, k := range cur.Ether.Contributes.MediaKinds {
		if k.HasLibrary() {
			haveKindLib[k.Key] = true
		}
	}
	for _, k := range next.Ether.Contributes.MediaKinds {
		if k.HasLibrary() && !haveKindLib[k.Key] {
			name := k.Library.Name
			if strings.HasPrefix(name, "$t:") {
				name = k.Key
			}
			added = append(added, "Adds a library: "+name)
		}
	}
	haveSecret := map[string]bool{}
	for _, s := range a.Secrets {
		haveSecret[s] = true
	}
	for _, s := range b.Secrets {
		if !haveSecret[s] {
			added = append(added, "Stores an access token")
		}
	}
	if !cur.HasCapability(CapEvents) && next.HasCapability(CapEvents) {
		added = append(added, "Gets play and new-release events")
	}
	return added
}

func newEventID() string {
	var b [8]byte
	_, _ = rand.Read(b[:])
	return hex.EncodeToString(b[:])
}

// Publish normalizes and fans out one Ether event: it is written to the
// 7-day event log and queued for every enabled plugin that subscribed to
// it (and was not revoked). Viewer identity is stripped per plugin unless
// the plugin's grants allow it.
func (m *Manager) Publish(ctx context.Context, ev Event) {
	if !KnownEvents[ev.Name] {
		return
	}
	m.mu.Lock()
	recs := make([]Record, 0, len(m.eventSubs[ev.Name]))
	for _, r := range m.eventSubs[ev.Name] {
		recs = append(recs, r)
	}
	m.mu.Unlock()
	if len(recs) == 0 {
		return
	}
	if ev.ID == "" {
		ev.ID = newEventID()
	}
	if ev.At.IsZero() {
		ev.At = m.now()
	}
	logged := false
	for _, r := range recs {
		if !r.Enabled || r.Manifest.Ether == nil || !r.Manifest.HasCapability(CapEvents) {
			continue
		}
		sub := false
		if evMeta := r.Manifest.Ether.Contributes.Events; evMeta != nil {
			for _, n := range evMeta.Subscribe {
				if n == ev.Name {
					sub = true
				}
			}
		}
		if !sub {
			continue
		}
		g, err := m.store.grants(ctx, r.ID)
		if err != nil || g.revoked("events") {
			continue
		}
		if !logged {
			m.store.logEvent(ctx, ev)
			logged = true
		}
		out := ev
		if !viewerOK(g, normLevel(r.Manifest.Ether.Permissions.Viewers.Identity), ev.ViewerID) {
			out.ViewerID = 0
			out.Payload = stripViewer(out.Payload)
		}
		dropped, err := m.store.enqueue(ctx, r.ID, out)
		if err == nil && dropped > 0 {
			m.healthMu.Lock()
			if h, err := m.store.health(ctx, r.ID); err == nil {
				h.Drops += int64(dropped)
				_ = m.store.putHealth(ctx, r.ID, h)
			}
			m.healthMu.Unlock()
		}
	}
}

// indexEventSubscriptions is updated together with the plugin's descriptors.
func (m *Manager) indexEventSubscriptions(r Record) {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, subscribers := range m.eventSubs {
		delete(subscribers, r.ID)
	}
	if !r.Enabled || r.Manifest.Ether == nil || !r.Manifest.HasCapability(CapEvents) || r.Manifest.Ether.Contributes.Events == nil {
		return
	}
	for _, name := range r.Manifest.Ether.Contributes.Events.Subscribe {
		if !KnownEvents[name] {
			continue
		}
		if m.eventSubs[name] == nil {
			m.eventSubs[name] = make(map[string]Record)
		}
		m.eventSubs[name][r.ID] = r
	}
}

func stripViewer(payload json.RawMessage) json.RawMessage {
	var doc any
	if json.Unmarshal(payload, &doc) != nil {
		return json.RawMessage(`{}`)
	}
	changed := false
	var strip func(any)
	strip = func(v any) {
		switch value := v.(type) {
		case map[string]any:
			for k, child := range value {
				lk := strings.ToLower(k)
				if strings.Contains(lk, "viewer") || strings.Contains(lk, "user") {
					delete(value, k)
					changed = true
				} else {
					strip(child)
				}
			}
		case []any:
			for _, child := range value {
				strip(child)
			}
		}
	}
	strip(doc)
	if !changed {
		return payload
	}
	out, err := json.Marshal(doc)
	if err != nil {
		return payload
	}
	return out
}

// NormalizePlayback maps a playback.Manager event kind to §5.7 names.
// state is the raw timeline state for updates (playing, paused, stopped).
// It returns "" for kinds with no normalized event.
func NormalizePlayback(kind, state string) string {
	switch kind {
	case "start", "started":
		return EventPlaybackStarted
	case "stop", "stopped":
		return EventPlaybackStopped
	case "completed", "complete":
		return EventPlaybackCompleted
	case "error":
		return EventPlaybackError
	case "failover", "downfailover":
		return EventPlaybackFailover
	case "update", "progress":
		switch state {
		case "paused":
			return EventPlaybackPaused
		case "playing":
			return EventPlaybackResumed
		}
	}
	return ""
}

// DeliverOutbox sends queued events to one plugin in batches of 50 and
// deletes the ones it acks. A missing ack keeps events for redelivery
// (at least once).
func (m *Manager) DeliverOutbox(ctx context.Context, pluginID string) error {
	for {
		evs, ids, err := m.store.outboxBatch(ctx, pluginID, 50)
		if err != nil || len(evs) == 0 {
			return err
		}
		body, _ := json.Marshal(map[string]any{"events": evs})
		resp, err := m.Call(ctx, pluginID, Request{Method: "POST", Path: "/ether/event", Body: body})
		if err != nil {
			return err
		}
		if resp.Status < 200 || resp.Status >= 300 {
			return fmt.Errorf("event delivery failed with status %d", resp.Status)
		}
		var out struct {
			Ack []string `json:"ack"`
		}
		_ = json.Unmarshal(resp.Body, &out)
		acked := map[string]bool{}
		for _, id := range out.Ack {
			acked[id] = true
		}
		var done []int64
		for i, ev := range evs {
			if acked[ev.ID] {
				done = append(done, ids[i])
			}
		}
		if len(done) == 0 {
			return nil // nothing acked; try again later
		}
		if err := m.store.ackOutbox(ctx, done); err != nil {
			return err
		}
		if len(done) < len(evs) {
			return nil
		}
	}
}

// Run drives health checks, scheduled jobs and outbox delivery until ctx
// ends. Leader plugins run jobs and event delivery only on the leader;
// every_node plugins run everywhere. Health checks run on every node.
func (m *Manager) Run(ctx context.Context) {
	defer func() {
		m.hashMu.Lock()
		defer m.hashMu.Unlock()
		for _, job := range m.hashJobs {
			job.cancel()
		}
	}()

	tick := time.NewTicker(5 * time.Second)
	defer tick.Stop()
	lastHealth := map[string]time.Time{}
	for {
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
			m.runOnce(ctx, lastHealth)
		}
	}
}

// runOnce is one scheduler pass; tests drive it directly.
// stremioManifestRefresh is how often an installed Stremio add-on's
// manifest is re-read.
const stremioManifestRefresh = time.Hour

func (m *Manager) runOnce(ctx context.Context, lastHealth map[string]time.Time) {
	recs, err := m.store.list(ctx)
	if err != nil {
		return
	}
	now := m.now()
	m.refreshOnAir(ctx, recs, now)
	for _, r := range recs {
		if r.Enabled && r.Manifest.IsStremioOnly() && r.SourceKind == "url" && m.isLeader() {
			// Stremio add-ons change catalogs and resources without a
			// version bump; re-read the manifest hourly (cluster leader).
			key := "stremio-manifest|" + r.ID
			if last, seen := lastHealth[key]; !seen || now.Sub(last) >= stremioManifestRefresh {
				lastHealth[key] = now
				if seen {
					go func(id string) {
						rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), time.Minute)
						defer cancel()
						_, _, _ = m.CheckUpdate(rctx, id)
					}(r.ID)
				}
			}
		}
		if !r.Enabled || r.Manifest.Ether == nil {
			continue
		}
		interval := time.Minute
		if d, err := time.ParseDuration(r.Manifest.Ether.Health.Interval); err == nil && d >= 15*time.Second {
			interval = d
		}
		if _, hasRuntime := m.factoryFor(r); hasRuntime && now.Sub(lastHealth[r.ID]) >= interval {
			lastHealth[r.ID] = now
			h, _ := m.store.health(ctx, r.ID)
			if h.NextRetry.IsZero() || !now.Before(h.NextRetry) || h.Status != "error" {
				_, _ = m.CheckHealth(ctx, r.ID)
			}
		}
		if !m.mayRunJobs(r) {
			continue
		}
		for _, job := range r.Manifest.Ether.Schedule {
			if job.Call == "/ether/feeds" {
				continue
			}
			every, err := time.ParseDuration(job.Every)
			if err != nil {
				continue
			}
			key := r.ID + "|" + job.Call
			m.mu.Lock()
			next, seen := m.nextRun[key]
			if !seen {
				m.nextRun[key] = now.Add(every)
				m.mu.Unlock()
				continue
			}
			if now.Before(next) {
				m.mu.Unlock()
				continue
			}
			m.nextRun[key] = now.Add(every)
			m.mu.Unlock()
			_, _ = m.Call(ctx, r.ID, Request{Method: "POST", Path: job.Call})
		}
		_ = m.DeliverOutbox(ctx, r.ID)
		// Capability refreshes ride the schedule: list sources and
		// channels declare their own refresh in contributes.
		m.maybeRefresh(ctx, r, now)
	}
}

func (m *Manager) factoryFor(r Record) (RuntimeFactory, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	f, ok := m.fatories[r.Manifest.RuntimeKind()]
	return f, ok
}

// mayRunJobs applies cluster placement: leader plugins only on the
// leader, every_node everywhere.
func (m *Manager) mayRunJobs(r Record) bool {
	if r.Manifest.Ether.Cluster == "every_node" {
		return true
	}
	return m.isLeader()
}

func (m *Manager) maybeRefresh(ctx context.Context, r Record, now time.Time) {
	type refresh struct {
		key   string
		every time.Duration
		path  string
	}
	var jobs []refresh
	c := r.Manifest.Ether.Contributes
	if c.Channels != nil && c.Channels.Refresh != "" {
		if d, err := time.ParseDuration(c.Channels.Refresh); err == nil {
			jobs = append(jobs, refresh{"channels", d, "/ether/channels.json"})
		}
	}
	for _, ls := range c.ListSources {
		refreshStr := ls.Refresh
		if refreshStr == "" {
			refreshStr = "1h"
		}
		if d, err := time.ParseDuration(refreshStr); err == nil {
			jobs = append(jobs, refresh{"list:" + ls.Key, d, "/catalog/movie/" + ls.Catalog + ".json"})
		}
	}
	for _, j := range jobs {
		key := r.ID + "|refresh:" + j.key
		m.mu.Lock()
		next, seen := m.nextRun[key]
		if !seen {
			m.nextRun[key] = now.Add(j.every)
			m.mu.Unlock()
			continue
		}
		if now.Before(next) {
			m.mu.Unlock()
			continue
		}
		m.nextRun[key] = now.Add(j.every)
		m.mu.Unlock()
		_, _ = m.Call(ctx, r.ID, Request{Method: "GET", Path: j.path})
	}
}

type folderHashWork struct {
	mu                 sync.Mutex
	plugin, root, path string
	status             FolderHashJob
	cancel             context.CancelFunc
}

func (h *host) FoldersHashStart(ctx context.Context, root, path string) (FolderHashJob, error) {
	if _, err := h.FoldersStat(ctx, root, path); err != nil {
		return FolderHashJob{}, err
	}
	m := h.m
	m.hashMu.Lock()
	defer m.hashMu.Unlock()
	if m.hashJobs == nil {
		m.hashJobs = make(map[string]*folderHashWork)
	}
	for id, w := range m.hashJobs {
		if w.plugin != h.plugin {
			continue
		}
		w.mu.Lock()
		running := w.status.State == "running"
		status := w.status
		w.mu.Unlock()
		if running {
			if w.root == root && w.path == path {
				return status, nil
			}
			return FolderHashJob{}, fmt.Errorf("folders.hash: plugin already has a running job")
		}
		delete(m.hashJobs, id)
	}
	select {
	case folderHashSlots <- struct{}{}:
	default:
		return FolderHashJob{}, fmt.Errorf("folders.hash: global job limit reached; retry later")
	}
	// The job intentionally survives the initiating host call, but has a finite lifetime.
	jobCtx, cancel := context.WithTimeout(context.Background(), 24*time.Hour)
	m.hashSequence++
	w := &folderHashWork{plugin: h.plugin, root: root, path: path, cancel: cancel, status: FolderHashJob{ID: fmt.Sprintf("hash-%d", m.hashSequence), State: "running"}}
	m.hashJobs[w.status.ID] = w
	go func() {
		defer func() { cancel(); <-folderHashSlots }()
		result, err := h.hashFile(jobCtx, root, path, true, func(n int64) { w.mu.Lock(); w.status.Bytes = n; w.mu.Unlock() })
		w.mu.Lock()
		defer w.mu.Unlock()
		if err != nil {
			w.status.State = "error"
			w.status.Error = err.Error()
			if jobCtx.Err() != nil {
				w.status.State = "canceled"
			}
		} else {
			w.status.State = "done"
			w.status.Bytes = result.Size
			w.status.Result = &result
		}
	}()
	return FolderHashJob{ID: w.status.ID, State: "running"}, nil
}

func (h *host) hashJob(ctx context.Context, id string, cancel bool) (FolderHashJob, error) {
	h.m.hashMu.Lock()
	w := h.m.hashJobs[id]
	h.m.hashMu.Unlock()
	if w == nil || w.plugin != h.plugin {
		return FolderHashJob{}, fmt.Errorf("folders.hash: unknown job")
	}
	if _, err := h.folderCheck(ctx, w.root, w.path); err != nil {
		w.cancel()
		return FolderHashJob{}, err
	}
	if cancel {
		w.cancel()
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	status := w.status
	if status.Result != nil {
		result := *status.Result
		status.Result = &result
	}
	return status, nil
}

func (h *host) FoldersHashPoll(ctx context.Context, id string) (FolderHashJob, error) {
	return h.hashJob(ctx, id, false)
}

func (h *host) FoldersHashCancel(ctx context.Context, id string) (FolderHashJob, error) {
	return h.hashJob(ctx, id, true)
}

func (s *storage) hashCacheGet(ctx context.Context, plugin, key string) ([]byte, bool, error) {
	var raw []byte
	err := s.db.QueryRowContext(ctx, `SELECT value FROM plugins_hash_cache WHERE plugin=? AND kkey=?`, plugin, key).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, false, nil
	}
	return raw, err == nil, err
}

func (s *storage) hashCachePut(ctx context.Context, plugin, key string, raw []byte) error {
	_, err := s.db.ExecContext(ctx, `INSERT INTO plugins_hash_cache(plugin,kkey,value) VALUES(?,?,?) ON CONFLICT(plugin,kkey) DO UPDATE SET value=excluded.value`, plugin, key, raw)
	return err
}

// host implements Host for one plugin. Grants are re-read on every call,
// so a revoke takes effect mid-call. Writes are journalled with their
// inverse; in shadow mode they are recorded without applying.
type host struct {
	m      *Manager
	plugin string
}

func (h *host) requireWritableToolContext(ctx context.Context) error {
	if readOnly, _ := ctx.Value(readOnlyToolContextKey{}).(bool); readOnly {
		h.noteDenied("read-only tool")
		return fmt.Errorf("%w: read-only tool cannot write", ErrPermissionDenied)
	}
	return nil
}

func (h *host) record(ctx context.Context) (Record, Grants, error) {
	r, err := h.m.store.record(ctx, h.plugin)
	if err != nil {
		return Record{}, Grants{}, err
	}
	if !r.Enabled {
		return Record{}, Grants{}, ErrDisabled
	}
	g, err := h.m.store.grants(ctx, h.plugin)
	return r, g, err
}

func (h *host) deny(r Record, g Grants, key, level string, allowed func(string) bool) error {
	if g.revoked(key) || !allowed(level) {
		h.noteDenied(key)
		return fmt.Errorf("%w: %s", ErrPermissionDenied, key)
	}
	return nil
}

func (h *host) noteDenied(key string) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if hh, err := h.m.store.health(ctx, h.plugin); err == nil && hh.Status == "ok" {
		hh.Status = "attention"
		hh.Reason = "A permission it needs was taken back: " + key
		_ = h.m.store.putHealth(ctx, h.plugin, hh)
	}
}

func viewerOK(g Grants, level string, viewerID int64) bool {
	switch level {
	case "all":
		return true
	case "granted_viewers":
		return g.viewerGranted(viewerID)
	}
	return false
}

func (h *host) KVGet(ctx context.Context, key string) ([]byte, bool, error) {
	if _, _, err := h.record(ctx); err != nil {
		return nil, false, err
	}
	return h.m.store.kvGet(ctx, h.plugin, key)
}

func (h *host) KVPut(ctx context.Context, key string, value []byte) error {
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	return h.m.store.kvPut(ctx, h.plugin, key, value)
}

func (h *host) KVDelete(ctx context.Context, key string) error {
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	return h.m.store.kvDelete(ctx, h.plugin, key)
}

func (h *host) KVList(ctx context.Context, prefix string) ([]string, error) {
	if _, _, err := h.record(ctx); err != nil {
