// journalWrite records a write (and, unless shadow, has already applied
// it; callers pass the inverse they obtained).
func (h *host) journal(ctx context.Context, r Record, op, detail string, inverse any) error {
	raw, err := json.Marshal(inverse)
	if err != nil {
		return err
	}
	_, err = h.m.store.journal(ctx, JournalEntry{Plugin: h.plugin, Op: op, Detail: detail, Inverse: raw, Shadow: r.Shadow})
	return err
}

type watchInverse struct {
	Op       string `json:"op"`
	ViewerID int64  `json:"viewerId"`
	TitleID  string `json:"titleId"`
	Watched  bool   `json:"watched"`
}

type collectionInverse struct {
	Op       string          `json:"op"`
	Previous json.RawMessage `json:"previous,omitempty"` // empty means delete
	Doc      json.RawMessage `json:"doc,omitempty"`
}

func (h *host) SetWatchState(ctx context.Context, viewerID int64, titleID string, watched bool) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, g, err := h.record(ctx)
	if err != nil {
		return err
	}
	if err := h.deny(r, g, "viewers.write_watch_state", normLevel(r.Manifest.Ether.Permissions.Viewers.WriteWatchState),
		func(l string) bool { return viewerOK(g, l, viewerID) }); err != nil {
		return err
	}
	if r.Shadow {
		return h.journal(ctx, r, "viewers.setWatchState", titleID, watchInverse{Op: "viewers.setWatchState", ViewerID: viewerID, TitleID: titleID, Watched: !watched})
	}
	if h.m.deps.Backends.SetWatchState == nil {
		return ErrUnavailable
	}
	prev, err := h.m.deps.Backends.SetWatchState(ctx, viewerID, titleID, watched)
	if err != nil {
		return err
	}
	return h.journal(ctx, r, "viewers.setWatchState", titleID, watchInverse{Op: "viewers.setWatchState", ViewerID: viewerID, TitleID: titleID, Watched: prev})
}

func (h *host) CollectionsUpsert(ctx context.Context, doc json.RawMessage) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, g, err := h.record(ctx)
	if err != nil {
		return err
	}
	if err := h.deny(r, g, "collections", normLevel(r.Manifest.Ether.Permissions.Collections),
		func(l string) bool { return l == "write" }); err != nil {
		return err
	}
	if r.Shadow {
		return h.journal(ctx, r, "collections.upsert", "", collectionInverse{Op: "collections.upsert", Doc: doc})
	}
	if h.m.deps.Backends.CollectionsUpsert == nil {
		return ErrUnavailable
	}
	prev, err := h.m.deps.Backends.CollectionsUpsert(collectionContext(ctx, h.plugin), doc)
	if err != nil {
		return err
	}
	return h.journal(ctx, r, "collections.upsert", "", collectionInverse{Op: "collections.upsert", Previous: prev, Doc: doc})
}

// UndoAll replays a plugin's live journal inverses, newest first, and
// returns how many entries were undone.
func (m *Manager) UndoAll(ctx context.Context, pluginID string) (int, error) {
	return m.UndoSince(ctx, pluginID, 0)
}

// UndoSince reverses the plugin's changes back to and including entry
// since (0 means all of them), newest first, so an older change is never
// reversed underneath a later one.
func (m *Manager) UndoSince(ctx context.Context, pluginID string, since int64) (int, error) {
	entries, err := m.store.journalList(ctx, pluginID, 10000, true)
	if err != nil {
		return 0, err
	}
	undone := 0
	for _, e := range entries { // journalList is newest first
		if e.ID < since {
			break
		}
		if err := m.applyInverse(ctx, e); err != nil {
			return undone, err
		}
		if err := m.store.markUndone(ctx, e.ID); err != nil {
			return undone, err
		}
		undone++
	}
	return undone, nil
}

func (m *Manager) applyInverse(ctx context.Context, e JournalEntry) error {
	switch e.Op {
	case "viewers.setWatchState":
		var inv watchInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		if m.deps.Backends.SetWatchState == nil {
			return ErrUnavailable
		}
		_, err := m.deps.Backends.SetWatchState(ctx, inv.ViewerID, inv.TitleID, inv.Watched)
		return err
	case "collections.upsert":
		var inv collectionInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		if len(inv.Previous) > 0 {
			if m.deps.Backends.CollectionsUpsert == nil {
				return ErrUnavailable
			}
			_, err := m.deps.Backends.CollectionsUpsert(collectionContext(ctx, e.Plugin), inv.Previous)
			return err
		}
		if m.deps.Backends.CollectionsDelete == nil {
			return ErrUnavailable
		}
		return m.deps.Backends.CollectionsDelete(collectionContext(ctx, e.Plugin), inv.Doc)
	case "kinds.upsert":
		var inv kindInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		b := m.kindBackends()
		if len(inv.Previous) > 0 {
			if b.KindUpsert == nil {
				return ErrUnavailable
			}
			if _, err := b.KindUpsert(ctx, e.Plugin, inv.Kind, inv.Previous); err != nil {
				return err
			}
		}
		if len(inv.Items) > 0 {
			if b.KindDelete == nil {
				return ErrUnavailable
			}
			if err := b.KindDelete(ctx, e.Plugin, inv.Kind, inv.Items); err != nil {
				return err
			}
		}
		return nil
	case "kinds.delete":
		var inv kindInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		b := m.kindBackends()
		if b.KindUpsert == nil {
			return ErrUnavailable
		}
		if len(inv.Previous) > 0 {
			_, err := b.KindUpsert(ctx, e.Plugin, inv.Kind, inv.Previous)
			return err
		}
		return nil
	default:
		return fmt.Errorf("plugins: no inverse for journal op %q", e.Op)
	}
}

func (h *host) folderCheck(ctx context.Context, root, path string) (string, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return "", err
	}
	if err := h.deny(r, g, "folders", normLevel(r.Manifest.Ether.Permissions.Folders),
		func(l string) bool { return l == "read" }); err != nil {
		return "", err
	}
	granted := false
	for _, f := range g.Folders {
		if f == root {
			granted = true
		}
	}
	if !granted {
		h.noteDenied("folders")
		return "", fmt.Errorf("%w: folder was not picked for this plugin", ErrPermissionDenied)
	}
	cleanRoot := filepath.Clean(root)
	joined := filepath.Clean(filepath.Join(cleanRoot, path))
	if joined != cleanRoot && !strings.HasPrefix(joined, cleanRoot+string(filepath.Separator)) {
		return "", fmt.Errorf("%w: path leaves the picked folder", ErrPermissionDenied)
	}
	return joined, nil
}

func (h *host) FoldersList(ctx context.Context, root, path string) ([]FolderEntry, error) {
	_, err := h.folderCheck(ctx, root, path)
	if err != nil {
		return nil, err
	}
	fs, err := os.OpenRoot(root)
	if err != nil {
		return nil, err
	}
	defer fs.Close()
	name := path
	if name == "" {
		name = "."
	}
	dir, err := fs.Open(name)
	if err != nil {
		return nil, err
	}
	defer dir.Close()
	entries, err := dir.ReadDir(1000)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, err
	}
	out := make([]FolderEntry, 0, len(entries))
	for _, e := range entries {
		fe := FolderEntry{Name: e.Name(), Path: filepath.Join(path, e.Name()), Dir: e.IsDir()}
		if e.Type()&os.ModeSymlink != 0 {
			// Follow a link only when its target stays inside the grant;
			// the rooted Stat fails for one that escapes.
			info, err := fs.Stat(filepath.Join(name, e.Name()))
			if err != nil {
				continue
			}
			fe.Dir, fe.Size, fe.Mtime = info.IsDir(), info.Size(), info.ModTime().Unix()
			out = append(out, fe)
			if len(out) >= 1000 {
				break
			}
			continue
		}
		if info, err := e.Info(); err == nil {
			fe.Size, fe.Mtime = info.Size(), info.ModTime().Unix()
		}
		out = append(out, fe)
		if len(out) >= 1000 {
			break
		}
	}
	return out, nil
}

func (h *host) FoldersStat(ctx context.Context, root, path string) (FolderEntry, error) {
	_, err := h.folderCheck(ctx, root, path)
	if err != nil {
		return FolderEntry{}, err
	}
	fs, err := os.OpenRoot(root)
	if err != nil {
		return FolderEntry{}, err
	}
	defer fs.Close()
	name := path
	if name == "" {
		name = "."
	}
	info, err := fs.Stat(name)
	if err != nil {
		return FolderEntry{}, err
	}
	return FolderEntry{Name: info.Name(), Path: path, Dir: info.IsDir(), Size: info.Size(), Mtime: info.ModTime().Unix()}, nil
}

func (m *Manager) rateOK(bucket map[string][]time.Time, key string, limit int, window time.Duration) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.now()
	kept := bucket[key][:0:0]
	for _, t := range bucket[key] {
		if now.Sub(t) < window {
			kept = append(kept, t)
		}
	}
	if len(kept) >= limit {
		bucket[key] = kept
		return false
	}
	bucket[key] = append(kept, now)
	return true
}

func (h *host) NotifyOwner(ctx context.Context, text string) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	if !h.m.rateOK(h.m.notifyTimes, h.plugin, 5, time.Hour) {
		return fmt.Errorf("plugins: owner notices are limited to five an hour")
	}
	text = h.m.store.redactKnown(ctx, h.plugin, text)
	if h.m.deps.Backends.Notice != nil {
		h.m.deps.Backends.Notice(truncate(text, 500))
	}
	h.m.store.addLog(ctx, h.plugin, "notice: "+text)
	return nil
}

func (h *host) Log(ctx context.Context, level, msg string, attrs map[string]any) error {
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	if !h.m.rateOK(h.m.logTimes, h.plugin, 600, time.Minute) {
		return nil // drop, never fail the caller for logging
	}
	line := level + ": " + msg
	if len(attrs) > 0 {
		if raw, err := json.Marshal(attrs); err == nil {
			line += " " + redactJSON(raw)
		}
	}
	h.m.store.addLog(ctx, h.plugin, line)
	return nil
}

// FoldersHash keeps small hashes synchronous; large files require an explicit job.
func (h *host) FoldersHash(ctx context.Context, root, path string) (FolderHash, error) {
	return h.hashFile(ctx, root, path, false, nil)
}

func (h *host) hashFile(ctx context.Context, root, path string, background bool, progress func(int64)) (FolderHash, error) {
	const capBytes = 256 << 20
	if _, err := h.folderCheck(ctx, root, path); err != nil {
		return FolderHash{}, err
	}
	for _, seg := range strings.FieldsFunc(path, func(r rune) bool { return r == '/' || r == '\\' }) {
		if seg == ".." {
			return FolderHash{}, ErrPermissionDenied
		}
	}
	realRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		return FolderHash{}, err
	}
	target, err := filepath.EvalSymlinks(filepath.Join(realRoot, path))
	if err != nil {
		return FolderHash{}, err
	}
	rel, err := filepath.Rel(realRoot, target)
	if err != nil || filepath.IsAbs(path) || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return FolderHash{}, ErrPermissionDenied
	}
	fs, err := os.OpenRoot(root)
	if err != nil {
		return FolderHash{}, err
	}
	defer fs.Close()
	f, err := fs.Open(path)
	if err != nil {
		return FolderHash{}, err
	}
	defer f.Close()
	info, err := f.Stat()
	if err != nil {
		return FolderHash{}, err
	}
	if !info.Mode().IsRegular() {
		return FolderHash{}, fmt.Errorf("folders.hash requires a regular file")
	}
	if !background && info.Size() > capBytes {
		return FolderHash{}, fmt.Errorf("folders.hash requires a regular file of at most 256 MiB")
	}
	key := fmt.Sprintf("host.hash.%x", sha256.Sum256([]byte(fmt.Sprintf("%s/%s:%d:%d", realRoot, rel, info.Size(), info.ModTime().UnixNano()))))
	if raw, ok, err := h.m.store.hashCacheGet(ctx, h.plugin, key); err != nil {
		return FolderHash{}, err
	} else if ok {
		var cached FolderHash
		if json.Unmarshal(raw, &cached) == nil {
			if _, err := h.folderCheck(ctx, root, path); err != nil {
				return FolderHash{}, err
			}
			return cached, nil
		}
	}
	crc, md, sha := crc32.NewIEEE(), md5.New(), sha1.New()
	w := io.MultiWriter(crc, md, sha)
	buf := make([]byte, 1<<20)
	var total int64
	for {
		if err := ctx.Err(); err != nil {
			return FolderHash{}, err
		}
		if _, err := h.folderCheck(ctx, root, path); err != nil {
			return FolderHash{}, err
		}
		n, err := f.Read(buf)
		total += int64(n)
		if !background && total > capBytes {
			return FolderHash{}, fmt.Errorf("folders.hash size limit exceeded")
		}
		if n > 0 {
			_, _ = w.Write(buf[:n])
			if progress != nil {
				progress(total)
			}
			if background {
				timer := time.NewTimer(2 * time.Millisecond)
				select {
				case <-ctx.Done():
					timer.Stop()
					return FolderHash{}, ctx.Err()
				case <-timer.C:
				}
			}
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return FolderHash{}, err
		}
	}
	after, err := f.Stat()
	if err != nil {
		return FolderHash{}, err
	}
	if total != info.Size() || after.Size() != info.Size() || !after.ModTime().Equal(info.ModTime()) {
		return FolderHash{}, fmt.Errorf("folders.hash file changed while hashing")
	}
	result := FolderHash{Size: total, ModTime: info.ModTime().Unix(), CRC32: fmt.Sprintf("%08x", crc.Sum32()), MD5: fmt.Sprintf("%x", md.Sum(nil)), SHA1: fmt.Sprintf("%x", sha.Sum(nil))}
	raw, _ := json.Marshal(result)
	if err := h.m.store.hashCachePut(ctx, h.plugin, key, raw); err != nil {
		return FolderHash{}, err
	}
	return result, nil
}

// KindBackends are the Ether services the kind host calls end in: the
// plugin-item store, the source resolver and the blob cache. Any field
// may be nil, in which case the matching host call returns
// ErrUnavailable. App wiring fills them (pluginitems, the indexer and
// debrid services, blobcache); the plugin id is always the caller's,
// so a plugin can only ever reach its own kinds and cache.
type KindBackends struct {
	KindUpsert     func(ctx context.Context, pluginID, kindKey string, items []core.KindItem) (accepted int, err error)
	KindDelete     func(ctx context.Context, pluginID, kindKey string, externalIDs []string) error
	KindItems      func(ctx context.Context, pluginID, kindKey, cursor string, limit int) (core.KindPage, error)
	ResolveSources func(ctx context.Context, pluginID string, q core.SourceQuery) ([]core.SourceCandidate, error)
	CachePut       func(ctx context.Context, pluginID, libraryKey, name string, r io.Reader) (blobRef string, err error)
	CacheOpen      func(ctx context.Context, pluginID, blobRef string) (io.ReadSeekCloser, error)
	// StreamURL mints a scoped stream ticket for one of the plugin's own
	// kind items for one viewer and returns the Ether stream URL (spec
	// §6.5). The backend re-checks item ownership and library visibility.
	StreamURL func(ctx context.Context, pluginID string, viewerID int64, itemRef string) (string, error)
}

// SetKindBackends wires the kind host services into the Manager's
// Backends. Called once at startup by app wiring or in tests.
func (m *Manager) SetKindBackends(b KindBackends) {
	m.mu.Lock()
	m.deps.Backends.KindUpsert = b.KindUpsert
	m.deps.Backends.KindDelete = b.KindDelete
	m.deps.Backends.KindItems = b.KindItems
	m.deps.Backends.ResolveSources = b.ResolveSources
	m.deps.Backends.CachePut = b.CachePut
	m.deps.Backends.CacheOpen = b.CacheOpen
	m.deps.Backends.StreamURL = b.StreamURL
	m.mu.Unlock()
}

func (m *Manager) kindBackends() KindBackends {
	m.mu.Lock()
	defer m.mu.Unlock()
	return KindBackends{
		KindUpsert:     m.deps.Backends.KindUpsert,
		KindDelete:     m.deps.Backends.KindDelete,
		KindItems:      m.deps.Backends.KindItems,
		ResolveSources: m.deps.Backends.ResolveSources,
		CachePut:       m.deps.Backends.CachePut,
		CacheOpen:      m.deps.Backends.CacheOpen,
		StreamURL:      m.deps.Backends.StreamURL,
	}
}

// Per-call caps for kind host services (spec §3.3 sizes, host side).
const (
	MaxKindUpsertItems = 1000
	MaxKindHintsBytes  = 16 << 10
	MaxKindArtRoles    = 16
)

// ValidExternalID reports whether id is a legal plugin external id
// (spec §2.2: no ':' or '/').
func ValidExternalID(id string) bool { return externalIDRe.MatchString(id) }

// CheckKindItem validates one item envelope against its kind
// declaration: identity, level, the string caps and the hints shape.
// Field-value typing against KindField is the item store's deeper
// check (spec §3.3); this one is shared by the host and the kit so a
// plugin is told the same thing everywhere. It returns a plain
// reason, or "" when the item passes.
func CheckKindItem(decl MediaKindMeta, it core.KindItem) string {
	switch {
	case !ValidExternalID(it.ID):
		return "id must start with a letter or digit and use letters, digits, dot, dash, underscore or tilde, at most 128 characters"
	case it.ParentID != "" && !ValidExternalID(it.ParentID):
		return "parentId must be a valid external id"
	case strings.TrimSpace(it.Title) == "":
		return "title is required"
	case utf8.RuneCountInString(it.Title) > 500:
		return "title is longer than 500 characters"
	case utf8.RuneCountInString(it.Summary) > 20000:
		return "summary is longer than 20000 characters"
	case len(it.Art) > MaxKindArtRoles:
		return "art lists more than 16 roles"
	case len(it.Hints) > MaxKindHintsBytes:
		return "hints are larger than 16 KiB"
	}
	lv, at, ok := decl.Level(it.Level)
	if !ok {
		return "level " + it.Level + " is not declared for this kind"
	}
	if at == 0 && it.ParentID != "" {
		return "a root-level item cannot name a parent"
	}
	if at > 0 && it.ParentID == "" {
		return "a " + it.Level + " item needs a parentId"
	}
	if it.Playable && !lv.Playable {
		return "level " + it.Level + " is not declared playable"
	}
	if len(it.Hints) > 0 {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal(it.Hints, &obj); err != nil || obj == nil {
			return "hints must be a JSON object"
		}
	}
	seenArt := map[string]bool{}
	for _, a := range it.Art {
		if a.Role == "" || a.URL == "" || seenArt[a.Role] {
			return "each art entry needs a distinct role and a url"
		}
		seenArt[a.Role] = true
	}
	for key := range it.Fields {
		if !kindFieldRe.MatchString(key) {
			return "field names must match the declared field pattern"
		}
	}
	return ""
}

// kindCheck resolves the caller's record and one declared kind,
// requiring one of caps. Roles the owner switched off are absent from
// the effective manifest, so they deny like a missing capability.
func (h *host) kindCheck(ctx context.Context, kindKey string, caps ...Capability) (Record, MediaKindMeta, error) {
	r, _, err := h.record(ctx)
	if err != nil {
		return Record{}, MediaKindMeta{}, err
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	allowed := false
	for _, c := range caps {
		if man.HasCapability(c) {
			allowed = true
		}
	}
	if !allowed {
		h.noteDenied(string(caps[0]))
		return Record{}, MediaKindMeta{}, fmt.Errorf("%w: %s", ErrPermissionDenied, caps[0])
	}
	decl, ok := man.MediaKindByKey(kindKey)
	if !ok {
		return Record{}, MediaKindMeta{}, fmt.Errorf("%w: kind %q is not declared", ErrUnavailable, kindKey)
	}
	return r, decl, nil
}

type kindInverse struct {
	Op       string          `json:"op"`
	Kind     string          `json:"kind"`
	Items    []string        `json:"items,omitempty"`    // external ids touched (or created on upsert)
	Previous []core.KindItem `json:"previous,omitempty"` // previous items before upsert or delete
}

// snapshotKindItems looks up any existing items for kindKey whose IDs
// are in ids so a live KindUpsert or KindDelete can record a real
// inverse in the journal.
func (h *host) snapshotKindItems(ctx context.Context, kindKey string, ids []string) (existing []core.KindItem, missing []string) {
	readFn := h.m.kindBackends().KindItems
	if readFn == nil || len(ids) == 0 {
		return nil, append([]string(nil), ids...)
	}
	want := make(map[string]bool, len(ids))
	for _, id := range ids {
		want[id] = true
	}
	found := make(map[string]core.KindItem, len(ids))
	cursor := ""
	seenCursor := map[string]bool{}
	for pageNum := 0; pageNum < 50 && len(found) < len(want); pageNum++ {
		seenCursor[cursor] = true
		page, err := readFn(ctx, h.plugin, kindKey, cursor, MaxKindUpsertItems)
		if err != nil {
			break
		}
		for _, it := range page.Items {
			if want[it.ID] {
				if _, dup := found[it.ID]; !dup {
					found[it.ID] = it
				}
			}
		}
		if page.NextCursor == "" || seenCursor[page.NextCursor] {
			break
		}
		cursor = page.NextCursor
	}
	seenID := map[string]bool{}
	for _, id := range ids {
		if seenID[id] {
			continue
		}
		seenID[id] = true
		if prev, ok := found[id]; ok {
			existing = append(existing, prev)
		} else {
			missing = append(missing, id)
		}
	}
	return existing, missing
}

func (h *host) KindUpsert(ctx context.Context, kindKey string, items []core.KindItem) (int, error) {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return 0, err
	}
	r, decl, err := h.kindCheck(ctx, kindKey, CapCatalogProvider)
	if err != nil {
		return 0, err
	}
	if decl.Sync.Mode != KindSyncPush {
		return 0, fmt.Errorf("%w: kind %s is pull-synced by Ether and takes no pushes", ErrPermissionDenied, kindKey)
	}
	if len(items) > MaxKindUpsertItems {
		return 0, fmt.Errorf("plugins: kind upsert batch larger than %d items", MaxKindUpsertItems)
	}
	ids := make([]string, 0, len(items))
	for _, it := range items {
		if msg := CheckKindItem(decl, it); msg != "" {
			return 0, fmt.Errorf("plugins: kind item %q: %s", it.ID, msg)
		}
		ids = append(ids, it.ID)
	}
	if r.Shadow {
		return len(items), h.journal(ctx, r, "kinds.upsert", kindKey, kindInverse{Op: "kinds.upsert", Kind: kindKey, Items: ids})
	}
	backend := h.m.kindBackends().KindUpsert
	if backend == nil {
		return 0, ErrUnavailable
	}
	prev, created := h.snapshotKindItems(ctx, kindKey, ids)
	accepted, err := backend(ctx, h.plugin, kindKey, items)
	if err != nil {
		return 0, err
	}
	if err := h.journal(ctx, r, "kinds.upsert", kindKey, kindInverse{
		Op:       "kinds.upsert",
		Kind:     kindKey,
		Items:    created,
		Previous: prev,
	}); err != nil {
		return 0, err
	}
	return accepted, nil
}

func (h *host) KindDelete(ctx context.Context, kindKey string, externalIDs []string) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, decl, err := h.kindCheck(ctx, kindKey, CapCatalogProvider)
	if err != nil {
		return err
	}
	if decl.Sync.Mode != KindSyncPush {
		return fmt.Errorf("%w: kind %s is pull-synced by Ether and takes no pushes", ErrPermissionDenied, kindKey)
	}
	if len(externalIDs) > MaxKindUpsertItems {
		return fmt.Errorf("plugins: kind delete batch larger than %d items", MaxKindUpsertItems)
	}
	for _, id := range externalIDs {
		if !ValidExternalID(id) {
			return fmt.Errorf("plugins: kind item id %q is not a valid external id", id)
		}
	}
	if r.Shadow {
		return h.journal(ctx, r, "kinds.delete", kindKey, kindInverse{Op: "kinds.delete", Kind: kindKey, Items: externalIDs})
	}
	backend := h.m.kindBackends().KindDelete
	if backend == nil {
		return ErrUnavailable
	}
	prev, _ := h.snapshotKindItems(ctx, kindKey, externalIDs)
	if err := backend(ctx, h.plugin, kindKey, externalIDs); err != nil {
		return err
	}
	return h.journal(ctx, r, "kinds.delete", kindKey, kindInverse{
		Op:       "kinds.delete",
		Kind:     kindKey,
		Items:    externalIDs,
		Previous: prev,
	})
}

func (h *host) KindItems(ctx context.Context, kindKey, cursor string, limit int) (core.KindPage, error) {
	if _, _, err := h.kindCheck(ctx, kindKey, CapCatalogProvider); err != nil {
		return core.KindPage{}, err
	}
	backend := h.m.kindBackends().KindItems
	if backend == nil {
		return core.KindPage{}, ErrUnavailable
	}
	if limit <= 0 {
		limit = 200
	}
	if limit > MaxKindUpsertItems {
		limit = MaxKindUpsertItems
	}
	return backend(ctx, h.plugin, kindKey, cursor, limit)
}

func (h *host) ResolveSources(ctx context.Context, q core.SourceQuery) ([]core.SourceCandidate, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return nil, err
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	if !man.HasCapability(CapKindResolver) {
		h.noteDenied(string(CapKindResolver))
		return nil, fmt.Errorf("%w: %s", ErrPermissionDenied, CapKindResolver)
	}
	need := "search"
	switch q.Kind {
	case "indexer_search":
		if strings.TrimSpace(q.Query) == "" {
			return nil, fmt.Errorf("plugins: indexer_search needs a query")
		}
	case "debrid_check":
		if len(q.InfoHashes) == 0 && q.InfoHash == "" {
			return nil, fmt.Errorf("plugins: debrid_check needs an info hash")
		}
	case "debrid_acquire":
		need = "acquire"
		if q.InfoHash == "" && q.Magnet == "" {
			return nil, fmt.Errorf("plugins: debrid_acquire needs an info hash or magnet")
		}
	default:
		return nil, fmt.Errorf("plugins: unknown source query kind %q", q.Kind)
	}
	level := normLevel(r.Manifest.Ether.Permissions.Sources)
	if err := h.deny(r, g, "sources", level, func(l string) bool {
		return l == "acquire" || (l == "search" && need == "search")
	}); err != nil {
		return nil, err
	}
	backend := h.m.kindBackends().ResolveSources
	if backend == nil {
		return nil, ErrUnavailable
	}
	return backend(ctx, h.plugin, q)
}

func (h *host) CachePut(ctx context.Context, libraryKey, name string, r io.Reader) (string, error) {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return "", err
	}
	rec, _, err := h.record(ctx)
	if err != nil {
		return "", err
	}
	man := rec.Manifest
	man.Ether = man.EffectiveEther()
	// The library key must name one of this plugin's own kinds; the
	// blob cache namespace follows from it, so a plugin can never
	// write into another library's cache.
	var decl MediaKindMeta
	found := false
	if man.Ether != nil {
		for _, k := range man.Ether.Contributes.MediaKinds {
			if core.PluginLibraryKey(h.plugin, k.Key) == libraryKey {
				decl, found = k, true
			}
		}
	}
	if !found || !(man.HasCapability(CapCatalogProvider) || man.HasCapability(CapKindResolver)) {
		h.noteDenied("cache")
		return "", fmt.Errorf("%w: cache", ErrPermissionDenied)
	}
	if strings.TrimSpace(name) == "" {
		return "", fmt.Errorf("plugins: cache put needs a name")
	}
	backend := h.m.kindBackends().CachePut
	if backend == nil {
		return "", ErrUnavailable
	}
	// A single blob can never exceed the whole per-library quota.
	limited := io.LimitReader(r, decl.Cache.EffectiveMaxBytes()+1)
	return backend(ctx, h.plugin, libraryKey, name, limited)
}

// viewerContextKey carries the authenticated viewer of a proxied request
// into a plugin call, so a host service can act as that viewer without the
// plugin passing (or being trusted with) the identity.
type viewerContextKey struct{}

// WithViewer attaches a viewer id to a plugin call context.
func WithViewer(ctx context.Context, viewerID int64) context.Context {
	return context.WithValue(ctx, viewerContextKey{}, viewerID)
}

// ViewerFromContext returns the viewer attached by WithViewer, if any.
func ViewerFromContext(ctx context.Context) (int64, bool) {
	id, ok := ctx.Value(viewerContextKey{}).(int64)
	return id, ok
}

// withViewerHeader reads the X-Ether-Viewer header the frontend adapter
// proxy injects and attaches that viewer to the context. A missing or
// malformed header leaves the context unchanged.
func withViewerHeader(ctx context.Context, headers map[string]string) context.Context {
	if headers == nil {
		return ctx
	}
	raw := headers["X-Ether-Viewer"]
	if raw == "" {
		return ctx
	}
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || id <= 0 {
		return ctx
	}
	return WithViewer(ctx, id)
}

// StreamURL mints a scoped stream ticket for one of the plugin's own kind
// items and returns the Ether stream URL (spec §6.5). The viewer is the one
// the proxied request authenticated, carried on the call context as
// X-Ether-Viewer. The backend re-checks that the item belongs to this plugin
// and that the viewer may see its library.
func (h *host) StreamURL(ctx context.Context, itemRef string) (string, error) {
	rec, _, err := h.record(ctx)
	if err != nil {
		return "", err
	}
	man := rec.Manifest
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || !man.HasCapability(CapFrontendAdapter) {
		h.noteDenied(string(CapFrontendAdapter))
		return "", fmt.Errorf("%w: %s", ErrPermissionDenied, CapFrontendAdapter)
	}
	viewerID, ok := ViewerFromContext(ctx)
	if !ok || viewerID <= 0 {
		return "", fmt.Errorf("%w: stream url needs an authenticated viewer", ErrPermissionDenied)
	}
	if strings.TrimSpace(itemRef) == "" {
		return "", fmt.Errorf("plugins: stream url needs an item ref")
	}
	backend := h.m.kindBackends().StreamURL
	if backend == nil {
		return "", ErrUnavailable
	}
	return backend(ctx, h.plugin, viewerID, itemRef)
}

func (h *host) CacheOpen(ctx context.Context, blobRef string) (io.ReadSeekCloser, error) {
	if _, _, err := h.record(ctx); err != nil {
		return nil, err
	}
	hexPart, ok := strings.CutPrefix(blobRef, "blob:")
	if !ok || len(hexPart) != 64 {
		return nil, fmt.Errorf("plugins: cache reference must be blob:<sha256>")
	}
	if _, err := hex.DecodeString(hexPart); err != nil {
		return nil, fmt.Errorf("plugins: cache reference must be blob:<sha256>")
	}
	backend := h.m.kindBackends().CacheOpen
	if backend == nil {
		return nil, ErrUnavailable
	}
	return backend(ctx, h.plugin, blobRef)
}

// HotRuntime is implemented by hosted runtimes whose plugin exports the
// hot-path ABI (SPEC §5.2): ranking steps and rule conditions. The ranking
// adapters reach it through Manager.Hot. Budgets are the manifest's
// (lowered, never raised) and every call reports a classified outcome.
type HotRuntime interface {
	Runtime
	// RankBatch returns one key per candidate (higher ranks first). A
	// candidate that exceeded its budget gets the neutral key 0 and counts
	// in HotOutcome.Slow; a batch that ran out of time returns neutral keys
	// for the rest.
	RankBatch(ctx context.Context, cands []CandidateFacts, config json.RawMessage) (keys []int64, out HotOutcome, err error)
	// CondMatch evaluates a rule condition; false when the budget runs out.
	CondMatch(ctx context.Context, cand CandidateFacts, operator string, value json.RawMessage) (match bool, out HotOutcome, err error)
	HasRankKey() bool
	HasCondMatch() bool
	// Budgets reports the effective per-candidate and per-batch limits.
	Budgets() HotBudgets
}

// HotOutcome classifies one hot-path call for health and replay.
type HotOutcome struct {
	// Status is ok, error, timeout, forbidden, aborted or governance.
	Status   string        `json:"status"`
	Duration time.Duration `json:"durationNs"`
	Units    int64         `json:"units"`
	// Slow counts candidates that went neutral on budget.
	Slow     int  `json:"slow"`
	MemoHits int  `json:"memoHits"`
	Trap     bool `json:"trap,omitempty"`
}

// Timeout reports whether the call ran out of time or budget.
func (o HotOutcome) Timeout() bool {
	return o.Status == string(wasm.StatusTimeout) || o.Status == string(wasm.StatusGovernance)
}

// HotBudgets are the effective hot-path limits for one plugin.
type HotBudgets struct {
	PerCandidate time.Duration `json:"perCandidateNs"`
	PerBatch     time.Duration `json:"perBatchNs"`
}

// rankingBudget is the manifest's per-step budget (SPEC §4.3: budget).
type rankingBudget struct {
	PerCandidateMicros int64 `json:"perCandidateMicros"`
	PerBatchMicros     int64 `json:"perBatchMicros"`
	PerBatchMillis     int64 `json:"perBatchMillis"`
}

// HotLimits lowers the runtime's hot-path defaults to the tightest budget a
// manifest declares across its ranking steps. The engine clamps anything
// above its defaults, so a manifest can lower budgets but never raise them.
// Studio replay uses it to run a plugin under its installed budgets.
func HotLimits(m Manifest) wasm.Limits {
	var lim wasm.Limits
	if m.Ether == nil {
		return lim
	}
	for _, step := range m.Ether.Contributes.RankingSteps {
		if len(step.Budget) == 0 {
			continue
		}
		var b rankingBudget
		if json.Unmarshal(step.Budget, &b) != nil {
			continue
		}
		if b.PerCandidateMicros > 0 {
			d := time.Duration(b.PerCandidateMicros) * time.Microsecond
			if lim.RankPerCandidate == 0 || d < lim.RankPerCandidate {
				lim.RankPerCandidate = d
			}
		}
		batch := time.Duration(b.PerBatchMicros) * time.Microsecond
		if b.PerBatchMillis > 0 {
			batch = time.Duration(b.PerBatchMillis) * time.Millisecond
		}
		if batch > 0 && (lim.RankBatch == 0 || batch < lim.RankBatch) {
			lim.RankBatch = batch
		}
	}
	return lim
}

func hotOutcome(o wasm.Outcome) HotOutcome {
	return HotOutcome{Status: string(o.Status), Duration: o.Duration, Units: o.Units, Slow: o.SlowCandidates, MemoHits: o.MemoHits, Trap: o.Trap}
}

// HostedRuntimeFactory opens hosted plugins (runtime.kind "hosted") on the
// wazero engine: JavaScript and TypeScript entries run on QuickJS, raw
// modules through the documented WASM ABI.
func HostedRuntimeFactory(eng *wasm.Engine) RuntimeFactory {
	return func(inst Installed) (Runtime, error) {
		if inst.Manifest.Ether == nil {
			return nil, fmt.Errorf("plugin %s: hosted plugins need an ether block", inst.ID)
		}
		decl := inst.Manifest.Ether.Runtime
		host := hostBridge{h: inst.Host}
		lim := HotLimits(inst.Manifest)
		switch {
		case decl.Module != "":
			module, ok := inst.Files(decl.Module)
			if !ok {
				return nil, fmt.Errorf("plugin %s: module %q is missing", inst.ID, decl.Module)
			}
			p, err := eng.LoadWASM(inst.ID, inst.Manifest.Version, module, host, lim)
			if err != nil {
				return nil, err
			}
			return &hostedRuntime{p: p}, nil
		case decl.Entry != "":
			src, ok := inst.Files(decl.Entry)
			if !ok {
				return nil, fmt.Errorf("plugin %s: entry %q is missing", inst.ID, decl.Entry)
			}
			js := string(src)
			if ext := strings.ToLower(path.Ext(decl.Entry)); ext == ".ts" || ext == ".tsx" || ext == ".mts" {
				out, _, diags := wasm.Compile(map[string]string{decl.Entry: js}, decl.Entry)
				if err := diagnosticsError(diags); err != nil {
					return nil, fmt.Errorf("plugin %s: %w", inst.ID, err)
				}
				js = string(out)
			}
			p, err := eng.LoadJS(inst.ID, inst.Manifest.Version, js, host, lim)
			if err != nil {
				return nil, err
			}
			return &hostedRuntime{p: p}, nil
		default:
			return nil, fmt.Errorf("plugin %s: hosted runtime needs an entry or a module", inst.ID)
		}
	}
}

func diagnosticsError(diags []wasm.Diagnostic) error {
	var msgs []string
	for _, d := range diags {
		if d.Severity == "error" {
			msgs = append(msgs, d.Text)
		}
	}
	if len(msgs) == 0 {
		return nil
	}
	return errors.New("compile: " + strings.Join(msgs, "; "))
}

type hostedRuntime struct {
	p *wasm.Plugin
}

// EffectiveBudgets mirrors the engine's clamping: the budgets a manifest
// gets as SPEC 5.2 states them, in reference-machine time. The engine
// scales them by its measured speed (wasm.HotScale); Budgets reports that.
func EffectiveBudgets(lim wasm.Limits) HotBudgets {
	per, batch := lim.RankPerCandidate, lim.RankBatch
	if per <= 0 || per > wasm.DefaultRankPerCandidate {
		per = wasm.DefaultRankPerCandidate
	}
	if batch <= 0 || batch > wasm.DefaultRankBatch {
		batch = wasm.DefaultRankBatch
	}
	return HotBudgets{PerCandidate: per, PerBatch: batch}
}

// Budgets reports the limits in force on this machine: the manifest's,
// scaled by the engine's measured speed.
func (r *hostedRuntime) Budgets() HotBudgets {
	per, batch := r.p.Budgets()
	return HotBudgets{PerCandidate: per, PerBatch: batch}
}

func (r *hostedRuntime) Call(ctx context.Context, req Request) (Response, error) {
	q := make(map[string][]string, len(req.Query))
	for k, v := range req.Query {
		q[k] = []string{v}
	}
	headers := req.Headers
	if req.Locale != "" {
		headers = cloneHeaders(headers)
		headers["X-Ether-Locale"] = req.Locale
	}
	resp, err := r.p.Call(ctx, wasm.Request{Op: req.Op, ID: req.ID, Method: req.Method, Path: req.Path, Query: q, Headers: headers, Body: req.Body})
	if err != nil {
		return Response{}, err
	}
	return Response{Status: resp.Status, Headers: resp.Headers, Body: resp.Body}, nil
}

func (r *hostedRuntime) RankBatch(ctx context.Context, cands []CandidateFacts, config json.RawMessage) ([]int64, HotOutcome, error) {
	in := make([]wasm.Candidate, len(cands))
	for i, c := range cands {
		facts, err := json.Marshal(c)
		if err != nil {
			return nil, HotOutcome{Status: string(wasm.StatusError)}, err
		}
		in[i] = wasm.Candidate{ReleaseID: c.ReleaseID, Facts: facts}
	}
	keys, out, err := r.p.RankBatch(ctx, in, config)
	return keys, hotOutcome(out), err
}

func (r *hostedRuntime) CondMatch(ctx context.Context, cand CandidateFacts, operator string, value json.RawMessage) (bool, HotOutcome, error) {
	facts, err := json.Marshal(cand)
	if err != nil {
		return false, HotOutcome{Status: string(wasm.StatusError)}, err
	}
	ok, out, err := r.p.CondMatch(ctx, wasm.Candidate{ReleaseID: cand.ReleaseID, Facts: facts}, operator, value)
	return ok, hotOutcome(out), err
}

func cloneHeaders(h map[string]string) map[string]string {
	out := make(map[string]string, len(h)+1)
	for k, v := range h {
		out[k] = v
	}
	return out
}

// Hot returns the hosted runtime of an enabled plugin when it exports the
// hot-path ABI, loading it if needed. It may block on a load, so it is for
// background work (replay, Studio); the play path uses HotReady.
func (m *Manager) Hot(ctx context.Context, pluginID string) (HotRuntime, bool) {
	r, err := m.Get(ctx, pluginID)
	if err != nil || !r.Enabled {
		return nil, false
	}
	rt, err := m.runtimeFor(ctx, r)
	if err != nil {
		return nil, false
	}
	hot, ok := rt.(HotRuntime)
	return hot, ok
}

// HotReady is the play-path accessor. It never blocks: it returns the
// plugin's hosted runtime only when it is already loaded, and otherwise
// starts loading it in the background and reports false, so the caller
// treats the plugin's steps and conditions as neutral for this resolve.
// Plugins in shadow mode are never ready on the play path. Runtimes are dropped on update, disable, remove and failure (closeRuntime)
// and warmed again when descriptors sync.
func (m *Manager) HotReady(pluginID string) (HotRuntime, bool) {
	m.mu.Lock()
	rt, ok := m.runtimes[pluginID]
	shadow := m.shadow[pluginID]
	m.mu.Unlock()
	if shadow {
		// A plugin in shadow mode never changes real picks; replay and the
		// shadow report show what it would have done.
		return nil, false
	}
	if !ok {
		m.warmAsync(pluginID)
		return nil, false
	}
	hot, ok := rt.(HotRuntime)
	return hot, ok
}

// prewarmHot loads, in the background, the runtime of an enabled plugin
// that contributes ranking steps or rule conditions, so the first resolve
// after start, install, update or enable finds it ready.
func (m *Manager) prewarmHot(r Record) {
	if !r.Enabled || r.Manifest.Ether == nil {
		return
	}
	c := r.Manifest.Ether.Contributes
	if len(c.RankingSteps) == 0 && len(c.RuleConditions) == 0 {
		return
	}
	m.warmAsync(r.ID)
}

// warmAsync loads one plugin's runtime once in the background.
func (m *Manager) warmAsync(pluginID string) {
	m.mu.Lock()
	if m.warming[pluginID] {
		m.mu.Unlock()
		return
	}
	m.warming[pluginID] = true
	m.mu.Unlock()
	go func() {
		defer func() {
			m.mu.Lock()
			delete(m.warming, pluginID)
			m.mu.Unlock()
		}()
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		r, err := m.Get(ctx, pluginID)
		if err != nil || !r.Enabled {
			return
		}
		if _, err := m.runtimeFor(ctx, r); err != nil {
			m.log.Warn("plugins: warm hot runtime", "plugin", pluginID, "err", err)
		}
	}()
}

// hostBridge maps the hosted runtime's dotted host calls (positional JSON
// argument arrays) onto the Host interface. Grant checks, journalling and
// shadow mode all live behind Host.
type hostBridge struct{ h Host }

func (b hostBridge) CallHost(ctx context.Context, name string, raw json.RawMessage) (json.RawMessage, error) {
	if b.h == nil {
		return nil, wasm.Forbidden("no host services are configured for this plugin")
	}
	var args []json.RawMessage
	if len(raw) > 0 && string(raw) != "null" {
		if err := json.Unmarshal(raw, &args); err != nil {
			return nil, &wasm.Fault{Code: "bad_arguments", Message: "host arguments must be an array"}
		}
	}
	str := func(i int) string {
		var s string
		if i < len(args) {
			_ = json.Unmarshal(args[i], &s)
		}
		return s
	}
	num := func(i int) int64 {
		var n float64
		if i < len(args) {
			_ = json.Unmarshal(args[i], &n)
		}
		return int64(n)
	}
	result := func(v any, err error) (json.RawMessage, error) {
		if err != nil {
			return nil, mapHostError(err)
		}
		if v == nil {
			return json.RawMessage("null"), nil
		}
		if r, ok := v.(json.RawMessage); ok {
			return r, nil
		}
		out, err := json.Marshal(v)
		return out, err
	}
	switch name {
	case "kv.get":
		v, ok, err := b.h.KVGet(ctx, str(0))
		if err != nil || !ok {
			return result(nil, err)
		}
		return result(string(v), nil)
	case "kv.put":
		var value string
		if len(args) > 1 {
			if err := json.Unmarshal(args[1], &value); err != nil {
				value = string(args[1]) // non-string values are stored as JSON text
			}
		}
		return result(nil, b.h.KVPut(ctx, str(0), []byte(value)))
	case "kv.delete":
		return result(nil, b.h.KVDelete(ctx, str(0)))
	case "kv.list":
		keys, err := b.h.KVList(ctx, str(0))
		return result(keys, err)
	case "settings.get":
		v, err := b.h.Settings(ctx)
		return result(v, err)
	case "secret.get":
		v, err := b.h.SecretGet(ctx, str(0))
		return result(v, err)
	case "http.fetch":
		var req struct {
			Method  string            `json:"method"`
			URL     string            `json:"url"`
			Headers map[string]string `json:"headers"`
			Body    string            `json:"body"`
			// BodyBase64 carries a binary request body; it wins over Body.
			BodyBase64 string `json:"bodyBase64"`
		}
		if len(args) > 0 {
			if err := json.Unmarshal(args[0], &req); err != nil {
				return nil, &wasm.Fault{Code: "bad_arguments", Message: "http.fetch takes {method, url, headers, body}"}
			}
		}
		if req.Method == "" {
			req.Method = "GET"
		}
		body := []byte(req.Body)
		if req.BodyBase64 != "" {
			decoded, err := base64.StdEncoding.DecodeString(req.BodyBase64)
			if err != nil {
				return nil, &wasm.Fault{Code: "bad_arguments", Message: "bodyBase64 is not valid base64"}
			}
			body = decoded
		}
		resp, err := b.h.HTTPFetch(ctx, FetchRequest{Method: req.Method, URL: req.URL, Headers: req.Headers, Body: body})
		if err != nil {
			return nil, mapHostError(err)
		}
		return result(FetchResult(resp), nil)
	case "catalog.search":
		v, err := b.h.CatalogSearch(ctx, str(0), int(num(1)), int(num(2)))
		return result(v, err)
	case "catalog.get":
		v, err := b.h.CatalogGet(ctx, str(0))
		return result(v, err)
	case "addon.get":
		ah, ok := b.h.(interface {
			AddonGet(ctx context.Context, route string) (json.RawMessage, error)
		})
		if !ok {
			return nil, &wasm.Fault{Code: "unavailable", Message: "this plugin is not bound to an add-on"}
		}
		v, err := ah.AddonGet(ctx, str(0))
		return result(v, err)
	case "viewers.granted":
		v, err := b.h.ViewerGranted(ctx)
		return result(v, err)
	case "viewers.history":
		v, err := b.h.ViewerHistory(ctx, num(0), int(num(1)), int(num(2)))
		return result(v, err)
	case "viewers.setWatchState":
		var watched bool
		if len(args) > 2 {
			_ = json.Unmarshal(args[2], &watched)
		}
		return result(nil, b.h.SetWatchState(ctx, num(0), str(1), watched))
	case "collections.upsert":
		var col json.RawMessage
		if len(args) > 0 {
			col = args[0]
		}
		return result(nil, b.h.CollectionsUpsert(ctx, col))
	case "kinds.upsert":
		var items []core.KindItem
		if len(args) > 1 {
			if err := json.Unmarshal(args[1], &items); err != nil {
				return nil, &wasm.Fault{Code: "bad_arguments", Message: "kinds.upsert takes (kind, items[])"}
			}
		}
		accepted, err := b.h.KindUpsert(ctx, str(0), items)
		if err != nil {
			return nil, mapHostError(err)
		}
		return result(map[string]any{"accepted": accepted}, nil)
	case "kinds.delete":
		var ids []string
		if len(args) > 1 {
			if err := json.Unmarshal(args[1], &ids); err != nil {
				return nil, &wasm.Fault{Code: "bad_arguments", Message: "kinds.delete takes (kind, ids[])"}
			}
		}
		return result(nil, b.h.KindDelete(ctx, str(0), ids))
	case "kinds.items":
		page, err := b.h.KindItems(ctx, str(0), str(1), int(num(2)))
		return result(page, err)
	case "frontend.streamURL":
		u, err := b.h.StreamURL(ctx, str(0))
		if err != nil {
			return nil, mapHostError(err)
		}
		return result(map[string]any{"url": u}, nil)
	case "sources.resolve":
		var q core.SourceQuery
		if len(args) > 0 {
			if err := json.Unmarshal(args[0], &q); err != nil {
				return nil, &wasm.Fault{Code: "bad_arguments", Message: "sources.resolve takes a query object"}
			}
		}
		cands, err := b.h.ResolveSources(ctx, q)
		if err != nil {
			return nil, mapHostError(err)
		}
		if cands == nil {
			cands = []core.SourceCandidate{}
		}
		return result(map[string]any{"candidates": cands}, nil)
	case "cache.put":
		var body []byte
		if len(args) > 2 {
			var s string
			if err := json.Unmarshal(args[2], &s); err == nil {
				body = []byte(s)
			} else {
				var wrapped struct {
					Body       string `json:"body"`
					BodyBase64 string `json:"bodyBase64"`
				}
				if err := json.Unmarshal(args[2], &wrapped); err != nil {
					return nil, &wasm.Fault{Code: "bad_arguments", Message: "cache.put takes (libraryKey, name, data)"}
				}
				body = []byte(wrapped.Body)
				if wrapped.BodyBase64 != "" {
					decoded, err := base64.StdEncoding.DecodeString(wrapped.BodyBase64)
					if err != nil {
						return nil, &wasm.Fault{Code: "bad_arguments", Message: "bodyBase64 is not valid base64"}
					}
					body = decoded
				}
			}
		}
		ref, err := b.h.CachePut(ctx, str(0), str(1), bytes.NewReader(body))
		if err != nil {
			return nil, mapHostError(err)
		}
		return result(map[string]any{"blob": ref}, nil)
	case "cache.open":
		rc, err := b.h.CacheOpen(ctx, str(0))
		if err != nil {
			return nil, mapHostError(err)
		}
		defer rc.Close()
		data, err := io.ReadAll(io.LimitReader(rc, wasm.MaxHostResultBytes+1))
		if err != nil {
			return nil, mapHostError(err)
		}
		if len(data) > wasm.MaxHostResultBytes {
			return nil, &wasm.Fault{Code: "host_error", Message: "cached blob exceeds host result size cap"}
		}
		out := map[string]any{}
		if utf8.Valid(data) {
			out["body"] = string(data)
		} else {
			out["body"] = ""
			out["bodyBase64"] = base64.StdEncoding.EncodeToString(data)
		}
		return result(out, nil)
	case "folders.list":
		v, err := b.h.FoldersList(ctx, str(0), str(1))
		return result(v, err)
	case "folders.hashStart":
		v, err := b.h.FoldersHashStart(ctx, str(0), str(1))
		return result(v, err)
	case "folders.hashPoll":
		v, err := b.h.FoldersHashPoll(ctx, str(0))
		return result(v, err)
	case "folders.hashCancel":
		v, err := b.h.FoldersHashCancel(ctx, str(0))
		return result(v, err)
	case "folders.hash":
		v, err := b.h.FoldersHash(ctx, str(0), str(1))
		return result(v, err)
	case "folders.stat":
		v, err := b.h.FoldersStat(ctx, str(0), str(1))
		return result(v, err)
	case "notify.owner":
		return result(nil, b.h.NotifyOwner(ctx, str(0)))
	case "log":
		level, msg := str(0), str(1)
		if len(args) == 1 {
			level, msg = "info", str(0)
		}
		var attrs map[string]any
		if len(args) > 2 {
			_ = json.Unmarshal(args[2], &attrs)
		}
		return result(nil, b.h.Log(ctx, level, msg, attrs))
	default:
		return nil, wasm.Forbidden("unknown host service " + name)
	}
}

func mapHostError(err error) error {
	var input *CollectionInputError
	var valid *ValidationError
	switch {
	case errors.As(err, &input):
		return &wasm.Fault{Code: string(wasm.StatusInvalidInput), Message: input.Message}
	case errors.As(err, &valid):
		return &wasm.Fault{Code: string(wasm.StatusInvalidInput), Message: valid.Error()}
	case errors.Is(err, ErrPermissionDenied):
		return wasm.Forbidden(err.Error())
	case errors.Is(err, context.DeadlineExceeded):
		return &wasm.Fault{Code: string(wasm.StatusTimeout), Message: "host call timed out"}
	default:
		return &wasm.Fault{Code: "host_error", Message: err.Error()}
	}
}

// FetchResult is the guest-facing http.fetch answer. body is the response
// as text (JSON, HTML, playlists); bodyBase64 carries the exact bytes only
// for responses that are not valid UTF-8 (archives, images), so a large
// text response is not sent twice into the 4 MiB host-result cap.
func FetchResult(resp FetchResponse) map[string]any {
	out := map[string]any{"status": resp.Status, "headers": resp.Headers}
	if utf8.Valid(resp.Body) {
		out["body"] = string(resp.Body)
	} else {
		out["body"] = ""
		out["bodyBase64"] = base64.StdEncoding.EncodeToString(resp.Body)
	}
	return out
}

// Check runs the full conformance kit against pkg and returns a structured Report.
func Check(ctx context.Context, pkg *Package) (rep Report) {
	start := time.Now()
	rep = Report{OK: true}
	defer func() {
		rep.DurationMS = float64(time.Since(start).Microseconds()) / 1000.0
	}()

	if pkg == nil || len(pkg.ManifestRaw) == 0 {
		rep.addErr("manifest", "manifest.json", "manifest.json is missing or empty")
		return rep
	}

	man, err := plugins.ParseManifest(pkg.ManifestRaw)
	if err != nil {
		rep.addErr("manifest", "manifest.json", err.Error())
		return rep
	}
	pkg.Manifest = man
	rep.PluginID = man.ID
	rep.Version = man.Version
	if man.Ether != nil {
		rep.Kind = string(man.Ether.Kind)
		rep.DeclaredHosts = append([]string(nil), man.Ether.Permissions.Network...)
	}

	// 1. Manifest and kind/capability rules (reusing WS7 Manifest.Validate).
	if err := man.Validate(); err != nil {
		var ve *plugins.ValidationError
		if errors.As(err, &ve) {
			for _, fe := range ve.Fields {
				rep.addErr("manifest", fe.Field, fe.Message)
			}
		} else {
			rep.addErr("manifest", "manifest.json", err.Error())
		}
	}

	if man.Ether == nil {
		return rep
	}

	// 2. Resolve and lint strings across every shipped locale, plus $t: references.
	stringsByLocale := checkStringsAndCopy(&rep, man, pkg.Files)

	// 3. Resolve and lint settings schema, including $t: references in every locale.
	checkSettingsSchema(&rep, man, pkg.Files, stringsByLocale)

	// 3a. Content-kind conformance notes beyond Validate (spec §9.4).
	checkMediaKinds(&rep, man)

	// 4. Validate SVG icon if present (rasterize and check legibility on light and dark).
	checkIcon(&rep, ctx, man, pkg.Files)

	// 5. Runtime checks (hosted WASM/JS/TS or remote with local entry).
	if man.Ether.Runtime.Kind == "hosted" {
		checkHostedRuntime(ctx, &rep, man, pkg.Files, stringsByLocale)
	}

	return rep
}

// stringUsage records how a $t:key is used so every locale is linted against
// the right character cap and sentence rules.
type stringUsage struct {
	field    string
	maxChars int
	isHint   bool // hints must be <= 120 chars and one sentence
}

func checkStringsAndCopy(rep *Report, man plugins.Manifest, files map[string][]byte) map[string]map[string]string {
	e := man.Ether
	out := map[string]map[string]string{}

	locs := make([]string, 0, len(e.Strings))
	for loc := range e.Strings {
		locs = append(locs, loc)
	}
	sort.Strings(locs)

	for _, loc := range locs {
		raw := e.Strings[loc]
		var filePath string
		var doc map[string]string
		if json.Unmarshal(raw, &filePath) == nil && filePath != "" {
			if isUnsafePath(filePath) {
				rep.addErr("strings", "ether.strings."+loc, "file path must stay inside the package")
				continue
			}
			b, ok := files[filePath]
			if !ok {
				rep.addErr("strings", "ether.strings."+loc, fmt.Sprintf("missing strings file %q", filePath))
				continue
			}
			if err := json.Unmarshal(b, &doc); err != nil {
				rep.addErr("strings", "ether.strings."+loc, "strings file must be a JSON object of string values")
				continue
			}
		} else if err := json.Unmarshal(raw, &doc); err != nil {
			rep.addErr("strings", "ether.strings."+loc, "must be a file path or a JSON object of string values")
			continue
		}
		out[loc] = doc
	}

	// Collect all $t: usages from manifest & contributes.
	usages := map[string][]stringUsage{}
	recordRef := func(field, val string, max int, isHint bool) {
		if strings.HasPrefix(val, "$t:") {
			key := strings.TrimPrefix(val, "$t:")
			usages[key] = append(usages[key], stringUsage{field: field, maxChars: max, isHint: isHint})
			return
		}
		// Plain text a Stremio add-on brings (catalogue names) is the
		// add-on's own; only the plugin's summary is held to Ether's rules.
		if e.Stremio && field != "ether.summary" {
			return
		}
		if strings.TrimSpace(val) != "" {
			if msg := plugins.LintCopy(val, max); msg != "" {
				rep.addErr("copy", field, msg)
			} else if isHint && isMultiSentence(val) {
				rep.addErr("copy", field, "must be one sentence")
			}
		}
	}

	recordRef("ether.summary", e.Summary, 80, false)
	c := e.Contributes
	for i, ls := range c.ListSources {
		base := fmt.Sprintf("ether.contributes.listSources[%d]", i)
		recordRef(base+".label", ls.Label, 40, false)
		recordRef(base+".hint", ls.Hint, 120, true)
	}
	for i, rs := range c.RankingSteps {
		base := fmt.Sprintf("ether.contributes.rankingSteps[%d]", i)
		recordRef(base+".label", rs.Label, 40, false)
		recordRef(base+".hint", rs.Hint, 120, true)
	}
	for i, rc := range c.RuleConditions {
		base := fmt.Sprintf("ether.contributes.ruleConditions[%d]", i)
		recordRef(base+".label", rc.Label, 40, false)
	}
	for i, tl := range c.Tools {
		base := fmt.Sprintf("ether.contributes.tools[%d]", i)
		recordRef(base+".title", tl.Title, 40, false)
	}
	for i, pg := range c.Pages {
		base := fmt.Sprintf("ether.contributes.pages[%d]", i)
		recordRef(base+".label", pg.Label, 40, false)
	}
	for i, sl := range c.Slots {
		base := fmt.Sprintf("ether.contributes.slots[%d]", i)
		recordRef(base+".label", sl.Label, 40, false)
	}
	for i, cm := range c.Commands {
		base := fmt.Sprintf("ether.contributes.commands[%d]", i)
		recordRef(base+".label", cm.Label, 40, false)
	}
	if c.Integration != nil {
		for i, a := range c.Integration.Adds {
			recordRef(fmt.Sprintf("ether.contributes.integration.adds[%d]", i), a, 80, false)
		}
	}

	// Lint every string in every locale.
	enDoc := out["en"]
	for _, loc := range locs {
		doc := out[loc]
		keys := make([]string, 0, len(doc))
		for k := range doc {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			val := doc[k]
			fieldPath := fmt.Sprintf("strings.%s.%s", loc, k)
			if strings.TrimSpace(val) == "" {
				rep.addErr("copy", fieldPath, "string value must not be empty")
				continue
			}
			// Base copy check for every string in every shipped locale.
			maxLen := 120
			isHint := strings.HasSuffix(strings.ToLower(k), "hint")
			if strings.HasSuffix(strings.ToLower(k), "label") || strings.HasSuffix(strings.ToLower(k), "title") {
				maxLen = 40
			}
			if ulist, ok := usages[k]; ok && len(ulist) > 0 {
				for _, u := range ulist {
					if msg := plugins.LintCopy(val, u.maxChars); msg != "" {
						rep.addErr("copy", fmt.Sprintf("%s (%s)", fieldPath, u.field), msg)
					} else if u.isHint && isMultiSentence(val) {
						rep.addErr("copy", fmt.Sprintf("%s (%s)", fieldPath, u.field), "must be one sentence")
					}
				}
			} else {
				if msg := plugins.LintCopy(val, maxLen); msg != "" {
					rep.addErr("copy", fieldPath, msg)
				} else if isHint && isMultiSentence(val) {
					rep.addErr("copy", fieldPath, "must be one sentence")
				}
			}
		}
	}

	// Verify all referenced $t: keys exist in en.
	refKeys := make([]string, 0, len(usages))
	for k := range usages {
		refKeys = append(refKeys, k)
	}
	sort.Strings(refKeys)
	for _, k := range refKeys {
		if enDoc == nil {
			rep.addErr("strings", usages[k][0].field, fmt.Sprintf("missing en strings for $t:%s", k))
			continue
		}
		if _, ok := enDoc[k]; !ok {
			rep.addErr("strings", usages[k][0].field, fmt.Sprintf("missing key %q in en strings", k))
		}
	}

	return out
}

func isMultiSentence(s string) bool {
	trimmed := strings.TrimSpace(s)
	trimmed = strings.TrimRight(trimmed, ".")
	return strings.Count(trimmed, ".") > 0
}

func checkSettingsSchema(rep *Report, man plugins.Manifest, files map[string][]byte, stringsByLocale map[string]map[string]string) {
	raw := man.Ether.Settings
	if len(raw) == 0 {
		return
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return // already reported by Manifest.Validate
	}
	if ref, ok := doc["$ref"].(string); ok && ref != "" {
		if isUnsafePath(ref) {
			return
		}
		b, exists := files[ref]
		if !exists {
			rep.addErr("settings", "ether.settings.$ref", fmt.Sprintf("missing settings schema file %q", ref))
			return
		}
		raw = b
	}
	if err := plugins.LintSettingsSchema(raw); err != nil {
		var ve *plugins.ValidationError
		if errors.As(err, &ve) {
			for _, fe := range ve.Fields {
				rep.addErr("settings", fe.Field, fe.Message)
			}
		} else {
			rep.addErr("settings", "ether.settings", err.Error())
		}
	}
	var resolved any
	if json.Unmarshal(raw, &resolved) == nil {
		walkSettingsRefs(rep, resolved, "ether.settings", man, stringsByLocale)
	}
}

func walkSettingsRefs(rep *Report, node any, fieldPath string, man plugins.Manifest, stringsByLocale map[string]map[string]string) {
	switch n := node.(type) {
	case map[string]any:
		if k, ok := n["kind"].(string); ok && k == "folder" {
			if man.Ether.Permissions.Folders != "read" {
				rep.addErr("settings", fieldPath+".kind", "folder field kind requires folders: read permission")
			}
		}
		if label, ok := n["label"].(string); ok && strings.HasPrefix(label, "$t:") {
			key := strings.TrimPrefix(label, "$t:")
			checkLocalizedRef(rep, fieldPath+".label", key, 40, false, stringsByLocale)
		}
		if hint, ok := n["hint"].(string); ok && strings.HasPrefix(hint, "$t:") {
			key := strings.TrimPrefix(hint, "$t:")
			checkLocalizedRef(rep, fieldPath+".hint", key, 120, true, stringsByLocale)
		}
		keys := make([]string, 0, len(n))
		for k := range n {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			walkSettingsRefs(rep, n[k], fieldPath+"."+k, man, stringsByLocale)
		}
	case []any:
		for i, item := range n {
			walkSettingsRefs(rep, item, fmt.Sprintf("%s[%d]", fieldPath, i), man, stringsByLocale)
		}
	}
}

func checkLocalizedRef(rep *Report, fieldPath, key string, max int, isHint bool, stringsByLocale map[string]map[string]string) {
	en := stringsByLocale["en"]
	if en == nil {
		rep.addErr("strings", fieldPath, fmt.Sprintf("missing en strings for $t:%s", key))
		return
	}
	if _, ok := en[key]; !ok {
		rep.addErr("strings", fieldPath, fmt.Sprintf("missing key %q in en strings", key))
		return
	}
	locs := make([]string, 0, len(stringsByLocale))
	for loc := range stringsByLocale {
		locs = append(locs, loc)
	}
	sort.Strings(locs)
	for _, loc := range locs {
		val, ok := stringsByLocale[loc][key]
		if !ok {
			continue
		}
		if msg := plugins.LintCopy(val, max); msg != "" {
			rep.addErr("copy", fmt.Sprintf("%s (%s:%s)", fieldPath, loc, key), msg)
		} else if isHint && isMultiSentence(val) {
			rep.addErr("copy", fmt.Sprintf("%s (%s:%s)", fieldPath, loc, key), "must be one sentence")
		}
	}
}

func checkIcon(rep *Report, ctx context.Context, man plugins.Manifest, files map[string][]byte) {
	iconPath := man.Ether.Icon
	if iconPath == "" || strings.HasPrefix(iconPath, "http://") || strings.HasPrefix(iconPath, "https://") {
		return
	}
	if isUnsafePath(iconPath) {
		rep.addErr("icon", "ether.icon", "icon path must stay inside the package")
		return
	}
	data, ok := files[iconPath]
	if !ok {
		rep.addErr("icon", "ether.icon", fmt.Sprintf("missing icon file %q", iconPath))
		return
	}
	rast := artwork.NewSVGRasterizer()
	if _, _, err := rast.Rasterize(ctx, "kit:"+man.ID, data, artwork.RasterOptions{Width: 64, Height: 64, Format: "png"}); err != nil {
		rep.addErr("icon", "ether.icon", fmt.Sprintf("icon cannot be rasterized safely: %v", err))
		return
	}
	// Check contrast/legibility on light (#f8fafc) and dark (#0f172a) backgrounds.
	if !iconLegibleOnBoth(data) {
		rep.addErr("icon", "ether.icon", "icon is not legible on both light and dark backgrounds")
	}
}

func iconLegibleOnBoth(data []byte) bool {
	icon, err := oksvg.ReadIconStream(strings.NewReader(string(data)), oksvg.StrictErrorMode)
	if err != nil || icon == nil {
		return false
	}
	const w, h = 64, 64
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	icon.SetTarget(0, 0, float64(w), float64(h))
	dasher := rasterx.NewDasher(w, h, rasterx.NewScannerGV(w, h, img, img.Bounds()))
	for _, p := range icon.SVGPaths {
		p.DrawTransformed(dasher, 1, icon.Transform)
	}
	lightBG := color.RGBA{R: 248, G: 250, B: 252, A: 255}
	darkBG := color.RGBA{R: 15, G: 23, B: 42, A: 255}
	var visibleLight, visibleDark int
	var nonTransparent int
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			if c.A < 25 {
				continue
			}
			nonTransparent++
			if colorContrast(c, lightBG) >= 1.25 {
				visibleLight++
			}
			if colorContrast(c, darkBG) >= 1.25 {
				visibleDark++
			}
		}
	}
	return nonTransparent > 0 && visibleLight > 0 && visibleDark > 0
}

func colorContrast(fg, bg color.RGBA) float64 {
	alpha := float64(fg.A) / 255.0
	r := float64(fg.R)*alpha + float64(bg.R)*(1-alpha)
	g := float64(fg.G)*alpha + float64(bg.G)*(1-alpha)
	b := float64(fg.B)*alpha + float64(bg.B)*(1-alpha)
	l1 := relLuminance(r, g, b)
	l2 := relLuminance(float64(bg.R), float64(bg.G), float64(bg.B))
	if l1 < l2 {
		l1, l2 = l2, l1
	}
	return (l1 + 0.05) / (l2 + 0.05)
}

func relLuminance(r, g, b float64) float64 {
	chanLum := func(v float64) float64 {
		v /= 255.0
		if v <= 0.03928 {
			return v / 12.92
		}
		return math.Pow((v+0.055)/1.055, 2.4)
	}
	return 0.2126*chanLum(r) + 0.7152*chanLum(g) + 0.0722*chanLum(b)
}

// recordingHost implements wasm.Host for conformance checking, recording
// outbound http.fetch hosts and auditing them against manifest permissions.
type recordingHost struct {
	mu       sync.Mutex
	man      plugins.Manifest
	kv       map[string]string
	observed map[string]int
	undecl   map[string]bool
	deferred int
}

func newRecordingHost(man plugins.Manifest) *recordingHost {
	return &recordingHost{
		man:      man,
		kv:       map[string]string{},
		observed: map[string]int{},
		undecl:   map[string]bool{},
	}
}

func (h *recordingHost) CallHost(ctx context.Context, name string, raw json.RawMessage) (json.RawMessage, error) {
	var args []json.RawMessage
	if len(raw) > 0 && string(raw) != "null" {
		_ = json.Unmarshal(raw, &args)
	}
	str := func(i int) string {
		var s string
		if i < len(args) {
			_ = json.Unmarshal(args[i], &s)
		}
		return s
	}
	h.mu.Lock()
	defer h.mu.Unlock()

	switch name {
	case "log":
		return json.RawMessage("null"), nil
	case "kv.get":
		if v, ok := h.kv[str(0)]; ok {
			b, _ := json.Marshal(v)
			return b, nil
		}
		return json.RawMessage("null"), nil
	case "kv.put":
		var val string
		if len(args) > 1 {
			if json.Unmarshal(args[1], &val) != nil {
				val = string(args[1])
			}
		}
		h.kv[str(0)] = val
		return json.RawMessage("null"), nil
	case "kv.delete":
		delete(h.kv, str(0))
		return json.RawMessage("null"), nil
	case "kv.list":
		prefix := str(0)
		var keys []string
		for k := range h.kv {
			if strings.HasPrefix(k, prefix) {
				keys = append(keys, k)
			}
		}
		sort.Strings(keys)
		b, _ := json.Marshal(keys)
		return b, nil
	case "secret.get":
		sec := str(0)
		for _, allowed := range h.man.Ether.Permissions.Secrets {
			if allowed == sec {
				return json.RawMessage(`"fixture-secret"`), nil
			}
		}
		return nil, wasm.Forbidden("undeclared secret " + sec)
	case "settings.get":
		return json.RawMessage(`{}`), nil
	case "addon.get":
		// An add-on-backed plugin's checks run offline: the add-on answers
		// with an empty, well-formed Stremio response.
		if !h.man.Ether.Stremio {
			return nil, wasm.Forbidden("addon.get is only for plugins made from an add-on")
		}
		body := `{"metas":[],"streams":[],"subtitles":[],"addons":[],"meta":{"id":"tt0000001","type":"movie","name":"Fixture"}}`
		if strings.HasSuffix(str(0), "/manifest.json") {
			body = `{"id":"fixture","version":"1.0.0","name":"Fixture","resources":[],"types":[]}`
		}
		b, _ := json.Marshal(map[string]any{"status": 200, "body": body})
		return b, nil
	case "http.fetch":
		var req struct {
			Method  string            `json:"method"`
			URL     string            `json:"url"`
			Headers map[string]string `json:"headers"`
			Body    string            `json:"body"`
		}
		if len(args) > 0 {
			_ = json.Unmarshal(args[0], &req)
		}
		u, err := url.Parse(req.URL)
		if err != nil || u.Hostname() == "" {
			return nil, wasm.Forbidden("invalid url in http.fetch: " + req.URL)
		}
		host := strings.ToLower(u.Hostname())
		h.observed[host]++
		if !hostMatches(h.man.Ether.Permissions.Network, host) {
			h.undecl[host] = true
			return nil, wasm.Forbidden("undeclared network host " + host)
		}
		// The offline checker cannot invent the upstream API's response shape.
		// Stop at this boundary and leave an explicit live-test warning.
		h.deferred++
		return nil, &wasm.Fault{Code: "check_dependency", Message: "declared network request needs a live test"}
	case "catalog.search":
		if h.man.Ether.Permissions.Catalog != "read" {
			return nil, wasm.Forbidden("catalog permission not declared")
		}
		return json.RawMessage(`{"titles":[{"id":1,"title":"The Kid","type":"movie","year":1921}]}`), nil
	case "catalog.get":
		if h.man.Ether.Permissions.Catalog != "read" {
			return nil, wasm.Forbidden("catalog permission not declared")
		}
		return json.RawMessage(`{"id":1,"title":"The Kid","type":"movie","year":1921}`), nil
	case "viewers.granted":
		return json.RawMessage(`[]`), nil
	case "viewers.history":
		if h.man.Ether.Permissions.Viewers.WatchHistory == "" || h.man.Ether.Permissions.Viewers.WatchHistory == "none" {
			return nil, wasm.Forbidden("viewers.watch_history permission not declared")
		}
		return json.RawMessage(`[]`), nil
	case "viewers.setWatchState":
		if h.man.Ether.Permissions.Viewers.WriteWatchState == "" || h.man.Ether.Permissions.Viewers.WriteWatchState == "none" {
			return nil, wasm.Forbidden("viewers.write_watch_state permission not declared")
		}
		return json.RawMessage("null"), nil
	case "collections.upsert":
		if h.man.Ether.Permissions.Collections != "write" {
			return nil, wasm.Forbidden("collections: write permission not declared")
		}
		return json.RawMessage("null"), nil
	case "folders.list":
		if h.man.Ether.Permissions.Folders != "read" {
			return nil, wasm.Forbidden("folders: read permission not declared")
		}
		return json.RawMessage(`[]`), nil
	case "folders.hashStart", "folders.hashPoll", "folders.hashCancel":
		if h.man.Ether.Permissions.Folders != "read" {
			return nil, wasm.Forbidden("folders: read permission not declared")
		}
		return json.RawMessage(`{"id":"hash-1","state":"done","bytes":1024,"result":{"size":1024,"modTime":0,"crc32":"00000000","md5":"00000000000000000000000000000000","sha1":"0000000000000000000000000000000000000000"}}`), nil
	case "folders.hash":
		if h.man.Ether.Permissions.Folders != "read" {
			return nil, wasm.Forbidden("folders: read permission not declared")
		}
		return json.RawMessage(`{"size":1024,"modTime":0,"crc32":"00000000","md5":"00000000000000000000000000000000","sha1":"0000000000000000000000000000000000000000"}`), nil
	case "folders.stat":
		if h.man.Ether.Permissions.Folders != "read" {
			return nil, wasm.Forbidden("folders: read permission not declared")
		}
		return json.RawMessage(`{"name":"movie.mkv","path":"movie.mkv","dir":false,"size":1024}`), nil
	case "notify.owner":
		return json.RawMessage("null"), nil
	default:
		return nil, wasm.Forbidden("unknown host service " + name)
	}
}

func hostMatches(patterns []string, host string) bool {
	host = strings.ToLower(host)
	for _, p := range patterns {
		p = strings.ToLower(p)
		if strings.HasPrefix(p, "*.") {
			if strings.HasSuffix(host, p[1:]) && host != p[2:] {
				return true
			}
			continue
		}
		if p == host {
			return true
		}
	}
	return false
}

func checkHostedRuntime(ctx context.Context, rep *Report, man plugins.Manifest, files map[string][]byte, stringsByLocale map[string]map[string]string) {
	eng := wasm.NewEngine(nil)
	defer func() { _ = eng.Close() }()

	host := newRecordingHost(man)
	decl := man.Ether.Runtime
	var plug *wasm.Plugin
	var err error

	switch {
	case decl.Module != "":
		modBytes, ok := files[decl.Module]
		if !ok {
			rep.addErr("runtime", "ether.runtime.module", fmt.Sprintf("missing WASM module %q", decl.Module))
			return
		}
		plug, err = eng.LoadWASM(man.ID, man.Version, modBytes, host, wasm.Limits{})
	case decl.Entry != "":
		jsSrc, compErr := loadOrCompileEntry(decl.Entry, files)
		if compErr != nil {
			rep.addErr("runtime", "ether.runtime.entry", compErr.Error())
			return
		}
		plug, err = eng.LoadJS(man.ID, man.Version, jsSrc, host, wasm.Limits{})
	default:
		return
	}
	if err != nil {
		rep.addErr("runtime", "ether.runtime", err.Error())
		return
	}
	defer func() { _ = plug.Close() }()
	rep.Exports = map[string]bool{"handle": plug.HasHandle(), "rank_key": plug.HasRankKey(), "cond_match": plug.HasCondMatch()}

	// Exercise declared routes and capabilities.
	checkRoutes(ctx, rep, man, plug, stringsByLocale, host)

	// Record observed and undeclared network hosts.
	host.mu.Lock()
	for h := range host.observed {
		rep.ObservedHosts = append(rep.ObservedHosts, h)
	}
	sort.Strings(rep.ObservedHosts)
	var undecl []string
	for h := range host.undecl {
		undecl = append(undecl, h)
	}
	sort.Strings(undecl)
	host.mu.Unlock()
	for _, h := range undecl {
		rep.addErr("permissions", "ether.permissions.network", fmt.Sprintf("plugin attempted http.fetch to undeclared host %q", h))
	}

	// Hot path check: ranking_step and rule_condition on a 10k-candidate corpus.
	if man.HasCapability(plugins.CapRankingStep) || man.HasCapability(plugins.CapRuleCondition) {
		checkHotPath(ctx, rep, man, plug)
	}
}

func loadOrCompileEntry(entry string, files map[string][]byte) (string, error) {
	if b, ok := files[entry]; ok {
		if isTSPath(entry) {
			srcMap := collectSources(files)
			js, _, diags := wasm.Compile(srcMap, entry)
			if err := compileDiagsError(diags); err != nil {
				return "", err
			}
			return string(js), nil
		}
		return string(b), nil
	}
	tsEntry := findTSEntry(files, entry)
	if tsEntry == "" {
		return "", fmt.Errorf("missing entry file %q", entry)
	}
	srcMap := collectSources(files)
	js, _, diags := wasm.Compile(srcMap, tsEntry)
	if err := compileDiagsError(diags); err != nil {
		return "", err
	}
	return string(js), nil
}

func checkRoutes(ctx context.Context, rep *Report, man plugins.Manifest, plug *wasm.Plugin, stringsByLocale map[string]map[string]string, host *recordingHost) {
	needsHandle := len(man.Ether.Contributes.Pages) > 0 ||
		len(man.Ether.Contributes.Slots) > 0 ||
		len(man.Ether.Contributes.Commands) > 0 ||
		len(man.Ether.Contributes.Tools) > 0 ||
		len(man.Ether.Contributes.ListSources) > 0 ||
		len(man.Ether.Schedule) > 0 ||
		man.HasCapability(plugins.CapStreamSource) ||
		man.HasCapability(plugins.CapDebridProvider) ||
		man.HasCapability(plugins.CapLiveTV) ||
		man.HasCapability(plugins.CapSubtitles) ||
		man.HasCapability(plugins.CapMarkers) ||
		man.HasCapability(plugins.CapNotify) ||
		man.HasCapability(plugins.CapEvents)

	if !plug.HasHandle() {
		if needsHandle {
			rep.addErr("routes", "handle", "plugin declares HTTP routes or capabilities that require exporting handle(request)")
		}
		return
	}

	var fixtures []routeFixture

	// Health check is standard on all handle-exporting plugins.
	fixtures = append(fixtures, routeFixture{
		method: "GET",
		path:   "/ether/health",
		validate: func(resp wasm.Response) string {
			var doc struct {
				Status string `json:"status"`
			}
			if err := decodeResponseBody(resp.Body, &doc); err != nil {
				return "health response must be a JSON object: " + err.Error()
			}
			if doc.Status != "ok" && doc.Status != "attention" && doc.Status != "error" {
				return fmt.Sprintf("health status must be ok, attention or error (got %q)", doc.Status)
			}
			return ""
		},
	})

	// Configure check.
	fixtures = append(fixtures, routeFixture{
		method: "POST",
		path:   "/ether/configure",
		body:   json.RawMessage(`{}`),
		validate: func(resp wasm.Response) string {
			var doc map[string]any
			if err := decodeResponseBody(resp.Body, &doc); err != nil {
				return "configure response must be a JSON object: " + err.Error()
			}
			return ""
		},
	})

	// Test route when declared.
	if (man.Ether.Contributes.Channels != nil && man.Ether.Contributes.Channels.Test) ||
		(man.Ether.Contributes.Notification != nil && man.Ether.Contributes.Notification.SendTest) ||
		(man.Ether.Contributes.Integration != nil && man.Ether.Contributes.Integration.Test) ||
		(man.HasCapability(plugins.CapStreamSource) || man.HasCapability(plugins.CapDebridProvider)) {
		fixtures = append(fixtures, routeFixture{
			method: "POST",
			path:   "/ether/test",
			body:   json.RawMessage(`{}`),
			validate: func(resp wasm.Response) string {
				var doc struct {
					OK *bool `json:"ok"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "test response must be a JSON object: " + err.Error()
				}
				if doc.OK == nil {
					return "test response must include boolean field 'ok'"
				}
				return ""
			},
		})
	}

	// Stream source routes.
	if man.HasCapability(plugins.CapStreamSource) {
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   "/stream/movie/tt0012349.json",
			validate: func(resp wasm.Response) string {
				var doc struct {
					Streams []map[string]any `json:"streams"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "stream response must be a JSON object with streams[]: " + err.Error()
				}
				if doc.Streams == nil {
					return "stream response must contain a streams array"
				}
				for i, st := range doc.Streams {
					if eth, ok := st["ether"].(map[string]any); ok {
						if f, hasFile := eth["file"].(string); hasFile && f != "" {
							if man.Ether.Permissions.Folders != "read" {
								return fmt.Sprintf("streams[%d].ether.file requires folders: read permission", i)
							}
							if isUnsafePath(f) {
								return fmt.Sprintf("streams[%d].ether.file must be a relative path without '..'", i)
							}
						}
					}
				}
				return ""
			},
		})
	}

	// List sources.
	for _, ls := range man.Ether.Contributes.ListSources {
		catPath := "/catalog/movie/" + ls.Catalog + ".json"
		if strings.Contains(ls.Catalog, "/") {
			// Native and adapted catalogues may both declare type/id.
			catPath = "/catalog/" + ls.Catalog + ".json"
		}
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   catPath,
			validate: func(resp wasm.Response) string {
				var doc struct {
					Metas []map[string]any `json:"metas"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "catalog response must be a JSON object with metas[]: " + err.Error()
				}
				if doc.Metas == nil {
					return "catalog response must contain a metas array"
				}
				return ""
			},
		})
	}

	// Live TV channels and guide.
	if man.HasCapability(plugins.CapLiveTV) {
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   "/ether/channels.json",
			validate: func(resp wasm.Response) string {
				var doc struct {
					Channels []map[string]any `json:"channels"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "channels response must be a JSON object with channels[]: " + err.Error()
				}
				if doc.Channels == nil {
					return "channels response must contain a channels array"
				}
				return ""
			},
		})
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   "/ether/guide/ch-1.json",
			query:  map[string][]string{"from": {"2026-01-01T00:00:00Z"}, "to": {"2026-01-01T06:00:00Z"}},
			validate: func(resp wasm.Response) string {
				var doc struct {
					Programmes []map[string]any `json:"programmes"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "guide response must be a JSON object: " + err.Error()
				}
				return ""
			},
		})
	}

	// Listing is public to the host; download requires a viewer pick.
	if man.HasCapability(plugins.CapSubtitles) {
		subPath := "/subtitles/movie/tt0012349/videoHash=0123456789abcdef.json"
		// Download must refuse a missing pick token. A plugin that answers
		// as a Stremio add-on hands out subtitle links instead and has no
		// download route.
		if !man.SpeaksStremio() {
			callNoPick(ctx, rep, plug, "/ether/subtitles/download")
		}
		// Listing succeeds without a pick and returns a subtitles array.
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   subPath,
			validate: func(resp wasm.Response) string {
				var doc struct {
					Subtitles []map[string]any `json:"subtitles"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "subtitles response must be a JSON object with subtitles[]: " + err.Error()
				}
				if doc.Subtitles == nil {
					return "subtitles response must contain a subtitles array"
				}
				return ""
			},
		})
	}

	// Markers.
	if man.HasCapability(plugins.CapMarkers) {
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   "/ether/markers/movie/tt0012349.json",
			validate: func(resp wasm.Response) string {
				var doc struct {
					Markers []map[string]any `json:"markers"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "markers response must be a JSON object with markers[]: " + err.Error()
				}
				if doc.Markers == nil {
					return "markers response must contain a markers array"
				}
				return ""
			},
		})
	}

	// Events.
	if man.HasCapability(plugins.CapEvents) {
		evName := plugins.EventPlaybackStarted
		if man.Ether.Contributes.Events != nil && len(man.Ether.Contributes.Events.Subscribe) > 0 {
			evName = man.Ether.Contributes.Events.Subscribe[0]
		}
		evBody, _ := json.Marshal(map[string]any{
			"events": []map[string]any{
				{"id": "ev-1", "name": evName, "at": "2026-01-01T00:00:00Z", "payload": map[string]any{"ratingKey": 1}},
			},
		})
		fixtures = append(fixtures, routeFixture{
			method: "POST",
			path:   "/ether/event",
			body:   evBody,
			validate: func(resp wasm.Response) string {
				var doc struct {
					Ack []string `json:"ack"`
				}
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "event response must be a JSON object with ack[]: " + err.Error()
				}
				if doc.Ack == nil {
					return "event response must contain an ack array"
				}
				return ""
			},
		})
	}

	// Pages & Slots (ViewSpec validation + literal string rejection).
	for _, pg := range man.Ether.Contributes.Pages {
		route := pg.Route
		field := fmt.Sprintf("page:%s (%s)", pg.Key, route)
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   route,
			query:  map[string][]string{"page": {"1"}, "q": {""}},
			validate: func(resp wasm.Response) string {
				return validateViewResponse(rep, field, resp.Body, stringsByLocale)
			},
		})
	}
	for _, sl := range man.Ether.Contributes.Slots {
		if strings.HasPrefix(sl.Slot, "actionMenu.") || sl.Slot == "command" {
			continue
		}
		route := sl.Route
		field := fmt.Sprintf("slot:%s (%s)", sl.Key, route)
		fixtures = append(fixtures, routeFixture{
			method: "GET",
			path:   route,
			query:  map[string][]string{"id": {"1"}, "viewerId": {"1"}},
			validate: func(resp wasm.Response) string {
				return validateViewResponse(rep, field, resp.Body, stringsByLocale)
			},
		})
	}

	// Commands (actions).
	for _, cm := range man.Ether.Contributes.Commands {
		actPath := "/ether/action/" + cm.Action
		fixtures = append(fixtures, routeFixture{
			method: "POST",
			path:   actPath,
			body:   json.RawMessage(`{}`),
			validate: func(resp wasm.Response) string {
				var doc map[string]any
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "action response must be a JSON object: " + err.Error()
				}
				return ""
			},
		})
	}

	// Tools.
	for _, tl := range man.Ether.Contributes.Tools {
		toolPath := "/ether/tool/" + tl.Name
		fixtures = append(fixtures, routeFixture{
			method: "POST",
			path:   toolPath,
			body:   sampleInputForSchema(tl.InputSchema),
			validate: func(resp wasm.Response) string {
				var doc map[string]any
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "tool response must be a JSON object: " + err.Error()
				}
				return ""
			},
		})
	}

	// Scheduled jobs.
	for _, job := range man.Ether.Schedule {
		fixtures = append(fixtures, routeFixture{
			method: "POST",
			path:   job.Call,
			body:   json.RawMessage(`{}`),
			validate: func(resp wasm.Response) string {
				var doc map[string]any
				if err := decodeResponseBody(resp.Body, &doc); err != nil {
					return "job response must be a JSON object: " + err.Error()
				}
				return ""
			},
		})
	}

	for _, fx := range fixtures {
		runRouteFixture(ctx, rep, plug, fx, host)
	}
}

func decodeResponseBody(raw json.RawMessage, dst any) error {
	if len(raw) == 0 {
		return fmt.Errorf("empty response body")
	}
	// Hosted JS plugins often return body as a JSON-encoded string or as a direct object.
	var asStr string
	if json.Unmarshal(raw, &asStr) == nil {
		return json.Unmarshal([]byte(asStr), dst)
	}
	return json.Unmarshal(raw, dst)
}

func unwrapResponseBytes(raw json.RawMessage) ([]byte, error) {
	if len(raw) == 0 {
		return nil, fmt.Errorf("empty response body")
	}
	var asStr string
	if json.Unmarshal(raw, &asStr) == nil {
		return []byte(asStr), nil
	}
	return raw, nil
}

// checkErrorShape enforces SPEC §5.1.2: `{ "error": { "code", "message" } }`.
func checkErrorShape(raw json.RawMessage) string {
	b, err := unwrapResponseBytes(raw)
	if err != nil {
		return "error response must have a JSON body"
	}
	var env struct {
		Error *struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(b, &env); err != nil || env.Error == nil {
		return `error response must use shape {"error":{"code":"...","message":"..."}}`
	}
	if strings.TrimSpace(env.Error.Code) == "" || strings.TrimSpace(env.Error.Message) == "" {
		return `error response must have non-empty "error.code" and "error.message"`
	}
	return ""
}

func validateViewResponse(rep *Report, field string, raw json.RawMessage, stringsByLocale map[string]map[string]string) string {
	b, err := unwrapResponseBytes(raw)
	if err != nil {
		return "view response is empty"
	}
	var envelope struct {
		Spec json.RawMessage `json:"spec"`
		Data json.RawMessage `json:"data"`
	}
	if err := json.Unmarshal(b, &envelope); err != nil {
		return "view response must be a JSON object with {spec, data}: " + err.Error()
	}
	if len(envelope.Spec) == 0 {
		return "view response is missing 'spec'"
	}
	res := viewspec.ValidatePlugin(envelope.Spec)
	if !res.OK {
		for _, e := range res.Errors {
			rep.addErr("viewspec", field, e)
		}
		return "ViewSpec validation failed: " + strings.Join(res.Errors, "; ")
	}
	var specDoc any
	if json.Unmarshal(envelope.Spec, &specDoc) == nil {
		checkViewSpecStrings(rep, field, specDoc, "", stringsByLocale)
	}
	return ""
}

// userVisibleSpecFields lists ViewSpec properties that hold user-visible labels
// and therefore must use `$t:key` (or a `{$: "path"}` binding), never raw literals
// (SPEC §5.6: "Every label in a plugin document is a $t:key ... Literal strings
// are rejected by the kit for user-visible fields").
var userVisibleSpecFields = map[string]bool{
	"title":             true,
	"description":       true,
	"label":             true,
	"header":            true, // table column header when string
	"content":           true, // heading / text block content
	"text":              true, // empty / emptyRow text
	"searchPlaceholder": true,
	"placeholder":       true,
	"submitLabel":       true,
	"openLabel":         true,
	"empty":             true, // when string prop on posterGrid/posterShelf
}

func checkViewSpecStrings(rep *Report, viewField string, node any, docPath string, stringsByLocale map[string]map[string]string) {
	switch t := node.(type) {
	case map[string]any:
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			v := t[k]
			p := k
			if docPath != "" {
				p = docPath + "." + k
			}
			if s, isStr := v.(string); isStr && userVisibleSpecFields[k] {
				if !strings.HasPrefix(s, "$t:") {
					rep.addErr("viewspec_copy", fmt.Sprintf("%s:%s", viewField, p),
						fmt.Sprintf("user-visible field %q must use a $t:key reference or field binding, not literal string %q", k, s))
				} else {
					key := strings.TrimPrefix(s, "$t:")
					max := 80
					if k == "label" || k == "header" || k == "submitLabel" || k == "openLabel" {
						max = 40
					}
					checkLocalizedRef(rep, fmt.Sprintf("%s:%s", viewField, p), key, max, false, stringsByLocale)
				}
				continue
			}
			checkViewSpecStrings(rep, viewField, v, p, stringsByLocale)
		}
	case []any:
		for i, item := range t {
			checkViewSpecStrings(rep, viewField, item, fmt.Sprintf("%s[%d]", docPath, i), stringsByLocale)
		}
	}
}

func sampleInputForSchema(raw json.RawMessage) json.RawMessage {
	var schema map[string]any
	if json.Unmarshal(raw, &schema) != nil {
		return json.RawMessage(`{}`)
	}
	props, _ := schema["properties"].(map[string]any)
	out := map[string]any{}
	for name, pRaw := range props {
		pm, ok := pRaw.(map[string]any)
		if !ok {
			continue
		}
		switch pm["type"] {
		case "string":
			out[name] = "test"
		case "number", "integer":
			out[name] = 1
		case "boolean":
			out[name] = true
		case "array":
			out[name] = []any{}
		case "object":
			out[name] = map[string]any{}
		}
	}
	b, _ := json.Marshal(out)
	return b
}

// checkHotPath validates determinism and budget on a generated 10,000-candidate
// corpus (SPEC §5.2, WS11g).
func checkHotPath(ctx context.Context, rep *Report, man plugins.Manifest, p1 *wasm.Plugin) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()
	const corpusSize = 10000
	const batchSize = 25

	if man.HasCapability(plugins.CapRankingStep) && !p1.HasRankKey() {
		rep.addErr("hot_path", "rank_key", "plugin declares ranking_step capability but does not export rank_key")
		return
	}
	if man.HasCapability(plugins.CapRuleCondition) && !p1.HasCondMatch() {
		rep.addErr("hot_path", "cond_match", "plugin declares rule_condition capability but does not export cond_match")
		return
	}

	corpusA, corpusB := sharedCorpora()

	ht := &HotTiming{
		Candidates:    corpusSize,
		Batches:       corpusSize / batchSize,
		Deterministic: true,
	}
	rep.HotPath = ht

	if p1.HasRankKey() {
		var batchDurs []float64
		scoresA := make([]int64, 0, corpusSize)
		cfg := json.RawMessage(`{"language":"en"}`)

		t0 := time.Now()
		for b := 0; b < corpusSize; b += batchSize {
			batch := corpusA[b : b+batchSize]
			bt0 := time.Now()
			sc, out, err := rankWithRetries(ctx, p1, batch, cfg)
			bdur := float64(time.Since(bt0).Microseconds()) / 1000.0
			batchDurs = append(batchDurs, bdur)
			if bdur > ht.MaxBatchMS {
				ht.MaxBatchMS = bdur
			}
			ht.SlowCount += out.SlowCandidates
			if err != nil || out.SlowCandidates != 0 {
				rep.addErr("hot_path", "rank_key", fmt.Sprintf("batch %d exceeded budget or failed: %v", b/batchSize, err))
				return
			}

			scoresA = append(scoresA, sc...)
		}
		ht.TotalMS = float64(time.Since(t0).Microseconds()) / 1000.0
		sort.Float64s(batchDurs)
		if len(batchDurs) > 0 {
			p95Batch := batchDurs[int(float64(len(batchDurs)-1)*0.95)]
			ht.PerCandP95MS = p95Batch / float64(batchSize)
		}
		if ht.SlowCount > corpusSize/100 {
			rep.addErr("hot_path", "rank_key", fmt.Sprintf("%d of %d candidates exceeded the 2ms per-candidate or 50ms per-batch budget", ht.SlowCount, corpusSize))
		}

		// Different memo keys ensure that every candidate is executed again.
		for b := 0; b < corpusSize; b += batchSize {
			scB, outB, err := rankWithRetries(ctx, p1, corpusB[b:b+batchSize], cfg)
			if err != nil || outB.SlowCandidates != 0 {
				ht.Deterministic = false
				rep.addErr("hot_path", "rank_key", fmt.Sprintf("second pass batch %d failed or exceeded budget: %v", b/batchSize, err))
				return
			}
			for i, got := range scB {
				if got != scoresA[b+i] {
					ht.Deterministic = false
					rep.addErr("determinism", "rank_key", fmt.Sprintf("nondeterministic rank_key at candidate %d: first pass returned %d, second pass returned %d", b+i, scoresA[b+i], got))
					return
				}
			}
		}

	}

	if p1.HasCondMatch() {
		op := "is"
		if len(man.Ether.Contributes.RuleConditions) > 0 && len(man.Ether.Contributes.RuleConditions[0].Operators) > 0 {
			op = man.Ether.Contributes.RuleConditions[0].Operators[0]
		}
		val := json.RawMessage(`"en"`)
		// Adjacent duplicate facts detect stateful hooks, with no memoization.
		for b := 0; b < corpusSize; b += batchSize {
			candidates := make([]wasm.Candidate, 0, 2*batchSize)
			for i := b; i < b+batchSize; i++ {
				candidates = append(candidates, corpusA[i], corpusB[i])
			}
			results, out, err := condBatchWithRetries(ctx, p1, candidates, op, val)
			if err != nil || out.SlowCandidates != 0 {
				rep.addErr("hot_path", "cond_match", fmt.Sprintf("condition batch %d exceeded budget or failed: %v", b/batchSize, err))
				return
			}
			for i := 0; i < len(results); i += 2 {
				if results[i] != results[i+1] {
					ht.Deterministic = false
					rep.addErr("determinism", "cond_match", fmt.Sprintf("nondeterministic cond_match at candidate %d: %v vs %v", b+i/2, results[i], results[i+1]))
					return
				}
			}
		}

	}
}

// A transient scheduler or GC pause can exhaust a deadline; retry with fresh
// memo keys so only repeatable budget violations fail the check.
func rankWithRetries(ctx context.Context, p *wasm.Plugin, batch []wasm.Candidate, cfg json.RawMessage) ([]int64, wasm.Outcome, error) {
	var scores []int64
	var out wasm.Outcome
	var err error
	for attempt := 0; attempt < 30; attempt++ {
		fresh := append([]wasm.Candidate(nil), batch...)
		for i := range fresh {
			fresh[i].ReleaseID += fmt.Sprintf("-try-%d", attempt)
		}
		scores, out, err = p.RankBatch(ctx, fresh, cfg)
		if err == nil && out.SlowCandidates == 0 {
			return scores, out, nil
		}
		select {
		case <-ctx.Done():
			return scores, out, ctx.Err()
		case <-time.After(20 * time.Millisecond):
		}
	}
	return scores, out, err
}

func condBatchWithRetries(ctx context.Context, p *wasm.Plugin, cands []wasm.Candidate, op string, val json.RawMessage) ([]bool, wasm.Outcome, error) {
	var result []bool
	var out wasm.Outcome
	var err error
	for attempt := 0; attempt < 30; attempt++ {
		result, out, err = p.CondBatch(ctx, cands, op, val)
		if err == nil && out.SlowCandidates == 0 {
			return result, out, nil
		}
		select {
		case <-ctx.Done():
			return result, out, ctx.Err()
		case <-time.After(20 * time.Millisecond):
		}
	}
	return result, out, err
}

var (
	corpusOnce sync.Once
	cachedA    []wasm.Candidate
	cachedB    []wasm.Candidate
)

func sharedCorpora() ([]wasm.Candidate, []wasm.Candidate) {
	corpusOnce.Do(func() {
		cachedA = generateCorpus("runA", 10000, 10000)
		cachedB = generateCorpus("runB", 10000, 10000)
	})
	return cachedA, cachedB
}

func generateCorpus(prefix string, n, unique int) []wasm.Candidate {
	resolutions := []string{"2160p", "1080p", "720p"}
	groups := []string{"FLUX", "NTb", "FRAMESTOR", "GRP"}
	langs := []string{`["en"]`, `["en","fr"]`, `["ja","en"]`, `["de"]`}

	rawFacts := make([]json.RawMessage, unique)
	for i := 0; i < unique; i++ {
		rawFacts[i] = json.RawMessage(fmt.Sprintf(
			`{"releaseId":"candidate-%d","resolution":%q,"languages":%s,"group":%q,"cached":%t}`,
			i, resolutions[i%len(resolutions)],
			langs[i%len(langs)],
			groups[i%len(groups)],
			i%2 == 0,
		))
	}

	out := make([]wasm.Candidate, n)
	for i := 0; i < n; i++ {
		u := i % unique
		out[i] = wasm.Candidate{
			ReleaseID: fmt.Sprintf("%s-%d", prefix, i),
			Facts:     rawFacts[u],
		}
	}
	return out
}

// checkMediaKinds adds the content-kind conformance notes that
// Manifest.Validate does not cover (spec §9.4). Manifest rule errors
// themselves come from Validate in Check, so the kit and the host
// always report the same field errors (lint parity); this pass only
// adds warnings about declarations that are valid but noteworthy.
func checkMediaKinds(rep *Report, man plugins.Manifest) {
	if man.Ether == nil {
		return
	}
	c := man.Ether.Contributes
	for i, k := range c.MediaKinds {
		base := fmt.Sprintf("ether.contributes.mediaKinds[%d]", i)
		if man.HasCapability(plugins.CapKindResolver) && !man.HasCapability(plugins.CapCatalogProvider) {
			rep.addWarn("kinds", base, "kind is resolver-only: nothing syncs items into its library")
		}
		if k.Present.Plex != nil && (k.Present.Plex.Base == "show" || k.Present.Plex.Base == "artist") && len(k.Levels) > 3 {
			rep.addWarn("kinds", base+".present.plex", "Plex nests three levels; deeper levels are flattened with their indexes kept")
		}
		if k.Browse.LiveSearch && !k.Browse.Search {
			rep.addWarn("kinds", base+".browse.liveSearch", "live search results are stored like synced items, but local search is off, so earlier live results will not be found again locally")
		}
		if k.Sync.Mode == plugins.KindSyncPull && k.Sync.Refresh == "" {
			rep.addWarn("kinds", base+".sync.refresh", "pull kind declares no refresh, so it syncs once at install and then only on demand")
		}
	}
	if man.HasCapability(plugins.CapFrontendAdapter) && man.Ether.Runtime.Kind == "hosted" {
		rep.addWarn("kinds", "ether.contributes.frontendAdapters", "hosted frontend adapters can only serve small responses; media bytes must come from Ether stream URLs")
	}
	if man.HasCapability(plugins.CapMatcher) && !man.HasCapability(plugins.CapKindResolver) {
		rep.addWarn("kinds", "ether.capabilities", "matcher without kind_resolver scores matches nothing resolves")
	}
}

// CheckKindUpgrade reports the non-additive declaration changes
// between two manifests (spec §2.5) as kit issues, for the Studio
// save path and catalogue CI.
func CheckKindUpgrade(prev, next plugins.Manifest) []Issue {
	kindsOf := func(m plugins.Manifest) []plugins.MediaKindMeta {
		if m.Ether == nil {
			return nil
		}
		return m.Ether.Contributes.MediaKinds
	}
	err := plugins.ValidateMediaKindsUpgrade(kindsOf(prev), kindsOf(next))
	if err == nil {
		return nil
	}
	var out []Issue
	var ve *plugins.ValidationError
	if errors.As(err, &ve) {
		for _, f := range ve.Fields {
			out = append(out, Issue{Rule: "kind-upgrade", Field: f.Field, Message: f.Message})
		}
		return out
	}
	return []Issue{{Rule: "kind-upgrade", Message: err.Error()}}
}

// ValidateKindPage checks one provider page against its kind
// declaration: page size, per-item envelope rules, and that item ids
// are not repeated inside the page. It is the offline half of the
// browse/detail conformance checks (§9.4).
func ValidateKindPage(decl plugins.MediaKindMeta, page core.KindPage, limit int) []Issue {
	var out []Issue
	if limit > 0 && len(page.Items) > limit {
		out = append(out, Issue{Rule: "kinds", Field: "items", Message: fmt.Sprintf("page holds %d items, more than the %d requested", len(page.Items), limit)})
	}
	seen := map[string]bool{}
	for i, it := range page.Items {
		if seen[it.ID] && it.ID != "" {
			out = append(out, Issue{Rule: "kinds", Field: fmt.Sprintf("items[%d].id", i), Message: "item id repeats inside one page"})
		}
		seen[it.ID] = true
		if msg := plugins.CheckKindItem(decl, it); msg != "" {
			out = append(out, Issue{Rule: "kinds", Field: fmt.Sprintf("items[%d]", i), Message: msg})
		}
	}
	return out
}

// KindCaller invokes one plugin route for CheckKindProvider: the same
// shape Manager.Call wraps, supplied by Studio preview or a test fake.
type KindCaller func(ctx context.Context, req plugins.Request) (plugins.Response, error)

var knownURLPlaceholders = map[string]bool{
	"{itemIndex}": true, "{pageNumber}": true, "{byteStart}": true, "{byteEnd}": true, "{byteRange}": true,
}

// CheckKindProvider runs a declared kind's provider through the
// scripted conformance calls (§9.4): browse must paginate and finish,
// pages must fit the limit, detail must round-trip, a declared live
// search must answer, /changes may decline (404/501 = re-walk), and a
// resolver's sources must use known patterns and URL placeholders.
// It never touches the network itself; call is the caller's transport.
func CheckKindProvider(ctx context.Context, decl plugins.MediaKindMeta, hasResolver bool, call KindCaller) []Issue {
	var out []Issue
	add := func(field, msg string) { out = append(out, Issue{Rule: "kinds", Field: field, Message: msg}) }
	post := func(path string, body any, v any) (int, bool) {
		raw, err := json.Marshal(body)
		if err != nil {
			add(path, err.Error())
			return 0, false
		}
		resp, err := call(ctx, plugins.Request{Method: http.MethodPost, Path: path, Body: raw})
		if err != nil {
			add(path, "call failed: "+err.Error())
			return 0, false
		}
		if resp.Status >= 200 && resp.Status < 300 && v != nil && len(resp.Body) > 0 {
			if err := json.Unmarshal(resp.Body, v); err != nil {
				add(path, "response is not the expected JSON: "+err.Error())
				return resp.Status, false
			}
		}
		return resp.Status, true
	}
	kindPath := "/ether/v1/kinds/" + decl.Key

	// Browse the root level with a small limit until the cursors run out.
	const limit = 3
	seenCursors := map[string]bool{}
	var roots []core.KindItem
	cursor := ""
	for pages := 0; pages < 20; pages++ {
		var page core.KindPage
		status, ok := post(kindPath+"/browse", core.KindBrowseRequest{Level: levelKey(decl, 0), Cursor: cursor, Limit: limit}, &page)
		if !ok {
			return out
		}
		if status < 200 || status >= 300 {
			add(kindPath+"/browse", fmt.Sprintf("browse answered status %d", status))
			return out
		}
		out = append(out, ValidateKindPage(decl, page, limit)...)
		roots = append(roots, page.Items...)
		if page.NextCursor == "" {
			break
		}
		if seenCursors[page.NextCursor] {
			add(kindPath+"/browse", "browse cursor repeats, so the walk never finishes")
			return out
		}
		seenCursors[page.NextCursor] = true
		cursor = page.NextCursor
		if pages == 19 {
			add(kindPath+"/browse", "browse still paginating after 20 pages at the root level")
		}
	}
	if len(roots) == 0 {
		add(kindPath+"/browse", "provider returned no root items; the conformance run needs at least one")
		return out
	}
	first := roots[0]

	// Detail of the first root.
	var detail core.KindItem
	if status, ok := post(kindPath+"/items/"+first.ID, map[string]any{}, &detail); ok {
		if status < 200 || status >= 300 {
			add(kindPath+"/items", fmt.Sprintf("detail answered status %d", status))
		} else if detail.ID != first.ID {
			add(kindPath+"/items", "detail returned a different item id than requested")
		}
	}

	// Declared live search must answer (§15.4); undeclared search may 501.
	if decl.Browse.LiveSearch {
		word := strings.Fields(first.Title)
		query := ""
		if len(word) > 0 {
			query = word[0]
		}
		var page core.KindPage
		if status, ok := post(kindPath+"/search", core.KindBrowseRequest{Query: query, Limit: limit}, &page); ok && (status < 200 || status >= 300) {
			add(kindPath+"/search", fmt.Sprintf("browse.liveSearch is set but search answered status %d", status))
		} else if ok {
			out = append(out, ValidateKindPage(decl, page, limit)...)
		}
	}

	// Changes may decline; if it answers, its upserts must validate.
	var changes core.KindChangePage
	if status, ok := post(kindPath+"/changes", map[string]any{"cursor": "", "limit": 500}, &changes); ok && status >= 200 && status < 300 {
		out = append(out, ValidateKindPage(decl, core.KindPage{Items: changes.Upserts}, 0)...)
	}

	// Resolve the first playable item seen, walking down the declared
	// levels through the first item of each level until one is playable.
	playable := findPlayable(roots)
	parent := first
	for depth := 1; playable == nil && depth < len(decl.Levels); depth++ {
		var page core.KindPage
		status, ok := post(kindPath+"/browse", core.KindBrowseRequest{ParentID: parent.ID, Level: levelKey(decl, depth), Limit: limit}, &page)
		if !ok || status < 200 || status >= 300 || len(page.Items) == 0 {
			break
		}
		out = append(out, ValidateKindPage(decl, page, limit)...)
		playable = findPlayable(page.Items)
		parent = page.Items[0]
	}
	if hasResolver {
		if playable == nil {
			add(kindPath+"/resolve", "no playable item found in the browsed sample to resolve")
		} else {
			var res core.KindResolveResponse
			body := core.KindResolveRequest{Item: *playable}
			if status, ok := post(kindPath+"/resolve", body, &res); ok {
				if status < 200 || status >= 300 {
					add(kindPath+"/resolve", fmt.Sprintf("resolve answered status %d", status))
				}
				for i, src := range res.Sources {
					out = append(out, checkPlayableSource(kindPath, i, src)...)
				}
			}
		}
	}
	return out
}

func levelKey(decl plugins.MediaKindMeta, i int) string {
	if i >= 0 && i < len(decl.Levels) {
		return decl.Levels[i].Key
	}
	return ""
}

func findPlayable(items []core.KindItem) *core.KindItem {
	for i := range items {
		if items[i].Playable {
			return &items[i]
		}
	}
	return nil
}

func checkPlayableSource(kindPath string, i int, src core.PlayableSource) []Issue {
	var out []Issue
	field := fmt.Sprintf("%s/resolve sources[%d]", kindPath, i)
	switch src.Pattern {
	case "range", "download", "direct":
		if src.URL == "" && src.BlobRef == "" {
			out = append(out, Issue{Rule: "kinds", Field: field, Message: "pattern " + src.Pattern + " needs a url or blobRef"})
		}
	case "container":
		if src.Container == nil || len(src.Container.Volumes) == 0 {
			out = append(out, Issue{Rule: "kinds", Field: field, Message: "container pattern needs container volumes"})
		} else if src.Container.Member == "" && src.Container.MemberIndex == nil {
			out = append(out, Issue{Rule: "kinds", Field: field, Message: "container pattern needs a member name or memberIndex"})
		}
	case "release":
		if src.Release == nil {
			out = append(out, Issue{Rule: "kinds", Field: field, Message: "release pattern needs a release hint"})
		}
	default:
		out = append(out, Issue{Rule: "kinds", Field: field, Message: "unknown pattern " + src.Pattern})
	}
	for _, ph := range urlPlaceholderRe.FindAllString(src.URL, -1) {
		if !knownURLPlaceholders[ph] {
			out = append(out, Issue{Rule: "kinds", Field: field, Message: "url placeholder " + ph + " is not one Ether substitutes"})
		}
	}
	return out
}

// Package holds an unpacked or directory-loaded plugin ready for checking
// or packing.
type Package struct {
	ManifestRaw json.RawMessage
	Manifest    plugins.Manifest
	Files       map[string][]byte
	Dir         string
}

// Issue is one error or warning found by the conformance kit.
type Issue struct {
	Rule    string `json:"rule"`
	Field   string `json:"field,omitempty"`
	Message string `json:"message"`
}

func (i Issue) String() string {
	if i.Field != "" {
		return fmt.Sprintf("[%s] %s: %s", i.Rule, i.Field, i.Message)
	}
	return fmt.Sprintf("[%s] %s", i.Rule, i.Message)
}

// HotTiming records the outcome and timing of the 10k-candidate hot-path check.
type HotTiming struct {
	Candidates    int     `json:"candidates"`
	Batches       int     `json:"batches"`
	TotalMS       float64 `json:"totalMs"`
	MaxBatchMS    float64 `json:"maxBatchMs"`
	PerCandP95MS  float64 `json:"perCandidateP95Ms"`
	SlowCount     int     `json:"slowCandidates"`
	Deterministic bool    `json:"deterministic"`
}

func (r *Report) addErr(rule, field, msg string) {
	r.Errors = append(r.Errors, Issue{Rule: rule, Field: field, Message: msg})
	r.OK = false
}

func (r *Report) addWarn(rule, field, msg string) {
	r.Warnings = append(r.Warnings, Issue{Rule: rule, Field: field, Message: msg})
}

// JSON returns the report as indented JSON bytes.
func (r Report) JSON() ([]byte, error) {
	return json.MarshalIndent(r, "", "  ")
}

// Text renders the report in plain human-readable text.
func (r Report) Text() string {
	var b strings.Builder
	title := r.PluginID
	if title == "" {
		title = "(unidentified plugin)"
	}
	if r.Version != "" {
		title += " " + r.Version
	}
	if r.Kind != "" {
		title += " (" + r.Kind + ")"
	}
	status := "PASS"
	if !r.OK {
		status = "FAIL"
	}
	fmt.Fprintf(&b, "%s: %s (%.1fms)\n", status, title, r.DurationMS)
	for _, e := range r.Errors {
		fmt.Fprintf(&b, "  error: %s\n", e.String())
	}
	for _, w := range r.Warnings {
		fmt.Fprintf(&b, "  warn:  %s\n", w.String())
	}
	if len(r.Routes) > 0 {
		fmt.Fprintf(&b, "  routes:\n")
		for _, rt := range r.Routes {
			mark := "ok"
			if !rt.OK {
				mark = "fail"
			}
			if rt.Skipped {
				mark = "live test needed"
			}
			fmt.Fprintf(&b, "    %s %s %s -> %d (%.2fms / %dms)\n", mark, rt.Method, rt.Route, rt.Status, rt.DurationMS, rt.DeadlineMS)
		}
	}
	if r.HotPath != nil {
		fmt.Fprintf(&b, "  hot path: %d candidates in %d batches (%.1fms total, max batch %.2fms, slow %d, deterministic=%t)\n",
			r.HotPath.Candidates, r.HotPath.Batches, r.HotPath.TotalMS, r.HotPath.MaxBatchMS, r.HotPath.SlowCount, r.HotPath.Deterministic)
	}
	return b.String()
}

// Load reads a plugin from a directory path or an .etherpkg file path.
func Load(target string) (*Package, error) {
	info, err := os.Stat(target)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		return LoadDir(target)
	}
	b, err := os.ReadFile(target)
	if err != nil {
		return nil, err
	}
	return LoadPkgBytes(b)
}

// LoadDir loads a plugin package from a filesystem directory.
func LoadDir(dir string) (*Package, error) {
	files := map[string][]byte{}
	err := filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(dir, p)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if rel == "." {
			return nil
		}
		if d.IsDir() {
			if d.Name() == ".git" || d.Name() == "node_modules" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(rel, ".etherpkg") {
			return nil
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		files[rel] = b
		return nil
	})
	if err != nil {
		return nil, err
	}
	manRaw, ok := files["manifest.json"]
	if !ok {
		return nil, fmt.Errorf("kit: directory %s has no manifest.json", dir)
	}
	man, err := plugins.ParseManifest(manRaw)
	if err != nil {
		return &Package{ManifestRaw: manRaw, Files: files, Dir: dir}, err
	}
	pkg := &Package{ManifestRaw: manRaw, Manifest: man, Files: files, Dir: dir}
	if man.Ether != nil && man.Ether.Runtime.Kind == "hosted" && isTSPath(man.Ether.Runtime.Entry) {
		entry := man.Ether.Runtime.Entry
		if isUnsafePath(entry) {
			return nil, fmt.Errorf("kit: unsafe entry %q", entry)
		}
		result := api.Build(api.BuildOptions{AbsWorkingDir: mustAbs(dir), EntryPoints: []string{entry}, Bundle: true, Write: false, Format: api.FormatIIFE, GlobalName: "__plugin", Platform: api.PlatformNeutral, Target: api.ES2020, LogLevel: api.LogLevelSilent})
		if len(result.Errors) != 0 {
			return nil, fmt.Errorf("kit: bundle: %s", result.Errors[0].Text)
		}
		manRaw, err = withEntry(manRaw, bundleEntry)
		if err != nil {
			return nil, err
		}
		man, err = plugins.ParseManifest(manRaw)
		if err != nil {
			return nil, err
		}
		files[bundleEntry] = result.OutputFiles[0].Contents
		files["manifest.json"] = manRaw
		pkg.ManifestRaw, pkg.Manifest = manRaw, man
	}
	return pkg, nil
}

// LoadPkgBytes loads a plugin package from .etherpkg zip bytes, verifying
// the digest entry when present.
func LoadPkgBytes(raw []byte) (*Package, error) {
	zr, err := zip.NewReader(bytes.NewReader(raw), int64(len(raw)))
	if err != nil {
		return nil, fmt.Errorf("kit: open package: %w", err)
	}
	files := map[string][]byte{}
	var total int64
	for _, f := range zr.File {
		name := strings.TrimPrefix(filepath.ToSlash(f.Name), "./")
		if f.FileInfo().IsDir() || isUnsafePath(name) || strings.HasPrefix(name, "__MACOSX") {
			continue
		}
		rc, err := f.Open()
		if err != nil {
			return nil, err
		}
		b, err := io.ReadAll(io.LimitReader(rc, 64<<20))
		_ = rc.Close()
		if err != nil {
			return nil, err
		}
		total += int64(len(b))
		if total > 128<<20 {
			return nil, fmt.Errorf("kit: package exceeds 128 MiB limit")
		}
		files[name] = b
	}
	manRaw, ok := files["manifest.json"]
	if !ok {
		return nil, fmt.Errorf("kit: package has no manifest.json")
	}
	if d, ok := files["digest"]; ok {
		want := plugins.PkgDigest(files)
		if strings.TrimSpace(string(d)) != want {
			return nil, fmt.Errorf("kit: package digest mismatch")
		}
	}
	man, err := plugins.ParseManifest(manRaw)
	if err != nil {
		return &Package{ManifestRaw: manRaw, Files: files}, err
	}
	return &Package{ManifestRaw: manRaw, Manifest: man, Files: files}, nil
}

// Pack compiles any TypeScript entry via wasm.Compile, bundles manifest,
// compiled JS/WASM, assets, schema, strings, and writes the verified
// `digest` entry into an installable .etherpkg archive.
func Pack(pkg *Package) ([]byte, error) {
	if pkg == nil || len(pkg.ManifestRaw) == 0 {
		return nil, fmt.Errorf("kit: pack: empty package")
	}
	man, err := plugins.ParseManifest(pkg.ManifestRaw)
	if err != nil {
		return nil, err
	}
	if err := man.Validate(); err != nil {
		return nil, err
	}
	outFiles := map[string][]byte{}
	for k, v := range pkg.Files {
		if k == "digest" || strings.HasPrefix(k, "tests/") || strings.HasSuffix(k, ".test.js") || strings.HasSuffix(k, ".test.ts") {
			continue
		}
		outFiles[k] = v
	}
	outFiles["manifest.json"] = pkg.ManifestRaw

	if man.Ether != nil && man.Ether.Runtime.Kind == "hosted" && man.Ether.Runtime.Entry != "" {
		entry := man.Ether.Runtime.Entry
		if _, hasEntry := outFiles[entry]; !hasEntry {
			// Look for a TypeScript source that compiles to entry (e.g. src/index.ts -> dist/plugin.js).
			tsEntry := findTSEntry(pkg.Files, entry)
			if tsEntry == "" {
				return nil, fmt.Errorf("kit: pack: entry %q not found and no TypeScript source found", entry)
			}
			srcMap := collectSources(pkg.Files)
			js, smap, diags := wasm.Compile(srcMap, tsEntry)
			if err := compileDiagsError(diags); err != nil {
				return nil, err
			}
			outFiles[entry] = js
			if len(smap) > 0 {
				outFiles[entry+".map"] = smap
			}
		} else if isTSPath(entry) {
			// The bundle goes to a .js entry and the manifest follows it,
			// keeping the source beside it. Left at the .ts path, the host
			// would compile the bundle again and its exports would vanish
			// inside the second wrapper.
			srcMap := collectSources(pkg.Files)
			js, smap, diags := wasm.Compile(srcMap, entry)
			if err := compileDiagsError(diags); err != nil {
				return nil, err
			}
			manRaw, err := withEntry(pkg.ManifestRaw, bundleEntry)
			if err != nil {
				return nil, err
			}
			outFiles["manifest.json"] = manRaw
			outFiles[bundleEntry] = js
			delete(outFiles, bundleEntry+".map")
			if len(smap) > 0 {
				outFiles[bundleEntry+".map"] = smap
			}
		}
	}

	// Compute deterministic digest over sorted package files.
	outFiles["digest"] = []byte(plugins.PkgDigest(outFiles))

	names := make([]string, 0, len(outFiles))
	for name := range outFiles {
		names = append(names, name)
	}
	sort.Strings(names)

	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	for _, name := range names {
		w, err := zw.Create(name)
		if err != nil {
			_ = zw.Close()
			return nil, err
		}
		if _, err := w.Write(outFiles[name]); err != nil {
			_ = zw.Close()
			return nil, err
		}
	}
	if err := zw.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// withEntry returns manifest JSON whose hosted runtime entry is entry.
func withEntry(manRaw []byte, entry string) ([]byte, error) {
	var doc map[string]any
	if err := json.Unmarshal(manRaw, &doc); err != nil {
		return nil, err
	}
	ether, _ := doc["ether"].(map[string]any)
	runtime, _ := ether["runtime"].(map[string]any)
	if runtime == nil {
		return nil, fmt.Errorf("kit: manifest runtime is missing")
	}
	runtime["entry"] = entry
	return json.Marshal(doc)
}

func isTSPath(p string) bool {
	ext := strings.ToLower(path.Ext(p))
	return ext == ".ts" || ext == ".tsx" || ext == ".mts"
}

func findTSEntry(files map[string][]byte, entry string) string {
	candidates := []string{
		strings.TrimSuffix(entry, path.Ext(entry)) + ".ts",
		"src/index.ts",
		"src/plugin.ts",
		"index.ts",
		"plugin.ts",
	}
	for _, c := range candidates {
		if _, ok := files[c]; ok {
			return c
		}
	}
	return ""
}

func collectSources(files map[string][]byte) map[string]string {
	out := map[string]string{}
	for k, v := range files {
		ext := strings.ToLower(path.Ext(k))
		if ext == ".ts" || ext == ".tsx" || ext == ".mts" || ext == ".js" || ext == ".json" {
			out[k] = string(v)
		}
	}
	return out
}

func compileDiagsError(diags []wasm.Diagnostic) error {
	var errs []string
	for _, d := range diags {
		if d.Severity == "error" {
			if d.File != "" && d.Line > 0 {
				errs = append(errs, fmt.Sprintf("%s:%d:%d: %s", d.File, d.Line, d.Column, d.Text))
			} else {
				errs = append(errs, d.Text)
			}
		}
	}
	if len(errs) == 0 {
		return nil
	}
	return fmt.Errorf("compile: %s", strings.Join(errs, "; "))
}

func isUnsafePath(p string) bool {
	return p != "" && (strings.HasPrefix(p, "/") || strings.Contains(p, ".."))
}

// CheckInstall adapts the conformance report to the plugin host's validation error.
func CheckInstall(ctx context.Context, manifest []byte, files map[string][]byte) error {
	report := Check(ctx, &Package{ManifestRaw: manifest, Files: files})
	if report.OK {
		return nil
	}
	fields := make([]plugins.FieldError, 0, len(report.Errors))
	for _, issue := range report.Errors {
		fields = append(fields, plugins.FieldError{Field: issue.Field, Message: issue.Message})
	}
	return &plugins.ValidationError{Fields: fields}
}

// TemplateOptions configures a scaffolded plugin project.
type TemplateOptions struct {
	Kind string // source|integration|notification_channel|livetv_source|extension
	Lang string // ts|js|python
	Dir  string
	ID   string
	Name string
}

// Scaffold generates a minimal working plugin for the requested kind and
// language in opts.Dir. Every generated template passes kit.Check out of
// the box.
func Scaffold(opts TemplateOptions) error {
	if opts.Kind == "" {
		opts.Kind = string(plugins.KindLiveTVSource)
	}
	switch plugins.Kind(opts.Kind) {
	case plugins.KindSource, plugins.KindIntegration, plugins.KindNotificationChannel, plugins.KindLiveTVSource, plugins.KindExtension:
	default:
		return fmt.Errorf("unknown plugin kind %q (must be source, integration, notification_channel, livetv_source or extension)", opts.Kind)
	}
	if opts.Lang == "" {
		opts.Lang = "ts"
	}
	switch opts.Lang {
	case "ts", "js", "python":
	default:
		return fmt.Errorf("unknown language %q (must be ts, js or python)", opts.Lang)
	}
	if opts.Dir == "" {
		return fmt.Errorf("target directory is required")
	}
	if entries, err := os.ReadDir(opts.Dir); err == nil {
		if len(entries) != 0 {
			return fmt.Errorf("target directory %q is not empty", opts.Dir)
		}
	} else if !os.IsNotExist(err) {
		return err
	}
	base := strings.ToLower(filepath.Base(opts.Dir))
	slug := strings.Trim(slugCleanRe.ReplaceAllString(base, "-"), "-")
	if slug == "" || !(slug[0] >= 'a' && slug[0] <= 'z') {
		slug = "sample-" + slug
		slug = strings.Trim(slug, "-")
	}
	if opts.ID == "" {
		opts.ID = "community.example." + strings.ReplaceAll(slug, "-", "")
	}
	if opts.Name == "" {
		opts.Name = humanName(slug)
	}

	files, err := GenerateTemplateFiles(opts)
	if err != nil {
		return err
	}
	for rel, content := range files {
		full := filepath.Join(opts.Dir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(full, content, 0o644); err != nil {
			return err
		}
	}
	return nil
}

func humanName(slug string) string {
	parts := strings.Split(slug, "-")
	for i, p := range parts {
		if len(p) > 0 {
			if i == 0 {
				parts[i] = strings.ToUpper(p[:1]) + p[1:]
			} else {
				parts[i] = p
			}
		}
	}
	name := strings.Join(parts, " ")
	if name == "" {
		return "Sample plugin"
	}
	return name
}

