    return 404, {"error": {"code": "not_found", "message": "Route not found"}}


class PluginHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        status, payload = handle_request("GET", self.path.split("?")[0], dict(self.headers), b"")
        self._respond(status, payload)

    def do_POST(self):
