// ParseSemVer parses a plain major.minor.patch version.
func ParseSemVer(v string) ([3]int, bool) {
	var out [3]int
	v = strings.TrimPrefix(strings.TrimSpace(v), "v")
	if i := strings.IndexAny(v, "-+"); i >= 0 {
		v = v[:i]
	}
	parts := strings.Split(v, ".")
	if len(parts) != 3 {
		return out, false
	}
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n < 0 {
			return out, false
		}
		out[i] = n
	}
	return out, true
}

// CompareSemVer returns -1, 0 or 1. Unparseable versions compare equal to 0.
func CompareSemVer(a, b string) int {
	va, _ := ParseSemVer(a)
	vb, _ := ParseSemVer(b)
	for i := 0; i < 3; i++ {
		if va[i] != vb[i] {
			if va[i] < vb[i] {
				return -1
			}
			return 1
		}
	}
	// A release sorts after any prerelease of the same core version.
	pre := func(v string) string {
		v, _, _ = strings.Cut(v, "+")
		_, p, _ := strings.Cut(v, "-")
		return p
	}
	pa, pb := pre(a), pre(b)
	if pa == pb {
		return 0
	}
	if pa == "" {
		return 1
	}
	if pb == "" {
		return -1
	}
	as, bs := strings.Split(pa, "."), strings.Split(pb, ".")
	for i := 0; i < len(as) && i < len(bs); i++ {
		x, y := as[i], bs[i]
		if x == y {
			continue
		}
		isNumeric := func(s string) bool {
			if s == "" {
				return false
			}
			for _, c := range s {
				if c < '0' || c > '9' {
					return false
				}
			}
			return true
		}
		xn, yn := isNumeric(x), isNumeric(y)
		if xn != yn {
			if xn {
				return -1
			}
			return 1
		}
		if xn {
			x, y = strings.TrimLeft(x, "0"), strings.TrimLeft(y, "0")
			if len(x) < len(y) {
				return -1
			}
			if len(x) > len(y) {
				return 1
			}
		}
		if x < y {
			return -1
		}
		if x > y {
			return 1
		}
	}
	if len(as) < len(bs) {
		return -1
	}
	if len(as) > len(bs) {
		return 1
	}
	return 0
}

