func validateMediaKinds(m Manifest, add func(string, string), label func(string, string, int)) {
	e := m.Ether
	kinds := e.Contributes.MediaKinds
	hasProvider := m.HasCapability(CapCatalogProvider)
	hasResolver := m.HasCapability(CapKindResolver)
	if e.Kind == KindContent && !hasProvider && !hasResolver {
		add("ether.capabilities", "a content plugin needs catalog_provider or kind_resolver")
	}
	if (hasProvider || hasResolver) && len(kinds) == 0 {
		add("ether.contributes.mediaKinds", "is required for catalog_provider and kind_resolver")
	}
	if !hasProvider && !hasResolver && len(kinds) > 0 {
		add("ether.contributes.mediaKinds", "needs the catalog_provider or kind_resolver capability")
	}
	seen := map[string]bool{}
	for i, k := range kinds {
		base := fmt.Sprintf("ether.contributes.mediaKinds[%d]", i)
		validateMediaKind(m, k, base, hasProvider, add, label)
		if seen[k.Key] {
			add(base+".key", "is listed twice")
		}
		seen[k.Key] = true
	}
}

func validateMediaKind(m Manifest, k MediaKindMeta, base string, hasProvider bool, add func(string, string), label func(string, string, int)) {
	if !kindKeyRe.MatchString(k.Key) {
		add(base+".key", "must be lower case letters, digits and dashes, at most 32 characters")
	}
	label(base+".label", k.Label, 60)
	if k.Library != (KindLibraryDecl{}) {
		label(base+".library.name", k.Library.Name, 60)
		if unsafePath(k.Library.Icon) {
			add(base+".library.icon", "must stay inside the package")
		}
	}

	if len(k.Levels) < 1 || len(k.Levels) > 5 {
		add(base+".levels", "must declare one to five levels")
	}
	levelKeys := map[string]bool{}
	playable := false
	for j, lv := range k.Levels {
		lbase := fmt.Sprintf("%s.levels[%d]", base, j)
		if !kindKeyRe.MatchString(lv.Key) {
			add(lbase+".key", "must be lower case letters, digits and dashes, at most 32 characters")
		}
		if levelKeys[lv.Key] {
			add(lbase+".key", "is listed twice")
		}
		levelKeys[lv.Key] = true
		label(lbase+".label", lv.Label, 40)
		if lv.Playable {
			playable = true
		}
	}
	if len(k.Levels) > 0 && !playable {
		add(base+".levels", "at least one level must be playable")
	}

	fields := map[string]KindField{}
	for j, f := range k.Fields {
		fbase := fmt.Sprintf("%s.fields[%d]", base, j)
		switch {
		case !kindFieldRe.MatchString(f.Key):
			add(fbase+".key", "must start with a lower case letter and use letters, digits and underscores, at most 40 characters")
		case kindEnvelopeKeys[f.Key]:
			add(fbase+".key", "collides with an item envelope key")
		case fields[f.Key].Key != "":
			add(fbase+".key", "is listed twice")
		}
		fields[f.Key] = f
		if !kindFieldTypes[f.Type] {
			add(fbase+".type", "must be string, int, float, bool, date, duration, enum, strings or people")
		}
		label(fbase+".label", f.Label, 40)
		if f.Type == "enum" {
			if len(f.Enum) == 0 {
				add(fbase+".enum", "an enum field needs at least one value")
			}
			seenEnum := map[string]bool{}
			for _, v := range f.Enum {
				if strings.TrimSpace(v) == "" || seenEnum[v] {
					add(fbase+".enum", "values must be non-empty and listed once")
					break
				}
				seenEnum[v] = true
			}
		} else if len(f.Enum) > 0 {
			add(fbase+".enum", "only enum fields list values")
		}
	}

	seenArt := map[string]bool{}
	for j, a := range k.Art {
		abase := fmt.Sprintf("%s.art[%d]", base, j)
		switch {
		case !kindArtRe.MatchString(a.Role):
			add(abase+".role", "must be lower case letters, digits and dashes, at most 32 characters")
		case BuiltinKindArtRoles[a.Role]:
			add(abase+".role", "is a built-in role and needs no declaration")
		case seenArt[a.Role]:
			add(abase+".role", "is listed twice")
		}
		seenArt[a.Role] = true
		label(abase+".label", a.Label, 40)
	}

	validatePresentations(m, k, base+".present", levelKeys, add)

	seenSort := map[string]bool{}
	for j, s := range k.Browse.Sorts {
		if !kindSorts[s] || seenSort[s] {
			add(fmt.Sprintf("%s.browse.sorts[%d]", base, j), "must be title, added, released, year, rating or index, listed once")
		}
		seenSort[s] = true
	}
	for j, f := range k.Browse.Facets {
		if f == "year" || f == "released" || f == "rating" {
			continue
		}
		field, ok := fields[f]
		if !ok {
			add(fmt.Sprintf("%s.browse.facets[%d]", base, j), "must name a declared field")
		} else if !field.Indexed {
			add(fmt.Sprintf("%s.browse.facets[%d]", base, j), "a facet field must be indexed")
		}
	}
	for j, f := range k.Browse.SearchFields {
		field, ok := fields[f]
		if !ok {
			add(fmt.Sprintf("%s.browse.searchFields[%d]", base, j), "must name a declared field")
		} else if field.Type != "string" && field.Type != "strings" && field.Type != "people" {
			add(fmt.Sprintf("%s.browse.searchFields[%d]", base, j), "a search field must hold text")
		}
	}
	if len(k.Browse.SearchFields) > 0 && !k.Browse.Search {
		add(base+".browse.search", "searchFields need search to be set")
	}
	if k.Browse.LiveSearch && !hasProvider {
		add(base+".browse.liveSearch", "live search needs the catalog_provider capability")
	}

	switch k.Sync.Mode {
	case "":
		if hasProvider && k.HasLibrary() {
			add(base+".sync.mode", "a catalog provider kind must be pull or push")
		}
	case KindSyncPull, KindSyncPush:
		if !hasProvider {
			add(base+".sync.mode", "sync needs the catalog_provider capability")
		}
	case "ondemand":
		add(base+".sync.mode", "ondemand is not supported; kinds sync with pull or push")
	default:
		add(base+".sync.mode", "must be pull or push")
	}
	if k.Sync.Refresh != "" {
		if k.Sync.Mode != KindSyncPull {
			add(base+".sync.refresh", "only pull kinds refresh on a schedule")
		} else if d, err := time.ParseDuration(k.Sync.Refresh); err != nil || d < 15*time.Minute {
			add(base+".sync.refresh", "must be a duration of at least 15m")
		}
	}
	if k.Cache.MaxBytes < 0 {
		add(base+".cache.maxBytes", "must not be negative")
	}
	if k.Cache.TTL != "" {
		if d, err := time.ParseDuration(k.Cache.TTL); err != nil || d <= 0 {
			add(base+".cache.ttl", "must be a positive duration")
		}
	}
	if k.Match.ThresholdDefault < 0 || k.Match.ThresholdDefault > 1 {
		add(base+".match.thresholdDefault", "must be between 0 and 1")
	}
}

func validatePresentations(m Manifest, k MediaKindMeta, base string, levelKeys map[string]bool, add func(string, string)) {
	p := k.Present
	protocols := 0
	if p.Plex != nil {
		protocols++
	}
	if p.MediaBrowser != nil {
		protocols++
	}
	if p.Stremio != nil {
		protocols++
	}
	if p.Xtream != nil {
		protocols++
	}
	if p.Silo != nil {
		protocols++
	}
	if p.AdapterOnly {
		if protocols > 0 {
			add(base, "adapterOnly cannot be combined with a protocol presentation")
		}
		if !m.HasCapability(CapFrontendAdapter) {
			add(base+".adapterOnly", "needs a frontend adapter")
		}
		return
	}
	if protocols == 0 {
		if k.HasLibrary() {
			add(base, "declare at least one protocol presentation, or adapterOnly with a frontend adapter")
		}
		return
	}
	levels := len(k.Levels)
	if p.Plex != nil {
		switch p.Plex.Base {
		case "movie", "photo":
		case "show", "artist":
			if levels < 2 {
				add(base+".plex.base", p.Plex.Base+" needs at least two levels")
			}
		default:
			add(base+".plex.base", "must be movie, show, artist or photo")
		}
	}
	if p.MediaBrowser != nil {
		if !mediaBrowserCollectionTypes[p.MediaBrowser.CollectionType] {
			add(base+".mediaBrowser.collectionType", "must be movies, tvshows, music, audiobooks, books, photos or homevideos")
		}
		for level, itemType := range p.MediaBrowser.ItemTypes {
			if !levelKeys[level] {
				add(base+".mediaBrowser.itemTypes", "unknown level "+level)
			}
			if !mediaBrowserItemTypes[itemType] {
				add(base+".mediaBrowser.itemTypes", "unknown item type "+itemType)
			}
		}
	}
	if p.Stremio != nil {
		switch p.Stremio.Type {
		case "movie", "channel", "tv":
		case "series":
			if levels < 2 {
				add(base+".stremio.type", "series needs at least two levels")
			}
		default:
			add(base+".stremio.type", "must be movie, series, channel or tv")
		}
	}
	if p.Xtream != nil {
		switch p.Xtream.Category {
		case "movie", "live":
		case "series":
			if levels < 2 {
				add(base+".xtream.category", "series needs at least two levels")
			}
		default:
			add(base+".xtream.category", "must be movie, series or live")
		}
	}
	if p.Silo != nil && !mediaBrowserItemTypes[p.Silo.Type] {
		add(base+".silo.type", "must be a MediaBrowser item type such as Movie or Series")
	}
}

func validateFrontendAdapters(m Manifest, add func(string, string), label func(string, string, int)) {
	adapters := m.Ether.Contributes.FrontendAdapters
	if m.HasCapability(CapFrontendAdapter) && len(adapters) == 0 {
		add("ether.contributes.frontendAdapters", "is required for frontend_adapter")
	}
	if !m.HasCapability(CapFrontendAdapter) && len(adapters) > 0 {
		add("ether.contributes.frontendAdapters", "needs the frontend_adapter capability")
	}
	seen := map[string]bool{}
	for i, a := range adapters {
		base := fmt.Sprintf("ether.contributes.frontendAdapters[%d]", i)
		if !kindKeyRe.MatchString(a.Key) || seen[a.Key] {
			add(base+".key", "must be a unique lower case key, at most 32 characters")
		}
		seen[a.Key] = true
		label(base+".label", a.Label, 60)
		if !map[string]bool{"opds": true, "subsonic": true, "custom": true}[a.ProtocolHint] {
			add(base+".protocolHint", "must be opds, subsonic or custom")
		}
		if !strings.HasPrefix(a.PathPrefix, "/") || a.PathPrefix == "/" {
			add(base+".pathPrefix", "must be a path below the shared listener root, such as /opds")
		}
		if a.DefaultPort < 0 || a.DefaultPort > 65535 {
			add(base+".defaultPort", "must be a port number")
		}
		if a.Auth != "" && !map[string]bool{"ether_token": true, "basic": true, "none_lan": true}[a.Auth] {
			add(base+".auth", "must be ether_token, basic or none_lan")
		}
		seenLib := map[string]bool{}
		for j, key := range a.Libraries {
			if !kindKeyRe.MatchString(key) || seenLib[key] {
				add(fmt.Sprintf("%s.libraries[%d]", base, j), "must name a declared media kind key")
			}
			seenLib[key] = true
			if _, ok := m.MediaKindByKey(key); !ok {
				add(fmt.Sprintf("%s.libraries[%d]", base, j), "must name a media kind declared by this plugin")
			}
		}
	}
}

// MediaKindByKey returns the declared kind with this key, if any.
func (m Manifest) MediaKindByKey(key string) (MediaKindMeta, bool) {
	if e := m.EffectiveEther(); e != nil {
		for _, k := range e.Contributes.MediaKinds {
			if k.Key == key {
				return k, true
			}
		}
	}
	return MediaKindMeta{}, false
}

// HasLibrary reports whether this media kind declares a library block.
// Creating a library is optional per kind: a kind without a library block
// (for example, a resolver-only kind) creates no library.
func (k MediaKindMeta) HasLibrary() bool {
	return strings.TrimSpace(k.Library.Name) != ""
}

// Level returns the declared level with this key and its position.
func (k MediaKindMeta) Level(key string) (KindLevel, int, bool) {
	for i, lv := range k.Levels {
		if lv.Key == key {
			return lv, i, true
		}
	}
	return KindLevel{}, -1, false
}

// DeclHash is the upgrade gate for an installed kind (spec §2.3/§2.5):
// the SHA-256 of the declaration's canonical JSON. Go marshals struct
// fields in declaration order and map keys sorted, so equal
// declarations always hash equal.
func (k MediaKindMeta) DeclHash() string {
	raw, _ := json.Marshal(k)
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// ValidateMediaKindsUpgrade applies the additive-only upgrade rule
// (spec §2.5): a new manifest may add kinds, fields, trailing levels
// and art roles, and may change labels, presentations, browse, cache
// and match defaults, but it may not drop or rename a kind, drop or
// retype a field, shrink an enum, drop a field's index, or remove,
// reorder or re-flag a level. A caller that gets an error refuses the
// upgrade unless the owner chose to replace the library contents.
func ValidateMediaKindsUpgrade(prev, next []MediaKindMeta) error {
	var f []FieldError
	add := func(field, msg string) { f = append(f, FieldError{field, msg}) }
	nextByKey := map[string]MediaKindMeta{}
	for _, k := range next {
		nextByKey[k.Key] = k
	}
	for _, old := range prev {
		base := "ether.contributes.mediaKinds." + old.Key
		nk, ok := nextByKey[old.Key]
		if !ok {
			add(base, "kind was removed; removing a kind needs the owner to replace its library")
			continue
		}
		for i, lv := range old.Levels {
			lbase := fmt.Sprintf("%s.levels[%d]", base, i)
			if i >= len(nk.Levels) {
				add(lbase, "level "+lv.Key+" was removed")
				continue
			}
			nl := nk.Levels[i]
			if nl.Key != lv.Key {
				add(lbase+".key", "levels cannot be removed or reordered; add new levels at the end")
			}
			if nl.Playable != lv.Playable || nl.Container != lv.Container {
				add(lbase, "level "+lv.Key+" changed its playable or container flag")
			}
		}
		nextFields := map[string]KindField{}
		for _, nf := range nk.Fields {
			nextFields[nf.Key] = nf
		}
		for _, of := range old.Fields {
			fbase := base + ".fields." + of.Key
			nf, ok := nextFields[of.Key]
			if !ok {
				add(fbase, "field was removed")
				continue
			}
			if nf.Type != of.Type {
				add(fbase+".type", "field changed type from "+of.Type+" to "+nf.Type)
			}
			if of.Indexed && !nf.Indexed {
				add(fbase+".indexed", "field lost its index")
			}
			if of.Type == "enum" && nf.Type == "enum" {
				have := map[string]bool{}
				for _, v := range nf.Enum {
					have[v] = true
				}
				for _, v := range of.Enum {
					if !have[v] {
						add(fbase+".enum", "enum value "+v+" was removed")
					}
				}
			}
		}
	}
	if len(f) > 0 {
		return &ValidationError{f}
	}
	return nil
}

// Host is the set of Ether services a remote plugin may call back
// into (SPEC §5.1.5). It mirrors plugins.Host method for method for
// the services remote plugins may use; secret.get is hosted-only and
// deliberately absent (remote plugins receive secrets in
// /ether/configure). Every method is expected to re-check the
// plugin's live grants and return ErrPermissionDenied when a grant
// is missing or revoked.
type Host interface {
	KVGet(ctx context.Context, pluginID, key string) ([]byte, bool, error)
	KVPut(ctx context.Context, pluginID, key string, value []byte) error
	KVDelete(ctx context.Context, pluginID, key string) error
	KVList(ctx context.Context, pluginID, prefix string) ([]string, error)

	CatalogSearch(ctx context.Context, pluginID, query string, limit, offset int) (json.RawMessage, error)
	CatalogGet(ctx context.Context, pluginID, id string) (json.RawMessage, error)

	ViewerGranted(ctx context.Context, pluginID string) (json.RawMessage, error)
	ViewerHistory(ctx context.Context, pluginID string, viewerID int64, limit, offset int) (json.RawMessage, error)
	SetWatchState(ctx context.Context, pluginID string, viewerID int64, titleID string, watched bool) error

	CollectionsUpsert(ctx context.Context, pluginID string, collection json.RawMessage) error

	KindUpsert(ctx context.Context, pluginID, kindKey string, items []core.KindItem) (int, error)
	KindDelete(ctx context.Context, pluginID, kindKey string, externalIDs []string) error
	KindItems(ctx context.Context, pluginID, kindKey, cursor string, limit int) (core.KindPage, error)
	ResolveSources(ctx context.Context, pluginID string, q core.SourceQuery) ([]core.SourceCandidate, error)
	CachePut(ctx context.Context, pluginID, libraryKey, name string, r io.Reader) (string, error)
	CacheOpen(ctx context.Context, pluginID, blobRef string) (io.ReadSeekCloser, error)

	// StreamURL mints a scoped stream ticket for one of the plugin's own
	// kind items for viewerID and returns the Ether stream URL (spec §6.5).
	StreamURL(ctx context.Context, pluginID string, viewerID int64, itemRef string) (string, error)

	Settings(ctx context.Context, pluginID string) (map[string]any, error)

	NotifyOwner(ctx context.Context, pluginID, text string) error
	Log(ctx context.Context, pluginID, level, msg string, attrs map[string]any) error
}

// Body caps for host calls. KV values get the largest allowance; the
// host's per-plugin quota still applies on top.
const (
	maxKVValueBytes    = 5 << 20
	maxHostBodyBytes   = 1 << 20
	maxCollectionBytes = 2 << 20
	maxKindUpsertBytes = 8 << 20
	maxCacheBlobBytes  = 256 << 20
	defaultPageLimit   = 50
	maxPageLimit       = 200
)

// HostHandler serves /ether/plugin-host/* for remote plugins. Every
// request is authenticated with a plugin credential; the resolved
// plugin id is the only identity a call can act as, so a plugin can
// never name another plugin in a request body and be believed.
type HostHandler struct {
	host Host
	auth CredentialResolver
	log  *slog.Logger
	mux  *http.ServeMux
}

// HostOptions configures a HostHandler.
type HostOptions struct {
	Host   Host
	Auth   CredentialResolver
	Logger *slog.Logger
}

// Mount registers the handler's routes on mux.
func (h *HostHandler) Mount(mux *http.ServeMux) {
	mux.Handle(HostPath, h)
}

func (h *HostHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if h.auth == nil || h.host == nil {
		writeHostError(w, http.StatusServiceUnavailable, "unavailable", "Plugin host API is not configured")
		return
	}
	pluginID, err := h.auth.ResolvePluginCredential(r.Context(), credentialFromRequest(r))
	if err != nil || pluginID == "" {
		writeHostError(w, http.StatusUnauthorized, "unauthorized", "Plugin credential rejected")
		return
	}
	r = r.WithContext(context.WithValue(r.Context(), pluginIDContextKey{}, pluginID))
	h.mux.ServeHTTP(w, r)
}

func pluginIDOf(r *http.Request) string {
	id, _ := r.Context().Value(pluginIDContextKey{}).(string)
	return id
}

func (h *HostHandler) kvGet(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	value, ok, err := h.host.KVGet(r.Context(), pluginIDOf(r), key)
	if !h.finishErr(w, err) {
		return
	}
	if !ok {
		writeHostError(w, http.StatusNotFound, "not_found", "No value for this key")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"key": key, "value": string(value)})
}

func (h *HostHandler) kvPut(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	var body struct {
		Value *string `json:"value"`
	}
	// Accept either {"value": "..."} or a raw text body: the SDKs send
	// JSON, hand-rolled sidecars often send the bare value.
	raw, err := readBody(w, r, maxKVValueBytes)
	if err != nil {
		h.finishErr(w, err)
		return
	}
	value := raw
	if strings.HasPrefix(r.Header.Get("Content-Type"), "application/json") {
		if err := json.Unmarshal(raw, &body); err != nil || body.Value == nil {
			writeHostError(w, http.StatusBadRequest, "invalid", `Body must be {"value": "..."}`)
			return
		}
		value = []byte(*body.Value)
	}
	if !h.finishErr(w, h.host.KVPut(r.Context(), pluginIDOf(r), key, value)) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (h *HostHandler) kvDelete(w http.ResponseWriter, r *http.Request) {
	if !h.finishErr(w, h.host.KVDelete(r.Context(), pluginIDOf(r), r.PathValue("key"))) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (h *HostHandler) kvList(w http.ResponseWriter, r *http.Request) {
	keys, err := h.host.KVList(r.Context(), pluginIDOf(r), r.URL.Query().Get("prefix"))
	if !h.finishErr(w, err) {
		return
	}
	if keys == nil {
		keys = []string{}
	}
	writeJSON(w, http.StatusOK, map[string]any{"keys": keys})
}

func (h *HostHandler) catalogSearch(w http.ResponseWriter, r *http.Request) {
	limit, offset := pageParams(r)
	out, err := h.host.CatalogSearch(r.Context(), pluginIDOf(r), r.URL.Query().Get("q"), limit, offset)
	h.writeRaw(w, out, err)
}

func (h *HostHandler) catalogGet(w http.ResponseWriter, r *http.Request) {
	out, err := h.host.CatalogGet(r.Context(), pluginIDOf(r), r.PathValue("id"))
	h.writeRaw(w, out, err)
}

func (h *HostHandler) viewerGranted(w http.ResponseWriter, r *http.Request) {
	out, err := h.host.ViewerGranted(r.Context(), pluginIDOf(r))
	h.writeRaw(w, out, err)
}

func (h *HostHandler) viewerHistory(w http.ResponseWriter, r *http.Request) {
	viewerID, err := strconv.ParseInt(r.PathValue("viewerId"), 10, 64)
	if err != nil || viewerID <= 0 {
		writeHostError(w, http.StatusBadRequest, "invalid", "viewerId must be a positive number")
		return
	}
	limit, offset := pageParams(r)
	out, err := h.host.ViewerHistory(r.Context(), pluginIDOf(r), viewerID, limit, offset)
	h.writeRaw(w, out, err)
}

func (h *HostHandler) setWatchState(w http.ResponseWriter, r *http.Request) {
	var body struct {
		ViewerID int64  `json:"viewerId"`
		TitleID  string `json:"titleId"`
		Watched  bool   `json:"watched"`
	}
	if !h.decode(w, r, maxHostBodyBytes, &body) {
		return
	}
	if body.ViewerID <= 0 || body.TitleID == "" {
		writeHostError(w, http.StatusBadRequest, "invalid", "viewerId and titleId are required")
		return
	}
	if !h.finishErr(w, h.host.SetWatchState(r.Context(), pluginIDOf(r), body.ViewerID, body.TitleID, body.Watched)) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (h *HostHandler) collectionsUpsert(w http.ResponseWriter, r *http.Request) {
	raw, err := readBody(w, r, maxCollectionBytes)
	if err != nil {
		h.finishErr(w, err)
		return
	}
	if !json.Valid(raw) {
		writeHostError(w, http.StatusBadRequest, "invalid", "Body must be a collection document as JSON")
		return
	}
	if !h.finishErr(w, h.host.CollectionsUpsert(r.Context(), pluginIDOf(r), raw)) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (h *HostHandler) kindItems(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	limit := defaultPageLimit
	if v, err := strconv.Atoi(q.Get("limit")); err == nil && v > 0 {
		limit = v
	}
	if limit > maxPageLimit {
		limit = maxPageLimit
	}
	page, err := h.host.KindItems(r.Context(), pluginIDOf(r), r.PathValue("kind"), q.Get("cursor"), limit)
	if !h.finishErr(w, err) {
		return
	}
	if page.Items == nil {
		page.Items = []core.KindItem{}
	}
	writeJSON(w, http.StatusOK, page)
}

func (h *HostHandler) kindUpsert(w http.ResponseWriter, r *http.Request) {
	raw, err := readBody(w, r, maxKindUpsertBytes)
	if err != nil {
		h.finishErr(w, err)
		return
	}
	var items []core.KindItem
	var envelope struct {
		Items []core.KindItem `json:"items"`
	}
	if err := json.Unmarshal(raw, &envelope); err == nil && envelope.Items != nil {
		items = envelope.Items
	} else if err := json.Unmarshal(raw, &items); err != nil {
		writeHostError(w, http.StatusBadRequest, "invalid", `Body must be {"items": [...]} or a JSON array of KindItem`)
		return
	}
	accepted, err := h.host.KindUpsert(r.Context(), pluginIDOf(r), r.PathValue("kind"), items)
	if !h.finishErr(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true, "accepted": accepted})
}

func (h *HostHandler) kindDelete(w http.ResponseWriter, r *http.Request) {
	raw, err := readBody(w, r, maxHostBodyBytes)
	if err != nil {
		h.finishErr(w, err)
		return
	}
	var ids []string
	var envelope struct {
		IDs         []string `json:"ids"`
		ExternalIDs []string `json:"externalIds"`
	}
	if err := json.Unmarshal(raw, &envelope); err == nil && (envelope.IDs != nil || envelope.ExternalIDs != nil) {
		ids = envelope.IDs
		if len(ids) == 0 {
			ids = envelope.ExternalIDs
		}
	} else if err := json.Unmarshal(raw, &ids); err != nil {
		writeHostError(w, http.StatusBadRequest, "invalid", `Body must be {"ids": [...]} or a JSON array of item ids`)
		return
	}
	if !h.finishErr(w, h.host.KindDelete(r.Context(), pluginIDOf(r), r.PathValue("kind"), ids)) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (h *HostHandler) resolveSources(w http.ResponseWriter, r *http.Request) {
	var q core.SourceQuery
	if !h.decode(w, r, maxHostBodyBytes, &q) {
		return
	}
	cands, err := h.host.ResolveSources(r.Context(), pluginIDOf(r), q)
	if !h.finishErr(w, err) {
		return
	}
	if cands == nil {
		cands = []core.SourceCandidate{}
	}
	writeJSON(w, http.StatusOK, map[string]any{"candidates": cands})
}

func (h *HostHandler) cachePut(w http.ResponseWriter, r *http.Request) {
	libraryKey := r.PathValue("libraryKey")
	name := r.PathValue("name")
	if name == "" {
		name = r.URL.Query().Get("name")
	}
	body := io.LimitReader(r.Body, maxCacheBlobBytes+1)
	ref, err := h.host.CachePut(r.Context(), pluginIDOf(r), libraryKey, name, body)
	if !h.finishErr(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true, "blob": ref})
}

func (h *HostHandler) cacheOpen(w http.ResponseWriter, r *http.Request) {
	rc, err := h.host.CacheOpen(r.Context(), pluginIDOf(r), r.PathValue("blobRef"))
	if !h.finishErr(w, err) {
		return
	}
	defer rc.Close()
	w.Header().Set("Cache-Control", "no-store")
	http.ServeContent(w, r, "", time.Time{}, rc)
}

// frontendStreamURL mints a scoped stream ticket for one of the plugin's
// own kind items and returns the Ether stream URL (spec §6.5). The viewer
// id is the one the adapter proxied the request for.
func (h *HostHandler) frontendStreamURL(w http.ResponseWriter, r *http.Request) {
