func (h *HostHandler) writeRaw(w http.ResponseWriter, out json.RawMessage, err error) {
	if !h.finishErr(w, err) {
		return
	}
	if len(out) == 0 {
		out = json.RawMessage("null")
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(out)
}

func (h *HostHandler) decode(w http.ResponseWriter, r *http.Request, max int64, into any) bool {
	raw, err := readBody(w, r, max)
	if err != nil {
		h.finishErr(w, err)
		return false
	}
	if err := json.Unmarshal(raw, into); err != nil {
		writeHostError(w, http.StatusBadRequest, "invalid", "Body is not valid JSON")
		return false
	}
	return true
}

// finishErr maps a host error onto the EPP error shape and reports
// whether the handler may continue. Host errors are mapped, never
// echoed raw: a storage error must not leak SQL or paths to a
// plugin.
func (h *HostHandler) finishErr(w http.ResponseWriter, err error) bool {
	if err == nil {
		return true
	}
	switch {
	case errors.Is(err, ErrPermissionDenied):
		writeHostError(w, http.StatusForbidden, "permission_denied", "This plugin does not have the grant this call needs")
	case errors.Is(err, ErrNotFound):
		writeHostError(w, http.StatusNotFound, "not_found", "Not found")
	case errors.Is(err, ErrTooLarge):
		writeHostError(w, http.StatusRequestEntityTooLarge, "too_large", "Request body is too large")
	case errors.Is(err, ErrInvalid):
		writeHostError(w, http.StatusBadRequest, "invalid", cleanMessage(err))
	case errors.Is(err, ErrUnavailable):
		writeHostError(w, http.StatusServiceUnavailable, "unavailable", "This host service is not available")
	case errors.Is(err, ErrUnauthorized):
		writeHostError(w, http.StatusUnauthorized, "unauthorized", "Plugin credential rejected")
	case errors.Is(err, context.DeadlineExceeded):
		writeHostError(w, http.StatusGatewayTimeout, "deadline", "The call ran past its deadline")
	default:
		h.log.Warn("plugin host call failed", "err", err)
		writeHostError(w, http.StatusInternalServerError, "error", "The host call failed")
	}
	return false
}

// cleanMessage strips the sentinel prefix from an ErrInvalid so the
// plugin sees the specific reason ("path escapes...") only.
func cleanMessage(err error) string {
	msg := err.Error()
	msg = strings.TrimPrefix(msg, "remote: invalid request: ")
	msg = strings.TrimPrefix(msg, "remote: invalid request")
	if msg == "" {
		return "The request is not valid"
	}
	return msg
}

// pageParams reads limit/offset, or page/pageSize, clamped.
func pageParams(r *http.Request) (limit, offset int) {
	q := r.URL.Query()
	limit = defaultPageLimit
	if v, err := strconv.Atoi(q.Get("limit")); err == nil && v > 0 {
		limit = v
	}
	if v, err := paging.ParseOffset(q.Get("offset"), limit); err == nil && v >= 0 {
		offset = v
	}
	if q.Get("page") != "" {
		pageSize := limit
		if v, err := strconv.Atoi(q.Get("pageSize")); err == nil && v > 0 {
			pageSize = v
		}
		if v, err := strconv.Atoi(q.Get("page")); err == nil && v >= 1 {
			limit = pageSize
			offset = paging.PageOffset(v, pageSize)
		}
	}
	if limit > maxPageLimit {
		limit = maxPageLimit
	}
	return limit, offset
}

func readBody(w http.ResponseWriter, r *http.Request, max int64) ([]byte, error) {
	if r.Body == nil {
		return nil, nil
	}
	raw, err := io.ReadAll(io.LimitReader(r.Body, max+1))
	if err != nil {
		return nil, err
	}
	if int64(len(raw)) > max {
		return nil, ErrTooLarge
	}
	return raw, nil
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	httpjson.Write(w, status, v)
}

// writeHostError emits the EPP error shape (SPEC §5.1.2).
func writeHostError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]any{
		"error": map[string]any{"code": code, "message": message},
	})
}

// NonSecretSettings applies declared defaults, then stored public settings.
// Explicit zero, false, empty and null values take precedence over defaults.
// Studio uses the same secret field classifier as installed settings storage.
func NonSecretSettings(settings map[string]any, schema json.RawMessage, declaredSecrets []string) map[string]any {
	secretNames := secretFieldNames(schema)
	for _, key := range declaredSecrets {
		secretNames[key] = true
	}
	out := make(map[string]any, len(settings))
	var doc map[string]any
	if json.Unmarshal(schema, &doc) == nil {
		visitSettingsFields(doc, func(key string, field map[string]any) {
			if field["kind"] == "secret" || field["type"] == "secret" {
				secretNames[key] = true
			}
		})
		visitSettingsFields(doc, func(key string, field map[string]any) {
			if value, exists := field["default"]; exists && !secretNames[key] {
				out[key] = value
			}
		})
	}
	for key, value := range settings {
		if !secretNames[key] {
			out[key] = value
		}
	}
	return out
}

// Only traverse the schema's supported field containers, never default values or
// arbitrary nested objects that happen to contain a key/default pair.
func visitSettingsFields(doc map[string]any, visit func(string, map[string]any)) {
	for _, container := range []string{"fields", "groups"} {
		entries, _ := doc[container].([]any)
		for _, entry := range entries {
			field, ok := entry.(map[string]any)
			if !ok {
				continue
			}
			if container == "fields" && field["kind"] != "group" {
				if key, ok := firstString(field, "key", "name", "id", "field"); ok {
					visit(key, field)
				}
			}
			visitSettingsFields(field, visit)
		}
	}
	properties, _ := doc["properties"].(map[string]any)
	for key, raw := range properties {
		if field, ok := raw.(map[string]any); ok {
			visit(key, field)
		}
	}
}

func settingsSecrets(rec Record) []string {
	if rec.Manifest.Ether == nil {
		return nil
	}
	return rec.Manifest.Ether.Permissions.Secrets
}

func init() {
	// v5: guided-setup step results (spec §8), one row per step the
	// owner has tested or skipped.
	store.Register("plugins", 5, `CREATE TABLE plugins_setup(plugin TEXT NOT NULL,step TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',detail TEXT NOT NULL DEFAULT '',at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(plugin,step));`)
}

// Setup step statuses stored in plugins_setup.
const (
	SetupPending = "pending"
	SetupOK      = "ok"
	SetupFailed  = "failed"
	SetupSkipped = "skipped"
)

// SetupStepState is the stored result of one setup step.
type SetupStepState struct {
	Step   string    `json:"step"`
	Status string    `json:"status"` // pending|ok|failed|skipped
	Detail string    `json:"detail,omitempty"`
	At     time.Time `json:"at"`
}

// SetupTestResult is the plugin's answer to a setup test call.
type SetupTestResult struct {
	OK     bool              `json:"ok"`
	Detail string            `json:"detail,omitempty"`
	Fields map[string]string `json:"fields,omitempty"` // settings key -> problem
}

func validateSetup(e *EtherBlock, add func(string, string), label func(string, string, int)) {
	if e.Contributes.Setup == nil {
		return
	}
	steps := e.Contributes.Setup.Steps
	if len(steps) == 0 {
		add("ether.contributes.setup.steps", "must list at least one step")
	}
	schemaFields := settingsFieldKeys(e.Settings)
	seen := map[string]bool{}
	for i, s := range steps {
		base := fmt.Sprintf("ether.contributes.setup.steps[%d]", i)
		if !keyRe.MatchString(s.Key) || seen[s.Key] {
			add(base+".key", "must be a unique simple key")
		}
		seen[s.Key] = true
		label(base+".label", s.Label, 60)
		if s.Hint != "" && !strings.HasPrefix(s.Hint, "$t:") {
			if msg := LintCopy(s.Hint, 120); msg != "" {
				add(base+".hint", msg)
			}
			if strings.Count(strings.TrimRight(s.Hint, "."), ".") > 0 {
				add(base+".hint", "must be one sentence")
			}
		}
		for j, f := range s.Fields {
			if !keyRe.MatchString(f) {
				add(fmt.Sprintf("%s.fields[%d]", base, j), "must be a settings field key")
			} else if schemaFields != nil && !schemaFields[f] {
				add(fmt.Sprintf("%s.fields[%d]", base, j), "is not a field in the settings schema")
			}
		}
		if s.Test != "" && !strings.HasPrefix(s.Test, "/") {
			add(base+".test", "must be a plugin route starting with /")
		}
	}
}

// settingsFieldKeys extracts every "key" string from an inline settings
// schema. A "$ref" schema is resolved at install, so it returns nil
// and field membership is not checked here.
func settingsFieldKeys(raw json.RawMessage) map[string]bool {
	if len(raw) == 0 {
		return map[string]bool{}
	}
	var doc any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil
	}
	if obj, ok := doc.(map[string]any); ok {
		if _, isRef := obj["$ref"]; isRef {
			return nil
		}
	}
	out := map[string]bool{}
	var walk func(v any)
	walk = func(v any) {
		switch n := v.(type) {
		case map[string]any:
			if k, ok := n["key"].(string); ok {
				out[k] = true
			}
			for _, child := range n {
				walk(child)
			}
		case []any:
			for _, child := range n {
				walk(child)
			}
		}
	}
	walk(doc)
	return out
}

func (s *storage) setupState(ctx context.Context, plugin string) ([]SetupStepState, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT step,status,detail,at FROM plugins_setup WHERE plugin=? ORDER BY step`, plugin)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []SetupStepState
	for rows.Next() {
		var st SetupStepState
		var at int64
		if err := rows.Scan(&st.Step, &st.Status, &st.Detail, &at); err != nil {
			return nil, err
		}
		st.At = time.Unix(at, 0).UTC()
		out = append(out, st)
	}
	return out, rows.Err()
}

func (s *storage) putSetupState(ctx context.Context, plugin, step, status, detail string) error {
	_, err := s.db.ExecContext(ctx, `INSERT INTO plugins_setup(plugin,step,status,detail,at) VALUES(?,?,?,?,?)
ON CONFLICT(plugin,step) DO UPDATE SET status=excluded.status,detail=excluded.detail,at=excluded.at`,
		plugin, step, status, detail, s.now().Unix())
	return err
}

// SetupState returns every recorded setup step result for a plugin,
// with unrecorded steps reported as pending, in manifest order.
func (m *Manager) SetupState(ctx context.Context, pluginID string) ([]SetupStepState, error) {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	stored, err := m.store.setupState(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	byStep := map[string]SetupStepState{}
	for _, st := range stored {
		byStep[st.Step] = st
	}
	var out []SetupStepState
	if e := r.Manifest.EffectiveEther(); e != nil && e.Contributes.Setup != nil {
		for _, step := range e.Contributes.Setup.Steps {
			if st, ok := byStep[step.Key]; ok {
				out = append(out, st)
			} else {
				out = append(out, SetupStepState{Step: step.Key, Status: SetupPending})
			}
		}
	}
	return out, nil
}

// SetupBlockers lists the required setup steps still holding a plugin
// back: steps that have neither passed nor been skipped by the owner
// (spec §8). Content adapters keep libraries hidden and sync stopped
// while this is non-empty.
func (m *Manager) SetupBlockers(ctx context.Context, pluginID string) ([]string, error) {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	e := r.Manifest.EffectiveEther()
	if e == nil || e.Contributes.Setup == nil {
		return nil, nil
	}
	state, err := m.SetupState(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	byStep := map[string]SetupStepState{}
	for _, st := range state {
		byStep[st.Step] = st
	}
	var blocked []string
	for _, step := range e.Contributes.Setup.Steps {
		if !step.Required {
			continue
		}
		if st := byStep[step.Key]; st.Status != SetupOK && st.Status != SetupSkipped {
			blocked = append(blocked, step.Key)
		}
	}
	return blocked, nil
}

func setupStepOf(r Record, key string) (SetupStep, bool) {
	if e := r.Manifest.EffectiveEther(); e != nil && e.Contributes.Setup != nil {
		for _, s := range e.Contributes.Setup.Steps {
			if s.Key == key {
				return s, true
			}
		}
	}
	return SetupStep{}, false
}

// TestSetupStep runs one setup step's test against the saved settings
// and records the result. Only the step's non-secret field values are
// sent; secrets reach the plugin through SecretGet, never in the test
// body (spec §8). A step with no test route passes once it is run.
func (m *Manager) TestSetupStep(ctx context.Context, pluginID, stepKey string) (SetupTestResult, error) {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return SetupTestResult{}, err
	}
	step, ok := setupStepOf(r, stepKey)
	if !ok {
		return SetupTestResult{}, fmt.Errorf("%w: plugin has no setup step %q", ErrUnavailable, stepKey)
	}
	if step.Test == "" {
		res := SetupTestResult{OK: true}
		if err := m.store.putSetupState(ctx, pluginID, stepKey, SetupOK, ""); err != nil {
			return res, err
		}
		m.syncDescriptors(ctx, r)
		m.broadcast(ctx)
		return res, nil
	}
	settings, err := m.HostFor(pluginID).Settings(ctx)
	if err != nil {
		return SetupTestResult{}, err
	}
	values := map[string]any{}
	for _, f := range step.Fields {
		if v, present := settings[f]; present {
			values[f] = v
		}
	}
	body, err := json.Marshal(map[string]any{"step": stepKey, "fields": values})
	if err != nil {
		return SetupTestResult{}, err
	}
	callCtx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	resp, err := m.Call(callCtx, pluginID, Request{Method: "POST", Path: step.Test, Body: body})
	if err != nil {
		_ = m.store.putSetupState(ctx, pluginID, stepKey, SetupFailed, "The plugin did not answer")
		m.syncDescriptors(ctx, r)
		m.broadcast(ctx)
		return SetupTestResult{OK: false, Detail: "The plugin did not answer"}, nil
	}
	var res SetupTestResult
	if len(resp.Body) > 0 {
		_ = json.Unmarshal(resp.Body, &res)
	}
	if resp.Status >= 300 {
		res.OK = false
		if res.Detail == "" {
			res.Detail = fmt.Sprintf("The plugin answered with status %d", resp.Status)
		}
	}
	res.Detail = textclip.Bytes(res.Detail, 500)
	status := SetupFailed
	if res.OK {
		status = SetupOK
	}
	if err := m.store.putSetupState(ctx, pluginID, stepKey, status, res.Detail); err != nil {
		return SetupTestResult{}, err
	}
	m.syncDescriptors(ctx, r)
	m.broadcast(ctx)
	return res, nil
}

// SkipSetupStep records the owner's "skip for now" on one step, which
// unblocks the plugin while leaving the step visibly unfinished.
func (m *Manager) SkipSetupStep(ctx context.Context, pluginID, stepKey string) error {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return err
	}
	if _, ok := setupStepOf(r, stepKey); !ok {
		return fmt.Errorf("%w: plugin has no setup step %q", ErrUnavailable, stepKey)
	}
	if err := m.store.putSetupState(ctx, pluginID, stepKey, SetupSkipped, ""); err != nil {
		return err
	}
	m.syncDescriptors(ctx, r)
	m.broadcast(ctx)
	return nil
}

// ToolDeps holds dependencies for the Studio and extensibility agent and MCP tools.
type ToolDeps struct {
	Studio       *Studio
	Registry     *extend.Registry
	TextResolver extend.TextResolver
	Manager      *plugins.Manager
	Runner       *Runner
	Engine       *wasm.Engine
}

// RegisterTools registers the Studio and extensibility tools into cat.
func RegisterTools(cat *tools.Catalogue, deps ToolDeps) error {
	if cat == nil {
		return fmt.Errorf("studio: tool catalogue is required")
	}
	return cat.Register(append(Tools(deps), ProjectTools(deps.Studio)...)...)
}

// Tools returns the 8 Studio and extensibility tools (WS11h):
// registry_describe, viewspec_validate, viewspec_render, plugin_scaffold,
// plugin_check, plugin_replay, plugin_shadow_report, and plugin_install.
func Tools(deps ToolDeps) []tools.Tool {
	if deps.Runner == nil {
		deps.Runner = NewRunner(ReplayDeps{
			Manager: deps.Manager,
			Engine:  deps.Engine,
		})
	}
	return []tools.Tool{
		registryDescribeTool(deps),
		viewspecValidateTool(),
		viewspecRenderTool(deps),
		pluginScaffoldTool(deps),
		pluginCheckTool(deps),
		pluginReplayTool(deps),
		pluginShadowReportTool(deps),
		pluginInstallTool(deps),
	}
}

func registryDescribeTool(deps ToolDeps) tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"properties": {
			"kind": {
				"type": "string",
				"description": "Optional descriptor kind to filter by (for example rankingStep, ruleField, collectionSource, page, widget, tool)."
			},
			"id": {
				"type": "string",
				"description": "Optional descriptor ID to inspect."
			},
			"owner": {
				"type": "string",
				"description": "Optional owner filter (builtin or a plugin ID)."
			},
			"locale": {
				"type": "string",
				"description": "Locale code for resolving copy, defaulting to en."
			},
			"limit": {
				"type": "integer",
				"minimum": 1,
				"maximum": 200,
				"description": "Maximum number of descriptors to return (1 to 200)."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "registry_describe",
		Title:       "Describe extension registry",
		Description: "List registered extension descriptors by kind or owner, or inspect one descriptor in detail.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(_ context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			if deps.Registry == nil {
				return tools.Result{}, tools.Userf("The extension registry is not available.")
			}
			kindStr, err := optString(input, "kind", 64)
			if err != nil {
				return tools.Result{}, err
			}
			idStr, err := optString(input, "id", 128)
			if err != nil {
				return tools.Result{}, err
			}
			ownerStr, err := optString(input, "owner", 128)
			if err != nil {
				return tools.Result{}, err
			}
			locale, err := optString(input, "locale", 16)
			if err != nil {
				return tools.Result{}, err
			}
			if locale == "" {
				locale = "en"
			}
			limit, err := optInt(input, "limit", 100, 1, 200)
			if err != nil {
				return tools.Result{}, err
			}

			if kindStr != "" && !extend.Known(extend.Kind(kindStr)) {
				return tools.Result{}, tools.Userf("Unknown descriptor kind %q.", kindStr)
			}

			resolver := deps.TextResolver
			if resolver == nil && deps.Manager != nil {
				resolver = deps.Manager.TextResolver()
			}
			resolveDescriptor := func(d extend.Descriptor) extend.Descriptor {
				if resolver != nil {
					if d.Label.Plugin != "" && d.Label.Key != "" {
						if s, ok := resolver(d.Label.Plugin, d.Label.Key, locale); ok {
							d.Label.Resolved = s
						}
					}
					if d.Hint.Plugin != "" && d.Hint.Key != "" {
						if s, ok := resolver(d.Hint.Plugin, d.Hint.Key, locale); ok {
							d.Hint.Resolved = s
						}
					}
				}
				return d
			}

			if kindStr != "" && idStr != "" {
				d, ok := deps.Registry.Get(extend.Kind(kindStr), idStr)
				if !ok {
					return tools.Result{}, tools.Userf("Descriptor %q of kind %q was not found.", idStr, kindStr)
				}
				return tools.Result{
					Data: map[string]any{
						"descriptor": resolveDescriptor(d),
					},
				}, nil
			}

			var list []extend.Descriptor
			if kindStr != "" {
				list = deps.Registry.List(extend.Kind(kindStr))
			} else {
				list = deps.Registry.List()
			}
			filtered := make([]extend.Descriptor, 0, len(list))
			for _, d := range list {
				if idStr != "" && d.ID != idStr {
					continue
				}
				if ownerStr != "" && d.Owner != ownerStr {
					continue
				}
				filtered = append(filtered, resolveDescriptor(d))
				if len(filtered) >= limit {
					break
				}
			}

			return tools.Result{
				Data: map[string]any{
					"count":       len(filtered),
					"descriptors": filtered,
				},
				Links: []tools.Link{
					{Label: "Open plugins", Route: "/settings/plugins"},
				},
			}, nil
		},
	}
}

func viewspecValidateTool() tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"required": ["spec"],
		"properties": {
			"spec": {
				"description": "The ViewSpec JSON object or JSON string to validate."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "viewspec_validate",
		Title:       "Validate ViewSpec document",
		Description: "Validate a ViewSpec JSON document against Ether's plugin UI rules and report any field errors.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(_ context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			rawSpec, ok := input["spec"]
			if !ok || rawSpec == nil {
				return tools.Result{}, tools.Userf("Provide a spec object to validate.")
			}
			specBytes, err := encodeBoundedJSON(rawSpec, maxManifestBytes, "spec")
			if err != nil {
				return tools.Result{}, err
			}
			res := viewspec.ValidatePlugin(specBytes)
			errs := res.Errors
			if errs == nil {
				errs = []string{}
			}
			return tools.Result{
				Data: map[string]any{
					"ok":     res.OK,
					"errors": errs,
				},
			}, nil
		},
