// applyProjectOptions customizes a template's files for the given PluginID, Name, Slot, or StremioURL.
func applyProjectOptions(tpl Template, opts CreateProjectOptions) (pluginID, name string, files map[string]string) {
	files = make(map[string]string, len(tpl.Files))
	for k, v := range tpl.Files {
		files[k] = v
	}
	pluginID = strings.TrimSpace(opts.PluginID)
	if pluginID == "" {
		pluginID = tpl.DefaultPluginID
	}
	name = strings.TrimSpace(opts.Name)
	if name == "" {
		name = tpl.DefaultName
	}

	var man map[string]any
	if err := json.Unmarshal([]byte(files["manifest.json"]), &man); err != nil {
		return pluginID, name, files
	}
	man["id"] = pluginID
	man["name"] = name

	etherObj, _ := man["ether"].(map[string]any)
	contributes, _ := etherObj["contributes"].(map[string]any)

	if slot := strings.TrimSpace(opts.Slot); slot != "" && etherObj != nil && contributes != nil {
		ensureUICap(etherObj)
		var en map[string]string
		if json.Unmarshal([]byte(files["i18n/en.json"]), &en) == nil && en != nil {
			if en["slot_label"] == "" {
				en["slot_label"] = "Plugin action"
				files["i18n/en.json"] = prettyJSON(en)
			}
		}
		switch slot {
		case "page":
			contributes["pages"] = []map[string]any{
				{
					"key":   "overview",
					"label": "$t:page_label",
					"route": "/ether/view/overview",
				},
			}
		case "command":
			contributes["commands"] = []map[string]any{
				{
					"key":    "run_command",
					"label":  "$t:slot_label",
					"action": "createHighlight",
				},
			}
		default:
			entry := map[string]any{"slot": slot, "key": "custom_slot", "label": "$t:slot_label"}
			if strings.HasPrefix(slot, "actionMenu.") {
				action := "createHighlight"
				switch tpl.ID {
				case "list":
					action = "syncShelf"
				case "local_files":
					action = "matchFolder"
				}
				entry["action"] = action
			} else {
				entry["route"] = "/ether/view/overview"
			}
			contributes["slots"] = []map[string]any{entry}
		}
	}

	// Add-on links often carry a debrid key in the path, so only the host is
	// written into source; the link itself is never stored with the draft.
	if u, err := url.Parse(strings.TrimSpace(opts.StremioURL)); err == nil && u.Host != "" {
		if src, ok := files["src/plugin.ts"]; ok {
			files["src/plugin.ts"] = fmt.Sprintf("// Upstream Stremio add-on host: %s\n", u.Host) + src
		}
	}

	if opts.LiveSearch != nil && contributes != nil {
		if kinds, ok := contributes["mediaKinds"].([]any); ok {
			for _, k := range kinds {
				if kind, ok := k.(map[string]any); ok {
					browse, _ := kind["browse"].(map[string]any)
					if browse == nil {
						browse = map[string]any{}
						kind["browse"] = browse
					}
					browse["liveSearch"] = *opts.LiveSearch
				}
			}
		}
	}

	files["manifest.json"] = prettyJSON(man)
	return pluginID, name, files
}

func ensureUICap(etherObj map[string]any) {
	raw, _ := etherObj["capabilities"].([]any)
	for _, item := range raw {
		if item == "ui" {
			return
		}
	}
	if strs, ok := etherObj["capabilities"].([]string); ok {
		for _, s := range strs {
			if s == "ui" {
				return
			}
		}
		etherObj["capabilities"] = append(strs, "ui")
		return
	}
	etherObj["capabilities"] = append(raw, "ui")
}

// faultPrefix marks a classified fault inside a JS exception message, the
// same trick appkit-sandbox uses to carry faults across the boundary.
const faultPrefix = "__ETHER_FAULT__"

func encodeFault(f *Fault) string {
	b, _ := json.Marshal(map[string]string{"code": f.Code, "message": f.Message})
	return faultPrefix + string(b)
}

func decodeFault(msg string) *Fault {
	at := strings.Index(msg, faultPrefix)
	if at < 0 {
		return nil
	}
	var f Fault
	// The payload may be followed by a JS stack trace; decode one value.
	dec := json.NewDecoder(strings.NewReader(msg[at+len(faultPrefix):]))
	var raw struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	}
	if dec.Decode(&raw) != nil || raw.Code == "" {
		return nil
	}
	f.Code, f.Message = raw.Code, raw.Message
	return &f
}

// ensureQJS creates the first QuickJS runtime in the process with
// CloseOnContextDone enabled. fastschema/qjs caches its wazero runtime
// config package-globally from the first New call, and context-driven
// module close is the only reliable way to interrupt a tight JS loop
// (its MaxExecutionTime does not interrupt one), so the first runtime
// must be ours.
func ensureQJS() {
	qjsOnce.Do(func() {
		defer func() { _ = recover() }()
		if rt, err := qjs.New(qjs.Option{Context: context.Background(), CloseOnContextDone: true,
			Stdout: io.Discard, Stderr: io.Discard}); err == nil {
			defer func() { _ = recover() }()
			rt.Close()
		}
	})
}

// servicePrelude builds the ether global for request-ABI instances. Host
// calls are synchronous functions backed by __ether_host, charged by the
// Go side; a Fault comes back as a thrown Error whose message carries the
// fault prefix, and ether.abort throws an aborted fault.
const servicePrelude = `
"use strict";
globalThis.ether = (() => {
  const call = (name, args) => JSON.parse(__ether_host(name, JSON.stringify(args)));
  const ether = {
    log: (...a) => { try { __ether_host("log", JSON.stringify(a.map(String))); } catch (e) {} },
    abort: (msg) => { throw new Error("__ETHER_FAULT__" + JSON.stringify({ code: "aborted", message: String(msg == null ? "aborted" : msg) })); },
    kv: { get: (k) => call("kv.get", [k]), put: (k, v) => call("kv.put", [k, v]),
          delete: (k) => call("kv.delete", [k]), list: (p) => call("kv.list", [p == null ? "" : p]) },
    settings: { get: () => call("settings.get", []) },
    secret: { get: (n) => call("secret.get", [n]) },
    http: { fetch: (req) => call("http.fetch", [req]) },
    catalog: { search: (q) => call("catalog.search", [q]), get: (id) => call("catalog.get", [id]) },
    addon: { get: (route) => call("addon.get", [route]) },
    viewers: { granted: () => call("viewers.granted", []), history: (id, page) => call("viewers.history", [id, page == null ? 0 : page]),
               setWatchState: (v) => call("viewers.setWatchState", [v]) },
    collections: { upsert: (c) => call("collections.upsert", [c]) },
    kinds: { upsert: (kind, items) => call("kinds.upsert", [kind, items == null ? [] : items]),
             delete: (kind, ids) => call("kinds.delete", [kind, ids == null ? [] : ids]),
             items: (kind, cursor, limit) => call("kinds.items", [kind, cursor == null ? "" : cursor, limit == null ? 0 : limit]) },
    sources: { resolve: (q) => call("sources.resolve", [q == null ? {} : q]) },
    cache: { put: (lib, name, data) => call("cache.put", [lib, name == null ? "" : name, data == null ? "" : data]),
             open: (blobRef) => call("cache.open", [blobRef]) },
    frontend: { streamURL: (itemRef) => call("frontend.streamURL", [itemRef]) },
    folders: { list: (root, path) => call("folders.list", [root, path == null ? "" : path]),
               hashStart: (root, path) => call("folders.hashStart", [root, path]),
               hashPoll: (id) => call("folders.hashPoll", [id]),
               hashCancel: (id) => call("folders.hashCancel", [id]),
               hash: (root, path) => call("folders.hash", [root, path]),
               stat: (root, path) => call("folders.stat", [root, path]) },
    notify: { owner: (text) => call("notify.owner", [text]) },
  };
  return ether;
})();
globalThis.console = { log: (...a) => ether.log(...a), error: (...a) => ether.log(...a), warn: (...a) => ether.log(...a) };
`

// hotPrelude locks a hot-path instance down: no host services except log
// and abort, Date fixed at the epoch, Math.random a seeded generator that
// __ether_rank_batch resets per batch. The monotonic clock is captured in
// a closure for budget checks, then hidden from plugin code.
//
// Budgets are measured with performance.now (WASI's monotonic clock), not
// Date.now: the wall clock counts whole milliseconds, can step, and on
// Windows advances only once per ~15.6 ms timer tick, so a 2 ms budget read
// from it flagged fast candidates that straddled a tick as slow. wazero
// backs the monotonic clock with QueryPerformanceCounter on Windows.
const hotPrelude = `
"use strict";
globalThis.ether = (() => {
  // Capture the monotonic clock for budget checks before it is replaced.
  // It lives only in this closure; plugin code sees the frozen Date and
  // performance below, and a host-function clock would cost a boundary
  // crossing per check.
  const now = performance.now.bind(performance);
  // The calling thread's CPU time in ms, or -1 without a CPU clock. Hidden
  // from plugin code like the monotonic clock.
  const cpu = typeof __ether_cpu_ms === "function" ? __ether_cpu_ms : () => -1;
  delete globalThis.__ether_cpu_ms;
  let state = 0x2545F491;
  const nextRandom = () => { state = (state * 1103515245 + 12345) & 0x7fffffff; return state / 0x80000000; };
  class FixedDate extends Date { constructor(...a) { super(...(a.length ? a : [0])); } static now() { return 0; } }
  globalThis.Date = FixedDate;
  globalThis.performance = Object.freeze({ now: () => 0, timeOrigin: 0 });
  Math.random = nextRandom;
  // A batch arrives in two calls. __ether_load_batch parses the facts and
  // the config or condition value: host work, run with the JSON functions
  // captured here so no plugin code runs in it, under its own deadline.
  // __ether_rank_batch and __ether_cond_batch then run the plugin over it.
  //
  // Budgets bound the plugin's own time (SPEC 5.2): each candidate gets
  // perMs, and the batch stops starting candidates once batchMs is spent;
  // the rest come back null (neutral, slow, not memoized). Wall time on a
  // busy host includes the time the thread sat descheduled, which is not
  // the plugin's. So the cheap monotonic clock is read first, and when it
  // says a budget is spent the thread's CPU clock decides: the batch goes on
  // while the plugin's CPU time is within budget, and a candidate over
  // budget by the wall clock runs once more and is slow only if that run's
  // CPU time is over budget too. Without a CPU clock the wall clock rules.
  const parse = JSON.parse, stringify = JSON.stringify;
  let batch = [], batchArg = null;
  globalThis.__ether_load_batch = (candsJson, argJson) => {
    batch = parse(candsJson);
    batchArg = parse(argJson);
    return batch.length;
  };
  const each = (perMs, batchMs, call, accept) => {
    const cands = batch;
    batch = [];
    const out = [];
    for (let i = 0; i < cands.length; i++) out.push(null);
    const wall0 = now(), cpu0 = cpu();
    for (let i = 0; i < cands.length; i++) {
      if (now() - wall0 > batchMs && (cpu0 < 0 || cpu() - cpu0 > batchMs)) break;
      let t0 = now(), v = call(cands[i]);
      if (now() - t0 > perMs) {
        // Over by the wall clock: run it again and judge the plugin's own time.
        const c0 = cpu();
        t0 = now();
        v = call(cands[i]);
        if (c0 < 0 ? now() - t0 > perMs : cpu() - c0 > perMs) continue;
      }
      out[i] = accept(v);
    }
    return stringify(out);
  };
  const score = (v) => (typeof v === "bigint" ? Number(v) : v);
  globalThis.__ether_rank_batch = (perMs, batchMs) => {
    state = 0x2545F491;
    const cfg = batchArg;
    return each(perMs, batchMs, (c) => rank_key(c, cfg), score);
  };
  globalThis.__ether_cond_batch = (op, perMs, batchMs) => {
    state = 0x2545F491;
    const value = batchArg;
    return each(perMs, batchMs, (c) => cond_match(c, op, value), (v) => !!v);
  };
  return {
    log: (...a) => { try { __ether_host("log", JSON.stringify(a.map(String))); } catch (e) {} },
    abort: (msg) => { throw new Error("__ETHER_FAULT__" + JSON.stringify({ code: "aborted", message: String(msg == null ? "aborted" : msg) })); },
  };
})();
globalThis.console = { log: (...a) => ether.log(...a), error: (...a) => ether.log(...a), warn: (...a) => ether.log(...a) };
`

// exportProbe reports entry points and normalizes esbuild's IIFE exports
// (global name __plugin) onto globalThis so both authoring styles work.
const exportProbe = `
(() => {
  const pick = (n) => (typeof globalThis[n] === "function" ? globalThis[n]
    : (globalThis.__plugin && typeof globalThis.__plugin[n] === "function" ? globalThis.__plugin[n] : undefined));
  for (const n of ["handle", "rank_key", "cond_match"]) { const f = pick(n); if (f) globalThis[n] = f; }
  return JSON.stringify({ handle: typeof globalThis.handle === "function",
    rank_key: typeof globalThis.rank_key === "function",
    cond_match: typeof globalThis.cond_match === "function" });
})()
`

// swapCtx is a context whose target can be swapped atomically per call.
// qjs calls wasm functions with its stored Context value; giving it a
// swapCtx lets one pooled instance take per-call deadlines (which close
// the module on expiry) without racing wazero's cancellation watcher.
type swapCtx struct {
	cur atomic.Pointer[context.Context]
}

func newSwapCtx() *swapCtx {
	s := &swapCtx{}
	bg := context.Background()
	s.cur.Store(&bg)
	return s
}

func (s *swapCtx) Deadline() (time.Time, bool) {
	return (*s.cur.Load()).Deadline()
}

// jsLogWriter keeps WASI output out of the process streams.
type jsLogWriter struct {
	logger   *slog.Logger
	pluginID string
}

func (w jsLogWriter) Write(p []byte) (int, error) {
	if w.logger != nil {
		w.logger.Debug("plugin output", "plugin", w.pluginID, "output", string(p))
	}
	return len(p), nil
}

func newJSInstance(ctx context.Context, source string, lim *Limits, hot bool, logger *slog.Logger, pluginID string) (in *jsInstance, err error) {
	defer func() {
		if r := recover(); r != nil {
			in, err = nil, &Error{Status: StatusError, Message: fmt.Sprintf("create JS instance: %v", r), Trap: true}
		}
	}()
	swap := newSwapCtx()
	initCtx, cancel := context.WithTimeout(ctx, lim.Deadline)
	defer cancel()
	swap.set(initCtx)
	defer swap.reset()
	rt, err2 := qjs.New(qjs.Option{Context: swap, CloseOnContextDone: true,
		MemoryLimit: int(lim.MemoryBytes), MaxStackSize: 1 << 20,
		Stdout: jsLogWriter{logger, pluginID}, Stderr: jsLogWriter{logger, pluginID}})
	if err2 != nil {
		return nil, &Error{Status: StatusError, Message: "create JS runtime: " + err2.Error(), Trap: true}
	}
	in = &jsInstance{rt: rt, qc: rt.Context(), swap: swap, hot: hot}
	qc := in.qc
	qc.SetFunc("__ether_host", func(this *qjs.This) (*qjs.Value, error) {
		args := this.Args()
		if in.cs == nil || len(args) != 2 {
			return nil, errors.New(encodeFault(Forbidden("host call outside a plugin call")))
		}
		out, fault := in.cs.dispatch(args[0].String(), json.RawMessage(args[1].String()))
		if fault != nil {
			return nil, errors.New(encodeFault(fault))
		}
		return qc.NewString(string(out)), nil
	})
	prelude := servicePrelude
	if hot {
		prelude = hotPrelude
		qc.SetFunc("__ether_cpu_ms", func(*qjs.This) (*qjs.Value, error) {
			d, ok := threadCPU()
			if !ok {
				return qc.NewFloat64(-1), nil
			}
			return qc.NewFloat64(budgetMs(d)), nil
		})
	}
	if _, err := qc.Eval("ether-prelude.js", qjs.Code(prelude)); err != nil {
		in.closeInstance()
		return nil, &Error{Status: StatusError, Message: "prelude: " + err.Error(), Trap: true}
	}
	if _, err := qc.Eval("plugin.js", qjs.Code(source)); err != nil {
		in.closeInstance()
		return nil, &Error{Status: StatusError, Message: "load plugin: " + firstLine(err.Error()), Trap: false}
	}
	v, err := qc.Eval("ether-probe.js", qjs.Code(exportProbe))
	if err != nil {
		in.closeInstance()
		return nil, &Error{Status: StatusError, Message: "probe exports: " + err.Error(), Trap: true}
	}
	var found struct {
		Handle    bool `json:"handle"`
		RankKey   bool `json:"rank_key"`
		CondMatch bool `json:"cond_match"`
	}
	if err := json.Unmarshal([]byte(v.String()), &found); err != nil {
		in.closeInstance()
		return nil, &Error{Status: StatusError, Message: "probe exports: " + err.Error(), Trap: true}
	}
	in.instanceCaps = caps{Handle: found.Handle, RankKey: found.RankKey, CondMatch: found.CondMatch}
	return in, nil
}

func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

func (in *jsInstance) closeInstance() {
	defer func() { _ = recover() }()
	in.rt.Close()
}

// jsCall runs fn with the call context installed, converting qjs panics
// (it panics when a deadline closes the module mid-call) into *Error.
func (in *jsInstance) jsCall(ctx context.Context, cs *callState, fn func() (*qjs.Value, error)) (val *qjs.Value, callErr *Error) {
	in.cs = cs
	in.swap.set(ctx)
	defer func() {
		in.cs = nil
		in.swap.reset()
		if r := recover(); r != nil {
			val = nil
			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
				callErr = &Error{Status: StatusTimeout, Message: "call exceeded its deadline", Trap: true}
				return
			}
			callErr = &Error{Status: StatusError, Message: fmt.Sprintf("%v", r), Trap: true}
		}
	}()
	v, err := fn()
	if err != nil {
		return nil, classifyJSError(ctx, err)
	}
	if v != nil && v.IsPromise() {
		v, err = v.Await()
		if err != nil {
			return nil, classifyJSError(ctx, err)
		}
	}
	return v, nil
}

func classifyJSError(ctx context.Context, err error) *Error {
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return &Error{Status: StatusTimeout, Message: "call exceeded its deadline", Trap: true}
	}
	msg := err.Error()
	if f := decodeFault(msg); f != nil {
		st := statusForFaultCode(f.Code)
		return &Error{Status: st, Message: f.Message, Trap: st == StatusAborted}
	}
	if strings.Contains(msg, "module closed") || strings.Contains(msg, "interrupted") {
		return &Error{Status: StatusTimeout, Message: "call exceeded its deadline", Trap: true}
	}
	return &Error{Status: StatusError, Message: firstLine(msg)}
}

func (in *jsInstance) globalFn(name string) *qjs.Value {
	return in.qc.Global().GetPropertyStr(name)
}

func (in *jsInstance) handle(ctx context.Context, cs *callState, reqJSON []byte) ([]byte, *Error) {
	v, err := in.jsCall(ctx, cs, func() (*qjs.Value, error) {
		g := in.qc.Global()
		return in.qc.Invoke(in.globalFn("__ether_dispatch_handle"), g, in.qc.NewString(string(reqJSON)))
	})
	if err != nil {
		// Fall back to calling handle directly with a parsed object; the
		// dispatch wrapper is installed by installDispatch at load. If it is
		// missing this error is the real one.
		return nil, err
	}
	return []byte(v.String()), nil
}

func (in *jsInstance) rankOne(ctx context.Context, cs *callState, cand, cfg []byte) (int64, *Error) {
	unbounded := Limits{RankPerCandidate: 1 << 60, RankBatch: 1 << 60}
	scores, err := in.rankBatch(ctx, cs, [][]byte{cand}, cfg, &unbounded)
	if err != nil {
		return 0, err
	}
	if scores[0] == nil {
		return 0, &Error{Status: StatusTimeout, Message: "candidate exceeded its budget", Trap: false}
	}
	return *scores[0], nil
}

// loadBatch hands a batch's facts and its config (or condition value) to
// the instance: one parse of one JSON array, under its own deadline, so
// the host's share of a batch is never charged to the plugin.
func (in *jsInstance) loadBatch(ctx context.Context, cs *callState, cands [][]byte, arg []byte, lim *Limits) *Error {
	candsJSON, ferr := factsArray(cands)
	if ferr != nil {
		return ferr
	}
	loadCtx, cancel := context.WithTimeout(ctx, lim.hotKill())
	defer cancel()
	_, err := in.jsCall(loadCtx, cs, func() (*qjs.Value, error) {
		return in.qc.Invoke(in.globalFn("__ether_load_batch"), in.qc.Global(),
			in.qc.NewString(string(candsJSON)), in.qc.NewString(string(arg)))
	})
	return err
}

func (in *jsInstance) rankBatch(ctx context.Context, cs *callState, cands [][]byte, cfg []byte, lim *Limits) ([]*int64, *Error) {
	if err := in.loadBatch(ctx, cs, cands, cfg, lim); err != nil {
		return nil, err
	}
	runCtx, cancel := context.WithTimeout(ctx, lim.hotKill())
	defer cancel()
	runtime.LockOSThread() // the budget reads this thread's CPU clock
	defer runtime.UnlockOSThread()
	v, err := in.jsCall(runCtx, cs, func() (*qjs.Value, error) {
		return in.qc.Invoke(in.globalFn("__ether_rank_batch"), in.qc.Global(),
			in.qc.NewFloat64(budgetMs(lim.RankPerCandidate)), in.qc.NewFloat64(budgetMs(lim.RankBatch)))
	})
	if err != nil {
		return nil, err
	}
	var out []*int64
	if uerr := json.Unmarshal([]byte(v.String()), &out); uerr != nil {
		return nil, &Error{Status: StatusError, Message: "rank_key returned a non-numeric result: " + uerr.Error()}
	}
	if len(out) != len(cands) {
		return nil, &Error{Status: StatusError, Message: "rank batch returned the wrong number of scores"}
	}
	return out, nil
}

// factsArray joins candidate facts into one JSON array, parsed once per
// batch instead of once per candidate. Each fact must be one JSON value, so
// a malformed fact cannot shift the others' positions.
func factsArray(cands [][]byte) ([]byte, *Error) {
	n := 2
	for _, c := range cands {
		if !json.Valid(c) {
			return nil, &Error{Status: StatusError, Message: "candidate facts are not valid JSON"}
		}
		n += len(c) + 1
	}
	b := make([]byte, 0, n)
	b = append(b, '[')
	for i, c := range cands {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, c...)
	}
	return append(b, ']'), nil
}

func (in *jsInstance) condBatch(ctx context.Context, cs *callState, cands [][]byte, op string, val []byte, lim *Limits) ([]*bool, *Error) {
	if err := in.loadBatch(ctx, cs, cands, val, lim); err != nil {
		return nil, err
	}
	runCtx, cancel := context.WithTimeout(ctx, lim.hotKill())
	defer cancel()
	runtime.LockOSThread() // the budget reads this thread's CPU clock
	defer runtime.UnlockOSThread()
	v, err := in.jsCall(runCtx, cs, func() (*qjs.Value, error) {
		return in.qc.Invoke(in.globalFn("__ether_cond_batch"), in.qc.Global(), in.qc.NewString(op),
			in.qc.NewFloat64(budgetMs(lim.RankPerCandidate)), in.qc.NewFloat64(budgetMs(lim.RankBatch)))
	})
	if err != nil {
		return nil, err
	}
	var out []*bool
	if err := json.Unmarshal([]byte(v.String()), &out); err != nil || len(out) != len(cands) {
		return nil, &Error{Status: StatusError, Message: "invalid condition batch result"}
	}
	return out, nil
}

func (in *jsInstance) condOne(ctx context.Context, cs *callState, cand []byte, op string, val []byte) (bool, *Error) {
	v, err := in.jsCall(ctx, cs, func() (*qjs.Value, error) {
		g := in.qc.Global()
		c := in.qc.ParseJSON(string(cand))
		value := in.qc.ParseJSON(string(val))
		return in.qc.Invoke(in.globalFn("cond_match"), g, c, in.qc.NewString(op), value)
	})
	if err != nil {
		return false, err
	}
	return v.Bool(), nil
}

// LoadJS loads a JavaScript plugin (TypeScript authors go through Compile
// first). A probe instance is built eagerly so syntax errors and a missing
// handle surface at load.
func (e *Engine) LoadJS(id, version, source string, host Host, lim Limits) (*Plugin, error) {
	lim.normalize()
	e.scaleHot(&lim)
	p := &Plugin{id: id, version: version, eng: e, host: host, lim: lim, memo: newMemo(4096), source: source}
	makeSvc := func(ctx context.Context) (instance, error) {
		in, err := newJSInstance(ctx, source, &p.lim, false, e.logger, id)
		if err != nil {
			return nil, err
		}
		if err := in.installDispatch(); err != nil {
			in.closeInstance()
			return nil, err
		}
		return in, nil
	}
	makeHot := func(ctx context.Context) (instance, error) {
		return newJSInstance(ctx, source, &p.lim, true, e.logger, id)
	}
	p.svc = newPool(lim.PoolSize, makeSvc)
	p.hot = newWarmPool(lim.PoolSize, makeHot)
	probe, err := p.svc.get(context.Background())
	if err != nil {
		p.Close()
		return nil, err
	}
	p.caps = probe.caps()
	p.svc.put(probe, true)
	if !p.caps.Handle && !p.caps.RankKey && !p.caps.CondMatch {
		p.Close()
		return nil, &Error{Status: StatusError, Message: "plugin defines none of handle, rank_key, cond_match"}
	}
	p.warmHot()
	return p, nil
}

// installDispatch wraps handle so Go passes one JSON string and gets one
// JSON string back; the plugin sees plain objects either side.
func (in *jsInstance) installDispatch() (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = &Error{Status: StatusError, Message: fmt.Sprintf("install dispatch: %v", r), Trap: true}
		}
	}()
	_, err2 := in.qc.Eval("ether-dispatch.js", qjs.Code(`
globalThis.__ether_dispatch_handle = (reqJson) => {
  const res = handle(JSON.parse(reqJson));
  if (res && typeof res.then === "function") return res.then((r) => JSON.stringify(r == null ? {} : r));
  return JSON.stringify(res == null ? {} : res);
};`))
	if err2 != nil {
		return &Error{Status: StatusError, Message: "install dispatch: " + err2.Error(), Trap: true}
	}
	return nil
}

// Fault is a classified, non-ambient failure. A Host returns a *Fault to make
// the call end with that status; Code is one of the Status values other than
// ok (usually forbidden), or an application code the plugin can catch.
type Fault struct {
	Code    string
	Message string
}

// Error is the error type returned by Plugin calls. It carries the Outcome so
// WS7's health loop can read the status, trap flag and cost from one value.
type Error struct {
	Status  Status
	Message string
	Trap    bool // the instance trapped (panic in guest) or was killed by a deadline
}

// Outcome accounts for one finished call.
type Outcome struct {
	Status         Status
	Units          int64 // host-call units plus wall-time units
	Duration       time.Duration
	Trap           bool
	SlowCandidates int // hot path: candidates that went neutral on budget
	MemoHits       int // hot path: candidates served from the memo
}

// Request is the HTTP-shaped plugin request (SPEC 5.1.2 / 5.2).
type Request struct {
	Op      string              `json:"op,omitempty"`
	ID      string              `json:"id,omitempty"`
	Method  string              `json:"method"`
	Path    string              `json:"path"`
	Query   map[string][]string `json:"query,omitempty"`
	Headers map[string]string   `json:"headers,omitempty"`
	Body    json.RawMessage     `json:"body,omitempty"`
}

// Response is the plugin's answer. Body is the raw JSON the plugin produced
// as its body field (usually a JSON string), passed through untouched.
type Response struct {
	Status  int               `json:"status"`
	Headers map[string]string `json:"headers,omitempty"`
	Body    json.RawMessage   `json:"body,omitempty"`
}

// Host is the plugin-to-Ether service surface (SPEC 5.1.5). Name is a dotted
// service method: kv.get, kv.put, kv.delete, kv.list, secret.get,
// http.fetch, catalog.search, catalog.get, viewers.history,
// viewers.setWatchState, collections.upsert, kinds.upsert, kinds.delete,
// kinds.items, sources.resolve, cache.put, cache.open, frontend.streamURL,
// folders.list, folders.stat, notify.owner, log. Args is a JSON array of positional
// arguments; the result is any JSON value. Return a *Fault to classify the
// failure (forbidden for a missing or revoked grant).
type Host interface {
	CallHost(ctx context.Context, name string, args json.RawMessage) (json.RawMessage, error)
}

// Default host-call unit costs, in the spirit of appkit-sandbox's priced
// host functions. Wall time adds 1 unit per WallUnitInterval.
var DefaultCosts = map[string]int64{
	"log": 1, "kv.get": 5, "kv.put": 10, "kv.delete": 5, "kv.list": 10,
	"secret.get": 5, "http.fetch": 100, "addon.get": 100, "catalog.search": 50, "catalog.get": 20,
	"viewers.history": 50, "viewers.setWatchState": 50, "collections.upsert": 50,
	"kinds.upsert": 50, "kinds.delete": 50, "kinds.items": 20,
	"sources.resolve": 100, "cache.put": 50, "cache.open": 20, "frontend.streamURL": 5,
	"folders.hashStart": 20, "folders.hashPoll": 20, "folders.hashCancel": 20, "folders.hash": 20, "folders.list": 20, "folders.stat": 20, "notify.owner": 20, "settings.get": 5,
}

const (
	// DefaultRankPerCandidate and DefaultRankBatch are the hot-path budgets
	// (SPEC §5.2). A manifest may lower them, never raise them.
	DefaultRankPerCandidate = 2 * time.Millisecond
	DefaultRankBatch        = 50 * time.Millisecond
	// WallUnitInterval is the wall time worth one unit.
	WallUnitInterval = 100 * time.Microsecond
	// BaseCallUnits is charged once per handle call.
	BaseCallUnits = 10
	// MaxMemoryBytes is the hard ceiling for a plugin instance.
	MaxMemoryBytes = 64 << 20
	// MaxResponseBytes caps a plugin response.
	MaxResponseBytes = 8 << 20
	// MaxHostResultBytes caps one host-call result returned to a guest.
	MaxHostResultBytes = 4 << 20
	maxLogsPerCall     = 100
)

// Limits bound one plugin. Zero fields take the defaults in normalize.
type Limits struct {
	MemoryBytes uint64        // per instance; default 32 MiB, max 64 MiB
	Deadline    time.Duration // per handle call; default 30s
	UnitBudget  int64         // per handle call; default 10000
	PoolSize    int           // instances per pool; default 2
	// Hot-path budgets. A manifest may lower these, never raise them:
	// normalize clamps to the defaults below.
	RankPerCandidate time.Duration // default (and max) 2ms
	RankBatch        time.Duration // default (and max) 50ms
	Costs            map[string]int64
	// unclamped lets this package's tests raise the hot-path budgets so
	// correctness checks do not depend on machine speed. Other packages
	// cannot set it, so production budgets are always clamped.
	unclamped bool
}

func (l *Limits) normalize() {
	if l.MemoryBytes == 0 || l.MemoryBytes > MaxMemoryBytes {
		if l.MemoryBytes == 0 {
			l.MemoryBytes = 32 << 20
		} else {
			l.MemoryBytes = MaxMemoryBytes
		}
	}
	if l.Deadline <= 0 {
		l.Deadline = 30 * time.Second
	}
	if l.UnitBudget <= 0 {
		l.UnitBudget = 10000
	}
	if l.PoolSize <= 0 {
		l.PoolSize = 2
	}
	if l.RankPerCandidate <= 0 || (l.RankPerCandidate > DefaultRankPerCandidate && !l.unclamped) {
		l.RankPerCandidate = DefaultRankPerCandidate
	}
	if l.RankBatch <= 0 || (l.RankBatch > DefaultRankBatch && !l.unclamped) {
		l.RankBatch = DefaultRankBatch
	}
	if l.Costs == nil {
		l.Costs = DefaultCosts
	}
}

// hotKill is the hard deadline of one hot-path call: the point where the
// instance is killed because plugin code stopped returning (an endless
// loop). It is not the plugin's budget. The budgets bound the plugin's own
// time and are enforced softly between candidates (see hotPrelude), so a
// batch that keeps to them ends normally; the deadline only has to catch
// code that never yields back. It sits one batch budget past the batch
// budget so the host's own work for the call (encoding and parsing the
// facts) and a busy machine's scheduling pauses cannot turn a well-behaved
// batch into a killed one. A JavaScript batch takes the deadline twice:
// once for the host to hand over the facts, once for the plugin's code.
// When the kill and the budget were the same
// instant, the batch lost every score it had already computed, nothing was
// memoized, and the next resolve started from zero and timed out again.
func (l *Limits) hotKill() time.Duration { return 2 * l.RankBatch }

func (l *Limits) costOf(name string) int64 {
	if c, ok := l.Costs[name]; ok {
		return c
	}
	return 25 // unpriced service: charge a middle rate, never free
}

type counters struct {
	calls, errors, timeouts, traps, forbidden, aborted, governance, slow, units atomic.Int64
}

func (c *counters) record(o Outcome) {
	c.calls.Add(1)
	c.units.Add(o.Units)
	c.slow.Add(int64(o.SlowCandidates))
	if o.Trap {
		c.traps.Add(1)
	}
	switch o.Status {
	case StatusError:
		c.errors.Add(1)
	case StatusTimeout:
		c.timeouts.Add(1)
	case StatusForbidden:
		c.forbidden.Add(1)
	case StatusAborted:
		c.aborted.Add(1)
	case StatusGovernance:
		c.governance.Add(1)
	}
}

func (c *counters) snapshot() Stats {
	return Stats{Calls: c.calls.Load(), Errors: c.errors.Load(), Timeouts: c.timeouts.Load(),
		Traps: c.traps.Load(), Forbidden: c.forbidden.Load(), Aborted: c.aborted.Load(),
		Governance: c.governance.Load(), SlowCandidates: c.slow.Load(), Units: c.units.Load()}
}

func (cs *callState) chargeWall() {
	now := time.Now()
	cs.units += int64(now.Sub(cs.last) / WallUnitInterval)
	cs.last = now
}

// charge accounts one host call. It returns a governance Fault when the
// budget is spent; the flag is sticky so a plugin that catches the error
// still ends the call as governance.
func (cs *callState) charge(name string) *Fault {
	cs.chargeWall()
	cs.units += cs.lim.costOf(name)
	if cs.units > cs.lim.UnitBudget {
		cs.exceeded = true
		return &Fault{Code: string(StatusGovernance),
			Message: fmt.Sprintf("governance budget exceeded (%d/%d units)", cs.units, cs.lim.UnitBudget)}
	}
	return nil
}

func (cs *callState) finishUnits() int64 {
	cs.chargeWall()
	if cs.units > cs.lim.UnitBudget {
		cs.exceeded = true
	}
	return cs.units
}

// dispatch runs one host service for a guest, applying governance and the
// hot-path lockdown. It is the single funnel for JS ether.* and raw
// ether.host_call.
func (cs *callState) dispatch(name string, args json.RawMessage) (json.RawMessage, *Fault) {
	if cs.hot && name != "log" {
		return nil, Forbidden("host services are not available on the hot path: " + name)
	}
	if name == "log" {
		cs.logs++
		if cs.logs > maxLogsPerCall {
			return json.RawMessage("null"), nil // rate-limited: drop quietly
		}
		if f := cs.charge(name); f != nil {
			return nil, f
		}
		if cs.host != nil {
			_, _ = cs.host.CallHost(cs.ctx, name, args)
		} else {
			cs.logger.Debug("plugin log", "plugin", cs.pluginID, "args", string(args))
		}
		return json.RawMessage("null"), nil
	}
	if f := cs.charge(name); f != nil {
		return nil, f
	}
	if cs.host == nil {
		return nil, Forbidden("no host services are configured for this plugin")
	}
	out, err := cs.host.CallHost(cs.ctx, name, args)
	// Time spent waiting on the host (a network fetch, a catalogue query) is
	// paid by the call's own unit price, not as guest wall time; otherwise
	// one slow upstream response spent the whole budget. The call deadline
	// still bounds the total.
	cs.last = time.Now()
	if err != nil {
		if f, ok := err.(*Fault); ok {
			return nil, f
		}
		return nil, &Fault{Code: "host_error", Message: err.Error()}
	}
	if len(out) > MaxHostResultBytes {
		return nil, &Fault{Code: "host_error", Message: "host result exceeds size cap"}
	}
	if len(out) == 0 {
		out = json.RawMessage("null")
	}
	return out, nil
}

// caps records which ABI entry points a plugin defines.
type caps struct {
	Handle    bool
	RankKey   bool
	CondMatch bool
}

// instance is one live guest (a QuickJS runtime or a raw module instance).
// Instances are not safe for concurrent use; the pool lends one at a time.
// Any call that ends with Trap set, or with a timeout, poisons the instance.
type instance interface {
	handle(ctx context.Context, cs *callState, reqJSON []byte) ([]byte, *Error)
	rankOne(ctx context.Context, cs *callState, cand, cfg []byte) (int64, *Error)
	condOne(ctx context.Context, cs *callState, cand []byte, op string, val []byte) (bool, *Error)
	caps() caps
	closeInstance()
}

// batchRanker is implemented by instances (JavaScript) that can score a
// whole batch in one crossing. They apply the per-candidate and batch
// budgets themselves and enforce the hot kill deadline (Limits.hotKill)
// on ctx. Nil scores mark slow candidates.
type batchRanker interface {
	rankBatch(ctx context.Context, cs *callState, cands [][]byte, cfg []byte, lim *Limits) ([]*int64, *Error)
}

// batchMatcher is the rule-condition counterpart of batchRanker.
type batchMatcher interface {
	condBatch(ctx context.Context, cs *callState, cands [][]byte, op string, val []byte, lim *Limits) ([]*bool, *Error)
}

// pool lends instances up to size, discarding poisoned ones so crash
// policy (backoff, disable) can count fresh failures.
//
// A service pool builds on demand under the caller's context: a handle
// call has a seconds-long deadline, and a cold build fits in it.
//
// A warm pool (the hot path) never builds on the caller's path. Building
// an instance costs milliseconds (a QuickJS runtime is several), more than
// the 2ms per-candidate and 50ms per-batch budgets, so building inline
// would make the first concurrent call, and every call after a discarded
// instance, time out; on a slow host the hot path then never recovers.
// Instead the pool is filled at load, a discarded instance is replaced in
// the background under the service deadline, and a caller only ever waits
// for an idle instance within its own budget.
type pool struct {
	makeFn func(context.Context) (instance, error)
	idle   chan instance
	slots  chan struct{} // one token per live instance: idle, lent or building
	warm   bool
	mu     sync.Mutex // orders returning an instance against close
	done   atomic.Bool
}

func newPool(size int, makeFn func(context.Context) (instance, error)) *pool {
	return &pool{makeFn: makeFn, idle: make(chan instance, size), slots: make(chan struct{}, size)}
}

func newWarmPool(size int, makeFn func(context.Context) (instance, error)) *pool {
	p := newPool(size, makeFn)
	p.warm = true
	return p
}

func (p *pool) get(ctx context.Context) (instance, error) {
	if p.done.Load() {
		return nil, &Error{Status: StatusError, Message: "plugin is closed"}
	}
	select {
	case in := <-p.idle:
		return in, nil
	default:
	}
	if p.warm {
		// A free slot means an earlier build failed; retry it off-path.
		p.refill()
		select {
		case in := <-p.idle:
			return in, nil
		case <-ctx.Done():
			return nil, &Error{Status: StatusTimeout, Message: "timed out waiting for a plugin instance"}
		}
	}
	select {
	case in := <-p.idle:
		return in, nil
	case p.slots <- struct{}{}:
		in, err := p.makeFn(ctx)
		if err != nil {
			<-p.slots
			return nil, err
		}
		return in, nil
	case <-ctx.Done():
		return nil, &Error{Status: StatusTimeout, Message: "timed out waiting for a plugin instance"}
	}
}

func (p *pool) put(in instance, healthy bool) {
	if !healthy {
		in.closeInstance()
		<-p.slots
		if p.warm {
			p.refill()
		}
		return
	}
	p.adopt(in)
}

// adopt returns a usable instance to the idle set, or closes it when the
// pool is closed or already full.
func (p *pool) adopt(in instance) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if !p.done.Load() {
		select {
		case p.idle <- in:
			return
		default:
		}
	}
	in.closeInstance()
	<-p.slots
}

// fill builds instances synchronously until the pool is full or a build
// fails. Plugins call it at load, off any request path.
func (p *pool) fill() {
	for !p.done.Load() {
		select {
		case p.slots <- struct{}{}:
		default:
			return
		}
		in, err := p.makeFn(context.Background())
		if err != nil {
			<-p.slots
			return
		}
		p.adopt(in)
	}
}

// refill builds one replacement in the background if a slot is free. The
// slot is held while building, so builds never exceed the pool size.
func (p *pool) refill() {
	if p.done.Load() {
		return
	}
	select {
	case p.slots <- struct{}{}:
	default:
		return
	}
	go func() {
		in, err := p.makeFn(context.Background())
		if err != nil {
			<-p.slots
			return
		}
		p.adopt(in)
	}()
}

func (p *pool) close() {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.done.Store(true)
	for {
		select {
		case in := <-p.idle:
			in.closeInstance()
			<-p.slots
		default:
			return
		}
	}
}

// Engine compiles and caches guest code and builds Plugins. It owns the
// wazero runtimes used by raw modules; JavaScript instances manage their
// own (QuickJS) modules. Safe for concurrent use.
type Engine struct {
	logger *slog.Logger
	mu     sync.Mutex
	raw    map[uint32]*rawRuntime // by memory-limit pages
	closed bool
	// speedLog logs the engine's measured speed once (see HotScale).
	speedLog sync.Once
}

func NewEngine(logger *slog.Logger) *Engine {
	if logger == nil {
		logger = slog.Default()
	}
	ensureQJS()
	return &Engine{logger: logger, raw: map[uint32]*rawRuntime{}}
}

func (e *Engine) Close() error {
	e.mu.Lock()
	defer e.mu.Unlock()
	e.closed = true
	for _, rt := range e.raw {
		_ = rt.rt.Close(context.Background())
	}
	e.raw = map[uint32]*rawRuntime{}
	return nil
}

// Plugin is one loaded hosted plugin. Call serves the request ABI;
// RankBatch and CondMatch serve the hot path. Safe for concurrent use.
type Plugin struct {
	id, version string
	eng         *Engine
	host        Host
	lim         Limits
	caps        caps
	svc         *pool
	hot         *pool
	stats       counters
	memo        *memo
	source      string // JS source (rebuild counts / cold start), raw: ""
	closed      atomic.Bool
}

// Budgets reports the plugin's effective hot-path budgets: the manifest's
// (lowered, never raised), scaled by the engine's measured speed.
func (p *Plugin) Budgets() (perCandidate, perBatch time.Duration) {
	return p.lim.RankPerCandidate, p.lim.RankBatch
}

func (p *Plugin) Close() error {
	if p.closed.Swap(true) {
		return nil
	}
	if p.svc != nil {
		p.svc.close()
	}
	if p.hot != nil {
		p.hot.close()
	}
	return nil
}

// Call runs the request ABI. The returned error, when non-nil, is a *Error
// classified for the host's health loop.
func (p *Plugin) Call(ctx context.Context, req Request) (Response, error) {
	resp, _, err := p.CallDetailed(ctx, req)
	return resp, err
}

// CallDetailed is Call plus the Outcome (units, duration, trap flag).
func (p *Plugin) CallDetailed(ctx context.Context, req Request) (Response, Outcome, error) {
	start := time.Now()
	out := Outcome{Status: StatusOK}
	defer func() {
		out.Duration = time.Since(start)
		p.stats.record(out)
	}()
	if p.closed.Load() {
		out.Status = StatusError
		return Response{}, out, &Error{Status: StatusError, Message: "plugin is closed"}
	}
	if !p.caps.Handle {
		out.Status = StatusError
		return Response{}, out, &Error{Status: StatusError, Message: "plugin does not export handle"}
	}
	reqJSON, err := json.Marshal(req)
	if err != nil {
		out.Status = StatusError
		return Response{}, out, &Error{Status: StatusError, Message: err.Error()}
	}
	callCtx, cancel := context.WithTimeout(ctx, p.lim.Deadline)
	defer cancel()
	cs := &callState{ctx: callCtx, host: p.host, lim: &p.lim, start: start, last: start,
		units: BaseCallUnits, logger: p.eng.logger, pluginID: p.id}
	in, err := p.svc.get(callCtx)
	if err != nil {
		out.Status = StatusTimeout
		if e, ok := err.(*Error); ok {
			out.Status = e.Status
		}
		return Response{}, out, err
	}
	// Waiting for a free instance is the host's queue, not the plugin's
	// work: concurrent calls (a metadata sweep) must not spend the budget
	// of the call at the back of the line.
	cs.last = time.Now()
	respJSON, callErr := in.handle(callCtx, cs, reqJSON)
	out.Units = cs.finishUnits()
	healthy := callErr == nil || !callErr.Trap
	if callErr != nil && callErr.Status == StatusTimeout {
		healthy = false
	}
	p.svc.put(in, healthy)
	if callErr != nil {
		out.Status, out.Trap = callErr.Status, callErr.Trap
		return Response{}, out, callErr
	}
	if cs.exceeded {
		out.Status = StatusGovernance
		return Response{}, out, &Error{Status: StatusGovernance, Message: "governance budget exceeded"}
	}
	if len(respJSON) > MaxResponseBytes {
		out.Status = StatusError
		return Response{}, out, &Error{Status: StatusError, Message: "plugin response exceeds size cap"}
	}
	var resp Response
	if err := json.Unmarshal(respJSON, &resp); err != nil {
		out.Status = StatusError
		return Response{}, out, &Error{Status: StatusError, Message: "plugin returned invalid response JSON: " + err.Error()}
	}
	if resp.Status == 0 {
		resp.Status = 200
	}
	return resp, out, nil
}

