function ok(body:any){return {status:200,body};}
export function handle(req:any){
 if(req.path==='/ether/configure')return ok({errors:{}});
 if(req.path==='/ether/health')return ok({status:'ok'});
 if(req.path==='/ether/channels.json')return ok({channels:CHANNELS.map(c=>({id:c.id,name:c.name,number:c.number,group:c.group,logo:c.logo||'',guideId:c.id}))});
 if(req.path.startsWith('/ether/guide/'))return ok({programmes:[]});
 if(req.path.startsWith('/stream/tv/')){const id=decodeURIComponent(req.path.slice(11,-5)),c=CHANNELS.find(c=>c.id===id);return ok({streams:c?[{name:c.name,url:c.url}]:[]});}
 if(req.path==='/ether/test'){
 const failures:string[]=[];for(const c of CHANNELS){try{const r=ether.http.fetch({url:c.url});if(r.status!==200||!String(r.body).startsWith('#EXTM3U'))failures.push(c.name);}catch(e){failures.push(c.name);}}
 return ok({ok:failures.length===0,message:failures.length?'Unavailable: '+failures.join(', '):'All six broadcaster HLS feeds are reachable.'});
 }
 if(req.path==='/ether/view/lineup')return ok({title:'Canada Live',spec:{specVersion:1,layout:'detail',header:[{kind:'page-header',title:{$:'title'},description:{$:'subtitle'}}],body:[{kind:'stat-tile',iconKey:'tv',accent:'primary',label:'$t:count',value:{$:'count'}},{kind:'panel',title:'$t:channels',blocks:[{kind:'repeat',items:{$:'channels'},itemKey:{$:'id'},blocks:[{kind:'widget',widget:'ether.channelRow',props:{name:{$:'name'},number:{$:'number'},group:{$:'group'}}}]}]},{kind:'panel',title:'$t:guide',blocks:[{kind:'text',content:'$t:guide_hint'}]}]},data:{title:'Canada Live',subtitle:'CPAC and Global News public streams. CPAC includes English and French audio. Regional channels are dedicated news feeds; availability follows each broadcaster.',count:String(CHANNELS.length),channels:CHANNELS.map(c=>({...c,number:String(c.number)}))}});
 return {status:404,body:{error:{code:'not_found',message:'Route not found.'}}};
}
(globalThis as any).handle=handle;

