  "name": "EasyDebrid",
  "version": "1.0.0",
  "description": "EasyDebrid cache checks and cached-file playback through Ether\u2019s native debrid pipeline.",
  "ether": {
    "protocol": 1,
    "kind": "source",
    "capabilities": [
      "debrid_provider",
      "ui"
    ],
    "summary": "$t:summary",
    "runtime": {
      "kind": "hosted",
      "entry": "src/plugin.ts"
    },
    "author": {
      "name": "Server owner"
    },
    "license": "MIT",
    "permissions": {
      "network": [
        "easydebrid.com"
      ],
      "secrets": [
        "apiKey"
      ]
    },
    "settings": {
      "fields": [
        {
          "key": "apiKey",
          "kind": "secret",
          "label": "$t:key",
          "hint": "$t:key_hint"
        }
      ]
    },
    "strings": {
      "en": "i18n/en.json"
    },
    "contributes": {
      "source": {
        "class": "debrid",
        "abilities": [
          "cache-check",
          "cached-playback"
        ]
      },
      "pages": [
        {
          "key": "account",
          "label": "$t:page",
          "route": "/ether/view/account"
        }
      ]
    }
  }
}

function ok(body:any){return {status:200,body};}
function token(){try{return String(ether.secret.get('apiKey')||'').trim();}catch{return '';}}
function fail(status:number,message:string):never{throw {status,message};}
function api(path:string,body?:any){const key=token();if(!key)fail(401,'Add an EasyDebrid API token in Setup.');const r=ether.http.fetch({url:'https://easydebrid.com/api/v1'+path,method:body?'POST':'GET',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(r.status<200||r.status>=300)fail(r.status===401||r.status===403?401:r.status===429?429:502,'EasyDebrid request failed (HTTP '+r.status+').');try{return typeof r.body==='string'?JSON.parse(r.body):r.body;}catch{fail(502,'EasyDebrid returned invalid JSON.');}}
function magnet(h:string){if(!/^[a-fA-F0-9]{40}$/.test(h))fail(400,'A valid torrent info hash is required.');return 'magnet:?xt=urn:btih:'+h.toLowerCase();}
function files(hash:string){const result=api('/link/generate',{url:magnet(hash)});if(!Array.isArray(result.files))fail(502,'EasyDebrid returned no file list.');return result.files.map((f:any)=>{const path=[...(Array.isArray(f.directory)?f.directory:[]),f.filename].filter(Boolean).join('/');return {id:path,path,size:Number(f.size)||0,link:String(f.url||'')};}).filter((f:any)=>f.path&&f.size>0);}
function account(){const a=api('/user/details');const day=String(a.paid_until||'');const end=/^\d{4}-\d{2}-\d{2}$/.test(day)?day+'T23:59:59Z':day;const ms=Date.parse(end);return {user:String(a.id||''),premium:Number.isFinite(ms)&&ms>Date.now(),...(Number.isFinite(ms)?{expires:new Date(ms).toISOString()}:{})};}
export function handle(req:any){try{
 if(req.path==='/ether/configure')return ok({errors:{}});
 if(req.path==='/ether/health')return ok({status:token()?'ok':'attention',reason:token()?'':'Add an EasyDebrid API token in Setup.'});
 if(req.path==='/ether/test'||req.path==='/ether/action/test'){const a=account();const message=a.premium?'EasyDebrid account connected; premium access is active.':'Account connected, but premium access is expired or unavailable.';return ok(req.path==='/ether/test'?{ok:a.premium,message}:{toast:message,refresh:true});}
 if(req.path==='/ether/view/account')return ok({title:'EasyDebrid',spec:{specVersion:1,layout:'detail',header:[{kind:'page-header',title:{$:'title'},description:{$:'subtitle'}}],body:[{kind:'stat-tile',iconKey:'key',accent:'primary',label:'$t:state',value:{$:'state'}},{kind:'panel',title:'$t:connection',blocks:[{kind:'widget',widget:'ether.actionButton',props:{label:'$t:test',action:'test'}}]},{kind:'panel',title:'$t:capabilities',blocks:[{kind:'text',content:'$t:help'},{kind:'text',content:'$t:docs'}]}]},data:{title:'EasyDebrid',subtitle:'A native plugin source in Sources → Debrid. Configure your account in Plugins → EasyDebrid → Setup, then run the connection test.',state:token()?'Token saved; test account':'Setup required'}});
 if(req.path==='/ether/debrid/account')return ok(account());
 if(req.path==='/ether/debrid/find'||req.path==='/ether/debrid/remove')return {status:501,body:{error:{code:'unsupported',message:'Cached-only provider; no account torrent queue.'}}};
 if(req.path==='/ether/debrid/check'){
  const hashes=Array.isArray(req.body?.hashes)?req.body.hashes:[];if(hashes.length>10000)fail(400,'Too many hashes.');const cached:any={};
  for(let n=0;n<hashes.length;n+=100){const batch=hashes.slice(n,n+100);const r=api('/link/lookup',{urls:batch.map(magnet)});if(!Array.isArray(r.cached)||r.cached.length!==batch.length)fail(502,'EasyDebrid returned an invalid cache check.');batch.forEach((h:string,i:number)=>cached[h]=r.cached[i]===true);}return ok({cached});
 }
 if(req.path==='/ether/debrid/acquire'){const h=String(req.body?.infoHash||'');const r=api('/link/lookup',{urls:[magnet(h)]});if(r.cached?.[0]!==true)return {status:409,body:{error:{code:'not_cached',message:'This torrent is not cached.'}}};return ok({torrentId:h,ready:true,added:false,files:files(h)});}
 if(req.path==='/ether/debrid/link'){const h=String(req.body?.infoHash||req.body?.torrentId||'');const f=files(h).find((f:any)=>f.path===req.body?.path);if(!f)fail(404,'The selected file is no longer available.');return ok({url:f.link,size:f.size});}
 return {status:404,body:{error:{code:'not_found',message:'Route not found.'}}};
 }catch(e){const status=Number(e.status)||502,message=e.status?e.message:'EasyDebrid could not be reached.';if(req.path==='/ether/test')return ok({ok:false,message});return {status,body:{error:{code:'provider_error',message}}};}}
(globalThis as any).handle=handle;

import { plugin, type Manifest } from '../../typescript/src/index.ts';
import manifest from './manifest.json' with { type: 'json' };
import en from './i18n/en.json' with { type: 'json' };
import fr from './i18n/fr.json' with { type: 'json' };

type History = { titleId: string; type: string; watchedAt: string; completed?: boolean };
type Title = { id: string; title: string; type: string; tmdbId?: number; imdbId?: string; year?: number; genres?: string[]; posterPath?: string; summary?: string };
async function yearData(ctx: any, viewer: number, year: number) {
  if (!Number.isSafeInteger(viewer) || viewer <= 0 || year < 1900 || year > 9999) return { titles: [], plays: 0, genres: [], months: Array(12).fill(0) };
  const viewers = await ctx.ether.viewers.granted();
  if (!viewers.some((v: any) => v.id === viewer)) return { titles: [], plays: 0, genres: [], months: Array(12).fill(0) };
  const history: History[] = await ctx.ether.viewers.history(viewer, 200, 0);
  const counts = new Map<string, number>();
  const months = Array(12).fill(0);
  for (const entry of history) {
    const date = new Date(entry.watchedAt);
    if (!entry.completed || date.getUTCFullYear() !== year) continue;
    let titleId = entry.titleId;
    if (entry.type === 'episode') { const key = Number(titleId); if (Number.isSafeInteger(key) && key >= 4e15 && key < 5e15) titleId = String(2e15 + Math.floor((key - 4e15) / 1e7)); }
    counts.set(titleId, (counts.get(titleId) || 0) + 1);
    months[date.getUTCMonth()]++;
  }
  const titles: Array<Title & {count: number}> = [];
  for (const [id, count] of counts) {
    try {
      const title = await ctx.ether.catalog.get(id) as Title | null;
      if (title) titles.push({ ...title, count });
    } catch { /* A removed title should not hide the rest of the year. */ }
  }
  titles.sort((a,b) => b.count-a.count || a.title.localeCompare(b.title));
  const genreCounts = new Map<string,number>();
  for (const title of titles) for (const genre of title.genres || []) genreCounts.set(genre, (genreCounts.get(genre) || 0) + title.count);
  const genres = [...genreCounts].sort((a,b) => b[1]-a[1] || a[0].localeCompare(b[0])).slice(0,5);
  return { titles, plays: months.reduce((a,b) => a+b,0), genres, months };
}
export const wrappedDefinition = { manifest: manifest as Manifest, strings: { en, fr }, routes: {
  async view(req, ctx) {
    const viewers = await ctx.ether.viewers.granted();
    const viewer = Number(req.query.viewer || viewers[0]?.id || 0);
    const year = Number(req.query.year || new Date().getUTCFullYear());
    const result = await yearData(ctx, viewer, year);
    const data: Record<string,unknown> = { year: String(year), plays: String(result.plays), titleCount: String(result.titles.length), genres: result.genres.map(([g,n]) => `${g} (${n})`).join(', '), titles: result.titles.map(t => ({ ratingKey:t.id, title:t.title, type:t.type, poster:t.posterPath ? `https://image.tmdb.org/t/p/w300${t.posterPath}` : undefined })), series: [{ key:'plays', label:ctx.t('plays'), values:result.months }], times: result.months.map((_,i) => `${year}-${String(i+1).padStart(2,'0')}-01T00:00:00Z`) };
    const page = Math.max(0, Math.min(Math.ceil(viewers.length / 6) - 1, Number(req.query.viewerPage) || 0));
    const links = viewers.slice(page * 6, page * 6 + 6).map((v,i) => { data[`viewer${i}`] = v.name; data[`active${i}`] = v.id === viewer; return { href:`?viewer=${v.id}&viewerPage=${page}`, label:{$:`viewer${i}`}, activeWhen:{$:`active${i}`} }; });
    data.neverActive = false;
    if (page > 0) links.unshift({href:`?viewerPage=${page-1}`, label:'$t:previous' as any, activeWhen:{$:'neverActive'}});
    if ((page + 1) * 6 < viewers.length) links.push({href:`?viewerPage=${page+1}`, label:'$t:next' as any, activeWhen:{$:'neverActive'}});
    return { spec: { specVersion:1, layout:'list', header:[{kind:'page-header',title:'$t:page',description:'$t:description'}], body:[{kind:'filter-bar',controls:{},leading:{kind:'toggle-links',links}}, {kind:'stat-tile',iconKey:'calendar',accent:'violet',label:'$t:year',value:{$:'year'}},{kind:'stat-tile',iconKey:'play',accent:'teal',label:'$t:plays',value:{$:'plays'}},{kind:'stat-tile',iconKey:'film',accent:'blue',label:'$t:titles',value:{$:'titleCount'}},{kind:'heading',level:2,content:'$t:top_titles'},{kind:'widget',widget:'ether.posterGrid',props:{items:{$:'titles'},empty:'$t:empty'}},{kind:'panel',title:'$t:genres',blocks:[{kind:'text',content:{$:'genres'}}]},{kind:'heading',level:2,content:'$t:activity'},{kind:'widget',widget:'ether.liveChart',props:{series:{$:'series'},times:{$:'times'},label:'$t:plays'}}] }, data };
  },
  async catalog(req,ctx) {
    const viewer = Number(req.extra.viewerId || 0), year = Number(req.extra.year || new Date().getUTCFullYear());
    const data = await yearData(ctx, viewer, year);
    return { metas: data.titles.filter(t => (req.type === 'series' ? t.type === 'show' : t.type === req.type) && t.imdbId).slice(req.skip,req.skip+100).map(t => ({id:t.imdbId!,type:req.type,name:t.title,releaseInfo:String(t.year || ''),description:t.summary})) };
  }
}};
export const wrappedPlugin = plugin(wrappedDefinition);
export const handle = wrappedPlugin.handle;

