// CandidateRef returns the stable ref matchers report for a candidate.
func (c SourceCandidate) CandidateRef() string {
	switch {
	case c.Ref != "":
		return c.Ref
	case c.InfoHash != "":
		return "infohash:" + strings.ToLower(c.InfoHash)
	case c.Magnet != "":
		return "magnet:" + c.Magnet
	case c.NZBURL != "":
		return "nzb:" + c.NZBURL
	default:
		return c.Title
	}
}

