func (p *Plugin) kinds() *kindHandlers {
	if p.kindHandlers == nil {
		p.kindHandlers = &kindHandlers{
			catalog: map[string]CatalogProvider{}, resolve: map[string]KindResolver{},
			match: map[string]KindMatcher{}, frontend: map[string]FrontendAdapter{},
		}
	}
	return p.kindHandlers
}

// StreamURL mints a short-lived, scoped ticket for one of this plugin's own
// kind items and returns the Ether stream URL to embed in a frontend adapter
// response (spec §6.5). The viewer is taken from the request's X-Ether-Viewer
// header, which Ether injects after authenticating; the plugin never sees a
// credential. Bytes are served by Ether from the ticket, never by the plugin.
func (c *Context) StreamURL(itemRef string) (string, error) {
	if c.Ether == nil {
		return "", errors.New("stream url: no host service available")
	}
	viewerID, err := strconv.ParseInt(strings.TrimSpace(c.Headers["X-Ether-Viewer"]), 10, 64)
	if err != nil || viewerID <= 0 {
		return "", errors.New("stream url: no authenticated viewer on this request")
	}
	return c.Ether.StreamURL(c.Context, viewerID, itemRef)
}

// dispatchKinds handles the /ether/v1/kinds, /ether/v1/setup and
// /ether/v1/frontend route families. It reports false when the path is
// none of them so Dispatch can fall through to its 404.
func (p *Plugin) dispatchKinds(pctx *Context, method, path string, req RawRequest) (RawResponse, bool) {
	if !strings.HasPrefix(path, "/ether/v1/") {
		return RawResponse{}, false
	}
	rest := strings.TrimPrefix(path, "/ether/v1/")
	parts := strings.Split(rest, "/")
	// Frontend adapters are protocol surfaces (WebDAV, Subsonic, OPDS, …) and
	// see every method token. The kind and setup routes stay JSON GET/POST.
	if parts[0] == "frontend" {
		if len(parts) >= 2 {
			key, _ := url.PathUnescape(parts[1])
			return p.dispatchFrontend(pctx, method, key, "/"+strings.Join(parts[2:], "/"), req), true
		}
		return RawResponse{}, false
	}
	if method != http.MethodPost && method != http.MethodGet {
		return errorJSON(http.StatusMethodNotAllowed, "method_not_allowed", "Kind routes use GET or POST."), true
	}
	switch {
	case len(parts) >= 2 && parts[0] == "kinds":
		kind, _ := url.PathUnescape(parts[1])
		return p.dispatchKind(pctx, kind, parts[2:], req), true
	case len(parts) == 3 && parts[0] == "setup" && parts[2] == "test":
		if p.kindHandlers == nil || p.kindHandlers.setup == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Setup test handler is not registered."), true
		}
		var in SetupTestRequest
		if len(req.Body) > 0 {
			if err := json.Unmarshal(req.Body, &in); err != nil {
				return errorJSON(http.StatusBadRequest, "invalid_json", "Request body must be valid JSON."), true
			}
		}
		if in.Step == "" {
			in.Step, _ = url.PathUnescape(parts[1])
		}
		res, err := p.kindHandlers.setup.TestSetup(pctx, in)
		if err != nil {
			return toRouteErrorResponse(err), true
		}
		return okJSON(res, http.StatusOK), true
	}
	return RawResponse{}, false
}

func (p *Plugin) dispatchKind(pctx *Context, kind string, tail []string, req RawRequest) RawResponse {
	h := p.kindHandlers
	decode := func(v any) (RawResponse, bool) {
		if len(req.Body) == 0 {
			return RawResponse{}, true
		}
		if err := json.Unmarshal(req.Body, v); err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Request body must be valid JSON."), false
		}
		return RawResponse{}, true
	}
	switch {
	case len(tail) == 1 && (tail[0] == "browse" || tail[0] == "search"):
		prov := lookup(h, func(k *kindHandlers) CatalogProvider { return k.catalog[kind] })
		if prov == nil {
			return errorJSON(http.StatusNotFound, "not_found", fmt.Sprintf("No catalogue provider is registered for kind %q.", kind))
		}
		var in KindBrowseRequest
		if resp, ok := decode(&in); !ok {
			return resp
		}
		in.Kind = kind
		if in.Limit <= 0 {
			in.Limit = 200
		}
		if tail[0] == "search" {
			sp, isSearch := prov.(SearchProvider)
			if !isSearch {
				return errorJSON(http.StatusNotImplemented, "not_implemented", "This provider does not search.")
			}
			page, err := sp.Search(pctx, in)
			return kindPageResponse(page, err, in.Limit)
		}
		page, err := prov.Browse(pctx, in)
		return kindPageResponse(page, err, in.Limit)
	case len(tail) == 2 && tail[0] == "items":
		prov := lookup(h, func(k *kindHandlers) CatalogProvider { return k.catalog[kind] })
		if prov == nil {
			return errorJSON(http.StatusNotFound, "not_found", fmt.Sprintf("No catalogue provider is registered for kind %q.", kind))
		}
		id, _ := url.PathUnescape(tail[1])
		item, err := prov.Detail(pctx, kind, id)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(item, http.StatusOK)
	case len(tail) == 1 && tail[0] == "changes":
		prov := lookup(h, func(k *kindHandlers) CatalogProvider { return k.catalog[kind] })
		cp, isChanges := prov.(ChangesProvider)
		if prov == nil || !isChanges {
			// 404/501 tells Ether to fall back to a re-walk diff.
			return errorJSON(http.StatusNotImplemented, "not_implemented", "This provider has no changes feed.")
		}
		var in KindChangesRequest
		if resp, ok := decode(&in); !ok {
			return resp
		}
		in.Kind = kind
		page, err := cp.Changes(pctx, in)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		if page.Upserts == nil {
			page.Upserts = []KindItem{}
		}
		return okJSON(page, http.StatusOK)
	case len(tail) == 1 && tail[0] == "resolve":
		var r KindResolver
		if h != nil {
			r = h.resolve[kind]
		}
		if r == nil {
			return errorJSON(http.StatusNotFound, "not_found", fmt.Sprintf("No resolver is registered for kind %q.", kind))
		}
		var in KindResolveRequest
		if resp, ok := decode(&in); !ok {
			return resp
		}
		in.Kind = kind
		res, err := r.Resolve(pctx, in)
		if err != nil {
			if errors.Is(err, ErrKindNotAvailable) {
				return okJSON(KindResolveResponse{Sources: []PlayableSource{}}, http.StatusOK)
			}
			return toRouteErrorResponse(err)
		}
		if res.Sources == nil {
			res.Sources = []PlayableSource{}
		}
		return okJSON(res, http.StatusOK)
	case len(tail) == 1 && tail[0] == "match":
		var m KindMatcher
		if h != nil {
			m = h.match[kind]
		}
		if m == nil {
			return errorJSON(http.StatusNotFound, "not_found", fmt.Sprintf("No matcher is registered for kind %q.", kind))
		}
		var in KindMatchRequest
		if resp, ok := decode(&in); !ok {
			return resp
		}
		in.Kind = kind
		res, err := m.Match(pctx, in)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		if res.Matches == nil {
			res.Matches = []KindMatchScore{}
		}
		return okJSON(res, http.StatusOK)
	}
	return errorJSON(http.StatusNotFound, "not_found", "No kind route matched.")
}

func lookup(h *kindHandlers, get func(*kindHandlers) CatalogProvider) CatalogProvider {
	if h == nil {
		return nil
	}
	return get(h)
}

// kindPageResponse enforces the page contract: never more than limit
// items (Ether treats an oversized page as a contract error).
func kindPageResponse(page KindPage, err error, limit int) RawResponse {
	if err != nil {
		return toRouteErrorResponse(err)
	}
	if limit > 0 && len(page.Items) > limit {
		page.Items = page.Items[:limit]
	}
	if page.Items == nil {
		page.Items = []KindItem{}
	}
	return okJSON(page, http.StatusOK)
}

func (p *Plugin) dispatchFrontend(pctx *Context, method, key, subPath string, req RawRequest) RawResponse {
	var a FrontendAdapter
	if p.kindHandlers != nil {
		a = p.kindHandlers.frontend[key]
	}
	if a == nil || a.Handler() == nil {
		return errorJSON(http.StatusNotFound, "not_found", fmt.Sprintf("No frontend adapter is registered for %q.", key))
	}
	if subPath == "/" || subPath == "" {
		subPath = "/"
	}
	// Protocol adapters (Subsonic, OPDS, WebDAV) carry their arguments in the
	// query string; the server relays them, so rebuild the request URL with
	// the original query. The server flattens repeated keys to the first
	// value, so a query map holds one value per key.
	_, query := parsePathAndQuery(req.Path, req.Query)
	target := "http://ether.invalid" + subPath
	if len(query) > 0 {
		target += "?" + encodeQuery(query)
	}
	httpReq := httptest.NewRequestWithContext(pctx.Context, method, target, bytes.NewReader(req.Body))
	for k, v := range req.Headers {
		httpReq.Header.Set(k, v)
	}
	rec := httptest.NewRecorder()
	a.Handler().ServeHTTP(rec, httpReq)
	res := rec.Result()
	defer res.Body.Close()
	body, err := io.ReadAll(io.LimitReader(res.Body, maxFrontendBody+1))
	if err != nil {
		return errorJSON(http.StatusBadGateway, "adapter_error", err.Error())
	}
	if len(body) > maxFrontendBody {
		return errorJSON(http.StatusBadGateway, "adapter_error", "Frontend adapter response is larger than 10 MiB; serve media through Ether stream URLs.")
	}
	hdrs := map[string]string{}
	for k := range res.Header {
		hdrs[k] = res.Header.Get(k)
	}
	// A HEAD reply carries headers only, exactly as a real server would.
	if method == http.MethodHead {
		body = nil
	}
	return RawResponse{Status: res.StatusCode, Headers: hdrs, BinaryBody: body}
}

// encodeQuery renders a query map back into a raw query string, preserving
// key order is unnecessary; values are escaped so adapters see what the
// viewer sent.
func encodeQuery(query map[string]string) string {
	keys := make([]string, 0, len(query))
	for k := range query {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, url.QueryEscape(k)+"="+url.QueryEscape(query[k]))
	}
	return strings.Join(parts, "&")
}

// Member is one non-directory entry in archive order.
type Member struct {
	Index int // position among non-directory members, archive order
	Name  string
	Size  int64
}

// List returns the non-directory members of a zip-shaped archive.
func List(data []byte) ([]Member, error) {
	zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return nil, err
	}
	var out []Member
	for _, f := range zr.File {
		if f.FileInfo().IsDir() || strings.HasSuffix(f.Name, "/") {
			continue
		}
		out = append(out, Member{Index: len(out), Name: f.Name, Size: int64(f.UncompressedSize64)})
	}
	return out, nil
}

// ListNatural is List sorted the way readers order pages (1, 2, 10).
func ListNatural(data []byte) ([]Member, error) {
	ms, err := List(data)
	if err != nil {
		return nil, err
	}
	sort.SliceStable(ms, func(i, j int) bool { return NaturalLess(ms[i].Name, ms[j].Name) })
	for i := range ms {
		ms[i].Index = i
	}
	return ms, nil
}

// ReadMember returns one member's bytes by exact name.
func ReadMember(data []byte, name string) ([]byte, error) {
	zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return nil, err
	}
	for _, f := range zr.File {
		if f.Name != name {
			continue
		}
		rc, err := f.Open()
		if err != nil {
			return nil, err
		}
		defer rc.Close()
		return io.ReadAll(rc)
	}
	return nil, fmt.Errorf("archivex: member %q not found", name)
}

// ReadMemberAt returns the nth non-directory member's bytes (0-based).
func ReadMemberAt(data []byte, index int) ([]byte, Member, error) {
	ms, err := List(data)
	if err != nil {
		return nil, Member{}, err
	}
	if index < 0 || index >= len(ms) {
		return nil, Member{}, fmt.Errorf("archivex: member index %d out of range (%d members)", index, len(ms))
	}
	b, err := ReadMember(data, ms[index].Name)
	return b, ms[index], err
}

// NaturalLess compares names with embedded numbers compared numerically.
func NaturalLess(a, b string) bool {
	ai, bi := 0, 0
	for ai < len(a) && bi < len(b) {
		ac, bc := a[ai], b[bi]
		if isDigit(ac) && isDigit(bc) {
			an, bn := 0, 0
			for ai < len(a) && isDigit(a[ai]) {
				an = an*10 + int(a[ai]-'0')
				ai++
			}
			for bi < len(b) && isDigit(b[bi]) {
				bn = bn*10 + int(b[bi]-'0')
				bi++
			}
			if an != bn {
				return an < bn
			}
			continue
		}
		if ac != bc {
			return ac < bc
		}
		ai++
		bi++
	}
	return len(a)-ai < len(b)-bi
}

// Feed is a normalised feed document.
type Feed struct {
	Title   string
	Summary string
	Link    string
	Image   string
	Entries []Entry
}

// Parse detects and parses RSS 2.0, Atom or JSON Feed.
func Parse(data []byte) (Feed, error) {
	trim := strings.TrimSpace(string(data))
	if strings.HasPrefix(trim, "{") {
		return parseJSONFeed(data)
	}
	var probe struct {
		XMLName xml.Name
	}
	if err := xml.Unmarshal(data, &probe); err != nil {
		return Feed{}, err
	}
	switch probe.XMLName.Local {
	case "rss", "RDF":
		return parseRSS(data)
	case "feed":
		return parseAtom(data)
	}
	return Feed{}, fmt.Errorf("feedparse: unrecognised feed document %q", probe.XMLName.Local)
}

func parseRSS(data []byte) (Feed, error) {
	var doc struct {
		Channel struct {
			Title string `xml:"title"`
			Desc  string `xml:"description"`
			Link  string `xml:"link"`
			Image struct {
				URL string `xml:"url"`
			} `xml:"image"`
			Items []struct {
				Title string `xml:"title"`
				Desc  string `xml:"description"`
				Link  string `xml:"link"`
				GUID  string `xml:"guid"`
				Date  string `xml:"pubDate"`
				Enc   struct {
					URL string `xml:"url,attr"`
				} `xml:"enclosure"`
			} `xml:"item"`
		} `xml:"channel"`
	}
	if err := xml.Unmarshal(data, &doc); err != nil {
		return Feed{}, err
	}
	feed := Feed{Title: doc.Channel.Title, Summary: doc.Channel.Desc, Link: doc.Channel.Link, Image: doc.Channel.Image.URL}
	for _, it := range doc.Channel.Items {
		feed.Entries = append(feed.Entries, Entry{
			ID: firstNonEmpty(it.GUID, it.Link), Title: it.Title, Summary: it.Desc,
			Link: it.Link, Audio: it.Enc.URL, Date: parseDate(it.Date),
		})
	}
	return feed, nil
}

func parseAtom(data []byte) (Feed, error) {
	type link struct {
		Href string `xml:"href,attr"`
		Rel  string `xml:"rel,attr"`
		Type string `xml:"type,attr"`
	}
	var doc struct {
		Title   string `xml:"title"`
		Summary string `xml:"subtitle"`
		Links   []link `xml:"link"`
		Entries []struct {
			ID      string `xml:"id"`
			Title   string `xml:"title"`
			Summary string `xml:"summary"`
			Updated string `xml:"updated"`
			Links   []link `xml:"link"`
			Author  struct {
				Name string `xml:"name"`
			} `xml:"author"`
		} `xml:"entry"`
	}
	if err := xml.Unmarshal(data, &doc); err != nil {
		return Feed{}, err
	}
	pick := func(ls []link) (page, media string) {
		for _, l := range ls {
			switch {
			case l.Rel == "enclosure":
				media = l.Href
			case l.Rel == "alternate" || l.Rel == "":
				page = firstNonEmpty(page, l.Href)
			}
		}
		return page, media
	}
	page, _ := pick(doc.Links)
	feed := Feed{Title: doc.Title, Summary: doc.Summary, Link: page}
	for _, e := range doc.Entries {
		p, m := pick(e.Links)
		ent := Entry{ID: firstNonEmpty(e.ID, p), Title: e.Title, Summary: e.Summary, Link: p, Audio: m, Date: parseDate(e.Updated)}
		if e.Author.Name != "" {
			ent.Authors = []string{e.Author.Name}
		}
		feed.Entries = append(feed.Entries, ent)
	}
	return feed, nil
}

func parseJSONFeed(data []byte) (Feed, error) {
	var doc struct {
		Title string `json:"title"`
		Desc  string `json:"description"`
		Home  string `json:"home_page_url"`
		Icon  string `json:"icon"`
		Items []struct {
			ID      string `json:"id"`
			Title   string `json:"title"`
			Summary string `json:"summary"`
			URL     string `json:"url"`
			Date    string `json:"date_published"`
			Image   string `json:"image"`
			Attach  []struct {
				URL string `json:"url"`
			} `json:"attachments"`
		} `json:"items"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		return Feed{}, err
	}
	feed := Feed{Title: doc.Title, Summary: doc.Desc, Link: doc.Home, Image: doc.Icon}
	for _, it := range doc.Items {
		ent := Entry{ID: firstNonEmpty(it.ID, it.URL), Title: it.Title, Summary: it.Summary, Link: it.URL, Image: it.Image, Date: parseDate(it.Date)}
		if len(it.Attach) > 0 {
			ent.Audio = it.Attach[0].URL
		}
		feed.Entries = append(feed.Entries, ent)
	}
	return feed, nil
}

// StableID turns a feed URL/id into a legal plugin external id.
func StableID(s string) string {
	if s == "" {
		return ""
	}
	return fmt.Sprintf("f%x", sha256.Sum256([]byte(s)))[:24]
}

// Items maps a feed onto a two-level kind: the feed as root, entries as
// playable leaves whose hints carry the link/media URLs for the resolver.
func (f Feed) Items(rootLevel, leafLevel, feedURL string) ([]etherplugin.KindItem, error) {
	rootID := StableID(firstNonEmpty(feedURL, f.Link, f.Title))
	root := etherplugin.KindItem{
		ID: rootID, Level: rootLevel, Title: f.Title, Summary: f.Summary,
		ChildCount: len(f.Entries), LeafCount: len(f.Entries),
	}
	if f.Image != "" {
		root.Art = []etherplugin.KindArtRef{{Role: "poster", URL: f.Image}}
	}
	out := []etherplugin.KindItem{root}
	for i, e := range f.Entries {
		hints, err := json.Marshal(map[string]string{"link": e.Link, "mediaUrl": e.Audio})
		if err != nil {
			return nil, err
		}
		item := etherplugin.KindItem{
			ID: StableID(firstNonEmpty(e.ID, e.Link, e.Title)), Level: leafLevel,
			ParentID: rootID, Index: i, Title: e.Title, Summary: e.Summary,
			Playable: e.Audio != "" || e.Link != "", Hints: hints,
		}
		if !e.Date.IsZero() {
			item.Released = e.Date.Unix()
			item.Year = e.Date.Year()
		}
		if e.Image != "" {
			item.Art = []etherplugin.KindArtRef{{Role: "poster", URL: e.Image}}
		}
		out = append(out, item)
	}
	return out, nil
}

func parseDate(s string) time.Time {
	for _, layout := range []string{time.RFC1123Z, time.RFC1123, time.RFC3339, "2006-01-02 15:04:05 -0700"} {
		if t, err := time.Parse(layout, strings.TrimSpace(s)); err == nil {
			return t
		}
	}
	return time.Time{}
}

func firstNonEmpty(vs ...string) string {
	for _, v := range vs {
		if strings.TrimSpace(v) != "" {
			return strings.TrimSpace(v)
		}
	}
	return ""
}

// Marshal encodes a hints struct as the JSON object KindItem.Hints holds.
func Marshal(v any) (json.RawMessage, error) {
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	if len(b) > MaxBytes {
		return nil, fmt.Errorf("hints: %d bytes exceeds the %d byte cap", len(b), MaxBytes)
	}
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(b, &obj); err != nil || obj == nil {
		return nil, fmt.Errorf("hints: value must encode as a JSON object")
	}
	return b, nil
}

// Unmarshal decodes hints into a typed struct; empty hints leave v alone.
func Unmarshal(raw json.RawMessage, v any) error {
	if len(raw) == 0 {
		return nil
	}
	return json.Unmarshal(raw, v)
}

// Fields encodes a value map as KindItem.Fields (key -> raw JSON value).
func Fields(values map[string]any) (map[string]json.RawMessage, error) {
	out := make(map[string]json.RawMessage, len(values))
	for k, v := range values {
		b, err := json.Marshal(v)
		if err != nil {
			return nil, fmt.Errorf("hints: field %q: %w", k, err)
		}
		out[k] = b
	}
	return out, nil
}

// EPUB parses a book's OPF metadata out of epub bytes.
func EPUB(data []byte) (map[string]any, error) {
	container, err := archivex.ReadMember(data, "META-INF/container.xml")
	if err != nil {
		return nil, err
	}
	var cont struct {
		Rootfiles []struct {
			FullPath string `xml:"full-path,attr"`
		} `xml:"rootfiles>rootfile"`
	}
	if err := xml.Unmarshal(container, &cont); err != nil || len(cont.Rootfiles) == 0 {
		return nil, err
	}
	opf, err := archivex.ReadMember(data, cont.Rootfiles[0].FullPath)
	if err != nil {
		return nil, err
	}
	var doc struct {
		Metadata struct {
			Title    string   `xml:"title"`
			Creators []string `xml:"creator"`
			Language string   `xml:"language"`
			Date     string   `xml:"date"`
			Subjects []string `xml:"subject"`
			Desc     string   `xml:"description"`
		} `xml:"metadata"`
	}
	// encoding/xml matches local names, so dc: prefixes parse flat.
	if err := xml.Unmarshal(stripPrefixes(opf), &doc); err != nil {
		return nil, err
	}
	out := map[string]any{}
	put(out, "title", doc.Metadata.Title)
	if len(doc.Metadata.Creators) > 0 {
		out["author"] = doc.Metadata.Creators
	}
	put(out, "language", doc.Metadata.Language)
	put(out, "summary", doc.Metadata.Desc)
	if len(doc.Metadata.Subjects) > 0 {
		out["subjects"] = doc.Metadata.Subjects
	}
	if y, ok := yearOf(doc.Metadata.Date); ok {
		out["year"] = y
	}
	return out, nil
}

// ComicInfo parses ComicInfo.xml (the cbz/cbr sidecar) into fields.
func ComicInfo(data []byte) (map[string]any, error) {
	var doc struct {
		Title     string `xml:"Title"`
		Series    string `xml:"Series"`
		Number    string `xml:"Number"`
		Volume    int    `xml:"Volume"`
		Year      int    `xml:"Year"`
		Summary   string `xml:"Summary"`
		Writer    string `xml:"Writer"`
		Genre     string `xml:"Genre"`
		PageCount int    `xml:"PageCount"`
	}
	if err := xml.Unmarshal(data, &doc); err != nil {
		return nil, err
	}
	out := map[string]any{}
	put(out, "title", doc.Title)
	put(out, "series", doc.Series)
	put(out, "number", doc.Number)
	put(out, "summary", doc.Summary)
	if doc.Writer != "" {
		out["writer"] = splitPeople(doc.Writer)
	}
	if doc.Genre != "" {
		out["genre"] = splitPeople(doc.Genre)
	}
	if doc.Volume > 0 {
		out["volume"] = doc.Volume
	}
	if doc.Year > 0 {
		out["year"] = doc.Year
	}
	if doc.PageCount > 0 {
		out["pageCount"] = doc.PageCount
	}
	return out, nil
}

// ID3 reads ID3v2.3/2.4 text frames (title, album, artist, track, year…).
func ID3(data []byte) map[string]any {
	if len(data) < 10 || string(data[:3]) != "ID3" {
		return nil
	}
	ver := data[3]
	size := syncSafe(data[6:10])
	body := data[10:]
	if size < len(body) {
		body = body[:size]
	}
	frames := map[string]string{
		"TIT2": "title", "TALB": "album", "TPE1": "artist", "TPE2": "albumArtist",
		"TRCK": "track", "TPOS": "disc", "TCON": "genre", "TYER": "year",
		"TDRC": "year", "TCOM": "composer", "TLEN": "durationMs",
	}
	out := map[string]any{}
	for len(body) >= 10 {
		id := string(body[:4])
		if id[0] == 0 {
			break
		}
		var fsize int
		if ver >= 4 {
			fsize = syncSafe(body[4:8])
		} else {
			fsize = int(binary.BigEndian.Uint32(body[4:8]))
		}
		body = body[10:]
		if fsize < 0 || fsize > len(body) {
			break
		}
		if key, ok := frames[id]; ok && fsize > 0 {
			out[key] = decodeID3Text(body[:fsize])
		}
		body = body[fsize:]
	}
	if n, ok := out["track"].(string); ok {
		if i, err := strconv.Atoi(strings.SplitN(n, "/", 2)[0]); err == nil {
			out["track"] = i
		}
	}
	if y, ok := out["year"].(string); ok {
		if yr, valid := yearOf(y); valid {
			out["year"] = yr
		}
	}
	return out
}

// FLAC reads the Vorbis comment block of a FLAC stream.
func FLAC(data []byte) map[string]any {
	if len(data) < 8 || string(data[:4]) != "fLaC" {
		return nil
	}
	rest := data[4:]
	for len(rest) >= 4 {
		last := rest[0]&0x80 != 0
		typ := rest[0] & 0x7f
		n := int(rest[1])<<16 | int(rest[2])<<8 | int(rest[3])
		rest = rest[4:]
		if n > len(rest) {
			return nil
		}
		if typ == 4 { // Vorbis comment
			return parseVorbis(rest[:n])
		}
		rest = rest[n:]
		if last {
			break
		}
	}
	return nil
}

func parseVorbis(b []byte) map[string]any {
	readStr := func() (string, bool) {
		if len(b) < 4 {
			return "", false
		}
		n := int(binary.LittleEndian.Uint32(b))
		b = b[4:]
		if n > len(b) {
			return "", false
		}
		s := string(b[:n])
		b = b[n:]
		return s, true
	}
	if _, ok := readStr(); !ok || len(b) < 4 { // vendor
		return nil
	}
	count := int(binary.LittleEndian.Uint32(b))
	b = b[4:]
	out := map[string]any{}
	for i := 0; i < count; i++ {
		s, ok := readStr()
		if !ok {
			break
		}
		k, v, found := strings.Cut(s, "=")
		if !found {
			continue
		}
		key := map[string]string{
			"TITLE": "title", "ALBUM": "album", "ARTIST": "artist", "ALBUMARTIST": "albumArtist",
			"TRACKNUMBER": "track", "DISCNUMBER": "disc", "GENRE": "genre", "DATE": "year",
		}[strings.ToUpper(k)]
		if key == "" {
			key = strings.ToLower(k)
		}
		out[key] = v
	}
	if y, ok := out["year"].(string); ok {
		if yr, valid := yearOf(y); valid {
			out["year"] = yr
		}
	}
	return out
}

func decodeID3Text(b []byte) string {
	if len(b) == 0 {
		return ""
	}
	switch b[0] {
	case 3: // UTF-8
		return strings.TrimRight(string(b[1:]), "\x00")
	case 1: // UTF-16 with BOM
		body := b[1:]
		if len(body) >= 2 && body[0] == 0xfe && body[1] == 0xff {
			return decodeUTF16(body[2:], binary.BigEndian)
		}
		if len(body) >= 2 && body[0] == 0xff && body[1] == 0xfe {
			return decodeUTF16(body[2:], binary.LittleEndian)
		}
	case 2:
		return decodeUTF16(b[1:], binary.BigEndian)
	default: // Latin-1, close enough for tags
		runes := make([]rune, 0, len(b))
		for _, c := range b[1:] {
			runes = append(runes, rune(c))
		}
		return strings.TrimRight(string(runes), "\x00")
	}
	return ""
}

func decodeUTF16(b []byte, order binary.ByteOrder) string {
	u := make([]uint16, 0, len(b)/2)
	for i := 0; i+1 < len(b); i += 2 {
		u = append(u, order.Uint16(b[i:]))
	}
	return strings.TrimRight(string(utf16.Decode(u)), "\x00")
}

func syncSafe(b []byte) int {
	n := 0
	for _, c := range b {
		n = n<<7 | int(c&0x7f)
	}
	return n
}

// stripPrefixes removes dc:/opf: element prefixes so encoding/xml local
// matching sees plain names. Good enough for metadata reading.
func stripPrefixes(b []byte) []byte {
	for _, p := range []string{"dc:", "opf:"} {
		b = bytes.ReplaceAll(b, []byte("<"+p), []byte("<"))
		b = bytes.ReplaceAll(b, []byte("</"+p), []byte("</"))
	}
	return b
}

func put(m map[string]any, k, v string) {
	if strings.TrimSpace(v) != "" {
		m[k] = strings.TrimSpace(v)
	}
}

func splitPeople(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

func yearOf(s string) (int, bool) {
	s = strings.TrimSpace(s)
	if len(s) < 4 {
		return 0, false
	}
	y, err := strconv.Atoi(s[:4])
	return y, err == nil && y > 0
}

// Fetcher wraps a plugin Host with a polite per-host delay.
type Fetcher struct {
	Host   etherplugin.Host
	Delay  time.Duration // between requests to one host; default 250ms
	mu     sync.Mutex
	lastAt map[string]time.Time
}

// Get fetches a URL through the host and returns the body.
func (f *Fetcher) Get(ctx context.Context, rawURL string) (string, int, error) {
	if err := f.wait(ctx, rawURL); err != nil {
		return "", 0, err
	}
	resp, err := f.Host.Fetch(ctx, etherplugin.HostFetchRequest{Method: "GET", URL: rawURL})
	return resp.Body, resp.Status, err
}

func (f *Fetcher) wait(ctx context.Context, rawURL string) error {
	delay := f.Delay
	if delay <= 0 {
		delay = 250 * time.Millisecond
	}
	host := rawURL
	if u, err := url.Parse(rawURL); err == nil {
		host = u.Host
	}
	f.mu.Lock()
	if f.lastAt == nil {
		f.lastAt = map[string]time.Time{}
	}
	next := f.lastAt[host].Add(delay)
	f.lastAt[host] = time.Now()
	f.mu.Unlock()
	if d := time.Until(next); d > 0 {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(d):
		}
	}
	f.mu.Lock()
	f.lastAt[host] = time.Now()
	f.mu.Unlock()
	return nil
}

var (
	tagRe  = regexp.MustCompile(`(?s)<script.*?</script>|<style.*?</style>|<[^>]+>`)
	linkRe = regexp.MustCompile(`(?is)<a\s[^>]*href\s*=\s*["']([^"']+)["'][^>]*>(.*?)</a>`)
)

// Text strips markup down to readable text.
func Text(pageHTML string) string {
	return strings.Join(strings.Fields(html.UnescapeString(tagRe.ReplaceAllString(pageHTML, " "))), " ")
}

// Link is one anchor: absolute URL plus its visible text.
type Link struct {
	URL  string
	Text string
}

// Links extracts anchors, resolving relative hrefs against base.
func Links(pageHTML, base string) []Link {
	baseURL, _ := url.Parse(base)
	var out []Link
	for _, m := range linkRe.FindAllStringSubmatch(pageHTML, -1) {
		href := html.UnescapeString(strings.TrimSpace(m[1]))
		if href == "" || strings.HasPrefix(href, "#") || strings.HasPrefix(href, "javascript:") {
			continue
		}
		if baseURL != nil {
			if u, err := url.Parse(href); err == nil {
				href = baseURL.ResolveReference(u).String()
			}
		}
		out = append(out, Link{URL: href, Text: Text(m[2])})
	}
	return out
}

// Matches returns the capturing groups of every regex match — the
// escape hatch for listing pages with regular shapes.
func Matches(page string, re *regexp.Regexp) [][]string {
	return re.FindAllStringSubmatch(page, -1)
}

// PairingPaths are the fixed Ether endpoints a sidecar uses to pair.
const (
	// PairExchangePath accepts a one-time code and returns a credential.
	PairExchangePath = "/ether/plugins/pair"
	// TunnelPath is the WebSocket endpoint a paired sidecar dials.
	TunnelPath = "/ether/plugins/tunnel"

	credentialFileMode os.FileMode = 0o600
	stateDirMode       os.FileMode = 0o700
)

// savedCredential is what the SDK writes to <state dir>/credential.
type savedCredential struct {
	Credential string `json:"credential"`
	URL        string `json:"url"`
}

// PairingInputs are the pairing settings read from options and the
// environment. Every SDK resolves them in the same order.
type PairingInputs struct {
	// URL is the server's http(s) base (from ETHER_URL).
	URL string
	// Code is a one-time pairing code (from ETHER_PAIRING_CODE).
	Code string
	// Credential is an explicit credential; it always wins.
	Credential string
	// StateDir overrides where the credential file is kept.
	StateDir string
}

// pairingInputsFromEnv reads the options and ETHER_* environment variables.
func pairingInputsFromEnv(opts ServeOptions) PairingInputs {
	in := PairingInputs{URL: strings.TrimSpace(opts.URL)}
	if in.URL == "" {
		in.URL = strings.TrimSpace(os.Getenv("ETHER_URL"))
	}
	in.Code = strings.TrimSpace(os.Getenv("ETHER_PAIRING_CODE"))
	in.Credential = strings.TrimSpace(opts.Credential)
	if in.Credential == "" {
		in.Credential = strings.TrimSpace(os.Getenv("ETHER_PLUGIN_CREDENTIAL"))
	}
	in.StateDir = strings.TrimSpace(opts.StateDir)
	if in.StateDir == "" {
		in.StateDir = strings.TrimSpace(os.Getenv("ETHER_PLUGIN_STATE_DIR"))
	}
	return in
}

// PairURL returns the absolute URL that exchanges a code for a credential.
func PairURL(base string) (string, error) {
	b, err := serverBase(base)
	if err != nil {
		return "", err
	}
	return b + PairExchangePath, nil
}

// TunnelURL returns the absolute ws(s) tunnel URL for a server base.
func TunnelURL(base string) (string, error) {
	b, err := serverBase(base)
	if err != nil {
		return "", err
	}
	u, err := url.Parse(b)
	if err != nil {
		return "", err
	}
	switch u.Scheme {
	case "https":
		u.Scheme = "wss"
	default:
		u.Scheme = "ws"
	}
	u.Path = TunnelPath
	return u.String(), nil
}

// serverBase normalizes an http(s) base, rejecting anything else.
func serverBase(base string) (string, error) {
	base = strings.TrimSpace(base)
	if base == "" {
		return "", errors.New("etherplugin: ETHER_URL is not set")
	}
	u, err := url.Parse(base)
	if err != nil {
		return "", fmt.Errorf("etherplugin: ETHER_URL is not a valid URL: %w", err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return "", errors.New("etherplugin: ETHER_URL must use http or https")
	}
	if u.Host == "" {
		return "", errors.New("etherplugin: ETHER_URL has no host")
	}
	u.Path = strings.TrimSuffix(u.Path, "/")
	u.RawQuery = ""
	u.Fragment = ""
	return u.String(), nil
}

// StateDir resolves where the credential file is kept: an explicit dir, else
// /data when it exists and is writable (a Docker volume), else the OS user
// config dir under ether-plugins/<plugin id>/.
func StateDir(explicit, pluginID string) (string, error) {
	if explicit = strings.TrimSpace(explicit); explicit != "" {
		return explicit, nil
	}
	if info, err := os.Stat("/data"); err == nil && info.IsDir() && writableDir("/data") {
		return "/data", nil
	}
	base, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("etherplugin: no state directory available: %w", err)
	}
	return filepath.Join(base, "ether-plugins", pluginID), nil
}

func writableDir(dir string) bool {
	f, err := os.CreateTemp(dir, ".ether-write-*")
	if err != nil {
		return false
	}
	name := f.Name()
	_ = f.Close()
	_ = os.Remove(name)
	return true
}

// resolveCredential applies the startup order: explicit credential, then the
// saved file, then a one-time pairing code (which is exchanged and saved). It
// returns whether the credential came from the file, so a later 401 can clear
// the file. It never logs the credential or the code.
func resolveCredential(ctx context.Context, in PairingInputs, pluginID string) (credential string, fromFile bool, err error) {
	dir, err := StateDir(in.StateDir, pluginID)
	if err != nil {
		return "", false, err
	}
	path := filepath.Join(dir, "credential")
	if in.Credential != "" {
		return in.Credential, false, nil
	}
	if saved, ok := readSavedCredential(path); ok {
		return saved.Credential, true, nil
	}
	if in.URL == "" {
		return "", false, noCredentialError()
	}
	if in.Code != "" {
		cred, err := exchangeCode(ctx, in.URL, in.Code, nil)
		if err != nil {
			return "", false, err
		}
		if err := writeSavedCredential(path, dir, savedCredential{Credential: cred, URL: in.URL}); err != nil {
			return "", false, err
		}
		return cred, true, nil
	}
	return "", false, noCredentialError()
}

func noCredentialError() error {
	return errors.New("No credential: create a pairing code in Ether (Plugins > this plugin > Connect a sidecar) and set ETHER_PAIRING_CODE.")
}

func readSavedCredential(path string) (savedCredential, bool) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return savedCredential{}, false
	}
	var saved savedCredential
	if json.Unmarshal(raw, &saved) != nil || saved.Credential == "" {
		return savedCredential{}, false
	}
	return saved, true
}

func writeSavedCredential(path, dir string, saved savedCredential) error {
	if err := os.MkdirAll(dir, stateDirMode); err != nil {
		return fmt.Errorf("etherplugin: cannot create state directory: %w", err)
	}
	if err := os.Chmod(dir, stateDirMode); err != nil {
		return fmt.Errorf("etherplugin: cannot secure state directory: %w", err)
	}
	raw, err := json.Marshal(saved)
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, ".credential-*")
	if err != nil {
		return fmt.Errorf("etherplugin: cannot write credential: %w", err)
	}
	name := tmp.Name()
	if err := os.Chmod(name, credentialFileMode); err != nil {
		_ = tmp.Close()
		_ = os.Remove(name)
		return err
	}
	if _, err := tmp.Write(raw); err != nil {
		_ = tmp.Close()
		_ = os.Remove(name)
		return err
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(name)
		return err
	}
	if err := os.Rename(name, path); err != nil {
		_ = os.Remove(name)
		return err
	}
	return nil
}

func clearSavedCredential(pluginID, explicitDir string) {
	dir, err := StateDir(explicitDir, pluginID)
	if err != nil {
		return
	}
	_ = os.Remove(filepath.Join(dir, "credential"))
}

// exchangeCode posts a one-time code to the server and returns the credential.
func exchangeCode(ctx context.Context, base, code string, client *http.Client) (string, error) {
	endpoint, err := PairURL(base)
	if err != nil {
		return "", err
	}
	body, err := json.Marshal(map[string]string{"code": code})
	if err != nil {
		return "", err
	}
	if client == nil {
		client = &http.Client{Timeout: 15 * time.Second}
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("etherplugin: pairing request failed: %w", err)
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("etherplugin: pairing code was rejected (HTTP %d)", resp.StatusCode)
	}
	var out struct {
		Credential string `json:"credential"`
	}
	if json.Unmarshal(raw, &out) != nil || out.Credential == "" {
		return "", errors.New("etherplugin: pairing response had no credential")
	}
	return out.Credential, nil
}

// T resolves a localized string key with optional parameter interpolation.
func (c *Context) T(key string, params map[string]any) string {
	if c.I18n == nil {
		return key
	}
	return c.I18n.T(key, params, c.Locale)
}

// Definition configures a new Plugin instance.
type Definition struct {
	Manifest          Manifest
	Routes            Routes
	DefaultSettings   map[string]any
	Strings           StringsCatalog
	DefaultLocale     string
	Host              Host
	RemoteHostOptions RemoteHostOptions
}

// New constructs a Plugin from a Definition.
func New(def Definition) *Plugin {
	defaultLocale := def.DefaultLocale
	if defaultLocale == "" {
		defaultLocale = "en"
	}
	catalog := StringsCatalog{}
	if def.Manifest.Ether != nil && def.Manifest.Ether.Strings != nil {
		for loc, raw := range def.Manifest.Ether.Strings {
			if m, ok := raw.(map[string]string); ok {
				tbl := map[string]string{}
				for k, v := range m {
					tbl[k] = v
				}
				catalog[loc] = tbl
			} else if m, ok := raw.(map[string]any); ok {
				tbl := map[string]string{}
				for k, v := range m {
					if s, ok := v.(string); ok {
						tbl[k] = s
					}
				}
				catalog[loc] = tbl
			}
		}
	}
	for loc, tbl := range def.Strings {
		if catalog[loc] == nil {
			catalog[loc] = map[string]string{}
		}
		for k, v := range tbl {
			catalog[loc][k] = v
		}
	}

	var schema *SettingsSchema
	pageRoutes := map[string]string{}
	if def.Manifest.Ether != nil {
		schema = def.Manifest.Ether.Settings
		if def.Manifest.Ether.Contributes != nil {
			for _, p := range def.Manifest.Ether.Contributes.Pages {
				if p.Route != "" && p.Key != "" {
					pageRoutes[p.Route] = p.Key
				}
			}
			for _, s := range def.Manifest.Ether.Contributes.Slots {
				if s.Route != "" && s.Key != "" {
					pageRoutes[s.Route] = s.Key
				}
			}
		}
	}
	initialSettings, _ := DecodeSettings(schema, nil, def.DefaultSettings)

	return &Plugin{
		manifest:        def.Manifest,
		routes:          def.Routes,
		defaultSettings: def.DefaultSettings,
		defaultLocale:   defaultLocale,
		i18n:            NewI18n(catalog, defaultLocale),
		host:            def.Host,
		remoteOpts:      def.RemoteHostOptions,
		pageRoutes:      pageRoutes,
		settings:        initialSettings,
	}
}

// Manifest returns the plugin's Manifest.
func (p *Plugin) Manifest() Manifest {
	return p.manifest
}

// GetSettings returns a copy of the plugin's active settings.
func (p *Plugin) GetSettings() map[string]any {
	p.mu.RLock()
	defer p.mu.RUnlock()
	out := make(map[string]any, len(p.settings))
	for k, v := range p.settings {
		out[k] = v
	}
	return out
}

// SetSettings validates and updates the plugin's settings.
func (p *Plugin) SetSettings(incoming map[string]any) (map[string]any, map[string]string) {
	var schema *SettingsSchema
	if p.manifest.Ether != nil {
		schema = p.manifest.Ether.Settings
	}
	decoded, errs := DecodeSettings(schema, incoming, p.defaultSettings)
	if len(errs) == 0 {
		p.mu.Lock()
		p.settings = decoded
		p.mu.Unlock()
	}
	return decoded, errs
}

// RankKey invokes the plugin's RankKey hot-path function.
func (p *Plugin) RankKey(candidate CandidateFacts, config map[string]any) int64 {
	if p.routes.RankKey == nil {
		return 0
	}
	if config == nil {
		config = p.GetSettings()
	}
	return p.routes.RankKey(candidate, config)
}

// CondMatch invokes the plugin's CondMatch hot-path function.
func (p *Plugin) CondMatch(candidate CandidateFacts, operator string, value any) bool {
	if p.routes.CondMatch == nil {
		return false
	}
	return p.routes.CondMatch(candidate, operator, value)
}

func headerValue(headers map[string]string, name string) string {
	for k, v := range headers {
		if strings.EqualFold(k, name) {
			return v
		}
	}
	return ""
}

func parsePathAndQuery(rawPath string, rawQuery map[string]string) (string, map[string]string) {
	pathOnly := rawPath
	if pathOnly == "" {
		pathOnly = "/"
	}
	query := map[string]string{}
	for k, v := range rawQuery {
		query[k] = v
	}
	if idx := strings.IndexByte(pathOnly, '?'); idx >= 0 {
		qs := pathOnly[idx+1:]
		pathOnly = pathOnly[:idx]
		if pathOnly == "" {
			pathOnly = "/"
		}
		if vals, err := url.ParseQuery(qs); err == nil {
			for k, list := range vals {
				if _, exists := query[k]; !exists && len(list) > 0 {
					query[k] = list[0]
				}
			}
		}
	}
	if !strings.HasPrefix(pathOnly, "/") {
		pathOnly = "/" + pathOnly
	}
	return pathOnly, query
}

func (p *Plugin) buildContext(ctx context.Context, req RawRequest) *Context {
	_, query := parsePathAndQuery(req.Path, req.Query)
	locale := req.Locale
	if locale == "" {
		locale = query["locale"]
	}
	if locale == "" {
		locale = headerValue(req.Headers, "X-Ether-Locale")
	}
	if locale == "" {
		locale = headerValue(req.Headers, "Accept-Language")
	}
	if locale == "" {
		locale = p.defaultLocale
	}
	if idx := strings.IndexByte(locale, ','); idx >= 0 {
		locale = locale[:idx]
	}
	locale = strings.TrimSpace(locale)
	if locale == "" {
		locale = "en"
	}

	hostClient := p.host
	if hostClient == nil {
		hostClient = defaultHostForRuntime(p.remoteOpts)
	}

	hdrs := map[string]string{}
	for k, v := range req.Headers {
		hdrs[k] = v
	}

	return &Context{
		Context:   ctx,
		Manifest:  p.manifest,
		Settings:  p.GetSettings(),
		Locale:    locale,
		PickToken: headerValue(req.Headers, "X-Ether-Pick"),
		RequestID: headerValue(req.Headers, "X-Ether-Request-ID"),
		Headers:   hdrs,
		Query:     query,
		Ether:     hostClient,
		I18n:      p.i18n,
	}
}

func okJSON(v any, status int) RawResponse {
	if status == 0 {
		status = http.StatusOK
	}
	b, err := json.Marshal(v)
	if err != nil {
		return errorJSON(http.StatusInternalServerError, "marshal_error", err.Error())
	}
	return RawResponse{
		Status:  status,
		Headers: map[string]string{"Content-Type": "application/json"},
		Body:    b,
	}
}

func errorJSON(status int, code, message string) RawResponse {
	b, _ := json.Marshal(map[string]any{
		"error": map[string]string{
			"code":    code,
			"message": message,
		},
	})
	return RawResponse{
		Status:  status,
		Headers: map[string]string{"Content-Type": "application/json"},
		Body:    b,
	}
}

func toRouteErrorResponse(err error) RawResponse {
	var re *RouteError
	if errors.As(err, &re) {
		return errorJSON(re.Status, re.Code, re.Message)
	}
	return errorJSON(http.StatusInternalServerError, "internal_error", err.Error())
}

type parsedStremioRoute struct {
	resource string
	typ      string
	id       string
	extra    map[string]string
}

func matchStremioRoute(path string, query map[string]string) *parsedStremioRoute {
	if !strings.HasSuffix(path, ".json") {
		return nil
	}
	trimmed := strings.TrimPrefix(strings.TrimSuffix(path, ".json"), "/")
	parts := strings.Split(trimmed, "/")
	if len(parts) < 3 || len(parts) > 4 {
		return nil
	}
	res := parts[0]
	switch res {
	case "catalog", "meta", "stream", "subtitles":
	default:
		return nil
	}
	typ, _ := url.PathUnescape(parts[1])
	id, _ := url.PathUnescape(parts[2])
	extra := map[string]string{}
	if len(parts) == 4 && parts[3] != "" {
		if vals, err := url.ParseQuery(parts[3]); err == nil {
			for k, list := range vals {
				if len(list) > 0 {
					extra[k] = list[0]
				}
			}
		}
	}
	for k, v := range query {
		if _, exists := extra[k]; !exists {
			extra[k] = v
		}
	}
	return &parsedStremioRoute{
		resource: res,
		typ:      typ,
		id:       id,
		extra:    extra,
	}
}

func decodeJSONMap(raw json.RawMessage) (map[string]any, error) {
	if len(raw) == 0 {
		return map[string]any{}, nil
	}
	var asStr string
	if json.Unmarshal(raw, &asStr) == nil {
		if strings.TrimSpace(asStr) == "" {
			return map[string]any{}, nil
		}
		raw = json.RawMessage(asStr)
	}
	out := map[string]any{}
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// Dispatch routes a RawRequest through the plugin and returns a RawResponse.
func (p *Plugin) Dispatch(ctx context.Context, req RawRequest) RawResponse {
	pctx := p.buildContext(ctx, req)
	if getter, ok := pctx.Ether.(interface {
		SettingsGet(context.Context) (map[string]any, error)
	}); ok && req.Path != "/ether/configure" {
		remote, isRemote := pctx.Ether.(*RemoteHostClient)
		if !isRemote || remote.credential != "" {
			settings, err := getter.SettingsGet(ctx)
			if err != nil {
				p.settingsFailure.Do(func() { log.Print("plugin settings lookup failed") })
				pctx.Settings = map[string]any{}
			} else {
				var schema *SettingsSchema
				if p.manifest.Ether != nil {
					schema = p.manifest.Ether.Settings
				}
				for _, field := range CollectSettingFields(schema) {
					if field.Kind == "secret" {
						if v, ok := pctx.Settings[field.Key]; ok {
							settings[field.Key] = v
						}
					}
				}
				pctx.Settings, _ = DecodeSettings(schema, settings, p.defaultSettings)
			}
		}
	}
	method := strings.ToUpper(req.Method)
	if method == "" {
		method = http.MethodGet
	}
	path, query := parsePathAndQuery(req.Path, req.Query)

	if method == http.MethodGet && path == "/manifest.json" {
		return okJSON(p.manifest, http.StatusOK)
	}

	if method == http.MethodGet && path == "/ether/health" {
		if p.routes.Health != nil {
			res, err := p.routes.Health(pctx)
			if err != nil {
				return toRouteErrorResponse(err)
			}
			return okJSON(res, http.StatusOK)
		}
		return okJSON(HealthResponse{Status: "ok"}, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/subtitles/download" {
		if strings.TrimSpace(pctx.PickToken) == "" {
			return errorJSON(http.StatusForbidden, "pick_required", "Subtitle downloads require an X-Ether-Pick token.")
		}
		if p.routes.SubtitleDownload == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Subtitle download handler is not registered.")
		}
		var input SubtitleDownloadRequest
		if err := json.Unmarshal(req.Body, &input); err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Request body must be valid JSON.")
		}
		res, err := p.routes.SubtitleDownload(pctx, input)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}
	if method == http.MethodPost && path == "/ether/configure" {
		bodyMap, err := decodeJSONMap(req.Body)
		if err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Request body must be valid JSON.")
		}
		incoming := bodyMap
		if nested, ok := bodyMap["settings"].(map[string]any); ok {
			incoming = nested
		}
		var schema *SettingsSchema
		if p.manifest.Ether != nil {
			schema = p.manifest.Ether.Settings
		}
		decoded, errs := DecodeSettings(schema, incoming, p.defaultSettings)
		if len(errs) > 0 {
			return okJSON(ConfigureResponse{Errors: errs}, http.StatusOK)
		}
		if p.routes.Configure != nil {
			pctx.Settings = decoded
			res, err := p.routes.Configure(pctx, decoded)
			if err != nil {
				return toRouteErrorResponse(err)
			}
			if len(res.Errors) == 0 {
				p.mu.Lock()
				p.settings = decoded
				p.mu.Unlock()
			}
			if res.Errors == nil {
				res.Errors = map[string]string{}
			}
			return okJSON(res, http.StatusOK)
		}
		p.mu.Lock()
		p.settings = decoded
		p.mu.Unlock()
		return okJSON(ConfigureResponse{Errors: map[string]string{}}, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/test" {
		if p.routes.Test != nil {
			res, err := p.routes.Test(pctx)
			if err != nil {
				return toRouteErrorResponse(err)
			}
			return okJSON(res, http.StatusOK)
		}
		return okJSON(TestResponse{OK: true}, http.StatusOK)
	}

	if method == http.MethodGet && strings.HasPrefix(path, "/ether/options/") {
		field, _ := url.PathUnescape(strings.TrimPrefix(path, "/ether/options/"))
		if p.routes.Options == nil {
			return okJSON([]FieldOption{}, http.StatusOK)
		}
		res, err := p.routes.Options(pctx, field)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		if res == nil {
			res = []FieldOption{}
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/stream/open" {
		if p.routes.OpenStream == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Stream open handler is not registered.")
		}
		bodyMap, err := decodeJSONMap(req.Body)
		if err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Request body must be valid JSON.")
		}
		streamID, _ := bodyMap["streamId"].(string)
		res, err := p.routes.OpenStream(pctx, OpenStreamRequest{StreamID: streamID})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodGet && strings.HasPrefix(path, "/ether/markers/") && strings.HasSuffix(path, ".json") {
		if p.routes.Markers == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Markers handler is not registered.")
		}
		trimmed := strings.TrimSuffix(strings.TrimPrefix(path, "/ether/markers/"), ".json")
		parts := strings.SplitN(trimmed, "/", 2)
		if len(parts) < 2 {
			return errorJSON(http.StatusBadRequest, "invalid_path", "Markers route requires type and id.")
		}
		typ, _ := url.PathUnescape(parts[0])
		id, _ := url.PathUnescape(parts[1])
		res, err := p.routes.Markers(pctx, MarkersRequest{Type: typ, ID: id})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodGet && path == "/ether/channels.json" {
		if p.routes.Channels == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Channels handler is not registered.")
		}
		res, err := p.routes.Channels(pctx)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodGet && strings.HasPrefix(path, "/ether/guide/") && strings.HasSuffix(path, ".json") {
		if p.routes.Guide == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Guide handler is not registered.")
		}
		channelID, _ := url.PathUnescape(strings.TrimSuffix(strings.TrimPrefix(path, "/ether/guide/"), ".json"))
		res, err := p.routes.Guide(pctx, GuideRequest{
			ChannelID: channelID,
			From:      query["from"],
			To:        query["to"],
		})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/notify" {
		if p.routes.Notify == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Notify handler is not registered.")
		}
		bodyMap, err := decodeJSONMap(req.Body)
		if err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Request body must be valid JSON.")
		}
		title, _ := bodyMap["title"].(string)
		msg, _ := bodyMap["message"].(string)
		if msg == "" {
			msg, _ = bodyMap["text"].(string)
		}
		eventName, _ := bodyMap["event"].(string)
		settingsMap, _ := bodyMap["settings"].(map[string]any)
		res, err := p.routes.Notify(pctx, NotifyRequest{
			Title:    title,
			Message:  msg,
			Event:    eventName,
			Settings: settingsMap,
		})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/event" {
		if p.routes.Event == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Event handler is not registered.")
		}
		var batch struct {
			Events []EtherEvent `json:"events"`
		}
		if len(req.Body) > 0 {
			if err := json.Unmarshal(req.Body, &batch); err != nil {
				return errorJSON(http.StatusBadRequest, "invalid_json", "Event batch body must be valid JSON.")
			}
		}
		res, err := p.routes.Event(pctx, batch.Events)
		if err != nil {
			return toRouteErrorResponse(err)
		}
		if res.Ack == nil {
			res.Ack = make([]string, 0, len(batch.Events))
			for _, ev := range batch.Events {
				res.Ack = append(res.Ack, ev.ID)
			}
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodGet {
		pageKey, matchedPage := p.pageRoutes[path]
		if matchedPage || path == "/ether/view" || strings.HasPrefix(path, "/ether/view/") {
			if p.routes.View == nil {
				return errorJSON(http.StatusNotFound, "not_found", "View handler is not registered.")
			}
			if !matchedPage {
				if path == "/ether/view" {
					pageKey = "home"
				} else {
					pageKey, _ = url.PathUnescape(strings.TrimPrefix(path, "/ether/view/"))
				}
			}
			res, err := p.routes.View(pctx, ViewRequest{Page: pageKey, Query: query})
			if err != nil {
				return toRouteErrorResponse(err)
			}
			return okJSON(res, http.StatusOK)
		}
	}

	if method == http.MethodPost && strings.HasPrefix(path, "/ether/action/") {
		if p.routes.Action == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Action handler is not registered.")
		}
		actionName, _ := url.PathUnescape(strings.TrimPrefix(path, "/ether/action/"))
		inputMap, err := decodeJSONMap(req.Body)
		if err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Action input must be valid JSON.")
		}
		res, err := p.routes.Action(pctx, ActionRequest{Action: actionName, Input: inputMap})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodPost && strings.HasPrefix(path, "/ether/tool/") {
		if p.routes.Tool == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Tool handler is not registered.")
		}
		toolName, _ := url.PathUnescape(strings.TrimPrefix(path, "/ether/tool/"))
		inputMap, err := decodeJSONMap(req.Body)
		if err != nil {
			return errorJSON(http.StatusBadRequest, "invalid_json", "Tool input must be valid JSON.")
		}
		res, err := p.routes.Tool(pctx, ToolRequest{Name: toolName, Input: inputMap})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodPost && strings.HasPrefix(path, "/ether/job/") {
		if p.routes.Job == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Job handler is not registered.")
		}
		jobName, _ := url.PathUnescape(strings.TrimPrefix(path, "/ether/job/"))
		res, err := p.routes.Job(pctx, JobRequest{Name: jobName})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		return okJSON(res, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/rank-key" {
		if p.routes.RankKey == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Rank key handler is not registered.")
		}
		var payload struct {
			Candidate *CandidateFacts `json:"candidate"`
			Config    map[string]any  `json:"config"`
		}
		_ = json.Unmarshal(req.Body, &payload)
		var cand CandidateFacts
		if payload.Candidate != nil {
			cand = *payload.Candidate
		} else {
			_ = json.Unmarshal(req.Body, &cand)
		}
		score := p.RankKey(cand, payload.Config)
		return okJSON(map[string]int64{"score": score}, http.StatusOK)
	}

	if method == http.MethodPost && path == "/ether/cond-match" {
		if p.routes.CondMatch == nil {
			return errorJSON(http.StatusNotFound, "not_found", "Condition match handler is not registered.")
		}
		var payload struct {
			Candidate CandidateFacts `json:"candidate"`
			Operator  string         `json:"operator"`
			Value     any            `json:"value"`
		}
		_ = json.Unmarshal(req.Body, &payload)
		if payload.Operator == "" {
			payload.Operator = "eq"
		}
		matched := p.CondMatch(payload.Candidate, payload.Operator, payload.Value)
		return okJSON(map[string]bool{"match": matched}, http.StatusOK)
	}

	if (method == http.MethodGet || method == http.MethodHead) && strings.HasPrefix(path, "/ether/file/") {
		if p.routes.File == nil {
			return errorJSON(http.StatusNotFound, "not_found", "File handler is not registered.")
		}
		relPath, _ := url.PathUnescape(strings.TrimPrefix(path, "/ether/file/"))
		if relPath == "" || strings.HasPrefix(relPath, "/") || containsDotDot(relPath) {
			return errorJSON(http.StatusBadRequest, "invalid_path", "File path must be a clean relative path.")
		}
		rangeHeader := headerValue(req.Headers, "Range")
		fileRes, err := p.routes.File(pctx, FileRequest{
			Path:     relPath,
			Range:    rangeHeader,
			HeadOnly: method == http.MethodHead,
		})
		if err != nil {
			return toRouteErrorResponse(err)
		}
		contentType := fileRes.ContentType
		if contentType == "" {
			contentType = "application/octet-stream"
		}
		hdrs := map[string]string{
			"Content-Type":  contentType,
			"Accept-Ranges": "bytes",
		}
		for k, v := range fileRes.Headers {
			hdrs[k] = v
		}
		if fileRes.ContentRange != "" {
			hdrs["Content-Range"] = fileRes.ContentRange
		} else if fileRes.TotalSize != nil {
			hdrs["Content-Length"] = strconv.FormatInt(*fileRes.TotalSize, 10)
		}
		status := fileRes.Status
		if status == 0 {
			if fileRes.ContentRange != "" {
				status = http.StatusPartialContent
			} else {
				status = http.StatusOK
			}
		}
		bodyBytes := fileRes.Body
		if method == http.MethodHead {
			bodyBytes = []byte{}
		}
		return RawResponse{
			Status:     status,
			Headers:    hdrs,
			BinaryBody: bodyBytes,
		}
	}

	if method == http.MethodGet {
		if stremio := matchStremioRoute(path, query); stremio != nil {
			switch stremio.resource {
			case "subtitles":
				if p.routes.Subtitles == nil {
					return errorJSON(http.StatusNotFound, "not_found", "Subtitles handler is not registered.")
				}
				var videoSize int64
				if rawSize, ok := stremio.extra["videoSize"]; ok {
					videoSize, _ = strconv.ParseInt(rawSize, 10, 64)
				}
				res, err := p.routes.Subtitles(pctx, SubtitlesRequest{
					Type:      stremio.typ,
					ID:        stremio.id,
					Extra:     stremio.extra,
					PickToken: pctx.PickToken,
					VideoHash: stremio.extra["videoHash"],
					VideoSize: videoSize,
					Filename:  stremio.extra["filename"],
				})
				if err != nil {
					return toRouteErrorResponse(err)
				}
				return okJSON(res, http.StatusOK)

			case "catalog":
				if p.routes.Catalog == nil {
					return errorJSON(http.StatusNotFound, "not_found", "Catalog handler is not registered.")
				}
				skip, _ := strconv.Atoi(stremio.extra["skip"])
				res, err := p.routes.Catalog(pctx, CatalogRequest{
					Type:   stremio.typ,
					ID:     stremio.id,
					Extra:  stremio.extra,
					Skip:   skip,
					Search: stremio.extra["search"],
					Genre:  stremio.extra["genre"],
				})
				if err != nil {
					return toRouteErrorResponse(err)
				}
				return okJSON(res, http.StatusOK)

			case "meta":
				if p.routes.Meta == nil {
					return errorJSON(http.StatusNotFound, "not_found", "Meta handler is not registered.")
				}
				res, err := p.routes.Meta(pctx, MetaRequest{Type: stremio.typ, ID: stremio.id})
				if err != nil {
					return toRouteErrorResponse(err)
				}
				return okJSON(res, http.StatusOK)

			case "stream":
				if p.routes.Stream == nil {
					return errorJSON(http.StatusNotFound, "not_found", "Stream handler is not registered.")
				}
				res, err := p.routes.Stream(pctx, StreamRequest{
					Type:  stremio.typ,
					ID:    stremio.id,
					Extra: stremio.extra,
				})
				if err != nil {
					return toRouteErrorResponse(err)
				}
				return okJSON(res, http.StatusOK)
			}
		}
	}

	if resp, handled := p.dispatchKinds(pctx, method, path, req); handled {
		return resp
	}

	return errorJSON(http.StatusNotFound, "not_found", "No route matched "+method+" "+path+".")
}

func containsDotDot(p string) bool {
	for _, seg := range strings.Split(p, "/") {
		if seg == ".." {
			return true
		}
	}
	return false
}

// ServeHTTP implements net/http.Handler for running a Plugin as an HTTP sidecar.
func (p *Plugin) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	bodyBytes, err := io.ReadAll(io.LimitReader(r.Body, 8<<20))
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusBadRequest)
		_, _ = w.Write([]byte(`{"error":{"code":"read_error","message":"Failed to read request body."}}`))
		return
	}
	hdrs := map[string]string{}
	for k, vals := range r.Header {
		if len(vals) > 0 {
			hdrs[k] = vals[0]
		}
	}
	query := map[string]string{}
	for k, vals := range r.URL.Query() {
		if len(vals) > 0 {
			query[k] = vals[0]
		}
	}
	res := p.Dispatch(r.Context(), RawRequest{
		Method:  r.Method,
		Path:    r.URL.EscapedPath(),
		Query:   query,
		Headers: hdrs,
		Body:    bodyBytes,
	})
	for k, v := range res.Headers {
		w.Header().Set(k, v)
	}
	payload := res.Body
	if res.BinaryBody != nil {
		payload = res.BinaryBody
	}
	w.Header().Set("Content-Length", strconv.Itoa(len(payload)))
	w.WriteHeader(res.Status)
	if r.Method != http.MethodHead && len(payload) > 0 {
		_, _ = w.Write(payload)
	}
}

// ServeOptions configures how Plugin.Serve runs in sidecar mode.
type ServeOptions struct {
	Mode       string
	Host       string
	Port       int
	TunnelURL  string
	Credential string
	// URL is the server's http(s) base (ETHER_URL). When set, the tunnel URL
	// and pair URL are derived from it and the SDK pairs with a code.
	URL string
	// StateDir overrides where the pairing credential is saved
	// (ETHER_PLUGIN_STATE_DIR).
	StateDir string
}

// ServeHandle represents a running HTTP or tunnel sidecar session.
type ServeHandle struct {
	// Done closes when the tunnel supervisor stops (ctx cancellation or Close).
	// Transient disconnects reconnect automatically. It is nil for HTTP servers.
	Done  <-chan struct{}
	Mode  string
	URL   string
	Port  int
	Close func() error
}

// Start launches the plugin sidecar in the background (either HTTP or WebSocket tunnel)
// and returns a ServeHandle that stops it when Close is called or ctx is cancelled.
func (p *Plugin) Start(ctx context.Context, opts ServeOptions) (*ServeHandle, error) {
	tunnelURL := opts.TunnelURL
	if tunnelURL == "" {
		tunnelURL = os.Getenv("ETHER_TUNNEL_URL")
	}
	inputs := pairingInputsFromEnv(opts)
	if tunnelURL == "" && inputs.URL != "" {
		derived, err := TunnelURL(inputs.URL)
		if err != nil {
			return nil, err
		}
		tunnelURL = derived
	}
	mode := opts.Mode
	if mode == "" {
		if tunnelURL != "" {
			mode = "tunnel"
		} else {
			mode = "http"
		}
	}
	if mode == "tunnel" {
		if tunnelURL == "" {
			return nil, fmt.Errorf("tunnel mode requires TunnelURL, ETHER_TUNNEL_URL or ETHER_URL")
		}
		credential, fromFile, err := resolveCredential(ctx, inputs, p.manifest.ID)
		if err != nil {
			return nil, err
		}
		return p.startTunnel(ctx, tunnelURL, credential, fromFile, inputs.StateDir)
	}

	host := opts.Host
	if host == "" {
		host = os.Getenv("ETHER_PLUGIN_HOST")
	}
	if host == "" {
		host = "127.0.0.1"
	}
	port := opts.Port
	if port == 0 && os.Getenv("ETHER_PLUGIN_PORT") != "" {
		port, _ = strconv.Atoi(os.Getenv("ETHER_PLUGIN_PORT"))
	}

	ln, err := net.Listen("tcp", net.JoinHostPort(host, strconv.Itoa(port)))
	if err != nil {
		return nil, err
	}
	actualPort := ln.Addr().(*net.TCPAddr).Port
	srv := &http.Server{Handler: p}

	go func() {
		_ = srv.Serve(ln)
	}()
	go func() {
		<-ctx.Done()
		_ = srv.Close()
	}()

	return &ServeHandle{
		Mode: "http",
		URL:  "http://" + net.JoinHostPort(host, strconv.Itoa(actualPort)),
		Port: actualPort,
		Close: func() error {
			return srv.Close()
		},
	}, nil
}

// Serve runs the plugin sidecar until ctx is cancelled.
func (p *Plugin) Serve(ctx context.Context, opts ServeOptions) error {
	h, err := p.Start(ctx, opts)
	if err != nil {
		return err
	}
	if h.Done != nil {
		select {
		case <-ctx.Done():
			return h.Close()
		case <-h.Done:
			_ = h.Close()
			if ctx.Err() != nil {
				return nil
			}
			return errors.New("tunnel disconnected")
		}
	}
	<-ctx.Done()
	return h.Close()
}

func defaultHostForRuntime(opts RemoteHostOptions) Host {
	return NewRemoteHostClient(opts)
}

// FieldProblem describes one schema validation or copy-rule problem.
type FieldProblem struct {
	Field   string `json:"field"`
	Message string `json:"message"`
}

// CollectSettingFields returns all leaf SettingFields from a SettingsSchema.
func CollectSettingFields(schema *SettingsSchema) []SettingField {
	if schema == nil {
		return nil
	}
	var out []SettingField
	var walk func(fields []SettingField)
	walk = func(fields []SettingField) {
		for _, f := range fields {
			if f.Key != "" && f.Kind != "" && f.Kind != "group" {
				out = append(out, f)
			}
			if len(f.Fields) > 0 {
				walk(f.Fields)
			}
		}
	}
	walk(schema.Fields)
	for _, g := range schema.Groups {
		walk(g.Fields)
	}
	return out
}

// LintSettingsSchema checks a SettingsSchema for forbidden kinds and copy-rule violations.
func LintSettingsSchema(schema *SettingsSchema) []FieldProblem {
	if schema == nil {
		return nil
	}
	var problems []FieldProblem
	var walk func(fields []SettingField, prefix string)
	walk = func(fields []SettingField, prefix string) {
		for idx, f := range fields {
			path := fmt.Sprintf("%s[%d]", prefix, idx)
			if f.Kind == "json" {
				problems = append(problems, FieldProblem{
					Field:   path + ".kind",
					Message: "the json field kind is not allowed in plugin settings",
				})
			} else if f.Kind != "" && !allowedSettingKinds[f.Kind] {
				problems = append(problems, FieldProblem{
					Field:   path + ".kind",
					Message: fmt.Sprintf("unknown field kind %q", f.Kind),
				})
			}
			if f.Label != "" && !strings.HasPrefix(f.Label, "$t:") {
				if msg := LintCopy(f.Label, 40); msg != "" {
					problems = append(problems, FieldProblem{Field: path + ".label", Message: msg})
				}
			}
			if f.Hint != "" && !strings.HasPrefix(f.Hint, "$t:") {
				if msg := LintCopy(f.Hint, 120); msg != "" {
					problems = append(problems, FieldProblem{Field: path + ".hint", Message: msg})
				}
				trimmed := strings.TrimRight(f.Hint, ".")
				if strings.Contains(trimmed, ".") {
					problems = append(problems, FieldProblem{Field: path + ".hint", Message: "must be one sentence"})
				}
			}
			if len(f.Fields) > 0 {
				walk(f.Fields, path+".fields")
			}
		}
	}
	if len(schema.Fields) > 0 {
		walk(schema.Fields, "ether.settings.fields")
	}
	for idx, g := range schema.Groups {
		gPath := fmt.Sprintf("ether.settings.groups[%d]", idx)
		if g.Label != "" && !strings.HasPrefix(g.Label, "$t:") {
			if msg := LintCopy(g.Label, 40); msg != "" {
				problems = append(problems, FieldProblem{Field: gPath + ".label", Message: msg})
			}
		}
		if g.Hint != "" && !strings.HasPrefix(g.Hint, "$t:") {
			if msg := LintCopy(g.Hint, 120); msg != "" {
				problems = append(problems, FieldProblem{Field: gPath + ".hint", Message: msg})
			}
		}
		walk(g.Fields, gPath+".fields")
	}
	return problems
}

// DecodeSettings applies schema defaults and validates incoming settings,
// returning the decoded settings map and any JSON-pointer keyed errors.
func DecodeSettings(
	schema *SettingsSchema,
	incoming map[string]any,
	defaults map[string]any,
) (map[string]any, map[string]string) {
	fields := CollectSettingFields(schema)
	result := map[string]any{}
	for k, v := range defaults {
		result[k] = v
	}
	for _, f := range fields {
		if f.Default != nil {
			if _, exists := result[f.Key]; !exists {
				result[f.Key] = f.Default
			}
		}
	}
	for k, v := range incoming {
		result[k] = v
	}

	errors := map[string]string{}
	for _, f := range fields {
		val, exists := result[f.Key]
		ptr := "/" + f.Key
		if f.Required && (!exists || val == nil || val == "") {
			errors[ptr] = "is required"
			continue
		}
		if !exists || val == nil || val == "" {
			continue
		}
		switch f.Kind {
		case "number", "bytes", "viewer":
			num, ok := toFloat64(val)
			if !ok || math.IsNaN(num) || math.IsInf(num, 0) {
				errors[ptr] = "must be a number"
				continue
			}
			if f.Min != nil && num < *f.Min {
				errors[ptr] = fmt.Sprintf("must be at least %v", *f.Min)
			}
			if f.Max != nil && num > *f.Max {
				errors[ptr] = fmt.Sprintf("must be at most %v", *f.Max)
			}
			result[f.Key] = num
		case "bool":
			if _, ok := val.(bool); !ok {
				errors[ptr] = "must be true or false"
			}
		case "list", "multiSelect", "orderedList":
			switch val.(type) {
			case []any, []string:
			default:
				errors[ptr] = "must be a list"
			}
		case "url":
			s, ok := val.(string)
			if !ok || (!strings.HasPrefix(s, "http://") && !strings.HasPrefix(s, "https://")) {
				errors[ptr] = "must be an http or https URL"
			}
		}
	}
	return result, errors
}

// TemplateOptions configures a capability starter template.
type TemplateOptions struct {
	ID          string
	Name        string
	Version     string
	Summary     string
	Description string
}

func baseManifest(opts TemplateOptions, kind PluginKind, caps []Capability) Manifest {
	version := opts.Version
	if version == "" {
		version = "0.1.0"
	}
	summary := opts.Summary
	if summary == "" {
		summary = opts.Name + " plugin for Ether."
	}
	desc := opts.Description
	if desc == "" {
		desc = summary
	}
	return Manifest{
		ID:          opts.ID,
		Name:        opts.Name,
		Version:     version,
		Description: desc,
		Types:       []string{"movie", "series"},
		IDPrefixes:  []string{"tt"},
		Ether: &EtherManifestBlock{
			Protocol:     1,
			Kind:         kind,
			Capabilities: caps,
			Summary:      summary,
			Runtime:      RuntimeDecl{Kind: "remote"},
			Permissions:  &Permissions{Catalog: "none"},
		},
	}
}

