	man.Ether.Settings = &SettingsSchema{
		Fields: []SettingField{{
			Key:     "boost4k",
			Kind:    "bool",
			Label:   "Boost 2160p releases",
			Default: true,
		}},
	}
	man.Ether.Contributes = &Contributes{
		RankingSteps: []RankingStepMeta{{
