            "subscribe": [
                "playback.started",
                "playback.paused",
                "playback.stopped",
                "playback.completed",
            ]
        },
    }

    def _event(events: List[Dict[str, Any]], ctx: PluginContext) -> Dict[str, Any]:
        ack: List[str] = []
        for ev in events:
            viewer_id = ev.get("viewerId") or 0
            ctx.ether.kv.put(f"last_event:{viewer_id}", json.dumps(ev))
