/**
 * Content-kind handlers (Ether v0.3.8): catalogue providers, resolvers,
 * matchers, frontend adapters and setup tests, plus the dispatch the
 * router calls for /ether/v1/kinds, /ether/v1/setup and
 * /ether/v1/frontend. Wire shapes live in types.ts and are pinned by
 * sdk/conformance/kinds/fixture.json across all three SDKs.
 */
import type { PluginContext } from "./router.ts";
import type {
  KindBrowseRequest,
  KindChangePage,
  KindItem,
  KindMatchRequest,
  KindMatchScore,
  KindPage,
  KindResolveRequest,
  KindResolveResponse,
  MaybePromise,
  RawRequest,
  RawResponse,
  SetupTestRequest,
  SetupTestResult,
  SourceCandidate,
} from "./types.ts";

export interface CatalogProvider<S = Record<string, unknown>> {
  browse(req: KindBrowseRequest, ctx: PluginContext<S>): MaybePromise<KindPage>;
  detail(kind: string, id: string, ctx: PluginContext<S>): MaybePromise<KindItem>;
  /** Optional delta feed for pull sync; without it Ether re-walks. */
  changes?(req: { kind: string; cursor?: string; limit?: number }, ctx: PluginContext<S>): MaybePromise<KindChangePage>;
  /** Optional provider search; required when the kind declares browse.liveSearch. */
  search?(req: KindBrowseRequest, ctx: PluginContext<S>): MaybePromise<KindPage>;
}

export interface KindResolver<S = Record<string, unknown>> {
  resolve(req: KindResolveRequest, ctx: PluginContext<S>): MaybePromise<KindResolveResponse>;
}

export interface KindMatcher<S = Record<string, unknown>> {
  match(req: KindMatchRequest, ctx: PluginContext<S>): MaybePromise<{ matches: KindMatchScore[] }>;
}

/** Spec-name alias. */
export type Matcher<S = Record<string, unknown>> = KindMatcher<S>;

export interface FrontendAdapter {
  handle(
    method: string,
    path: string,
    headers: Record<string, string>,
    body: string,
  ): MaybePromise<{ status: number; headers?: Record<string, string>; body: string }>;
}

export interface SetupTester<S = Record<string, unknown>> {
  testSetup(req: SetupTestRequest, ctx: PluginContext<S>): MaybePromise<SetupTestResult>;
}

/** The stable ref matchers report for a source candidate. */
export function candidateRef(c: SourceCandidate): string {
  if (c.infoHash) return `infohash:${c.infoHash.toLowerCase()}`;
  if (c.magnet) return `magnet:${c.magnet}`;
  if (c.nzbUrl) return `nzb:${c.nzbUrl}`;
  return c.title ?? "";
}

/**
 * Mint a scoped, short-lived Ether stream URL for one of this plugin's own
 * kind items (spec §6.5). The viewer is the one Ether authenticated on this
 * request (X-Ether-Viewer); bytes are served by Ether, never by the plugin.
 */
export async function streamUrl<S = Record<string, unknown>>(
  ctx: PluginContext<S>,
  itemRef: string,
): Promise<string> {
  if (!ctx.ether?.frontend) throw new Error("stream url: no host service available");
  const raw = ctx.headers["X-Ether-Viewer"] ?? ctx.headers["x-ether-viewer"];
  const value = Array.isArray(raw) ? raw[0] : raw;
  const viewerId = Number.parseInt(String(value ?? ""), 10);
  if (!Number.isFinite(viewerId) || viewerId <= 0) {
    throw new Error("stream url: no authenticated viewer on this request");
  }
  return ctx.ether.frontend.streamUrl(viewerId, itemRef);
}

export interface KindHandlers<S = Record<string, unknown>> {
  catalog: Map<string, CatalogProvider<S>>;
  resolve: Map<string, KindResolver<S>>;
  match: Map<string, KindMatcher<S>>;
  frontend: Map<string, FrontendAdapter>;
  setup?: SetupTester<S>;
}

export function createKindHandlers<S = Record<string, unknown>>(): KindHandlers<S> {
  return { catalog: new Map(), resolve: new Map(), match: new Map(), frontend: new Map() };
}

function ok(body: unknown): RawResponse {
  return { status: 200, headers: { "Content-Type": "application/json" }, body };
}

function err(status: number, code: string, message: string): RawResponse {
  return { status, headers: { "Content-Type": "application/json" }, body: { error: { code, message } } };
}

function parseBody(body: unknown): Record<string, unknown> {
  if (typeof body === "string" && body.trim()) {
    const parsed = JSON.parse(body) as unknown;
    return parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : {};
  }
  if (body && typeof body === "object") return body as Record<string, unknown>;
  return {};
}

/**
 * The original query for a frontend-adapter request, from the flat `query`
 * map and the query string still attached to `path`. Repeated keys arrive
 * flattened to the first value by the server.
 */
function frontendQuery(req: RawRequest): URLSearchParams {
  const query = new URLSearchParams();
  if (req.query) {
    for (const [k, v] of Object.entries(req.query)) {
      if (Array.isArray(v)) {
        if (v.length > 0) query.set(k, String(v[0]));
      } else if (v !== undefined && v !== null) {
        query.set(k, String(v));
      }
    }
  }
  const qIndex = (req.path || "").indexOf("?");
  if (qIndex >= 0) {
    for (const [k, v] of new URLSearchParams((req.path || "").slice(qIndex + 1))) {
      if (!query.has(k)) query.set(k, v);
    }
  }
  return query;
}

/** Dispatch one /ether/v1/* request; returns null when the path is not a kind route. */
export async function dispatchKinds<S = Record<string, unknown>>(
  handlers: KindHandlers<S>,
  req: RawRequest,
  ctx: PluginContext<S>,
): Promise<RawResponse | null> {
  const method = (req.method || "GET").toUpperCase();
  const path = (req.path || "/").split("?")[0] ?? "/";
  if (!path.startsWith("/ether/v1/")) return null;
  const parts = path.slice("/ether/v1/".length).split("/").map((p) => decodeURIComponent(p));

  // Frontend adapters are protocol surfaces (WebDAV, Subsonic, OPDS, …) and
  // see every method token. The kind and setup routes stay JSON GET/POST.
  if (parts.length >= 2 && parts[0] === "frontend") {
    const adapter = handlers.frontend.get(parts[1] ?? "");
    if (!adapter) return err(404, "not_found", `No frontend adapter is registered for "${parts[1]}".`);
    const headers: Record<string, string> = {};
    for (const [k, v] of Object.entries(req.headers ?? {})) headers[k] = Array.isArray(v) ? (v[0] ?? "") : v;
    // Rebuild the adapter URL with the original query. The server flattens
    // repeated keys to the first value, so the query holds one value per key.
    let subPath = `/${parts.slice(2).join("/")}`;
    const query = frontendQuery(req);
    const qs = query.toString();
    if (qs) subPath += `?${qs}`;
    const res = await adapter.handle(method, subPath, headers, typeof req.body === "string" ? req.body : "");
    if (res.body.length > 10 * 1024 * 1024) return err(502, "adapter_error", "Frontend adapter response is larger than 10 MiB; serve media through Ether stream URLs.");
    // A HEAD reply carries headers only, exactly as a real server would.
    return { status: res.status, headers: res.headers ?? {}, body: method === "HEAD" ? "" : res.body };
  }

  if (method !== "GET" && method !== "POST") {
    return err(405, "method_not_allowed", "Kind routes use GET or POST.");
  }

  let body: Record<string, unknown>;
  try {
    body = parseBody(req.body);
  } catch {
    return err(400, "invalid_json", "Request body must be valid JSON.");
  }

  if (parts.length === 3 && parts[0] === "setup" && parts[2] === "test") {
    if (!handlers.setup) return err(404, "not_found", "Setup test handler is not registered.");
    const input = { step: String(body.step || parts[1]), fields: body.fields as Record<string, unknown> | undefined };
    return ok(await handlers.setup.testSetup(input, ctx));
  }

  if (parts.length < 3 || parts[0] !== "kinds") return null;
  const kind = parts[1] ?? "";
  const tail = parts.slice(2);
  const browseReq = { ...body, kind } as unknown as KindBrowseRequest;
  const page = async (p: MaybePromise<KindPage>): Promise<RawResponse> => {
    const result = { ...(await p) };
    const limit = Number(browseReq.limit || 200);
    result.items = (result.items ?? []).slice(0, limit);
    if (!result.nextCursor) delete result.nextCursor;
    return ok(result);
  };

  if (tail.length === 1 && (tail[0] === "browse" || tail[0] === "search")) {
    const provider = handlers.catalog.get(kind);
    if (!provider) return err(404, "not_found", `No catalogue provider is registered for kind "${kind}".`);
    if (tail[0] === "search") {
      if (!provider.search) return err(501, "not_implemented", "This provider does not search.");
      return page(provider.search(browseReq, ctx));
    }
    return page(provider.browse(browseReq, ctx));
  }
  if (tail.length === 2 && tail[0] === "items") {
    const provider = handlers.catalog.get(kind);
    if (!provider) return err(404, "not_found", `No catalogue provider is registered for kind "${kind}".`);
    return ok(await provider.detail(kind, tail[1] ?? "", ctx));
  }
  if (tail.length === 1 && tail[0] === "changes") {
    const provider = handlers.catalog.get(kind);
    if (!provider?.changes) return err(501, "not_implemented", "This provider has no changes feed.");
    const result = { ...(await provider.changes({ kind, cursor: body.cursor as string | undefined, limit: body.limit as number | undefined }, ctx)) };
    result.upserts = result.upserts ?? [];
    return ok(result);
  }
  if (tail.length === 1 && tail[0] === "resolve") {
    const resolver = handlers.resolve.get(kind);
    if (!resolver) return err(404, "not_found", `No resolver is registered for kind "${kind}".`);
    const result = { ...(await resolver.resolve({ ...body, kind } as unknown as KindResolveRequest, ctx)) };
    result.sources = result.sources ?? [];
    return ok(result);
  }
  if (tail.length === 1 && tail[0] === "match") {
    const matcher = handlers.match.get(kind);
    if (!matcher) return err(404, "not_found", `No matcher is registered for kind "${kind}".`);
    const result = { ...(await matcher.match({ ...body, kind } as unknown as KindMatchRequest, ctx)) };
    result.matches = result.matches ?? [];
    return ok(result);
  }
  return err(404, "not_found", "No kind route matched.");
}

/**
 * Kit helpers for content-kind plugins (stdlib/runtime only, matching
 * sdk/go/kit): feed parsing, zip member listing, and simple HTML text
 * and link extraction for listing pages.
 */

export interface FeedEntry {
  id: string;
  title: string;
  summary: string;
  link: string;
  audio: string;
  date: string;
}

export interface ParsedFeed {
  title: string;
  summary: string;
  link: string;
  entries: FeedEntry[];
}

function tagText(block: string, name: string): string {
  const m = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, "i").exec(block);
  return m ? m[1]!.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/, "$1").trim() : "";
}

function blocks(xml: string, name: string): string[] {
  return [...xml.matchAll(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, "gi"))].map((m) => m[1]!);
}

/** Parse RSS, Atom or JSON Feed into a normalised feed. */
export function parseFeed(data: string): ParsedFeed {
  if (data.trimStart().startsWith("{")) {
    const doc = JSON.parse(data) as Record<string, any>;
    return {
      title: doc.title ?? "",
      summary: doc.description ?? "",
      link: doc.home_page_url ?? "",
      entries: (doc.items ?? []).map((it: Record<string, any>) => ({
        id: it.id || it.url || "",
        title: it.title ?? "",
        summary: it.summary ?? "",
        link: it.url ?? "",
        audio: it.attachments?.[0]?.url ?? "",
        date: it.date_published ?? "",
      })),
    };
  }
  if (/<feed[\s>]/.test(data)) {
    return {
      title: tagText(data, "title"),
      summary: tagText(data, "subtitle"),
      link: "",
      entries: blocks(data, "entry").map((e) => {
        let page = "";
        let media = "";
        for (const m of e.matchAll(/<link[^>]*href="([^"]+)"[^>]*>/gi)) {
          if (/rel="enclosure"/.test(m[0])) media = m[1]!;
          else if (!page) page = m[1]!;
        }
        return { id: tagText(e, "id") || page, title: tagText(e, "title"), summary: tagText(e, "summary"), link: page, audio: media, date: tagText(e, "updated") };
      }),
    };
  }
  const channel = blocks(data, "channel")[0] ?? data;
  return {
    title: tagText(channel.split("<item")[0]!, "title"),
    summary: tagText(channel.split("<item")[0]!, "description"),
    link: tagText(channel.split("<item")[0]!, "link"),
    entries: blocks(data, "item").map((e) => ({
      id: tagText(e, "guid") || tagText(e, "link"),
      title: tagText(e, "title"),
      summary: tagText(e, "description"),
      link: tagText(e, "link"),
      audio: /<enclosure[^>]*url="([^"]+)"/.exec(e)?.[1] ?? "",
      date: tagText(e, "pubDate"),
    })),
  };
}

/** One non-directory zip member, in archive order. */
export interface ArchiveMember {
  index: number;
  name: string;
  size: number;
}

/** List zip/cbz/epub members by reading the central directory. */
export function archiveList(data: Uint8Array): ArchiveMember[] {
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  let eocd = -1;
  for (let i = data.length - 22; i >= 0; i--) {
    if (view.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error("archiveList: not a zip archive");
  const count = view.getUint16(eocd + 10, true);
  let off = view.getUint32(eocd + 16, true);
  const decoder = new TextDecoder();
  const out: ArchiveMember[] = [];
  for (let n = 0; n < count && off + 46 <= data.length; n++) {
    if (view.getUint32(off, true) !== 0x02014b50) break;
    const size = view.getUint32(off + 24, true);
    const nameLen = view.getUint16(off + 28, true);
    const extraLen = view.getUint16(off + 30, true);
    const commentLen = view.getUint16(off + 32, true);
    const name = decoder.decode(data.subarray(off + 46, off + 46 + nameLen));
    if (!name.endsWith("/")) out.push({ index: out.length, name, size });
    off += 46 + nameLen + extraLen + commentLen;
  }
  return out;
}

/** Strip markup down to readable text. */
export function scrapeText(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<[^>]+>/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Extract anchors with absolute URLs resolved against base. */
export function scrapeLinks(html: string, base: string): Array<{ url: string; text: string }> {
  const out: Array<{ url: string; text: string }> = [];
  for (const m of html.matchAll(/<a\s[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const href = m[1]!.trim();
    if (!href || href.startsWith("#") || href.startsWith("javascript:")) continue;
    out.push({ url: new URL(href, base).toString(), text: scrapeText(m[2]!) });
  }
  return out;
}

/**
 * Sidecar pairing built into the SDK. Every plugin used to hand-write the
 * code exchange and keep the credential in memory; this resolves a credential
 * once, saves it under the state directory, and reuses it across restarts.
 */
export const PAIR_EXCHANGE_PATH = "/ether/plugins/pair";
export const TUNNEL_PATH = "/ether/plugins/tunnel";

const CREDENTIAL_FILE_MODE = 0o600;
const STATE_DIR_MODE = 0o700;

export class CredentialError extends Error {}

export function noCredentialMessage(): string {
  return (
    "No credential: create a pairing code in Ether (Plugins > this plugin > " +
    "Connect a sidecar) and set ETHER_PAIRING_CODE."
  );
}

export interface PairingInputs {
  url?: string;
  code?: string;
  credential?: string;
  stateDir?: string;
}

function env(name: string): string | undefined {
  const g = globalThis as { process?: { env?: Record<string, string | undefined> } };
  return g.process?.env?.[name];
}

async function nodeFs(): Promise<typeof import("node:fs")> {
  // A computed specifier keeps a hosted bundle from resolving the Node module.
  const spec = "node:" + "fs";
  return (await import(/* @vite-ignore */ spec)) as typeof import("node:fs");
}

async function nodeOs(): Promise<typeof import("node:os")> {
  const spec = "node:" + "os";
  return (await import(/* @vite-ignore */ spec)) as typeof import("node:os");
}

export function serverBase(base: string | undefined): string {
  const trimmed = (base ?? "").trim();
  if (!trimmed) {
    throw new CredentialError("ETHER_URL is not set");
  }
  let parsed: URL;
  try {
    parsed = new URL(trimmed);
  } catch {
    throw new CredentialError("ETHER_URL is not a valid URL");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new CredentialError("ETHER_URL must use http or https");
  }
  if (!parsed.host) {
    throw new CredentialError("ETHER_URL has no host");
  }
  return `${parsed.protocol}//${parsed.host}`;
}

export function tunnelUrlFromBase(base: string | undefined): string {
  const parsed = new URL(serverBase(base));
  const scheme = parsed.protocol === "https:" ? "wss:" : "ws:";
  return `${scheme}//${parsed.host}${TUNNEL_PATH}`;
}

export function pairUrlFromBase(base: string | undefined): string {
  return serverBase(base) + PAIR_EXCHANGE_PATH;
}

export async function resolveStateDir(explicit: string, pluginId: string): Promise<string> {
  if (explicit.trim()) {
    return explicit.trim();
  }
  const fs = await nodeFs();
  try {
    const info = fs.statSync("/data");
    if (info.isDirectory()) {
      fs.accessSync("/data", fs.constants.W_OK);
      return "/data";
    }
  } catch {
    // Fall through to the user config directory.
  }
  const os = await nodeOs();
  const configHome = env("XDG_CONFIG_HOME") ?? `${os.homedir()}/.config`;
  return `${configHome}/ether-plugins/${pluginId || "plugin"}`;
}

function credentialPath(stateDir: string): string {
  return `${stateDir}/credential`;
}

export async function readSavedCredential(stateDir: string): Promise<string | undefined> {
  const fs = await nodeFs();
  try {
    const raw = fs.readFileSync(credentialPath(stateDir), "utf8");
    const parsed = JSON.parse(raw) as { credential?: string };
    return parsed.credential || undefined;
  } catch {
    return undefined;
  }
}

export async function writeSavedCredential(
  stateDir: string,
  credential: string,
  url: string,
): Promise<void> {
  const fs = await nodeFs();
  fs.mkdirSync(stateDir, { recursive: true, mode: STATE_DIR_MODE });
  try {
    fs.chmodSync(stateDir, STATE_DIR_MODE);
  } catch {
    // Best effort: some filesystems ignore modes.
  }
  const path = credentialPath(stateDir);
  fs.writeFileSync(path, JSON.stringify({ credential, url }), { mode: CREDENTIAL_FILE_MODE });
  try {
    fs.chmodSync(path, CREDENTIAL_FILE_MODE);
  } catch {
    // Best effort.
  }
}

export async function clearSavedCredential(stateDir: string): Promise<void> {
  const fs = await nodeFs();
  try {
    fs.unlinkSync(credentialPath(stateDir));
  } catch {
    // Already gone.
  }
}

async function exchangeCode(base: string, code: string): Promise<string> {
  const res = await fetch(pairUrlFromBase(base), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ code }),
  });
  if (!res.ok) {
    throw new CredentialError(`Pairing code was rejected (HTTP ${res.status}).`);
  }
  const payload = (await res.json()) as { credential?: string };
  if (!payload.credential) {
    throw new CredentialError("Pairing response had no credential.");
  }
  return payload.credential;
}

/**
 * Applies the startup order: explicit credential, then the saved file, then a
 * one-time pairing code (exchanged and saved). Returns the credential, whether
 * it came from the file, and the state directory. Never logs either secret.
 */
export async function resolveCredential(
  pluginId: string,
  inputs: PairingInputs,
): Promise<{ credential: string; fromFile: boolean; stateDir: string }> {
  const stateDir = await resolveStateDir(
    inputs.stateDir ?? env("ETHER_PLUGIN_STATE_DIR") ?? "",
    pluginId,
  );
  const explicit = (inputs.credential ?? env("ETHER_PLUGIN_CREDENTIAL") ?? "").trim();
  if (explicit) {
    return { credential: explicit, fromFile: false, stateDir };
  }
  const saved = await readSavedCredential(stateDir);
  if (saved) {
    return { credential: saved, fromFile: true, stateDir };
  }
  const url = inputs.url ?? env("ETHER_URL") ?? "";
  const code = (inputs.code ?? env("ETHER_PAIRING_CODE") ?? "").trim();
  if (url.trim() && code) {
    const credential = await exchangeCode(url, code);
    await writeSavedCredential(stateDir, credential, url);
    return { credential, fromFile: true, stateDir };
  }
  throw new CredentialError(noCredentialMessage());
}

