function getHeader(
  headers: Record<string, string | string[]> | undefined,
  name: string,
): string | undefined {
  if (!headers) return undefined;
  const target = name.toLowerCase();
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === target) {
      return Array.isArray(v) ? v[0] : v;
    }
  }
  return undefined;
}

function parseUrlPathAndQuery(
  rawPath: string,
  rawQuery?: Record<string, string | string[]>,
): { path: string; query: Record<string, string> } {
  let pathOnly = rawPath || "/";
  const query: Record<string, string> = {};
  if (rawQuery) {
    for (const [k, v] of Object.entries(rawQuery)) {
      if (Array.isArray(v)) {
        if (v.length > 0) query[k] = String(v[0]);
      } else if (v !== undefined && v !== null) {
        query[k] = String(v);
      }
    }
  }
  const qIndex = pathOnly.indexOf("?");
  if (qIndex >= 0) {
    const qs = pathOnly.slice(qIndex + 1);
    pathOnly = pathOnly.slice(0, qIndex) || "/";
    const params = parseParams(qs);
    Object.entries(params).forEach(([k, v]) => {
      if (query[k] === undefined) {
        query[k] = v;
      }
    });
  }
  if (!pathOnly.startsWith("/")) {
    pathOnly = "/" + pathOnly;
  }
  return { path: pathOnly, query };
}

function parseJsonBody(body: unknown): Record<string, unknown> {
  if (body === undefined || body === null || body === "") {
    return {};
  }
  if (typeof body === "string") {
    const trimmed = body.trim();
    if (!trimmed) return {};
    const parsed = JSON.parse(trimmed);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
    return {};
  }
  if (typeof body === "object" && !Array.isArray(body)) {
    return body as Record<string, unknown>;
  }
  return {};
}

function okResponse(body: unknown, headers?: Record<string, string>, status = 200): RawResponse {
  return {
    status,
    headers: {
      "Content-Type": "application/json",
      ...(headers ?? {}),
    },
    body,
  };
}

function errorResponse(status: number, code: string, message: string): RawResponse {
  return {
    status,
    headers: { "Content-Type": "application/json" },
    body: { error: { code, message } },
  };
}

function isEtherHostFault(err: unknown): boolean {
  if (!err) return false;
  const msg = err instanceof Error ? err.message : String(err);
  return msg.includes("__ETHER_FAULT__");
}

interface ParsedStremioRoute {
  resource: "catalog" | "meta" | "stream" | "subtitles";
  type: string;
  id: string;
  extra: Record<string, string>;
}

function parseParams(input: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const part of input.split("&")) {
    if (!part) continue;
    const index = part.indexOf("=");
    const decode = (value: string) => decodeURIComponent(value.replace(/\+/g, " "));
    result[decode(index < 0 ? part : part.slice(0, index))] = decode(index < 0 ? "" : part.slice(index + 1));
  }
  return result;
}

function parseExtraSegment(rawExtra: string | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  if (!rawExtra) return out;
  const params = parseParams(rawExtra);
  Object.entries(params).forEach(([k, v]) => {
    out[k] = v;
  });
  return out;
}

function matchStremioRoute(path: string, query: Record<string, string>): ParsedStremioRoute | null {
  if (!path.endsWith(".json")) return null;
  const trimmed = path.slice(1, -5);
  const parts = trimmed.split("/");
  if (parts.length < 3 || parts.length > 4) return null;
  const resource = parts[0];
  if (
    resource !== "catalog" &&
    resource !== "meta" &&
    resource !== "stream" &&
    resource !== "subtitles"
  ) {
    return null;
  }
  const type = decodeURIComponent(parts[1] ?? "");
  const id = decodeURIComponent(parts[2] ?? "");
  const extra = parseExtraSegment(parts[3]);
  for (const [k, v] of Object.entries(query)) {
    if (extra[k] === undefined) {
      extra[k] = v;
    }
  }
  return { resource, type, id, extra };
}

function buildInlineStrings(manifest: Manifest, explicit?: StringsCatalog): StringsCatalog {
  const catalog: StringsCatalog = {};
  if (manifest.ether?.strings) {
    for (const [loc, val] of Object.entries(manifest.ether.strings)) {
      if (val && typeof val === "object") {
        catalog[loc] = { ...(val as Record<string, string>) };
      }
    }
  }
  if (explicit) {
    for (const [loc, table] of Object.entries(explicit)) {
      catalog[loc] = { ...(catalog[loc] ?? {}), ...table };
    }
  }
  return catalog;
}

export function plugin<S = Record<string, unknown>>(
  def: PluginDefinition<S>,
): PluginInstance<S> {
  if (!def || !def.manifest) {
    throw new Error("Plugin manifest is required.");
  }
  const manifest = def.manifest;
  if (!manifest.id || !manifest.name || !manifest.version) {
    throw new Error("Plugin manifest requires id, name, and version.");
  }

  const routes = def.routes ?? {};
  const kindHandlers = createKindHandlers<S>();
  const i18n = createI18n(
    buildInlineStrings(manifest, def.strings),
    def.defaultLocale ?? "en",
  );
  const settingsSchema = manifest.ether?.settings;
  let currentSettings: S = decodeSettings<S>(
    settingsSchema,
    undefined,
    def.defaultSettings,
  ).settings;

  const pageRoutes = new Map<string, string>();
  if (manifest.ether?.contributes?.pages) {
    for (const p of manifest.ether.contributes.pages) {
      if (p.route) {
        pageRoutes.set(p.route, p.key);
      }
    }
  }
  if (manifest.ether?.contributes?.slots) {
    for (const s of manifest.ether.contributes.slots) {
      if (s.route) {
        pageRoutes.set(s.route, s.key);
      }
    }
  }

  let settingsFailureLogged = false;
  function buildContext(req: RawRequest): MaybePromise<PluginContext<S>> {
    const { query } = parseUrlPathAndQuery(req.path, req.query);
    const localeHeader =
      req.locale ??
      query.locale ??
      getHeader(req.headers, "X-Ether-Locale") ??
      getHeader(req.headers, "Accept-Language") ??
      def.defaultLocale ??
      "en";
    const locale = localeHeader.split(",")[0]?.trim() || "en";
    const pickToken = getHeader(req.headers, "X-Ether-Pick");
    const requestId = getHeader(req.headers, "X-Ether-Request-ID");
    const hostClient =
      def.host ??
      (isHostedRuntime()
        ? createHostedClient()
        : createRemoteHostClient(def.remoteHostOptions));
    const makeContext = (settings: S): PluginContext<S> => ({
      manifest,
      settings,
      locale,
      pickToken,
      requestId,
      headers: req.headers ?? {},
      query,
      ether: hostClient,
      i18n,
      t: (key, params) => i18n.t(key, params, locale),
    });
    if (!hostClient.settings || req.path === "/ether/configure") return makeContext(currentSettings);
    const fallback = () => {
      if (!settingsFailureLogged) { console.warn("plugin settings lookup failed"); settingsFailureLogged = true; }
      return makeContext({} as S);
    };
    let fresh: MaybePromise<Record<string, unknown>>;
    try { fresh = hostClient.settings.get(); } catch { return fallback(); }
    const resolve = (v: Record<string, unknown>) => {
      const merged = { ...v };
      for (const field of collectSettingFields(settingsSchema)) {
        if (field.kind === "secret" && (currentSettings as Record<string, unknown>)[field.key] !== undefined) merged[field.key] = (currentSettings as Record<string, unknown>)[field.key];
      }
      return makeContext(decodeSettings<S>(settingsSchema, merged, def.defaultSettings).settings);
    };
    return fresh instanceof Promise ? fresh.then(resolve, fallback) : resolve(fresh);
  }

  function mapResult<T>(
    value: MaybePromise<T>,
    transform: (resolved: T) => RawResponse = (r) => okResponse(r),
  ): MaybePromise<RawResponse> {
    if (value instanceof Promise) {
      return value.then(transform);
    }
    return transform(value);
  }

  function dispatchCore(req: RawRequest, ctx: PluginContext<S>): MaybePromise<RawResponse> {
    const method = (req.method || "GET").toUpperCase();
    const { path, query } = parseUrlPathAndQuery(req.path, req.query);

    if (method === "GET" && path === "/manifest.json") {
      return okResponse(manifest);
    }

    if (method === "GET" && path === "/ether/health") {
      if (routes.health) {
        return mapResult(routes.health(ctx));
      }
      const fallback: HealthResponse = { status: "ok" };
      return okResponse(fallback);
    }

    if (method === "POST" && path === "/ether/configure") {
      let bodyObj: Record<string, unknown>;
      try {
        bodyObj = parseJsonBody(req.body);
      } catch {
        return errorResponse(400, "invalid_json", "Request body must be valid JSON.");
      }
      const incoming =
        bodyObj.settings && typeof bodyObj.settings === "object" && !Array.isArray(bodyObj.settings)
          ? (bodyObj.settings as Record<string, unknown>)
          : bodyObj;
      const decoded = decodeSettings<S>(settingsSchema, incoming, def.defaultSettings);
      if (Object.keys(decoded.errors).length > 0) {
        return okResponse({ errors: decoded.errors });
      }
      if (routes.configure) {
        const nextCtx: PluginContext<S> = { ...ctx, settings: decoded.settings };
        return mapResult(routes.configure(decoded.settings, nextCtx), (res) => {
          const errors = res?.errors ?? {};
          if (Object.keys(errors).length === 0) {
            currentSettings = decoded.settings;
          }
          return okResponse({ errors });
        });
      }
      currentSettings = decoded.settings;
      return okResponse({ errors: {} });
    }

    if (method === "POST" && path === "/ether/subtitles/download") {
      if (!ctx.pickToken?.trim()) return errorResponse(403, "pick_required", "A subtitle pick is required.");
      if (!routes.subtitlesDownload) return errorResponse(404, "not_found", "Subtitle download handler is not registered.");
      const body = parseJsonBody(req.body);
      return mapResult(routes.subtitlesDownload({ id: String(body.id || ""), lang: String(body.lang || ""), format: String(body.format || "") }, ctx));
    }

    if (method === "POST" && path === "/ether/test") {
      if (routes.test) {
        return mapResult(routes.test(ctx));
      }
      const fallback: TestResponse = { ok: true };
      return okResponse(fallback);
    }

    if (method === "GET" && path.startsWith("/ether/options/")) {
      const field = decodeURIComponent(path.slice("/ether/options/".length));
      if (!routes.options) {
        return okResponse([]);
      }
      return mapResult(routes.options(field, ctx));
    }

    if (method === "POST" && path === "/ether/stream/open") {
      if (!routes.openStream) {
        return errorResponse(404, "not_found", "Stream open handler is not registered.");
      }
      const bodyObj = parseJsonBody(req.body);
      return mapResult(
        routes.openStream({ streamId: String(bodyObj.streamId ?? "") }, ctx),
      );
    }

    if (method === "GET" && path.startsWith("/ether/markers/") && path.endsWith(".json")) {
      if (!routes.markers) {
        return errorResponse(404, "not_found", "Markers handler is not registered.");
      }
      const trimmed = path.slice("/ether/markers/".length, -5);
      const parts = trimmed.split("/");
      if (parts.length < 2) {
        return errorResponse(400, "invalid_path", "Markers route requires type and id.");
      }
      return mapResult(
        routes.markers(
          {
            type: decodeURIComponent(parts[0] ?? ""),
            id: decodeURIComponent(parts.slice(1).join("/")),
          },
          ctx,
        ),
      );
    }

    if (method === "GET" && path === "/ether/channels.json") {
      if (!routes.channels) {
        return errorResponse(404, "not_found", "Channels handler is not registered.");
      }
      return mapResult(routes.channels(ctx));
    }

    if (method === "GET" && path.startsWith("/ether/guide/") && path.endsWith(".json")) {
      if (!routes.guide) {
        return errorResponse(404, "not_found", "Guide handler is not registered.");
      }
      const channelId = decodeURIComponent(path.slice("/ether/guide/".length, -5));
      return mapResult(
        routes.guide({ channelId, from: query.from, to: query.to }, ctx),
      );
    }

    if (method === "POST" && path === "/ether/notify") {
      if (!routes.notify) {
        return errorResponse(404, "not_found", "Notify handler is not registered.");
      }
      const bodyObj = parseJsonBody(req.body);
      return mapResult(
        routes.notify(
          {
            title: typeof bodyObj.title === "string" ? bodyObj.title : undefined,
            message: String(bodyObj.message ?? bodyObj.text ?? ""),
            event: typeof bodyObj.event === "string" ? bodyObj.event : undefined,
            settings:
              bodyObj.settings && typeof bodyObj.settings === "object"
                ? (bodyObj.settings as Record<string, unknown>)
                : undefined,
          },
          ctx,
        ),
      );
    }

    if (method === "POST" && path === "/ether/event") {
      if (!routes.event) {
        return errorResponse(404, "not_found", "Event handler is not registered.");
      }
      const bodyObj = parseJsonBody(req.body);
      const events = Array.isArray(bodyObj.events) ? (bodyObj.events as EtherEvent[]) : [];
      return mapResult(routes.event(events, ctx), (res) => {
        if (res && Array.isArray(res.ack)) {
          return okResponse({ ack: res.ack });
        }
        return okResponse({ ack: events.map((e) => e.id) });
      });
    }

    if (
      method === "GET" &&
      (path === "/ether/view" || path.startsWith("/ether/view/") || pageRoutes.has(path))
    ) {
      if (!routes.view) {
        return errorResponse(404, "not_found", "View handler is not registered.");
      }
      let page = pageRoutes.get(path);
      if (!page) {
        page =
          path === "/ether/view" ? "home" : decodeURIComponent(path.slice("/ether/view/".length));
      }
      return mapResult(routes.view({ page, query }, ctx));
    }

    if (method === "POST" && path.startsWith("/ether/action/")) {
      if (!routes.action) {
        return errorResponse(404, "not_found", "Action handler is not registered.");
      }
      const action = decodeURIComponent(path.slice("/ether/action/".length));
      const input = parseJsonBody(req.body);
      return mapResult(routes.action({ action, input }, ctx));
    }

    if (method === "POST" && path.startsWith("/ether/tool/")) {
      if (!routes.tool) {
        return errorResponse(404, "not_found", "Tool handler is not registered.");
      }
      const name = decodeURIComponent(path.slice("/ether/tool/".length));
      const input = parseJsonBody(req.body);
      return mapResult(routes.tool({ name, input }, ctx));
    }

    if (method === "POST" && path.startsWith("/ether/job/")) {
      if (!routes.job) {
        return errorResponse(404, "not_found", "Job handler is not registered.");
      }
      const name = decodeURIComponent(path.slice("/ether/job/".length));
      return mapResult(routes.job({ name }, ctx));
    }

    if (method === "POST" && path === "/ether/rank-key") {
      if (!routes.rankKey) {
        return errorResponse(404, "not_found", "Rank key handler is not registered.");
      }
      const bodyObj = parseJsonBody(req.body);
      const candidate = (bodyObj.candidate ?? bodyObj) as unknown as CandidateFacts;
      const cfg = (bodyObj.config as S | undefined) ?? currentSettings;
      const score = Number(routes.rankKey(candidate, cfg)) || 0;
      return okResponse({ score });
    }

    if (method === "POST" && path === "/ether/cond-match") {
      if (!routes.condMatch) {
        return errorResponse(404, "not_found", "Condition match handler is not registered.");
      }
      const bodyObj = parseJsonBody(req.body);
      const candidate = (bodyObj.candidate ?? bodyObj) as unknown as CandidateFacts;
      const operator = String(bodyObj.operator ?? "eq");
      const value = bodyObj.value;
      const matched = Boolean(routes.condMatch(candidate, operator, value));
      return okResponse({ match: matched });
    }

    if ((method === "GET" || method === "HEAD") && path.startsWith("/ether/file/")) {
      if (!routes.file) {
        return errorResponse(404, "not_found", "File handler is not registered.");
      }
      const relPath = decodeURIComponent(path.slice("/ether/file/".length));
      if (!relPath || relPath.startsWith("/") || relPath.split("/").includes("..")) {
        return errorResponse(400, "invalid_path", "File path must be a clean relative path.");
      }
      const rangeHeader = getHeader(req.headers, "Range");
      return mapResult(
        routes.file({ path: relPath, range: rangeHeader, headOnly: method === "HEAD" }, ctx),
        (fileRes) => {
          const headers: Record<string, string> = {
            "Content-Type": fileRes.contentType || "application/octet-stream",
            "Accept-Ranges": "bytes",
            ...(fileRes.headers ?? {}),
          };
          if (fileRes.contentRange) {
            headers["Content-Range"] = fileRes.contentRange;
          }
          if (fileRes.totalSize !== undefined && !fileRes.contentRange) {
            headers["Content-Length"] = String(fileRes.totalSize);
          }
          return {
            status: fileRes.status ?? (fileRes.contentRange ? 206 : 200),
            headers,
            body: method === "HEAD" ? new Uint8Array(0) : fileRes.body,
          };
        },
      );
    }

    if (method === "GET") {
      const stremio = matchStremioRoute(path, query);
      if (stremio) {
        if (stremio.resource === "subtitles") {
          if (!routes.subtitles) {
            return errorResponse(404, "not_found", "Subtitles handler is not registered.");
          }
          const videoSize = stremio.extra.videoSize ? Number(stremio.extra.videoSize) : undefined;
          return mapResult(
            routes.subtitles(
              {
                type: stremio.type,
                id: stremio.id,
                extra: stremio.extra,
                pickToken: ctx.pickToken,
                videoHash: stremio.extra.videoHash,
                videoSize: Number.isFinite(videoSize) ? videoSize : undefined,
                filename: stremio.extra.filename,
              },
              ctx,
            ),
          );
        }

        if (stremio.resource === "catalog") {
          if (!routes.catalog) {
            return errorResponse(404, "not_found", "Catalog handler is not registered.");
          }
          const skip = stremio.extra.skip ? Number(stremio.extra.skip) || 0 : 0;
          return mapResult(
            routes.catalog(
              {
                type: stremio.type,
                id: stremio.id,
                extra: stremio.extra,
                skip,
                search: stremio.extra.search,
                genre: stremio.extra.genre,
              },
              ctx,
            ),
          );
        }

        if (stremio.resource === "meta") {
          if (!routes.meta) {
            return errorResponse(404, "not_found", "Meta handler is not registered.");
          }
          return mapResult(routes.meta({ type: stremio.type, id: stremio.id }, ctx));
        }

        if (stremio.resource === "stream") {
          if (!routes.stream) {
            return errorResponse(404, "not_found", "Stream handler is not registered.");
          }
          return mapResult(
            routes.stream({ type: stremio.type, id: stremio.id, extra: stremio.extra }, ctx),
          );
        }
      }
    }

    if (path.startsWith("/ether/v1/")) {
      return dispatchKinds(kindHandlers, req, ctx).then(
        (r) => r ?? errorResponse(404, "not_found", `No route matched ${method} ${path}.`),
      );
    }

    return errorResponse(404, "not_found", `No route matched ${method} ${path}.`);
  }

  function handleRouteError(err: unknown): RawResponse {
    if (isEtherHostFault(err)) {
      throw err;
    }
    if (err instanceof PluginHttpError) {
      return errorResponse(err.status, err.code, err.message);
    }
    if (
      err &&
      typeof err === "object" &&
      "status" in err &&
      typeof (err as { status: unknown }).status === "number"
    ) {
      const e = err as { status: number; code?: string; message?: string };
      return errorResponse(e.status, e.code || "plugin_error", e.message || "Request failed.");
    }
    const message = err instanceof Error ? err.message : String(err);
    return errorResponse(500, "internal_error", message || "Internal plugin error.");
  }

  function handleRequest(req: RawRequest): MaybePromise<RawResponse> {
    try {
      const ctx = buildContext(req);
      const res = ctx instanceof Promise ? ctx.then(c => dispatchCore(req, c)) : dispatchCore(req, ctx);
      return res instanceof Promise ? res.catch(handleRouteError) : res;
    } catch (err) {
      return handleRouteError(err);
    }
  }

  async function dispatch(req: RawRequest): Promise<RawResponse> {
    try {
      const ctx = await buildContext(req);
      return await dispatchCore(req, ctx);
    } catch (err) {
      return handleRouteError(err);
    }
  }

  function rankKey(candidate: CandidateFacts, config?: S): number {
    if (!routes.rankKey) return 0;
    return Number(routes.rankKey(candidate, config ?? currentSettings)) || 0;
  }

  function condMatch(candidate: CandidateFacts, operator: string, value: unknown): boolean {
    if (!routes.condMatch) return false;
    return Boolean(routes.condMatch(candidate, operator, value));
  }

  const instance: PluginInstance<S> = {
    manifest,
    routes,
    getSettings: () => currentSettings,
    setSettings: (incoming) => {
      const decoded = decodeSettings<S>(settingsSchema, incoming, def.defaultSettings);
      if (Object.keys(decoded.errors).length === 0) {
        currentSettings = decoded.settings;
      }
      return decoded;
    },
    handle: handleRequest,
    dispatch,
    rank_key: rankKey,
    cond_match: condMatch,
    onCatalog: (kind, provider) => { kindHandlers.catalog.set(kind, provider); },
    onResolve: (kind, resolver) => { kindHandlers.resolve.set(kind, resolver); },
    onMatch: (kind, matcher) => { kindHandlers.match.set(kind, matcher); },
    onFrontend: (key, adapter) => { kindHandlers.frontend.set(key, adapter); },
    onSetupTest: (tester) => { kindHandlers.setup = tester; },
  };

  if (isHostedRuntime()) {
    const g = globalThis as Record<string, unknown>;
    g.handle = handleRequest;
    g.rank_key = rankKey;
    g.cond_match = condMatch;
  }

  return instance;
}

import type { RawRequest, RawResponse } from "./types.ts";
import type { PluginInstance } from "./router.ts";
import { isHostedRuntime } from "./host.ts";
import {
  clearSavedCredential,
  CredentialError,
  noCredentialMessage,
  resolveCredential,
  tunnelUrlFromBase,
} from "./pairing.ts";

export interface ServeOptions {
  mode?: "http" | "tunnel";
  host?: string;
  port?: number;
  tunnelUrl?: string;
  credential?: string;
  signal?: AbortSignal;
  /** The server's http(s) base (ETHER_URL). Derives the tunnel URL and pairing. */
  url?: string;
  /** A one-time pairing code (ETHER_PAIRING_CODE). */
  code?: string;
  /** Overrides where the pairing credential is saved. */
  stateDir?: string;
}

export interface ServeHandle {
  mode: "http" | "tunnel" | "hosted";
  url?: string;
  port?: number;
  close(): Promise<void>;
}

const TUNNEL_PROTOCOL = "ether-tunnel-v1";
const DEFAULT_MAX_CHUNK_BYTES = 64 * 1024;

function readEnv(name: string): string | undefined {
  const g = globalThis as { process?: { env?: Record<string, string | undefined> } };
  return g.process?.env?.[name];
}

function serializeResponseBody(body: unknown): { bytes: Uint8Array; isBinary: boolean } {
  if (body instanceof Uint8Array) {
    return { bytes: body, isBinary: true };
  }
  if (typeof body === "string") {
    return { bytes: new TextEncoder().encode(body), isBinary: false };
  }
  const json = JSON.stringify(body ?? {});
  return { bytes: new TextEncoder().encode(json), isBinary: false };
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]!);
  }
  return btoa(binary);
}

function base64ToBytes(b64: string): Uint8Array {
  if (!b64) {
    return new Uint8Array(0);
  }
  const binary = atob(b64);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    out[i] = binary.charCodeAt(i);
  }
  return out;
}

function concatBytes(chunks: Uint8Array[]): Uint8Array {
  let total = 0;
  for (const c of chunks) {
    total += c.byteLength;
  }
  const out = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) {
    out.set(c, offset);
    offset += c.byteLength;
  }
  return out;
}

function toMultiHeaders(headers: Record<string, string> | undefined): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  if (!headers) {
    return out;
  }
  for (const [k, v] of Object.entries(headers)) {
    out[k] = [v];
  }
  return out;
}

export interface TunnelFrame {
  type:
    | "hello"
    | "welcome"
    | "request"
    | "response"
    | "response_start"
    | "response_chunk"
    | "response_end"
    | "cancel"
    | "error";
  id?: string;
  requestId?: string;
  protocol?: string;
  plugin?: string;
  pluginId?: string;
  connectionId?: string;
  features?: string[];
  maxChunkBytes?: number;
  method?: string;
  path?: string;
  query?: Record<string, string[]>;
  headers?: Record<string, string[]>;
  body?: string;
  data?: string;
  status?: number;
  deadline?: string;
  error?: {
    code: string;
    message: string;
  };
}

export async function dispatchOverTunnelFrame<S>(
  instance: PluginInstance<S>,
  frame: TunnelFrame,
  maxChunkBytes = DEFAULT_MAX_CHUNK_BYTES,
): Promise<TunnelFrame[]> {
  if (frame.type !== "request" || !frame.id) {
    return [];
  }
  const decodedBodyBytes = frame.body ? base64ToBytes(frame.body) : new Uint8Array(0);
  const rawBodyText =
    decodedBodyBytes.length > 0 ? new TextDecoder().decode(decodedBodyBytes) : undefined;
  const headers: Record<string, string | string[]> = {};
  if (frame.headers) {
    for (const [k, v] of Object.entries(frame.headers)) {
      headers[k] = v;
    }
  }
  if (frame.requestId && !headers["X-Ether-Request-ID"]) {
    headers["X-Ether-Request-ID"] = frame.requestId;
  }

  const req: RawRequest = {
    method: frame.method ?? "GET",
    path: frame.path ?? "/",
    query: frame.query,
    headers,
    body: rawBodyText,
  };

  let res: RawResponse;
  try {
    res = await instance.dispatch(req);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return [
      {
        type: "error",
        id: frame.id,
        error: { code: "internal_error", message },
      },
    ];
  }

  const { bytes, isBinary } = serializeResponseBody(res.body);
  const multiHeaders = toMultiHeaders(res.headers);

  if (isBinary && (req.path || "").startsWith("/ether/file/")) {
    const out: TunnelFrame[] = [
      {
        type: "response_start",
        id: frame.id,
        status: res.status,
        headers: multiHeaders,
      },
    ];
    const chunkLimit = Math.max(1024, maxChunkBytes);
    for (let offset = 0; offset < bytes.length; offset += chunkLimit) {
      const slice = bytes.subarray(offset, Math.min(bytes.length, offset + chunkLimit));
      out.push({
        type: "response_chunk",
        id: frame.id,
        data: bytesToBase64(slice),
      });
    }
    out.push({
      type: "response_end",
      id: frame.id,
    });
    return out;
  }

  return [
    {
      type: "response",
      id: frame.id,
      status: res.status,
      headers: multiHeaders,
      body: bytes.length > 0 ? bytesToBase64(bytes) : undefined,
    },
  ];
}

async function serveHttp<S>(
  instance: PluginInstance<S>,
  options: ServeOptions,
): Promise<ServeHandle> {
  type NodeHttpMod = typeof import("node:http");
  const nodeHttpSpec = "node:" + "http";
  const httpMod = (await import(nodeHttpSpec)) as NodeHttpMod;
  const host = options.host ?? readEnv("ETHER_PLUGIN_HOST") ?? "127.0.0.1";
  const port =
    options.port ??
    (readEnv("ETHER_PLUGIN_PORT") ? Number(readEnv("ETHER_PLUGIN_PORT")) : 0);

  const server = httpMod.createServer(async (incoming, outgoing) => {
    try {
      const chunks: Uint8Array[] = [];
      for await (const chunk of incoming) {
        chunks.push(chunk instanceof Uint8Array ? chunk : new Uint8Array(chunk));
      }
      const merged = concatBytes(chunks);
      const rawBody = merged.byteLength > 0 ? new TextDecoder().decode(merged) : undefined;
      const headers: Record<string, string | string[]> = {};
      for (const [k, v] of Object.entries(incoming.headers)) {
        if (typeof v === "string" || Array.isArray(v)) {
          headers[k] = v;
        }
      }
      const req: RawRequest = {
        method: incoming.method ?? "GET",
        path: incoming.url ?? "/",
        headers,
        body: rawBody,
      };
      const res = await instance.dispatch(req);
      const { bytes } = serializeResponseBody(res.body);
      const outHeaders: Record<string, string> = {
        "Content-Type": "application/json",
        ...(res.headers ?? {}),
        "Content-Length": String(bytes.byteLength),
      };
      outgoing.writeHead(res.status, outHeaders);
      if ((incoming.method ?? "GET").toUpperCase() === "HEAD") {
        outgoing.end();
      } else {
        outgoing.end(bytes);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      const bodyBytes = new TextEncoder().encode(
        JSON.stringify({ error: { code: "internal_error", message: msg } }),
      );
      outgoing.writeHead(500, {
        "Content-Type": "application/json",
        "Content-Length": String(bodyBytes.byteLength),
      });
      outgoing.end(bodyBytes);
    }
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, host, () => {
      server.removeListener("error", reject);
      resolve();
    });
  });

  const addr = server.address();
  const actualPort = typeof addr === "object" && addr ? addr.port : port;
  const url = `http://${host}:${actualPort}`;

  const close = async (): Promise<void> => {
    await new Promise<void>((resolve, reject) => {
      server.close((err?: Error) => (err ? reject(err) : resolve()));
    });
  };

  if (options.signal) {
    if (options.signal.aborted) {
      await close();
    } else {
      options.signal.addEventListener("abort", () => {
        void close();
      });
    }
  }

  return {
    mode: "http",
    url,
    port: actualPort,
    close,
  };
}

/**
 * Probes a tunnel URL with a credential. Ether answers 401 before the WebSocket
 * upgrade when the credential is rejected; any other status means the handshake
 * was allowed to proceed. Transient failures are treated as not-rejected so the
 * existing reconnect/backoff still applies.
 */
async function tunnelCredentialRejected(
  tunnelUrl: string,
  credential: string,
): Promise<boolean> {
  const httpUrl = tunnelUrl.replace(/^ws/, "http");
  try {
    const res = await fetch(httpUrl, {
      method: "GET",
      headers: { "X-Ether-Plugin-Credential": credential },
    });
    return res.status === 401;
  } catch {
    return false;
  }
}

async function serveTunnel<S>(
  instance: PluginInstance<S>,
  options: ServeOptions,
): Promise<ServeHandle> {
  let tunnelUrl = options.tunnelUrl ?? readEnv("ETHER_TUNNEL_URL");
  const base = options.url ?? readEnv("ETHER_URL") ?? "";
  if (!tunnelUrl && base) {
    tunnelUrl = tunnelUrlFromBase(base);
  }
  if (!tunnelUrl) {
    throw new Error("Tunnel mode requires tunnelUrl, ETHER_TUNNEL_URL or ETHER_URL.");
  }

  let credential = "";
  let fromFile = false;
  let stateDir = "";
  try {
    const resolved = await resolveCredential(instance.manifest.id, {
      credential: options.credential,
      url: base,
      code: options.code,
      stateDir: options.stateDir,
    });
    credential = resolved.credential;
    fromFile = resolved.fromFile;
    stateDir = resolved.stateDir;
  } catch (err) {
    // A low-level caller may pass only a tunnel URL for testing; the pairing
    // flow always has ETHER_URL, so the clear line still applies to sidecars.
    if (base) {
      throw err;
    }
  }

  // A saved credential the server no longer accepts is dead: clear the file and
  // fail rather than reconnect with it forever. The tunnel returns 401 before
  // the upgrade, so a plain request detects it.
  if (fromFile && credential) {
    const rejected = await tunnelCredentialRejected(tunnelUrl, credential);
    if (rejected) {
      await clearSavedCredential(stateDir);
      throw new CredentialError(noCredentialMessage());
    }
  }

  const WebSocketCtor = (globalThis as unknown as { WebSocket?: typeof WebSocket }).WebSocket;
  if (!WebSocketCtor) {
    throw new Error("Global WebSocket constructor is required for tunnel mode.");
  }

  const protocols = [TUNNEL_PROTOCOL];
  if (credential) {
    protocols.push(`ether-credential.${credential}`);
  }

  const ws = new WebSocketCtor(tunnelUrl, protocols);
  let maxChunkBytes = DEFAULT_MAX_CHUNK_BYTES;
  let closed = false;

  await new Promise<void>((resolve, reject) => {
    const onOpen = () => {
      const hello: TunnelFrame = {
        type: "hello",
        protocol: TUNNEL_PROTOCOL,
        plugin: instance.manifest.id,
        features: ["range", "stream"],
      };
      ws.send(JSON.stringify(hello));
    };

    const onMessage = async (event: MessageEvent) => {
      try {
        const text = typeof event.data === "string" ? event.data : String(event.data);
        const frame = JSON.parse(text) as TunnelFrame;
        if (frame.type === "welcome") {
          if (frame.maxChunkBytes && frame.maxChunkBytes > 0) {
            maxChunkBytes = frame.maxChunkBytes;
          }
          resolve();
          return;
        }
        if (frame.type === "request") {
          const replies = await dispatchOverTunnelFrame(instance, frame, maxChunkBytes);
          for (const reply of replies) {
            if (!closed && ws.readyState === ws.OPEN) {
              ws.send(JSON.stringify(reply));
            }
          }
        }
      } catch (err) {
        const id = extractFrameId(event.data);
        if (id) {
          const msg = err instanceof Error ? err.message : String(err);
          ws.send(
            JSON.stringify({
              type: "error",
              id,
              error: { code: "internal_error", message: msg },
            }),
          );
        }
      }
    };

    const onError = (ev: Event) => {
      reject(new Error(`Tunnel WebSocket error: ${String(ev)}`));
    };

    ws.addEventListener("open", onOpen);
    ws.addEventListener("message", (ev) => {
      void onMessage(ev);
    });
    ws.addEventListener("error", onError, { once: true });
  });

  const close = async (): Promise<void> => {
    if (closed) {
      return;
    }
    closed = true;
    if (ws.readyState === ws.OPEN || ws.readyState === ws.CONNECTING) {
      ws.close(1000, "Plugin shutting down");
    }
  };

  if (options.signal) {
    if (options.signal.aborted) {
      await close();
    } else {
      options.signal.addEventListener("abort", () => {
        void close();
      });
    }
  }

  return {
    mode: "tunnel",
    url: tunnelUrl,
    close,
  };
}

function extractFrameId(raw: unknown): string | undefined {
  try {
    const parsed = JSON.parse(typeof raw === "string" ? raw : String(raw)) as { id?: string };
    return parsed.id;
  } catch {
    return undefined;
  }
}

export async function serve<S>(
  instance: PluginInstance<S>,
  options: ServeOptions = {},
): Promise<ServeHandle> {
  if (isHostedRuntime()) {
    const g = globalThis as Record<string, unknown>;
    g.handle = instance.handle;
    g.rank_key = instance.rank_key;
    g.cond_match = instance.cond_match;
    return {
      mode: "hosted",
      close: async () => {},
    };
  }

  const requestedMode =
    options.mode ??
    (options.tunnelUrl || readEnv("ETHER_TUNNEL_URL") || readEnv("ETHER_URL")
      ? "tunnel"
      : "http");
  if (requestedMode === "tunnel") {
    return serveTunnel(instance, options);
  }
  return serveHttp(instance, options);
}

/**
 * Settings schema decoding and validation (SPEC §5.5).
 * Mirrors internal/plugins/manifest.go and internal/plugins/install.go.
 */

import type { SettingField, SettingsSchema } from "./types.ts";
import { lintCopy } from "./i18n.ts";

const ALLOWED_KINDS = new Set([
  "group",
  "text",
  "secret",
  "duration",
  "readonly",
  "number",
  "bool",
  "select",
  "list",
  "bytes",
  "hidden",
  "multiSelect",
  "orderedList",
  "language",
  "viewer",
  "collection",
  "folder",
  "url",
  "title",
]);

export interface DecodedSettings<S> {
  settings: S;
  errors: Record<string, string>;
}

/** Collects all leaf setting fields from a SettingsSchema. */
export function collectSettingFields(
  schema: SettingsSchema | Record<string, unknown> | undefined,
): SettingField[] {
  if (!schema || typeof schema !== "object") return [];
  const out: SettingField[] = [];
  const walk = (node: unknown): void => {
    if (!node || typeof node !== "object") return;
    if (Array.isArray(node)) {
      for (const item of node) walk(item);
      return;
    }
    const obj = node as Record<string, unknown>;
    const key =
      typeof obj.key === "string"
        ? obj.key
        : typeof obj.name === "string"
          ? obj.name
          : typeof obj.id === "string"
            ? obj.id
            : typeof obj.field === "string"
              ? obj.field
              : "";
    const kind = typeof obj.kind === "string" ? obj.kind : "";
    if (key && kind && kind !== "group") {
      out.push({
        key,
        kind: kind as SettingField["kind"],
        label: typeof obj.label === "string" ? obj.label : undefined,
        hint: typeof obj.hint === "string" ? obj.hint : undefined,
        required: obj.required === true,
        default: obj.default,
        min: typeof obj.min === "number" ? obj.min : undefined,
        max: typeof obj.max === "number" ? obj.max : undefined,
      });
    }
    for (const v of Object.values(obj)) {
      if (v && typeof v === "object") walk(v);
    }
  };
  walk(schema);
  return out;
}

/** Lints a settings schema for forbidden kinds and copy-rule violations (SPEC §5.5). */
export function lintSettingsSchema(
  schema: SettingsSchema | Record<string, unknown> | undefined,
): Array<{ field: string; message: string }> {
  if (!schema || typeof schema !== "object") return [];
  const problems: Array<{ field: string; message: string }> = [];
  const walk = (node: unknown, path: string): void => {
    if (!node || typeof node !== "object") return;
    if (Array.isArray(node)) {
      node.forEach((item, i) => walk(item, `${path}[${i}]`));
      return;
    }
    const obj = node as Record<string, unknown>;
    if (typeof obj.kind === "string") {
      if (obj.kind === "json") {
        problems.push({
          field: `${path}.kind`,
          message: "the json field kind is not allowed in plugin settings",
        });
      } else if (!ALLOWED_KINDS.has(obj.kind)) {
        problems.push({
          field: `${path}.kind`,
          message: `unknown field kind ${JSON.stringify(obj.kind)}`,
        });
      }
    }
    if (typeof obj.label === "string" && !obj.label.startsWith("$t:")) {
      const msg = lintCopy(obj.label, 40);
      if (msg) problems.push({ field: `${path}.label`, message: msg });
    }
    if (typeof obj.hint === "string" && !obj.hint.startsWith("$t:")) {
      const msg = lintCopy(obj.hint, 120);
      if (msg) problems.push({ field: `${path}.hint`, message: msg });
      const trimmed = obj.hint.replace(/\.+$/, "");
      if (trimmed.includes(".")) {
        problems.push({ field: `${path}.hint`, message: "must be one sentence" });
      }
    }
    for (const [k, v] of Object.entries(obj)) {
      walk(v, `${path}.${k}`);
    }
  };
  walk(schema, "ether.settings");
  return problems;
}

/**
 * Decodes and validates incoming settings against a plugin's settings schema,
 * applying field defaults and returning JSON-pointer keyed errors for `/ether/configure`.
 */
export function decodeSettings<S = Record<string, unknown>>(
  schema: SettingsSchema | Record<string, unknown> | undefined,
  incoming: Record<string, unknown> | undefined,
  defaults?: Partial<S>,
): DecodedSettings<S> {
  const fields = collectSettingFields(schema);
  const result: Record<string, unknown> = { ...(defaults as Record<string, unknown> | undefined) };
  const errors: Record<string, string> = {};

  for (const field of fields) {
    if (field.default !== undefined && result[field.key] === undefined) {
      result[field.key] = field.default;
    }
  }

  if (incoming && typeof incoming === "object") {
    for (const [k, v] of Object.entries(incoming)) {
      result[k] = v;
    }
  }

  for (const field of fields) {
    const val = result[field.key];
    const ptr = `/${field.key}`;
    if (field.required && (val === undefined || val === null || val === "")) {
      errors[ptr] = "is required";
      continue;
    }
    if (val === undefined || val === null || val === "") {
      continue;
    }
    switch (field.kind) {
      case "number":
      case "bytes":
      case "viewer": {
        const num = typeof val === "number" ? val : Number(val);
        if (!Number.isFinite(num)) {
          errors[ptr] = "must be a number";
        } else {
          if (field.min !== undefined && num < field.min) {
            errors[ptr] = `must be at least ${field.min}`;
          }
          if (field.max !== undefined && num > field.max) {
            errors[ptr] = `must be at most ${field.max}`;
          }
          result[field.key] = num;
        }
        break;
      }
      case "bool": {
        if (typeof val !== "boolean") {
          errors[ptr] = "must be true or false";
        }
        break;
      }
      case "list":
      case "multiSelect":
      case "orderedList": {
        if (!Array.isArray(val)) {
          errors[ptr] = "must be a list";
        }
        break;
      }
      case "url": {
        if (typeof val !== "string" || (!val.startsWith("http://") && !val.startsWith("https://"))) {
          errors[ptr] = "must be an http or https URL";
        }
        break;
      }
      default:
        break;
    }
  }

  return {
    settings: result as S,
    errors,
  };
}

import type { Capability, Manifest, PluginKind } from "./types.ts";
import type { PluginDefinition } from "./router.ts";

export interface TemplateOptions {
  id: string;
  name: string;
  version?: string;
  summary?: string;
  description?: string;
}

function baseManifest(
  opts: TemplateOptions,
  kind: PluginKind,
  capabilities: Capability[],
  extra?: Partial<Manifest>,
): Manifest {
  const summary = opts.summary ?? `${opts.name} plugin for Ether.`;
  return {
    id: opts.id,
    name: opts.name,
    version: opts.version ?? "0.1.0",
    description: opts.description ?? summary,
    types: ["movie", "series"],
    idPrefixes: ["tt"],
    ether: {
      protocol: 1,
      kind,
      capabilities,
      summary,
      runtime: {
        kind: "hosted",
        entry: "plugin.ts",
      },
      permissions: {
        catalog: "none",
      },
    },
    ...extra,
  };
}

export function createCatalogTemplate(
  opts: TemplateOptions,
): PluginDefinition<{ apiKey: string }> {
  const base = baseManifest(opts, "extension", ["list_source"], {
    catalogs: [
      {
        type: "movie",
        id: "featured",
        name: "Featured movies",
        extra: [{ name: "search", isRequired: false }],
      },
    ],
    resources: ["catalog", "meta"],
  });
  return {
    manifest: {
      ...base,
      ether: {
        ...base.ether!,
        settings: {
          fields: [
            {
              key: "apiKey",
              kind: "secret",
              label: "Access token",
              hint: "Token used to query the upstream catalog",
            },
          ],
        },
        contributes: {
          listSources: [
            {
              key: "featured",
              label: "Featured movies",
              hint: "Curated movies from the upstream list",
              catalog: "featured",
              refresh: "1h",
            },
          ],
        },
      },
    },
    routes: {
      catalog({ type, id, search }) {
        return {
          metas: [
            {
              id: "tt0133093",
              type,
              name: search ? `Result for ${search}` : `Featured in ${id}`,
              releaseInfo: "1999",
            },
          ],
        };
      },
      meta({ type, id }) {
        return {
          meta: {
            id,
            type,
            name: `Title ${id}`,
            releaseInfo: "1999",
            description: "Catalog metadata entry.",
          },
        };
      },
    },
  };
}

