      value: ViewSpecValue;
      sub?: ViewSpecValue;
      tone?: "default" | "positive" | "warning" | "negative" | ViewSpecFieldRef;
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "panel";
      title: ViewSpecValue;
      iconKey?: ViewSpecValue;
      hint?: ViewSpecValue;
      blocks: ViewSpecBlock[];
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "text";
      content: ViewSpecValue;
      tone?:
        | "default"
        | "negative"
        | "positive"
        | "warning"
        | "muted"
        | "strong"
        | ViewSpecFieldRef;
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "heading";
      level: 2 | 3;
      content: ViewSpecValue;
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "grid";
      as?: "div" | "section";
      blocks: ViewSpecBlock[];
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "widget";
      widget:
        | "ether.posterGrid"
        | "ether.posterShelf"
        | "ether.titleCard"
        | "ether.liveChart"
        | "ether.settingsForm"
        | "ether.actionButton"
        | "ether.titleMatch"
        | "ether.healthStrip"
        | "ether.channelRow"
        | "ether.badge";
      props?: Record<string, unknown>;
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "frame";
      frame: "ether.section" | "ether.tabs" | "ether.drawer";
      props?: Record<string, unknown>;
      blocks: ViewSpecBlock[];
      when?: ViewSpecFieldRef;
    }
  | {
      kind: "repeat";
      items: ViewSpecFieldRef;
      itemKey: ViewSpecFieldRef;
      unwrapped?: boolean;
      empty?: { text: ViewSpecValue };
      blocks: ViewSpecBlock[];
      when?: ViewSpecFieldRef;
    }
  | Record<string, unknown>;

